DO $pre$
DECLARE missing text;
BEGIN
  SELECT string_agg(x, ', ') INTO missing
  FROM unnest(ARRAY['pg_cron','pg_net','pgcrypto','uuid-ossp']) AS x
  WHERE NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = x);
  IF missing IS NOT NULL THEN
    RAISE EXCEPTION 'baseline precondition failed: extension(s) not installed: %', missing;
  END IF;
END $pre$;

