--
-- Name: accept_org_invitation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_org_invitation(invitation_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  inv record;
  new_member_id uuid;
BEGIN
  -- Get invitation
  SELECT * INTO inv
  FROM public.invitations
  WHERE id = invitation_id AND status = 'pending';

  IF inv IS NULL THEN
    RAISE EXCEPTION 'Invalid or expired invitation.';
  END IF;

  -- Verify the current user matches invitation email
  IF inv.email != (SELECT email FROM auth.users WHERE id = auth.uid()) THEN
    RAISE EXCEPTION 'This invitation is not for your account.';
  END IF;

  -- Check not already a member
  IF EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE user_id = auth.uid() AND organization_id = inv.organization_id
  ) THEN
    -- Already a member, just mark invitation as accepted
    UPDATE public.invitations SET status = 'accepted', accepted_at = now() WHERE id = invitation_id;
    RETURN (SELECT id FROM public.organization_users WHERE user_id = auth.uid() AND organization_id = inv.organization_id);
  END IF;

  -- Add member
  INSERT INTO public.organization_users (organization_id, user_id, role)
  VALUES (inv.organization_id, auth.uid(), inv.role)
  RETURNING id INTO new_member_id;

  -- Mark invitation accepted
  UPDATE public.invitations SET status = 'accepted', accepted_at = now() WHERE id = invitation_id;

  RETURN new_member_id;
END;
$$;


--
-- Name: acknowledge_failed_email_safe(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acknowledge_failed_email_safe(p_email_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_email RECORD;
  v_org_id UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_email FROM email_queue WHERE id = p_email_id;
  IF v_email.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Email not found');
  END IF;

  v_org_id := v_email.organization_id;
  IF NOT user_has_role_at_least(v_user_id, v_org_id, 'manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: manager+ required');
  END IF;

  IF v_email.status != 'failed' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Can only acknowledge failed emails');
  END IF;

  UPDATE email_queue SET
    status = 'ignored',
    acknowledged_at = now(),
    acknowledged_by = v_user_id,
    updated_at = now()
  WHERE id = p_email_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
  VALUES (v_org_id, 'email', p_email_id, 'acknowledged_failure', v_user_id,
    jsonb_build_object('last_error', v_email.last_error_message));

  RETURN jsonb_build_object('success', true, 'email_id', p_email_id);
END;
$$;


--
-- Name: acknowledge_vat_reconciliation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acknowledge_vat_reconciliation(p_reconciliation_id uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reconciliation RECORD;
  v_user_id UUID;
  v_org_role TEXT;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Fetch reconciliation
  SELECT * INTO v_reconciliation FROM vat_reconciliations WHERE id = p_reconciliation_id;

  IF v_reconciliation.id IS NULL THEN
    RAISE EXCEPTION 'Reconciliation not found';
  END IF;

  -- Check user has org access and is at least staff
  SELECT role INTO v_org_role FROM organization_users 
  WHERE user_id = v_user_id AND organization_id = v_reconciliation.organization_id;

  IF v_org_role IS NULL THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF v_org_role NOT IN ('owner', 'admin', 'staff') THEN
    RAISE EXCEPTION 'Only accountants can acknowledge reconciliation differences';
  END IF;

  -- Only WARNING classification requires acknowledgement
  IF v_reconciliation.classification != 'WARNING' THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'Reconciliation is INFO classification, no acknowledgement required'
    );
  END IF;

  -- Already acknowledged?
  IF v_reconciliation.acknowledged THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'Reconciliation already acknowledged',
      'acknowledged_by', v_reconciliation.acknowledged_by_user_id,
      'acknowledged_at', v_reconciliation.acknowledged_at
    );
  END IF;

  -- Acknowledge
  UPDATE vat_reconciliations
  SET 
    acknowledged = true,
    acknowledged_by_user_id = v_user_id,
    acknowledged_at = now(),
    acknowledgement_note = p_note,
    updated_at = now()
  WHERE id = p_reconciliation_id;

  -- Audit log
  INSERT INTO audit_log (
    organization_id, entity_type, entity_id, action, user_id, metadata
  ) VALUES (
    v_reconciliation.organization_id,
    'vat_reconciliation',
    p_reconciliation_id,
    'VAT_RECONCILIATION_ACKNOWLEDGED',
    v_user_id,
    jsonb_build_object(
      'difference', v_reconciliation.difference,
      'classification', v_reconciliation.classification,
      'vat_period_id', v_reconciliation.vat_period_id,
      'model_snapshot_id', v_reconciliation.model_snapshot_id,
      'note', p_note
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'acknowledged_at', now(),
    'acknowledged_by', v_user_id
  );
END;
$$;


--
-- Name: add_org_member(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_org_member(target_org_id uuid, target_user_id uuid, target_role text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  caller_role text;
  new_id uuid;
BEGIN
  -- Validate role
  IF target_role NOT IN ('admin', 'staff') THEN
    RAISE EXCEPTION 'Invalid role. Only admin or staff can be assigned.';
  END IF;

  -- Check caller is owner of the org
  SELECT role INTO caller_role
  FROM public.organization_users
  WHERE user_id = auth.uid() AND organization_id = target_org_id;

  IF caller_role IS NULL OR caller_role != 'owner' THEN
    RAISE EXCEPTION 'Only owners can add members directly.';
  END IF;

  -- Prevent duplicate
  IF EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE user_id = target_user_id AND organization_id = target_org_id
  ) THEN
    RAISE EXCEPTION 'User is already a member of this organization.';
  END IF;

  INSERT INTO public.organization_users (organization_id, user_id, role)
  VALUES (target_org_id, target_user_id, target_role)
  RETURNING id INTO new_id;

  -- Audit log
  INSERT INTO public.audit_log (organization_id, user_id, entity_type, entity_id, action, actor_role, metadata)
  VALUES (target_org_id, auth.uid(), 'organization_user', new_id, 'member_added', caller_role,
    jsonb_build_object('target_user_id', target_user_id, 'assigned_role', target_role));

  RETURN new_id;
END;
$$;


--
-- Name: add_reconciliation_line(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_reconciliation_line(p_reconciliation_id uuid, p_bank_transaction_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rec public.reconciliations%ROWTYPE;
  v_txn public.bank_transactions%ROWTYPE;
  v_line_id uuid;
BEGIN
  SELECT * INTO v_rec FROM public.reconciliations WHERE id = p_reconciliation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reconciliation not found'; END IF;
  IF v_rec.status <> 'in_progress' THEN
    RAISE EXCEPTION 'Reconciliation is not in progress (status=%)', v_rec.status;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = v_rec.organization_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not authorized for this organization';
  END IF;

  SELECT * INTO v_txn FROM public.bank_transactions WHERE id = p_bank_transaction_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Bank transaction not found'; END IF;

  IF v_txn.bank_account_id <> v_rec.bank_account_id THEN
    RAISE EXCEPTION 'Transaction belongs to a different bank account';
  END IF;
  IF v_txn.transaction_date < v_rec.statement_start_date
     OR v_txn.transaction_date > v_rec.statement_end_date THEN
    RAISE EXCEPTION 'Transaction date % outside reconciliation period', v_txn.transaction_date;
  END IF;
  IF v_txn.matched_ledger_entry_id IS NULL THEN
    RAISE EXCEPTION 'Transaction must be posted/matched to the ledger before reconciliation';
  END IF;

  -- Prevent duplicate inclusion in any reconciliation
  IF EXISTS (
    SELECT 1 FROM public.reconciliation_lines
    WHERE bank_transaction_id = p_bank_transaction_id
  ) THEN
    RAISE EXCEPTION 'Transaction already included in a reconciliation';
  END IF;

  INSERT INTO public.reconciliation_lines (
    reconciliation_id, bank_transaction_id, ledger_entry_id, match_type, amount
  ) VALUES (
    p_reconciliation_id, p_bank_transaction_id, v_txn.matched_ledger_entry_id, 'auto', v_txn.amount
  ) RETURNING id INTO v_line_id;

  UPDATE public.bank_transactions
     SET status = 'RECONCILED', updated_at = now()
   WHERE id = p_bank_transaction_id;

  RETURN v_line_id;
END;
$$;


--
-- Name: add_service_to_client(uuid, uuid, uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_service_to_client(p_client_id uuid, p_company_id uuid, p_service_id uuid, p_period_start date, p_period_end date, p_period_label text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_service_code text;
  v_service_name text;
  v_billing_frequency text;
  v_frequency text;
  v_engagement_id uuid;
  v_job_id uuid;
BEGIN
  IF (p_client_id IS NULL) = (p_company_id IS NULL) THEN
    RAISE EXCEPTION 'Provide exactly one of client or company';
  END IF;

  IF p_company_id IS NOT NULL THEN
    SELECT organization_id INTO v_org FROM public.companies WHERE id = p_company_id;
  ELSE
    SELECT organization_id INTO v_org FROM public.clients WHERE id = p_client_id;
  END IF;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Entity not found';
  END IF;
  IF NOT public.user_has_organization_access(v_org) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT code, name, billing_model
    INTO v_service_code, v_service_name, v_billing_frequency
    FROM public.services_catalog WHERE id = p_service_id;
  IF v_service_code IS NULL THEN
    RAISE EXCEPTION 'Service not found';
  END IF;
  v_frequency := CASE WHEN v_billing_frequency = 'monthly' THEN 'monthly' ELSE 'one_off' END;

  SELECT id INTO v_engagement_id
    FROM public.engagements
    WHERE service_id = p_service_id
      AND client_id IS NOT DISTINCT FROM p_client_id
      AND company_id IS NOT DISTINCT FROM p_company_id
    LIMIT 1;
  IF v_engagement_id IS NULL THEN
    INSERT INTO public.engagements
      (organization_id, client_id, company_id, service_id, frequency, start_date, status, activated_at)
    VALUES
      (v_org, p_client_id, p_company_id, p_service_id, v_frequency, CURRENT_DATE, 'active', now())
    RETURNING id INTO v_engagement_id;
  ELSE
    UPDATE public.engagements
      SET status = 'active', activated_at = COALESCE(activated_at, now())
      WHERE id = v_engagement_id;
  END IF;

  v_job_id := public.lifecycle_upsert_job_with_deadlines(
    v_org, p_client_id, p_company_id, v_engagement_id,
    v_service_code, v_service_name, p_period_start, p_period_end, p_period_label,
    'manual_add_service'
  );

  RETURN v_job_id;
END;
$$;


--
-- Name: allocate_credit_note(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocate_credit_note(p_credit_note_id uuid, p_allocations jsonb, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cn record;
  v_alloc jsonb;
  v_doc_id uuid;
  v_amount numeric;
  v_total_alloc numeric := 0;
  v_inv record;
  v_bill record;
  v_new_paid numeric;
  v_new_remaining numeric;
  v_membership boolean;
  v_new_cn_remaining numeric;
  v_new_cn_status text;
BEGIN
  SELECT * INTO v_cn FROM credit_notes WHERE id = p_credit_note_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_message', 'Credit note not found');
  END IF;

  IF NOT v_cn.is_posted THEN
    RETURN jsonb_build_object('success', false, 'error_message', 'Credit note must be approved before allocating');
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM organization_users
    WHERE organization_id = v_cn.organization_id
      AND user_id = COALESCE(p_user_id, auth.uid())
  ) INTO v_membership;
  IF NOT v_membership THEN
    RETURN jsonb_build_object('success', false, 'error_message', 'Not authorized for this organization');
  END IF;

  -- Validate totals first
  FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations) LOOP
    v_amount := COALESCE((v_alloc->>'amount')::numeric, 0);
    IF v_amount <= 0 THEN
      RETURN jsonb_build_object('success', false, 'error_message', 'Allocation amount must be positive');
    END IF;
    v_total_alloc := v_total_alloc + v_amount;
  END LOOP;

  IF v_total_alloc > v_cn.remaining_allocation + 0.005 THEN
    RETURN jsonb_build_object('success', false, 'error_message', 'Total allocation exceeds remaining credit');
  END IF;

  -- Apply each allocation
  FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations) LOOP
    v_doc_id := (v_alloc->>'document_id')::uuid;
    v_amount := (v_alloc->>'amount')::numeric;

    IF v_cn.credit_note_type = 'SALES' THEN
      SELECT id, organization_id, amount_paid, total_gross
      INTO v_inv FROM invoices WHERE id = v_doc_id FOR UPDATE;
      IF NOT FOUND OR v_inv.organization_id <> v_cn.organization_id THEN
        RETURN jsonb_build_object('success', false, 'error_message', 'Invoice not found / wrong org');
      END IF;

      INSERT INTO credit_note_allocations (
        organization_id, credit_note_id, invoice_id, bill_id,
        amount, allocation_date, created_by
      ) VALUES (
        v_cn.organization_id, v_cn.id, v_doc_id, NULL,
        v_amount, CURRENT_DATE, COALESCE(p_user_id, auth.uid())
      );

      v_new_paid := COALESCE(v_inv.amount_paid, 0) + v_amount;
      v_new_remaining := v_inv.total_gross - v_new_paid;
      UPDATE invoices
      SET amount_paid = v_new_paid,
          remaining_balance = v_new_remaining,
          status = CASE WHEN v_new_remaining <= 0.005 THEN 'PAID' ELSE 'PART_PAID' END,
          updated_at = now()
      WHERE id = v_doc_id;

    ELSE
      SELECT id, organization_id, amount_paid, total_gross
      INTO v_bill FROM bills WHERE id = v_doc_id FOR UPDATE;
      IF NOT FOUND OR v_bill.organization_id <> v_cn.organization_id THEN
        RETURN jsonb_build_object('success', false, 'error_message', 'Bill not found / wrong org');
      END IF;

      INSERT INTO credit_note_allocations (
        organization_id, credit_note_id, invoice_id, bill_id,
        amount, allocation_date, created_by
      ) VALUES (
        v_cn.organization_id, v_cn.id, NULL, v_doc_id,
        v_amount, CURRENT_DATE, COALESCE(p_user_id, auth.uid())
      );

      v_new_paid := COALESCE(v_bill.amount_paid, 0) + v_amount;
      v_new_remaining := v_bill.total_gross - v_new_paid;
      UPDATE bills
      SET amount_paid = v_new_paid,
          remaining_balance = v_new_remaining,
          status = CASE WHEN v_new_remaining <= 0.005 THEN 'PAID' ELSE 'PART_PAID' END,
          updated_at = now()
      WHERE id = v_doc_id;
    END IF;
  END LOOP;

  v_new_cn_remaining := GREATEST(0, v_cn.remaining_allocation - v_total_alloc);
  v_new_cn_status := CASE WHEN v_new_cn_remaining <= 0.005 THEN 'FULLY_ALLOCATED' ELSE 'PARTIALLY_ALLOCATED' END;

  UPDATE credit_notes
  SET remaining_allocation = v_new_cn_remaining,
      status = v_new_cn_status,
      updated_at = now(),
      updated_by = COALESCE(p_user_id, auth.uid())
  WHERE id = p_credit_note_id;

  RETURN jsonb_build_object(
    'success', true,
    'remaining_allocation', v_new_cn_remaining,
    'credit_note_status', v_new_cn_status
  );
END;
$$;


--
-- Name: apply_bank_match(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_bank_match(p_bank_transaction_id uuid, p_allocations jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_txn RECORD;
  v_alloc JSONB;
  v_doc_id UUID;
  v_doc_type TEXT;
  v_amount NUMERIC;
  v_total_allocated NUMERIC := 0;
  v_journal_id UUID;
  v_settings RECORD;
  v_contra_account_id UUID;
  v_invoice RECORD;
  v_bill RECORD;
  v_entries JSONB := '[]'::jsonb;
  v_user_id UUID := auth.uid();
  v_post_result JSONB;
  v_before JSONB;
BEGIN
  SELECT * INTO v_txn FROM public.bank_transactions WHERE id = p_bank_transaction_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bank transaction not found';
  END IF;
  IF upper(COALESCE(v_txn.status,'')) IN ('MATCHED','RECONCILED') THEN
    RAISE EXCEPTION 'Transaction already %', v_txn.status;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE user_id = v_user_id AND organization_id = v_txn.organization_id
  ) THEN
    RAISE EXCEPTION 'Not authorised for organization';
  END IF;

  PERFORM assert_no_locked_period_write(
    v_txn.organization_id, v_txn.client_id, v_txn.company_id, v_txn.transaction_date
  );

  FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations) LOOP
    v_amount := (v_alloc->>'amount')::numeric;
    IF v_amount <= 0 THEN
      RAISE EXCEPTION 'Allocation amounts must be positive';
    END IF;
    v_total_allocated := v_total_allocated + v_amount;
  END LOOP;

  IF ROUND(v_total_allocated::numeric, 2) <> ROUND(ABS(v_txn.amount)::numeric, 2) THEN
    RAISE EXCEPTION 'Allocations (%) must equal transaction amount (%)',
      v_total_allocated, ABS(v_txn.amount);
  END IF;

  SELECT * INTO v_settings FROM public.org_settings
   WHERE organization_id = v_txn.organization_id
   LIMIT 1;

  v_before := to_jsonb(v_txn);

  FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations) LOOP
    v_doc_id := (v_alloc->>'document_id')::uuid;
    v_doc_type := v_alloc->>'document_type';
    v_amount := (v_alloc->>'amount')::numeric;

    IF v_doc_type = 'invoice' THEN
      SELECT * INTO v_invoice FROM public.invoices WHERE id = v_doc_id;
      IF NOT FOUND OR v_invoice.organization_id <> v_txn.organization_id THEN
        RAISE EXCEPTION 'Invoice % not found or cross-tenant', v_doc_id;
      END IF;
      IF v_invoice.client_id IS DISTINCT FROM v_txn.client_id
         OR v_invoice.company_id IS DISTINCT FROM v_txn.company_id THEN
        RAISE EXCEPTION 'Invoice % belongs to a different entity', v_doc_id;
      END IF;

      v_contra_account_id := v_settings.ar_control_account_id;
      IF v_contra_account_id IS NULL THEN
        RAISE EXCEPTION 'AR control account not configured in org_settings';
      END IF;

      v_entries := v_entries || jsonb_build_array(
        jsonb_build_object('account_id', v_txn.bank_account_id, 'debit', v_amount, 'credit', 0,
                           'description', 'Receipt: invoice ' || COALESCE(v_invoice.invoice_number, v_doc_id::text)),
        jsonb_build_object('account_id', v_contra_account_id, 'debit', 0, 'credit', v_amount,
                           'description', 'Receipt: invoice ' || COALESCE(v_invoice.invoice_number, v_doc_id::text))
      );

      INSERT INTO public.invoice_payments(
        invoice_id, amount, payment_date, bank_account_id,
        bank_transaction_id, reference, payment_type, created_by
      ) VALUES (
        v_doc_id, v_amount, v_txn.transaction_date, v_txn.bank_account_id,
        p_bank_transaction_id,
        'Bank match: ' || LEFT(COALESCE(v_txn.description,''), 80),
        'normal', v_user_id
      );

    ELSIF v_doc_type = 'bill' THEN
      SELECT * INTO v_bill FROM public.bills WHERE id = v_doc_id;
      IF NOT FOUND OR v_bill.organization_id <> v_txn.organization_id THEN
        RAISE EXCEPTION 'Bill % not found or cross-tenant', v_doc_id;
      END IF;
      IF v_bill.client_id IS DISTINCT FROM v_txn.client_id
         OR v_bill.company_id IS DISTINCT FROM v_txn.company_id THEN
        RAISE EXCEPTION 'Bill % belongs to a different entity', v_doc_id;
      END IF;

      v_contra_account_id := v_settings.ap_control_account_id;
      IF v_contra_account_id IS NULL THEN
        RAISE EXCEPTION 'AP control account not configured in org_settings';
      END IF;

      v_entries := v_entries || jsonb_build_array(
        jsonb_build_object('account_id', v_contra_account_id, 'debit', v_amount, 'credit', 0,
                           'description', 'Payment: bill ' || COALESCE(v_bill.bill_number, v_doc_id::text)),
        jsonb_build_object('account_id', v_txn.bank_account_id, 'debit', 0, 'credit', v_amount,
                           'description', 'Payment: bill ' || COALESCE(v_bill.bill_number, v_doc_id::text))
      );

      INSERT INTO public.bill_payments(
        bill_id, amount, payment_date, bank_account_id,
        bank_transaction_id, reference, payment_type, created_by
      ) VALUES (
        v_doc_id, v_amount, v_txn.transaction_date, v_txn.bank_account_id,
        p_bank_transaction_id,
        'Bank match: ' || LEFT(COALESCE(v_txn.description,''), 80),
        'normal', v_user_id
      );
    ELSE
      RAISE EXCEPTION 'Unsupported document type: %', v_doc_type;
    END IF;
  END LOOP;

  v_post_result := public.post_to_ledger(
    p_organization_id := v_txn.organization_id,
    p_client_id       := v_txn.client_id,
    p_company_id      := v_txn.company_id,
    p_transaction_date:= v_txn.transaction_date,
    p_description     := 'Bank match: ' || LEFT(COALESCE(v_txn.description,''), 80),
    p_source_type     := 'BANK_TRANSACTION',
    p_source_id       := p_bank_transaction_id,
    p_entries         := v_entries
  );

  v_journal_id := (v_post_result->>'journal_id')::uuid;

  UPDATE public.bank_transactions
     SET status = 'MATCHED',
         matched_ledger_entry_id = v_journal_id
   WHERE id = p_bank_transaction_id;

  INSERT INTO public.bookkeeping_audit_log(
    organization_id, entity_type, entity_id, action, actor_id,
    before_state, after_state, metadata
  ) VALUES (
    v_txn.organization_id, 'bank_transaction', p_bank_transaction_id, 'apply_bank_match', v_user_id,
    v_before,
    jsonb_build_object('status','MATCHED','journal_id',v_journal_id),
    jsonb_build_object('allocations', p_allocations)
  );

  RETURN jsonb_build_object('success', true, 'journal_id', v_journal_id);
END;
$$;


--
-- Name: apply_bank_rule(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_bank_rule(p_bank_transaction_id uuid, p_rule_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_txn record;
  v_rule record;
  v_bank record;
  v_actions jsonb;
  v_action jsonb;
  v_account_id uuid;
  v_vat_code_id uuid;
  v_category text;
  v_post_result jsonb;
  v_before jsonb;
  v_actor uuid := auth.uid();
  v_is_member boolean;
BEGIN
  -- Lock the transaction row to serialise concurrent rule applications
  SELECT * INTO v_txn FROM bank_transactions
    WHERE id = p_bank_transaction_id
    FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'transaction_not_found',
                              'error_message', 'Bank transaction not found');
  END IF;

  SELECT user_in_organization(v_actor, v_txn.organization_id) INTO v_is_member;
  IF NOT COALESCE(v_is_member, false) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'forbidden',
                              'error_message', 'Only accountants in this organisation can apply bank rules');
  END IF;

  IF upper(COALESCE(v_txn.status,'')) IN ('MATCHED','RECONCILED','CATEGORIZED') THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'already_categorized',
                              'error_message', 'Transaction is already categorised');
  END IF;

  BEGIN
    PERFORM assert_no_locked_period_write(
      v_txn.organization_id, v_txn.client_id, v_txn.company_id, v_txn.transaction_date
    );
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'period_locked',
                              'error_message', SQLERRM);
  END;

  SELECT * INTO v_rule FROM bank_rules WHERE id = p_rule_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'rule_not_found',
                              'error_message', 'Bank rule not found');
  END IF;
  IF v_rule.organization_id <> v_txn.organization_id THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'org_mismatch',
                              'error_message', 'Rule and transaction belong to different organisations');
  END IF;
  IF v_rule.is_active IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'rule_inactive',
                              'error_message', 'Rule is not active');
  END IF;
  IF v_rule.client_id IS NOT NULL AND v_rule.client_id IS DISTINCT FROM v_txn.client_id THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'scope_mismatch',
                              'error_message', 'Rule is scoped to a different client');
  END IF;
  IF v_rule.company_id IS NOT NULL AND v_rule.company_id IS DISTINCT FROM v_txn.company_id THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'scope_mismatch',
                              'error_message', 'Rule is scoped to a different company');
  END IF;
  IF v_rule.bank_account_id IS NOT NULL AND v_rule.bank_account_id IS DISTINCT FROM v_txn.bank_account_id THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'bank_account_mismatch',
                              'error_message', 'Rule is scoped to a different bank account');
  END IF;

  v_actions := COALESCE(v_rule.actions, '[]'::jsonb);
  FOR v_action IN SELECT * FROM jsonb_array_elements(v_actions) LOOP
    IF v_action->>'type' = 'set_account' THEN
      v_account_id := NULLIF(v_action->>'value','')::uuid;
    ELSIF v_action->>'type' = 'set_vat_code' THEN
      v_vat_code_id := NULLIF(v_action->>'value','')::uuid;
    ELSIF v_action->>'type' = 'set_category' THEN
      v_category := v_action->>'value';
    END IF;
  END LOOP;

  IF v_account_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'missing_account_action',
                              'error_message', 'Rule must define a set_account action');
  END IF;

  SELECT * INTO v_bank FROM bank_accounts WHERE id = v_txn.bank_account_id;
  IF NOT FOUND OR v_bank.organization_id <> v_txn.organization_id THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'bank_account_invalid',
                              'error_message', 'Bank account not found or not in this organisation');
  END IF;

  v_before := to_jsonb(v_txn);

  -- REVIEW MODE: stage suggestion only, do not post.
  IF v_rule.requires_review OR NOT v_rule.auto_post THEN
    UPDATE bank_transactions
       SET rule_id = p_rule_id,
           category = COALESCE(v_category, category),
           client_suggested_account_id = v_account_id,
           review_status = 'pending'::bk_review_status,
           status = 'PENDING_REVIEW'
     WHERE id = p_bank_transaction_id;

    INSERT INTO bank_rule_executions(
      organization_id, bank_rule_id, bank_transaction_id, executed_by,
      matched_conditions, applied_actions, result
    ) VALUES (
      v_txn.organization_id, p_rule_id, p_bank_transaction_id, v_actor,
      v_rule.conditions, v_rule.actions, 'pending_review'
    );

    INSERT INTO bookkeeping_audit_log(
      organization_id, entity_type, entity_id, action, actor_id,
      before_state, after_state, metadata
    ) VALUES (
      v_txn.organization_id, 'bank_transaction', p_bank_transaction_id, 'apply_bank_rule_suggested', v_actor,
      v_before,
      jsonb_build_object('suggested_account_id', v_account_id, 'rule_id', p_rule_id,
                         'category', v_category, 'status', 'PENDING_REVIEW'),
      jsonb_build_object('rule_source', v_rule.source, 'vat_sensitive', v_rule.vat_sensitive)
    );

    UPDATE bank_rules
       SET times_applied = COALESCE(times_applied, 0) + 1,
           last_applied_at = now()
     WHERE id = p_rule_id;

    RETURN jsonb_build_object('success', true, 'mode', 'review',
                              'message', 'Rule staged for accountant review');
  END IF;

  -- AUTO-POST MODE
  v_post_result := post_bank_transaction(
    p_bank_transaction_id := p_bank_transaction_id,
    p_contra_account_id   := v_account_id,
    p_vat_code_id         := v_vat_code_id,
    p_vat_amount          := 0,
    p_description         := COALESCE(v_txn.description, v_rule.rule_name)
  );

  IF v_post_result IS NULL OR (v_post_result->>'success')::boolean IS DISTINCT FROM true THEN
    INSERT INTO bank_rule_executions(
      organization_id, bank_rule_id, bank_transaction_id, executed_by,
      matched_conditions, applied_actions, result, error_message
    ) VALUES (
      v_txn.organization_id, p_rule_id, p_bank_transaction_id, v_actor,
      v_rule.conditions, v_rule.actions, 'failed',
      COALESCE(v_post_result->>'error_message', v_post_result->>'error', 'unknown')
    );
    INSERT INTO bookkeeping_audit_log(
      organization_id, entity_type, entity_id, action, actor_id,
      before_state, after_state, metadata
    ) VALUES (
      v_txn.organization_id, 'bank_transaction', p_bank_transaction_id, 'apply_bank_rule_failed', v_actor,
      v_before, NULL,
      jsonb_build_object('rule_id', p_rule_id, 'error', v_post_result)
    );
    RETURN v_post_result;
  END IF;

  UPDATE bank_transactions
     SET rule_id = p_rule_id,
         category = COALESCE(v_category, category),
         status = 'MATCHED'
   WHERE id = p_bank_transaction_id;

  INSERT INTO bank_rule_executions(
    organization_id, bank_rule_id, bank_transaction_id, executed_by,
    matched_conditions, applied_actions, result
  ) VALUES (
    v_txn.organization_id, p_rule_id, p_bank_transaction_id, v_actor,
    v_rule.conditions, v_rule.actions, 'success'
  );

  UPDATE bank_rules
     SET times_applied = COALESCE(times_applied, 0) + 1,
         last_applied_at = now()
   WHERE id = p_rule_id;

  INSERT INTO bookkeeping_audit_log(
    organization_id, entity_type, entity_id, action, actor_id,
    before_state, after_state, metadata
  ) VALUES (
    v_txn.organization_id, 'bank_transaction', p_bank_transaction_id, 'apply_bank_rule', v_actor,
    v_before,
    jsonb_build_object('rule_id', p_rule_id, 'account_id', v_account_id,
                       'vat_code_id', v_vat_code_id, 'category', v_category, 'status', 'MATCHED'),
    jsonb_build_object('post_result', v_post_result, 'rule_source', v_rule.source)
  );

  RETURN v_post_result;
END;
$$;


--
-- Name: apply_ch_diff(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_ch_diff(p_diff_id uuid, p_decision text, p_notes text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_diff record;
BEGIN
  SELECT * INTO v_diff FROM public.companies_house_diff_staging WHERE id = p_diff_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Diff not found'; END IF;
  IF NOT user_has_organization_access(v_diff.organization_id) THEN RAISE EXCEPTION 'Not authorised'; END IF;
  IF v_diff.status <> 'pending' THEN RAISE EXCEPTION 'Diff already decided'; END IF;
  IF p_decision NOT IN ('accept','reject') THEN RAISE EXCEPTION 'Invalid decision'; END IF;

  IF p_decision = 'accept' AND v_diff.company_id IS NOT NULL THEN
    CASE v_diff.field_path
      WHEN 'registered_office_address' THEN
        UPDATE public.companies
          SET registered_office_address = v_diff.incoming_value
          WHERE id = v_diff.company_id;
      WHEN 'sic_codes' THEN
        UPDATE public.companies
          SET sic_codes = CASE
            WHEN v_diff.incoming_value IS NULL OR jsonb_typeof(v_diff.incoming_value) = 'null' THEN NULL
            ELSE ARRAY(SELECT jsonb_array_elements_text(v_diff.incoming_value))
          END
          WHERE id = v_diff.company_id;
      WHEN 'company_type' THEN
        UPDATE public.companies
          SET company_type = NULLIF(v_diff.incoming_value #>> '{}', '')
          WHERE id = v_diff.company_id;
      WHEN 'confirmation_statement_made_up_to' THEN
        UPDATE public.companies
          SET confirmation_statement_made_up_to = NULLIF(v_diff.incoming_value #>> '{}', '')::date
          WHERE id = v_diff.company_id;
      WHEN 'confirmation_statement_next_due' THEN
        UPDATE public.companies
          SET confirmation_statement_next_due = NULLIF(v_diff.incoming_value #>> '{}', '')::date
          WHERE id = v_diff.company_id;
      ELSE
        -- Unknown field path: record but do not write
        NULL;
    END CASE;
  END IF;

  UPDATE public.companies_house_diff_staging
    SET status = CASE WHEN p_decision = 'accept' THEN 'accepted' ELSE 'rejected' END,
        decided_by = auth.uid(),
        decided_at = now(),
        decision_notes = p_notes
  WHERE id = p_diff_id;
END;
$$;


--
-- Name: apply_client_override(uuid, uuid, uuid, uuid, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_client_override(p_org_id uuid, p_client_id uuid, p_rule_id uuid, p_chaser_policy_id uuid, p_enabled boolean, p_config jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF NOT user_in_organization(auth.uid(), p_org_id) THEN RAISE EXCEPTION 'not a member'; END IF;
  INSERT INTO automation_client_overrides(organization_id, client_id, rule_id, chaser_policy_id, enabled, config_overrides)
  VALUES (p_org_id, p_client_id, p_rule_id, p_chaser_policy_id, p_enabled, p_config)
  ON CONFLICT (client_id, rule_id) WHERE rule_id IS NOT NULL
  DO UPDATE SET enabled = excluded.enabled, config_overrides = excluded.config_overrides, updated_at = now()
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN
    INSERT INTO automation_client_overrides(organization_id, client_id, rule_id, chaser_policy_id, enabled, config_overrides)
    VALUES (p_org_id, p_client_id, p_rule_id, p_chaser_policy_id, p_enabled, p_config)
    ON CONFLICT (client_id, chaser_policy_id) WHERE chaser_policy_id IS NOT NULL
    DO UPDATE SET enabled = excluded.enabled, config_overrides = excluded.config_overrides, updated_at = now()
    RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END;$$;


