--
-- Name: apply_opening_balances(uuid, uuid, uuid, date, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_opening_balances(p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_opening_date date, p_entries jsonb, p_lock_period boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_source_id uuid := gen_random_uuid();
  v_actor uuid := auth.uid();
BEGIN
  v_result := post_to_ledger(
    p_organization_id, p_client_id, p_company_id,
    p_opening_date, 'OPENING-BAL', 'Opening balances', 'OPENING_BALANCE',
    'OPENING_BALANCE', v_source_id, 'GBP', 1.0, v_actor, p_entries
  );

  IF COALESCE((v_result->>'success')::boolean, false) AND p_lock_period THEN
    INSERT INTO period_locks (organization_id, client_id, company_id, lock_date, locked_by, reason)
    VALUES (p_organization_id, p_client_id, p_company_id, p_opening_date, v_actor, 'Opening balance period lock')
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: approve_bill(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_bill(p_bill_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bill RECORD;
  v_entity_type text;
  v_entity_id uuid;
  v_creditors_id uuid;
  v_vat_id uuid;
  v_entries jsonb := '[]'::jsonb;
  v_line RECORD;
  v_post_result jsonb;
  v_uid uuid := COALESCE(p_user_id, auth.uid());
BEGIN
  SELECT * INTO v_bill FROM bills WHERE id = p_bill_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_found', 'error_message', 'Bill not found');
  END IF;
  IF v_bill.status <> 'DRAFT' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'invalid_status', 'error_message', 'Bill is not in draft status');
  END IF;
  IF v_bill.is_posted THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'already_posted', 'error_message', 'Bill already posted');
  END IF;

  v_entity_type := CASE WHEN v_bill.client_id IS NOT NULL THEN 'client' ELSE 'company' END;
  v_entity_id   := COALESCE(v_bill.client_id, v_bill.company_id);

  SELECT id INTO v_creditors_id FROM bookkeeping_accounts
   WHERE organization_id = v_bill.organization_id
     AND ((v_entity_type='client'  AND client_id  = v_entity_id)
       OR (v_entity_type='company' AND company_id = v_entity_id))
     AND is_active = true AND is_control_account = true
     AND account_subtype IN ('TRADE_CREDITORS','CREDITOR','PAYABLE','ACCOUNTS_PAYABLE')
   LIMIT 1;
  IF v_creditors_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'missing_control_account', 'error_message', 'Trade Creditors control account not found');
  END IF;

  SELECT id INTO v_vat_id FROM bookkeeping_accounts
   WHERE organization_id = v_bill.organization_id
     AND ((v_entity_type='client'  AND client_id  = v_entity_id)
       OR (v_entity_type='company' AND company_id = v_entity_id))
     AND is_active = true AND is_control_account = true
     AND account_subtype IN ('VAT_CONTROL','VAT')
   LIMIT 1;

  -- DR expense accounts per line (net)
  FOR v_line IN SELECT * FROM bill_lines WHERE bill_id = p_bill_id ORDER BY line_number LOOP
    v_entries := v_entries || jsonb_build_array(jsonb_build_object(
      'account_id', v_line.account_id,
      'debit', v_line.net_amount,
      'credit', NULL,
      'description', 'Bill ' || COALESCE(v_bill.bill_number, substr(p_bill_id::text,1,8)) || ': ' || v_line.description,
      'vat_code_id', v_line.vat_code_id
    ));
  END LOOP;

  IF v_bill.total_vat > 0 AND v_vat_id IS NOT NULL THEN
    v_entries := v_entries || jsonb_build_array(jsonb_build_object(
      'account_id', v_vat_id,
      'debit', v_bill.total_vat,
      'credit', NULL,
      'description', 'VAT on Bill ' || COALESCE(v_bill.bill_number, substr(p_bill_id::text,1,8))
    ));
  END IF;

  -- CR Trade Creditors (gross)
  v_entries := v_entries || jsonb_build_array(jsonb_build_object(
    'account_id', v_creditors_id,
    'debit', NULL,
    'credit', v_bill.total_gross,
    'description', 'Bill ' || COALESCE(v_bill.bill_number, substr(p_bill_id::text,1,8))
  ));

  v_post_result := post_to_ledger(
    p_organization_id := v_bill.organization_id,
    p_client_id       := CASE WHEN v_entity_type='client'  THEN v_entity_id ELSE NULL END,
    p_company_id      := CASE WHEN v_entity_type='company' THEN v_entity_id ELSE NULL END,
    p_journal_date    := v_bill.issue_date,
    p_reference       := v_bill.bill_number,
    p_description     := 'BILL posting',
    p_journal_type    := 'SYSTEM',
    p_source_type     := 'BILL',
    p_source_id       := p_bill_id,
    p_currency        := COALESCE(v_bill.currency,'GBP'),
    p_fx_rate         := COALESCE(v_bill.exchange_rate,1.0),
    p_created_by      := v_uid,
    p_entries         := v_entries
  );

  IF NOT (v_post_result->>'success')::boolean THEN
    RAISE EXCEPTION 'Posting failed: %', v_post_result->>'error_message'
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE bills
     SET status = 'AWAITING_PAYMENT',
         is_posted = true,
         posted_at = now(),
         posted_by = v_uid,
         updated_at = now()
   WHERE id = p_bill_id;

  RETURN jsonb_build_object('success', true, 'journal_id', v_post_result->>'journal_id');
END;
$$;


--
-- Name: approve_bill_safe(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_bill_safe(p_bill_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_bill record;
BEGIN
  PERFORM set_config('app.rpc', '1', true);

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_bill FROM bills WHERE id = p_bill_id;
  IF v_bill.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bill not found');
  END IF;

  IF NOT public.user_in_organization(v_user_id, v_bill.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  IF NOT public.user_has_role_at_least(v_user_id, v_bill.organization_id, 'manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Manager role required');
  END IF;

  IF v_bill.status != 'DRAFT' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only DRAFT bills can be approved');
  END IF;

  UPDATE bills SET status = 'APPROVED', approved_at = now(), approved_by = v_user_id
  WHERE id = p_bill_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id)
  VALUES (v_bill.organization_id, 'bill', p_bill_id, 'approved', v_user_id);

  RETURN jsonb_build_object('success', true, 'bill_id', p_bill_id);
END;
$$;

