--
-- Name: approve_credit_note(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_credit_note(p_credit_note_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cn record;
  v_org uuid;
  v_entity_type text;
  v_entity_id uuid;
  v_control_subtypes text[];
  v_control_account uuid;
  v_vat_account uuid;
  v_entries jsonb := '[]'::jsonb;
  v_line record;
  v_post_result jsonb;
  v_journal_id uuid;
  v_membership boolean;
BEGIN
  SELECT * INTO v_cn FROM credit_notes WHERE id = p_credit_note_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_message', 'Credit note not found');
  END IF;

  IF v_cn.status <> 'DRAFT' OR v_cn.is_posted THEN
    RETURN jsonb_build_object('success', false, 'error_message', 'Credit note is not in DRAFT status');
  END IF;

  v_org := v_cn.organization_id;

  -- Membership / tenancy check
  SELECT EXISTS(
    SELECT 1 FROM organization_users
    WHERE organization_id = v_org
      AND user_id = COALESCE(p_user_id, auth.uid())
  ) INTO v_membership;
  IF NOT v_membership THEN
    RETURN jsonb_build_object('success', false, 'error_message', 'Not authorized for this organization');
  END IF;

  IF v_cn.client_id IS NOT NULL THEN
    v_entity_type := 'client';
    v_entity_id := v_cn.client_id;
  ELSIF v_cn.company_id IS NOT NULL THEN
    v_entity_type := 'company';
    v_entity_id := v_cn.company_id;
  ELSE
    RETURN jsonb_build_object('success', false, 'error_message', 'Credit note has no entity scope');
  END IF;

  -- Resolve control account
  IF v_cn.credit_note_type = 'SALES' THEN
    v_control_subtypes := ARRAY['TRADE_DEBTORS','DEBTOR','RECEIVABLE','ACCOUNTS_RECEIVABLE'];
  ELSE
    v_control_subtypes := ARRAY['TRADE_CREDITORS','CREDITOR','PAYABLE','ACCOUNTS_PAYABLE'];
  END IF;

  SELECT id INTO v_control_account
  FROM bookkeeping_accounts
  WHERE organization_id = v_org
    AND is_active = true
    AND is_control_account = true
    AND account_subtype = ANY(v_control_subtypes)
    AND ((v_entity_type = 'client' AND client_id = v_entity_id)
      OR (v_entity_type = 'company' AND company_id = v_entity_id))
  LIMIT 1;

  IF v_control_account IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_message',
      'No control account configured for ' || v_cn.credit_note_type);
  END IF;

  -- Resolve VAT control if needed
  IF v_cn.vat_total > 0 THEN
    SELECT id INTO v_vat_account
    FROM bookkeeping_accounts
    WHERE organization_id = v_org
      AND is_active = true
      AND is_control_account = true
      AND account_subtype IN ('VAT_CONTROL','VAT')
      AND ((v_entity_type = 'client' AND client_id = v_entity_id)
        OR (v_entity_type = 'company' AND company_id = v_entity_id))
    LIMIT 1;
    IF v_vat_account IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error_message', 'VAT control account not configured');
    END IF;
  END IF;

  -- Build entries. SALES credit note REVERSES original sales:
  --   Dr Sales (net), Dr VAT, Cr Debtors (gross)
  -- PURCHASE credit note REVERSES original purchase:
  --   Cr Expense (net), Cr VAT, Dr Creditors (gross)
  FOR v_line IN
    SELECT account_id, net_amount, vat_amount
    FROM credit_note_lines
    WHERE credit_note_id = p_credit_note_id
  LOOP
    IF v_line.account_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error_message', 'Credit note line missing account');
    END IF;
    IF v_cn.credit_note_type = 'SALES' THEN
      v_entries := v_entries || jsonb_build_array(jsonb_build_object(
        'account_id', v_line.account_id,
        'debit', v_line.net_amount,
        'credit', NULL,
        'description', 'Sales credit',
        'vat_code_id', NULL
      ));
    ELSE
      v_entries := v_entries || jsonb_build_array(jsonb_build_object(
        'account_id', v_line.account_id,
        'debit', NULL,
        'credit', v_line.net_amount,
        'description', 'Purchase credit',
        'vat_code_id', NULL
      ));
    END IF;
  END LOOP;

  IF v_cn.vat_total > 0 THEN
    IF v_cn.credit_note_type = 'SALES' THEN
      v_entries := v_entries || jsonb_build_array(jsonb_build_object(
        'account_id', v_vat_account, 'debit', v_cn.vat_total, 'credit', NULL,
        'description', 'VAT on sales credit', 'vat_code_id', NULL));
    ELSE
      v_entries := v_entries || jsonb_build_array(jsonb_build_object(
        'account_id', v_vat_account, 'debit', NULL, 'credit', v_cn.vat_total,
        'description', 'VAT on purchase credit', 'vat_code_id', NULL));
    END IF;
  END IF;

  -- Control account leg
  IF v_cn.credit_note_type = 'SALES' THEN
    v_entries := v_entries || jsonb_build_array(jsonb_build_object(
      'account_id', v_control_account, 'debit', NULL, 'credit', v_cn.total,
      'description', 'Debtor reduction', 'vat_code_id', NULL));
  ELSE
    v_entries := v_entries || jsonb_build_array(jsonb_build_object(
      'account_id', v_control_account, 'debit', v_cn.total, 'credit', NULL,
      'description', 'Creditor reduction', 'vat_code_id', NULL));
  END IF;

  -- Post atomically
  v_post_result := public.post_to_ledger(
    p_organization_id := v_org,
    p_client_id       := CASE WHEN v_entity_type = 'client'  THEN v_entity_id ELSE NULL END,
    p_company_id      := CASE WHEN v_entity_type = 'company' THEN v_entity_id ELSE NULL END,
    p_journal_date    := v_cn.issue_date,
    p_reference       := COALESCE(v_cn.credit_note_number, 'CN-' || left(v_cn.id::text, 8)),
    p_description     := 'Credit Note ' || COALESCE(v_cn.credit_note_number, ''),
    p_journal_type    := 'SYSTEM',
    p_source_type     := 'CREDIT_NOTE',
    p_source_id       := v_cn.id,
    p_currency        := v_cn.currency,
    p_fx_rate         := COALESCE(v_cn.fx_rate, 1.0),
    p_created_by      := COALESCE(p_user_id, auth.uid()),
    p_entries         := v_entries
  );

  IF NOT COALESCE((v_post_result->>'success')::boolean, false) THEN
    RETURN jsonb_build_object('success', false,
      'error_message', COALESCE(v_post_result->>'error', 'Posting failed'));
  END IF;

  v_journal_id := (v_post_result->>'journal_id')::uuid;

  UPDATE credit_notes
  SET status = 'APPROVED',
      is_posted = true,
      posted_at = now(),
      posted_by = COALESCE(p_user_id, auth.uid()),
      journal_id = v_journal_id,
      remaining_allocation = total,
      updated_at = now(),
      updated_by = COALESCE(p_user_id, auth.uid())
  WHERE id = p_credit_note_id;

  RETURN jsonb_build_object('success', true, 'journal_id', v_journal_id);
END;
$$;


--
-- Name: approve_filing_safe(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_filing_safe(p_filing_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_filing record;
BEGIN
  -- Fetch filing
  SELECT * INTO v_filing FROM filings WHERE id = p_filing_id;

  IF v_filing.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Filing not found');
  END IF;

  -- Check permission
  IF NOT can_approve_filings(auth.uid(), v_filing.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: Only managers and above can approve filings');
  END IF;

  -- Update filing
  UPDATE filings SET 
    status = 'approved_by_client',
    approved_by = auth.uid(),
    approved_at = now()
  WHERE id = p_filing_id;

  -- Write audit log
  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, field_name, old_value, new_value, user_id)
  VALUES (v_filing.organization_id, 'filing', p_filing_id, 'approve', 'status', v_filing.status, 'approved_by_client', auth.uid());

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: approve_invoice(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_invoice(p_invoice_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice RECORD;
  v_entity_type text;
  v_entity_id uuid;
  v_debtors_id uuid;
  v_vat_id uuid;
  v_entries jsonb := '[]'::jsonb;
  v_line RECORD;
  v_post_result jsonb;
  v_uid uuid := COALESCE(p_user_id, auth.uid());
BEGIN
  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_found', 'error_message', 'Invoice not found');
  END IF;

  IF v_invoice.status <> 'DRAFT' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'invalid_status', 'error_message', 'Invoice is not in draft status');
  END IF;
  IF v_invoice.is_posted THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'already_posted', 'error_message', 'Invoice already posted');
  END IF;

  v_entity_type := CASE WHEN v_invoice.client_id IS NOT NULL THEN 'client' ELSE 'company' END;
  v_entity_id   := COALESCE(v_invoice.client_id, v_invoice.company_id);

  -- Resolve control accounts (structured taxonomy, not name matching)
  SELECT id INTO v_debtors_id FROM bookkeeping_accounts
   WHERE organization_id = v_invoice.organization_id
     AND ((v_entity_type='client'  AND client_id  = v_entity_id)
       OR (v_entity_type='company' AND company_id = v_entity_id))
     AND is_active = true AND is_control_account = true
     AND account_subtype IN ('TRADE_DEBTORS','DEBTOR','RECEIVABLE','ACCOUNTS_RECEIVABLE')
   LIMIT 1;
  IF v_debtors_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'missing_control_account', 'error_message', 'Trade Debtors control account not found');
  END IF;

  SELECT id INTO v_vat_id FROM bookkeeping_accounts
   WHERE organization_id = v_invoice.organization_id
     AND ((v_entity_type='client'  AND client_id  = v_entity_id)
       OR (v_entity_type='company' AND company_id = v_entity_id))
     AND is_active = true AND is_control_account = true
     AND account_subtype IN ('VAT_CONTROL','VAT')
   LIMIT 1;

  -- DR Trade Debtors (gross)
  v_entries := v_entries || jsonb_build_array(jsonb_build_object(
    'account_id', v_debtors_id,
    'debit', v_invoice.total_gross,
    'credit', NULL,
    'description', 'Sales Invoice ' || COALESCE(v_invoice.invoice_number, substr(p_invoice_id::text,1,8)) || ': ' || COALESCE(v_invoice.contact_name,'')
  ));

  -- CR Sales accounts per line (net)
  FOR v_line IN SELECT * FROM invoice_lines WHERE invoice_id = p_invoice_id ORDER BY line_number LOOP
    v_entries := v_entries || jsonb_build_array(jsonb_build_object(
      'account_id', v_line.account_id,
      'debit', NULL,
      'credit', v_line.net_amount,
      'description', COALESCE(v_invoice.invoice_number,'') || ': ' || v_line.description,
      'vat_code_id', v_line.vat_code_id
    ));
  END LOOP;

  -- CR VAT Control (total VAT)
  IF v_invoice.total_vat > 0 AND v_vat_id IS NOT NULL THEN
    v_entries := v_entries || jsonb_build_array(jsonb_build_object(
      'account_id', v_vat_id,
      'debit', NULL,
      'credit', v_invoice.total_vat,
      'description', 'VAT on Invoice ' || COALESCE(v_invoice.invoice_number, substr(p_invoice_id::text,1,8))
    ));
  END IF;

  v_post_result := post_to_ledger(
    p_organization_id := v_invoice.organization_id,
    p_client_id       := CASE WHEN v_entity_type='client'  THEN v_entity_id ELSE NULL END,
    p_company_id      := CASE WHEN v_entity_type='company' THEN v_entity_id ELSE NULL END,
    p_journal_date    := v_invoice.issue_date,
    p_reference       := v_invoice.invoice_number,
    p_description     := 'INVOICE posting',
    p_journal_type    := 'SYSTEM',
    p_source_type     := 'INVOICE',
    p_source_id       := p_invoice_id,
    p_currency        := COALESCE(v_invoice.currency,'GBP'),
    p_fx_rate         := COALESCE(v_invoice.exchange_rate,1.0),
    p_created_by      := v_uid,
    p_entries         := v_entries
  );

  IF NOT (v_post_result->>'success')::boolean THEN
    RAISE EXCEPTION 'Posting failed: %', v_post_result->>'error_message'
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE invoices
     SET status = 'AWAITING_PAYMENT',
         is_posted = true,
         posted_at = now(),
         posted_by = v_uid,
         updated_at = now()
   WHERE id = p_invoice_id;

  RETURN jsonb_build_object('success', true, 'journal_id', v_post_result->>'journal_id');
END;
$$;


--
-- Name: approve_onboarding_transactional(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_onboarding_transactional(p_application_id uuid, p_actor uuid DEFAULT auth.uid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_app record;
  v_core jsonb;
  v_company_id uuid;
  v_client_id uuid;
  v_snapshot_exists boolean;
  v_company_name text;
  v_existing_utr text;
  v_existing_vat text;
  v_paye text;
  v_person jsonb;
  v_target_id uuid;
  v_action text;
  v_name text;
  v_first text;
  v_last text;
  v_existing_dob date;
  v_existing_nino text;
  v_existing_person_utr text;
  v_existing_home text;
  v_idx int := 0;
  v_persons_merged int := 0;
  v_persons_created int := 0;
  v_persons_skipped int := 0;
  v_fields_recorded int := 0;
  v_resolved jsonb := '[]'::jsonb;
  v_masked_persons jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id;
  IF v_app.id IS NULL THEN
    RAISE EXCEPTION 'onboarding application not found';
  END IF;

  IF NOT user_has_organization_access(v_app.organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.onboarding_approval_snapshots WHERE application_id = p_application_id
  ) INTO v_snapshot_exists;

  IF v_app.status = 'approved' AND v_snapshot_exists THEN
    RETURN jsonb_build_object(
      'idempotent', true,
      'application_id', p_application_id,
      'status', 'approved'
    );
  END IF;

  BEGIN
    SELECT public.lifecycle_approve_onboarding(p_application_id) INTO v_core;

    v_company_id := coalesce(v_app.company_id, (v_core->>'company_id')::uuid);
    v_client_id  := coalesce(v_app.client_id,  (v_core->>'client_id')::uuid);

    IF v_company_id IS NOT NULL THEN
      SELECT company_name, utr, vat_number
        INTO v_company_name, v_existing_utr, v_existing_vat
        FROM public.companies WHERE id = v_company_id;

      IF nullif(v_app.utr, '') IS NOT NULL AND (v_existing_utr IS NULL OR v_existing_utr = '') THEN
        UPDATE public.companies SET utr = v_app.utr WHERE id = v_company_id;
        PERFORM public.governance_record_merge_field(
          v_app.organization_id, 'company', v_company_id, 'company.utr',
          v_existing_utr, v_app.utr, p_actor);
        v_fields_recorded := v_fields_recorded + 1;
      END IF;

      IF nullif(v_app.vat_number, '') IS NOT NULL AND (v_existing_vat IS NULL OR v_existing_vat = '') THEN
        UPDATE public.companies SET vat_number = v_app.vat_number WHERE id = v_company_id;
        PERFORM public.governance_record_merge_field(
          v_app.organization_id, 'company', v_company_id, 'company.vat_number',
          v_existing_vat, v_app.vat_number, p_actor);
        v_fields_recorded := v_fields_recorded + 1;
      END IF;

      v_paye := nullif(v_app.paye_reference, '');
      IF v_paye IS NOT NULL THEN
        IF NOT EXISTS (
          SELECT 1 FROM public.paye_schemes
          WHERE company_id = v_company_id AND employer_paye_reference = v_paye
        ) THEN
          INSERT INTO public.paye_schemes (
            organization_id, company_id, employer_paye_reference, name
          )
          VALUES (
            v_app.organization_id, v_company_id, v_paye,
            coalesce(v_company_name, 'PAYE Scheme')
          );
          PERFORM public.governance_record_merge_field(
            v_app.organization_id, 'company', v_company_id, 'company.paye_reference',
            NULL, v_paye, p_actor);
          v_fields_recorded := v_fields_recorded + 1;
        END IF;
      END IF;
    END IF;

    FOR v_person IN
      SELECT value FROM jsonb_array_elements(coalesce(v_app.personal_details, '[]'::jsonb))
    LOOP
      v_target_id := NULL;
      v_action := NULL;

      IF nullif(v_person->>'person_id', '') IS NOT NULL THEN
        SELECT id INTO v_target_id FROM public.company_persons
          WHERE id = (v_person->>'person_id')::uuid
            AND organization_id = v_app.organization_id;
        IF v_target_id IS NOT NULL THEN v_action := 'merged'; END IF;
      ELSIF nullif(v_person->>'ch_officer_id', '') IS NOT NULL THEN
        SELECT id INTO v_target_id FROM public.company_persons
          WHERE organization_id = v_app.organization_id
            AND ch_officer_id = v_person->>'ch_officer_id'
          LIMIT 1;
        IF v_target_id IS NOT NULL THEN v_action := 'merged'; END IF;
      END IF;

      IF v_target_id IS NULL THEN
        v_name := regexp_replace(trim(coalesce(v_person->>'name', '')), '\s+', ' ', 'g');

        IF v_name = ''
           AND nullif(v_person->>'person_id', '') IS NULL
           AND nullif(v_person->>'ch_officer_id', '') IS NULL THEN
          v_persons_skipped := v_persons_skipped + 1;
          v_idx := v_idx + 1;
          CONTINUE;
        END IF;

        v_first := split_part(v_name, ' ', 1);
        IF position(' ' in v_name) = 0 THEN
          v_last := v_first;
        ELSE
          v_last := trim(substr(v_name, position(' ' in v_name) + 1));
        END IF;
        IF v_last IS NULL OR v_last = '' THEN v_last := v_first; END IF;

        INSERT INTO public.company_persons (organization_id, first_name, last_name)
        VALUES (v_app.organization_id, v_first, v_last)
        RETURNING id INTO v_target_id;
        v_action := 'created';
        v_persons_created := v_persons_created + 1;
      ELSE
        v_persons_merged := v_persons_merged + 1;
      END IF;

      SELECT date_of_birth, nino, utr, residential_address_line_1
        INTO v_existing_dob, v_existing_nino, v_existing_person_utr, v_existing_home
        FROM public.company_persons WHERE id = v_target_id;

      IF nullif(v_person->>'date_of_birth', '') IS NOT NULL AND v_existing_dob IS NULL THEN
        UPDATE public.company_persons
          SET date_of_birth = (v_person->>'date_of_birth')::date
          WHERE id = v_target_id;
        PERFORM public.governance_record_merge_field(
          v_app.organization_id, 'person', v_target_id, 'person.date_of_birth',
          NULL, v_person->>'date_of_birth', p_actor);
        v_fields_recorded := v_fields_recorded + 1;
      END IF;

      IF nullif(v_person->>'nino', '') IS NOT NULL AND (v_existing_nino IS NULL OR v_existing_nino = '') THEN
        UPDATE public.company_persons SET nino = v_person->>'nino' WHERE id = v_target_id;
        PERFORM public.governance_record_merge_field(
          v_app.organization_id, 'person', v_target_id, 'person.nino',
          v_existing_nino, v_person->>'nino', p_actor);
        v_fields_recorded := v_fields_recorded + 1;
      END IF;

      IF nullif(v_person->>'utr', '') IS NOT NULL AND (v_existing_person_utr IS NULL OR v_existing_person_utr = '') THEN
        UPDATE public.company_persons SET utr = v_person->>'utr' WHERE id = v_target_id;
        PERFORM public.governance_record_merge_field(
          v_app.organization_id, 'person', v_target_id, 'person.utr',
          v_existing_person_utr, v_person->>'utr', p_actor);
        v_fields_recorded := v_fields_recorded + 1;
      END IF;

      IF nullif(v_person->>'home_address', '') IS NOT NULL AND (v_existing_home IS NULL OR v_existing_home = '') THEN
        UPDATE public.company_persons
          SET residential_address_line_1 = v_person->>'home_address'
          WHERE id = v_target_id;
        PERFORM public.governance_record_merge_field(
          v_app.organization_id, 'person', v_target_id, 'person.home_address',
          v_existing_home, v_person->>'home_address', p_actor);
        v_fields_recorded := v_fields_recorded + 1;
      END IF;

      v_resolved := v_resolved || jsonb_build_object(
        'index', v_idx, 'person_id', v_target_id, 'action', v_action);

      v_masked_persons := v_masked_persons || jsonb_build_object(
        'name', v_person->>'name',
        'role', v_person->>'role',
        'date_of_birth', public.governance_mask_value('person.date_of_birth', v_person->>'date_of_birth'),
        'nino', public.governance_mask_value('person.nino', v_person->>'nino'),
        'utr', public.governance_mask_value('person.utr', v_person->>'utr'),
        'home_address', public.governance_mask_value('person.home_address', v_person->>'home_address'),
        'person_id', v_person->>'person_id',
        'ch_officer_id', v_person->>'ch_officer_id'
      );

      v_idx := v_idx + 1;
    END LOOP;

    INSERT INTO public.onboarding_approval_snapshots (
      organization_id, application_id, created_by, snapshot
    )
    VALUES (
      v_app.organization_id, p_application_id, p_actor,
      jsonb_build_object(
        'provisional', jsonb_build_object(
          'application_id', p_application_id,
          'organization_id', v_app.organization_id,
          'client_id', v_client_id,
          'company_id', v_company_id,
          'lead_id', v_app.lead_id,
          'paye_reference', v_app.paye_reference,
          'vat_number', v_app.vat_number,
          'utr', v_app.utr,
          'ch_correction_note', v_app.ch_correction_note,
          'personal_details', v_masked_persons
        ),
        'resolved_persons', v_resolved,
        'approved_at', now(),
        'actor', p_actor
      )
    );

    UPDATE public.onboarding_applications
      SET approval_blocked_at = NULL, approval_blocked_reason = NULL
      WHERE id = p_application_id;

    RETURN v_core || jsonb_build_object(
      'governance', jsonb_build_object(
        'persons_merged', v_persons_merged,
        'persons_created', v_persons_created,
        'persons_skipped', v_persons_skipped,
        'fields_recorded', v_fields_recorded
      ),
      'snapshot_written', true
    );

  EXCEPTION WHEN OTHERS THEN
    UPDATE public.onboarding_applications
      SET approval_blocked_at = now(),
          approval_blocked_reason = left(SQLERRM, 500)
      WHERE id = p_application_id;
    RETURN jsonb_build_object(
      'approved', false,
      'blocked', true,
      'reason', left(SQLERRM, 500),
      'application_id', p_application_id
    );
  END;
END;
$$;


--
-- Name: approve_vat_return_for_filing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_vat_return_for_filing(_vat_return_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.vat_returns%ROWTYPE;
  v_uid uuid := auth.uid();
  v_snapshot_id uuid := gen_random_uuid();
  v_hash text;
  v_payload jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Access denied: not authenticated';
  END IF;

  SELECT * INTO v_row FROM public.vat_returns WHERE id = _vat_return_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'VAT return not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = v_row.organization_id AND user_id = v_uid
  ) THEN
    RAISE EXCEPTION 'Access denied: not a member of this organization';
  END IF;

  IF v_row.submitted_at IS NOT NULL THEN
    RAISE EXCEPTION 'VAT return already submitted';
  END IF;

  IF v_row.filing_approved_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'already_approved', true,
      'model_snapshot_id', v_row.model_snapshot_id,
      'model_snapshot_hash', v_row.model_snapshot_hash,
      'filing_approved_at', v_row.filing_approved_at
    );
  END IF;

  v_payload := jsonb_build_object(
    'vat_return_id', v_row.id,
    'organization_id', v_row.organization_id,
    'client_id', v_row.client_id,
    'company_id', v_row.company_id,
    'period_start', v_row.period_start,
    'period_end', v_row.period_end,
    'box_1_vat_due_sales', v_row.box_1_vat_due_sales,
    'box_2_vat_due_acquisitions', v_row.box_2_vat_due_acquisitions,
    'box_3_total_vat_due', v_row.box_3_total_vat_due,
    'box_4_vat_reclaimed', v_row.box_4_vat_reclaimed,
    'box_5_net_vat', v_row.box_5_net_vat,
    'box_6_total_sales', v_row.box_6_total_sales,
    'box_7_total_purchases', v_row.box_7_total_purchases,
    'box_8_total_supplies_eu', v_row.box_8_total_supplies_eu,
    'box_9_total_acquisitions_eu', v_row.box_9_total_acquisitions_eu
  );

  v_hash := encode(digest(v_payload::text, 'sha256'), 'hex');

  UPDATE public.vat_returns
     SET filing_approved_at = now(),
         filing_approved_by = v_uid,
         model_snapshot_id = v_snapshot_id,
         model_snapshot_hash = v_hash,
         updated_at = now()
   WHERE id = _vat_return_id;

  RETURN jsonb_build_object(
    'ok', true,
    'model_snapshot_id', v_snapshot_id,
    'model_snapshot_hash', v_hash,
    'filing_approved_at', now()
  );
END;
$$;


