--
-- Name: bank_rule_safety_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_rule_safety_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_action jsonb;
  v_has_vat boolean := false;
BEGIN
  -- Detect VAT sensitivity from actions
  IF NEW.actions IS NOT NULL THEN
    FOR v_action IN SELECT * FROM jsonb_array_elements(COALESCE(NEW.actions,'[]'::jsonb)) LOOP
      IF v_action->>'type' = 'set_vat_code' AND COALESCE(v_action->>'value','') <> '' THEN
        v_has_vat := true;
      END IF;
    END LOOP;
  END IF;
  NEW.vat_sensitive := v_has_vat;

  -- Portal-created rules can never auto-post and always require review
  IF NEW.source = 'portal' THEN
    NEW.auto_post := false;
    NEW.requires_review := true;
  END IF;

  -- VAT-sensitive rules default to requires_review unless caller explicitly
  -- set auto_post = true (accountant-confirmed automation).
  IF v_has_vat AND TG_OP = 'INSERT' AND NEW.auto_post IS NOT TRUE THEN
    NEW.requires_review := true;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: block_portal_vat_submit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_portal_vat_submit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF public.is_portal_user() THEN
    IF NEW.submitted_at IS DISTINCT FROM OLD.submitted_at
       OR NEW.submitted_by IS DISTINCT FROM OLD.submitted_by
       OR NEW.hmrc_receipt IS DISTINCT FROM OLD.hmrc_receipt
       OR (NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('submitted','accepted','filed')) THEN
      RAISE EXCEPTION 'Portal users cannot submit VAT returns' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END $$;


