--
-- Name: bookkeeping_accounts_protect_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bookkeeping_accounts_protect_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF COALESCE(OLD.is_system_account, false) THEN
    RAISE EXCEPTION 'Cannot delete system account %', OLD.code USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM ledger_entries WHERE account_id = OLD.id LIMIT 1) THEN
    RAISE EXCEPTION 'Account % is referenced by ledger_entries', OLD.code USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM journal_lines WHERE account_id = OLD.id LIMIT 1) THEN
    RAISE EXCEPTION 'Account % is referenced by journal_lines', OLD.code USING ERRCODE = 'check_violation';
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: bulk_apply_active_bank_rules(uuid, uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_apply_active_bank_rules(p_organization_id uuid, p_client_id uuid DEFAULT NULL::uuid, p_company_id uuid DEFAULT NULL::uuid, p_bank_account_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_is_member boolean;
  v_txn record;
  v_rule record;
  v_applied int := 0;
  v_skipped int := 0;
  v_failed int := 0;
  v_result jsonb;
  v_matches boolean;
BEGIN
  IF p_client_id IS NULL AND p_company_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'missing_entity',
                              'error_message', 'Either client_id or company_id is required');
  END IF;

  SELECT user_in_organization(v_actor, p_organization_id) INTO v_is_member;
  IF NOT COALESCE(v_is_member, false) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'forbidden',
                              'error_message', 'Not a member of this organisation');
  END IF;

  FOR v_txn IN
    SELECT * FROM bank_transactions
     WHERE organization_id = p_organization_id
       AND (p_client_id IS NULL OR client_id = p_client_id)
       AND (p_company_id IS NULL OR company_id = p_company_id)
       AND (p_bank_account_id IS NULL OR bank_account_id = p_bank_account_id)
       AND upper(COALESCE(status,'')) = 'UNREVIEWED'
     ORDER BY transaction_date ASC
     LIMIT p_limit
  LOOP
    FOR v_rule IN
      SELECT * FROM bank_rules
       WHERE organization_id = p_organization_id
         AND is_active = true
         AND (client_id IS NULL OR client_id = v_txn.client_id)
         AND (company_id IS NULL OR company_id = v_txn.company_id)
         AND (bank_account_id IS NULL OR bank_account_id = v_txn.bank_account_id)
       ORDER BY priority ASC, created_at ASC
    LOOP
      -- Delegate conditions check to apply_bank_rule (it validates scope);
      -- here we just attempt application and accept first success.
      v_result := apply_bank_rule(v_txn.id, v_rule.id);
      IF (v_result->>'success')::boolean IS TRUE THEN
        v_applied := v_applied + 1;
        EXIT;
      ELSIF v_result->>'error_code' IN ('already_categorized','period_locked') THEN
        v_skipped := v_skipped + 1;
        EXIT;
      ELSE
        -- Try next rule for non-fatal mismatch errors
        IF v_result->>'error_code' NOT IN ('scope_mismatch','bank_account_mismatch','rule_inactive') THEN
          v_failed := v_failed + 1;
          EXIT;
        END IF;
      END IF;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('success', true,
                            'applied', v_applied,
                            'skipped', v_skipped,
                            'failed', v_failed);
END;
$$;


--
-- Name: calculate_cash_vat_proportion(numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_cash_vat_proportion(p_net_amount numeric, p_vat_amount numeric, p_paid_amount numeric, p_gross_amount numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE 
    WHEN p_gross_amount = 0 THEN 0
    ELSE (p_paid_amount / p_gross_amount) * p_vat_amount
  END;
$$;


--
-- Name: calculate_deadline(text, date, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_deadline(filing_type text, period_start date, period_end date, metadata jsonb DEFAULT '{}'::jsonb) RETURNS date
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
-- System A (calculate_deadline) is THE active deadline engine; System B
-- (lifecycle_generate_deadlines_for_job + canonical_deadline_rules) is dormant/reference —
-- do not route jobs into B without the dedicated engine-consolidation effort.
DECLARE
  result_date DATE;
  ard DATE;
  made_up_date DATE;
  quarter_end DATE;
BEGIN
  CASE filing_type
    WHEN 'companies_house_accounts' THEN
      ard := (metadata->>'accounting_reference_date')::DATE;
      IF ard IS NULL THEN
        ard := period_end;
      END IF;
      result_date := ard + INTERVAL '9 months';

    WHEN 'companies_house_confirmation' THEN
      made_up_date := (metadata->>'made_up_date')::DATE;
      IF made_up_date IS NULL THEN
        made_up_date := period_end;
      END IF;
      result_date := made_up_date + INTERVAL '12 months';

    WHEN 'corporation_tax_filing' THEN
      ard := (metadata->>'accounting_reference_date')::DATE;
      IF ard IS NULL THEN
        ard := period_end;
      END IF;
      result_date := ard + INTERVAL '12 months';

    WHEN 'corporation_tax_payment' THEN
      ard := (metadata->>'accounting_reference_date')::DATE;
      IF ard IS NULL THEN
        ard := period_end;
      END IF;
      result_date := ard + INTERVAL '9 months' + INTERVAL '1 day';

    WHEN 'self_assessment' THEN
      result_date := DATE_TRUNC('year', period_end)::DATE + INTERVAL '1 year' + INTERVAL '1 month' - INTERVAL '1 day';
      IF EXTRACT(MONTH FROM period_end) < 4 THEN
        result_date := result_date - INTERVAL '1 year';
      END IF;

    WHEN 'mtd_quarter' THEN
      -- MTD-ITSA quarterly update: fixed statutory date = the 7th of the month AFTER the
      -- standard 5th-ending quarter-end (5 Jul→7 Aug, 5 Oct→7 Nov, 5 Jan→7 Feb, 5 Apr→7 May).
      -- Standard 5th-ending quarters only; the calendar-quarter election is out of scope for v1.
      result_date := (DATE_TRUNC('month', period_end) + INTERVAL '1 month' + INTERVAL '6 days')::DATE;

    WHEN 'mtd_itsa_final' THEN
      -- MTD-ITSA final declaration: 31 January following the tax year (mirrors self_assessment;
      -- a tax year ending 5 Apr 2026 → 31 Jan 2027).
      result_date := make_date(EXTRACT(YEAR FROM period_end)::int + 1, 1, 31);

    WHEN 'vat_return' THEN
      quarter_end := period_end;
      result_date := quarter_end + INTERVAL '1 month' + INTERVAL '7 days';

    WHEN 'payroll_fps' THEN
      result_date := period_end;

    WHEN 'payroll_eps' THEN
      result_date := DATE_TRUNC('month', period_end)::DATE + INTERVAL '1 month' + INTERVAL '18 days';

    ELSE
      result_date := period_end + INTERVAL '1 month';
  END CASE;

  RETURN result_date;
END;
$$;


