--
-- Name: generate_recurring_invoice(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_recurring_invoice(p_schedule_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sched RECORD;
  v_uid uuid := COALESCE(p_user_id, auth.uid());
  v_invoice_id uuid := gen_random_uuid();
  v_client RECORD;
  v_account_id uuid;
  v_vat_rate numeric := 0;
  v_vat_code_id uuid := NULL;
  v_net numeric;
  v_vat numeric;
  v_gross numeric;
  v_issue_date date := CURRENT_DATE;
  v_due_date date;
  v_next_run timestamptz;
  v_approve_result jsonb := NULL;
BEGIN
  SELECT * INTO v_sched FROM recurring_invoice_schedules
   WHERE id = p_schedule_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code','not_found','error_message','Schedule not found');
  END IF;
  IF v_sched.status <> 'active' THEN
    RETURN jsonb_build_object('success', false, 'error_code','inactive','error_message','Schedule not active');
  END IF;
  IF v_sched.end_date IS NOT NULL AND v_issue_date > v_sched.end_date THEN
    UPDATE recurring_invoice_schedules SET status='completed', updated_at=now() WHERE id = p_schedule_id;
    RETURN jsonb_build_object('success', false, 'error_code','ended','error_message','Schedule end date reached');
  END IF;

  SELECT * INTO v_client FROM clients WHERE id = v_sched.client_id;
  IF v_client IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code','missing_client','error_message','Client not found');
  END IF;

  -- Resolve a default revenue account: prefer metadata.account_id, else first SALES account
  v_account_id := NULLIF(v_sched.metadata->>'account_id','')::uuid;
  IF v_account_id IS NULL THEN
    SELECT id INTO v_account_id FROM bookkeeping_accounts
     WHERE organization_id = v_sched.organization_id
       AND client_id = v_sched.client_id
       AND is_active = true
       AND account_subtype IN ('SALES','REVENUE','SERVICE_REVENUE','TRADING_INCOME')
     ORDER BY created_at ASC LIMIT 1;
  END IF;
  IF v_account_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code','missing_revenue_account',
                              'error_message','No revenue account configured for this client');
  END IF;

  -- Optional VAT code from metadata
  v_vat_code_id := NULLIF(v_sched.metadata->>'vat_code_id','')::uuid;
  IF v_vat_code_id IS NOT NULL THEN
    SELECT rate INTO v_vat_rate FROM vat_codes WHERE id = v_vat_code_id;
    v_vat_rate := COALESCE(v_vat_rate, 0);
  END IF;

  v_net   := COALESCE(v_sched.amount, 0);
  v_vat   := ROUND(v_net * v_vat_rate / 100.0, 2);
  v_gross := v_net + v_vat;
  v_due_date := v_issue_date + (COALESCE(v_sched.payment_terms_days, 30) || ' days')::interval;

  INSERT INTO invoices (
    id, organization_id, client_id, customer_id, invoice_type, contact_name,
    invoice_number, reference, issue_date, due_date, currency, exchange_rate,
    status, is_posted, total_net, total_vat, total_gross, remaining_balance, amount_paid,
    notes
  ) VALUES (
    v_invoice_id, v_sched.organization_id, v_sched.client_id, NULL, 'SALES',
    COALESCE(v_client.company_name, v_client.first_name || ' ' || v_client.last_name, 'Customer'),
    NULL, 'REC-' || substr(p_schedule_id::text,1,8) || '-' || to_char(v_issue_date,'YYYYMMDD'),
    v_issue_date, v_due_date, v_sched.currency, 1.0,
    'DRAFT', false, v_net, v_vat, v_gross, v_gross, 0,
    'Auto-generated from recurring schedule ' || p_schedule_id::text
  );

  INSERT INTO invoice_lines (
    invoice_id, line_number, description, quantity, unit_price,
    account_id, vat_code_id, vat_rate, net_amount, vat_amount, gross_amount
  ) VALUES (
    v_invoice_id, 1,
    COALESCE(v_sched.metadata->>'description', 'Recurring services'),
    1, v_net, v_account_id, v_vat_code_id, v_vat_rate, v_net, v_vat, v_gross
  );

  -- Advance next_run_at by cadence
  v_next_run := CASE v_sched.cadence
    WHEN 'weekly'       THEN COALESCE(v_sched.next_run_at, now()) + interval '7 days'
    WHEN 'fortnightly'  THEN COALESCE(v_sched.next_run_at, now()) + interval '14 days'
    WHEN 'monthly'      THEN COALESCE(v_sched.next_run_at, now()) + interval '1 month'
    WHEN 'quarterly'    THEN COALESCE(v_sched.next_run_at, now()) + interval '3 months'
    WHEN 'semi_annual'  THEN COALESCE(v_sched.next_run_at, now()) + interval '6 months'
    WHEN 'annual'       THEN COALESCE(v_sched.next_run_at, now()) + interval '1 year'
    ELSE COALESCE(v_sched.next_run_at, now()) + interval '1 month'
  END;

  UPDATE recurring_invoice_schedules SET
    last_run_at = now(),
    last_invoice_id = v_invoice_id,
    next_run_at = v_next_run,
    failure_count = 0,
    status = CASE WHEN v_sched.end_date IS NOT NULL AND v_next_run::date > v_sched.end_date
                  THEN 'completed' ELSE status END,
    updated_at = now()
   WHERE id = p_schedule_id;

  -- Optional auto-post when configured
  IF v_sched.create_draft_only = false THEN
    v_approve_result := public.approve_invoice(v_invoice_id, v_uid);
    IF NOT COALESCE((v_approve_result->>'success')::boolean, false) THEN
      -- Roll back schedule advancement on post failure
      UPDATE recurring_invoice_schedules SET
        failure_count = COALESCE(failure_count,0) + 1,
        status = CASE WHEN COALESCE(failure_count,0) + 1 >= 3 THEN 'failed' ELSE status END,
        updated_at = now()
       WHERE id = p_schedule_id;
      RETURN jsonb_build_object('success', false, 'error_code','post_failed',
                                'error_message', v_approve_result->>'error_message',
                                'invoice_id', v_invoice_id);
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'invoice_id', v_invoice_id,
    'auto_posted', v_sched.create_draft_only = false,
    'next_run_at', v_next_run
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error_code','exception','error_message', SQLERRM);
END $$;


--
-- Name: generate_vat_periods(text, integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_vat_periods(p_frequency text, p_stagger integer, p_from date, p_to date) RETURNS TABLE(period_start date, period_end date, period_label text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_freq       text := lower(trim(p_frequency));
  v_ms         date;
  v_pe         date;
  v_ps         date;
  v_target_mod integer;
  v_year       integer;
BEGIN
  IF v_freq = 'annual_accounting' THEN
    v_freq := 'annual';
  END IF;

  IF v_freq NOT IN ('monthly', 'quarterly', 'annual') THEN
    RAISE EXCEPTION 'generate_vat_periods: unknown p_frequency %, expected monthly|quarterly|annual(_accounting)', p_frequency;
  END IF;

  IF p_from IS NULL OR p_to IS NULL OR p_from > p_to THEN
    RETURN;
  END IF;

  IF v_freq = 'monthly' THEN
    v_ms := date_trunc('month', p_from)::date;
    WHILE v_ms <= p_to LOOP
      v_ps := v_ms;
      v_pe := (v_ms + INTERVAL '1 month' - INTERVAL '1 day')::date;
      IF v_pe >= p_from AND v_pe <= p_to THEN
        period_start := v_ps;
        period_end   := v_pe;
        period_label := 'VAT M/E ' || to_char(v_pe, 'DD Mon YYYY');
        RETURN NEXT;
      END IF;
      v_ms := (v_ms + INTERVAL '1 month')::date;
    END LOOP;

  ELSIF v_freq = 'quarterly' THEN
    IF p_stagger IS NULL OR p_stagger NOT IN (1, 2, 3) THEN
      RAISE EXCEPTION 'generate_vat_periods: quarterly requires p_stagger in (1,2,3), got %', p_stagger;
    END IF;
    v_target_mod := (p_stagger + 2) % 3;
    v_ms := date_trunc('month', p_from)::date;
    WHILE v_ms <= p_to LOOP
      IF (EXTRACT(MONTH FROM v_ms)::integer % 3) = v_target_mod THEN
        v_pe := (v_ms + INTERVAL '1 month' - INTERVAL '1 day')::date;
        v_ps := (v_ms - INTERVAL '2 months')::date;
        IF v_pe >= p_from AND v_pe <= p_to THEN
          period_start := v_ps;
          period_end   := v_pe;
          period_label := 'VAT Q/E ' || to_char(v_pe, 'DD Mon YYYY');
          RETURN NEXT;
        END IF;
      END IF;
      v_ms := (v_ms + INTERVAL '1 month')::date;
    END LOOP;

  ELSE
    IF p_stagger IS NULL OR p_stagger < 1 OR p_stagger > 12 THEN
      RAISE EXCEPTION 'generate_vat_periods: annual requires p_stagger as an end-month 1..12, got %', p_stagger;
    END IF;
    FOR v_year IN (EXTRACT(YEAR FROM p_from)::integer - 1) .. (EXTRACT(YEAR FROM p_to)::integer + 1) LOOP
      v_pe := (make_date(v_year, p_stagger, 1) + INTERVAL '1 month' - INTERVAL '1 day')::date;
      IF v_pe >= p_from AND v_pe <= p_to THEN
        v_ps := ((v_pe + INTERVAL '1 day') - INTERVAL '1 year')::date;
        period_start := v_ps;
        period_end   := v_pe;
        period_label := 'VAT Y/E ' || to_char(v_pe, 'DD Mon YYYY');
        RETURN NEXT;
      END IF;
    END LOOP;
  END IF;

  RETURN;
END;
$$;


--
-- Name: vat_registrations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vat_registrations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    company_id uuid,
    client_id uuid,
    vrn text NOT NULL,
    scheme text DEFAULT 'STANDARD'::text NOT NULL,
    flat_rate_percentage numeric(5,2),
    flat_rate_trade_sector text,
    flat_rate_first_year_discount boolean DEFAULT false,
    cash_scheme_joined_at date,
    cash_scheme_threshold numeric(15,2) DEFAULT 1350000,
    annual_accounting_joined_at date,
    annual_accounting_payment_schedule text,
    partial_exemption_applicable boolean DEFAULT false,
    partial_exemption_rate numeric(5,4),
    partial_exemption_method text DEFAULT 'STANDARD'::text,
    effective_from date NOT NULL,
    effective_to date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    notes text,
    CONSTRAINT vat_registrations_annual_accounting_payment_schedule_check CHECK ((annual_accounting_payment_schedule = ANY (ARRAY['MONTHLY'::text, 'QUARTERLY'::text]))),
    CONSTRAINT vat_registrations_entity_check CHECK ((((company_id IS NOT NULL) AND (client_id IS NULL)) OR ((company_id IS NULL) AND (client_id IS NOT NULL)))),
    CONSTRAINT vat_registrations_partial_exemption_method_check CHECK ((partial_exemption_method = ANY (ARRAY['STANDARD'::text, 'SPECIAL'::text]))),
    CONSTRAINT vat_registrations_scheme_check CHECK ((scheme = ANY (ARRAY['STANDARD'::text, 'CASH_ACCOUNTING'::text, 'FLAT_RATE'::text, 'ANNUAL_ACCOUNTING'::text])))
);


--
-- Name: get_active_vat_registration(uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_vat_registration(p_entity_id uuid, p_entity_type text, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS public.vat_registrations
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT *
  FROM public.vat_registrations
  WHERE (
    (p_entity_type = 'company' AND company_id = p_entity_id) OR
    (p_entity_type = 'client' AND client_id = p_entity_id)
  )
  AND effective_from <= p_as_of_date
  AND (effective_to IS NULL OR effective_to >= p_as_of_date)
  ORDER BY effective_from DESC
  LIMIT 1;
$$;


--
-- Name: get_aged_creditors(uuid, uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_aged_creditors(p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_as_at date) RETURNS TABLE(supplier_id uuid, supplier_name text, current_amount numeric, bucket_1_30 numeric, bucket_31_60 numeric, bucket_61_90 numeric, bucket_90_plus numeric, total_outstanding numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM organization_users
    WHERE organization_id = p_organization_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not authorized for organization';
  END IF;

  IF (p_client_id IS NULL) = (p_company_id IS NULL) THEN
    RAISE EXCEPTION 'Exactly one of client_id or company_id required';
  END IF;

  RETURN QUERY
  WITH open_bill AS (
    SELECT
      b.supplier_id,
      COALESCE(b.remaining_balance, b.total_gross - COALESCE(b.amount_paid,0)) AS outstanding,
      (p_as_at - b.due_date) AS days_overdue
    FROM bills b
    WHERE b.organization_id = p_organization_id
      AND ((p_client_id IS NOT NULL AND b.client_id = p_client_id)
        OR (p_company_id IS NOT NULL AND b.company_id = p_company_id))
      AND b.issue_date <= p_as_at
      AND COALESCE(b.status, '') NOT IN ('void','draft','cancelled')
      AND COALESCE(b.remaining_balance, b.total_gross - COALESCE(b.amount_paid,0)) > 0.005
      AND b.supplier_id IS NOT NULL
  )
  SELECT
    o.supplier_id,
    s.name AS supplier_name,
    SUM(CASE WHEN o.days_overdue <= 0 THEN o.outstanding ELSE 0 END)::numeric AS current_amount,
    SUM(CASE WHEN o.days_overdue BETWEEN 1 AND 30 THEN o.outstanding ELSE 0 END)::numeric AS bucket_1_30,
    SUM(CASE WHEN o.days_overdue BETWEEN 31 AND 60 THEN o.outstanding ELSE 0 END)::numeric AS bucket_31_60,
    SUM(CASE WHEN o.days_overdue BETWEEN 61 AND 90 THEN o.outstanding ELSE 0 END)::numeric AS bucket_61_90,
    SUM(CASE WHEN o.days_overdue > 90 THEN o.outstanding ELSE 0 END)::numeric AS bucket_90_plus,
    SUM(o.outstanding)::numeric AS total_outstanding
  FROM open_bill o
  JOIN suppliers s ON s.id = o.supplier_id
  GROUP BY o.supplier_id, s.name
  ORDER BY s.name;
END;
$$;


--
-- Name: get_aged_debtors(uuid, uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_aged_debtors(p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_as_at date) RETURNS TABLE(customer_id uuid, customer_name text, current_amount numeric, bucket_1_30 numeric, bucket_31_60 numeric, bucket_61_90 numeric, bucket_90_plus numeric, total_outstanding numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM organization_users
    WHERE organization_id = p_organization_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not authorized for organization';
  END IF;

  IF (p_client_id IS NULL) = (p_company_id IS NULL) THEN
    RAISE EXCEPTION 'Exactly one of client_id or company_id required';
  END IF;

  RETURN QUERY
  WITH open_inv AS (
    SELECT
      i.customer_id,
      COALESCE(i.remaining_balance, i.total_gross - COALESCE(i.amount_paid,0)) AS outstanding,
      (p_as_at - i.due_date) AS days_overdue
    FROM invoices i
    WHERE i.organization_id = p_organization_id
      AND ((p_client_id IS NOT NULL AND i.client_id = p_client_id)
        OR (p_company_id IS NOT NULL AND i.company_id = p_company_id))
      AND i.issue_date <= p_as_at
      AND COALESCE(i.status, '') NOT IN ('void','draft','cancelled')
      AND COALESCE(i.remaining_balance, i.total_gross - COALESCE(i.amount_paid,0)) > 0.005
      AND i.customer_id IS NOT NULL
  )
  SELECT
    o.customer_id,
    c.name AS customer_name,
    SUM(CASE WHEN o.days_overdue <= 0 THEN o.outstanding ELSE 0 END)::numeric AS current_amount,
    SUM(CASE WHEN o.days_overdue BETWEEN 1 AND 30 THEN o.outstanding ELSE 0 END)::numeric AS bucket_1_30,
    SUM(CASE WHEN o.days_overdue BETWEEN 31 AND 60 THEN o.outstanding ELSE 0 END)::numeric AS bucket_31_60,
    SUM(CASE WHEN o.days_overdue BETWEEN 61 AND 90 THEN o.outstanding ELSE 0 END)::numeric AS bucket_61_90,
    SUM(CASE WHEN o.days_overdue > 90 THEN o.outstanding ELSE 0 END)::numeric AS bucket_90_plus,
    SUM(o.outstanding)::numeric AS total_outstanding
  FROM open_inv o
  JOIN customers c ON c.id = o.customer_id
  GROUP BY o.customer_id, c.name
  ORDER BY c.name;
END;
$$;


--
-- Name: get_balance_sheet(uuid, uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_balance_sheet(p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_as_at_date date) RETURNS TABLE(account_id uuid, account_code text, account_name text, account_type text, account_subtype text, balance numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_retained_earnings numeric;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = p_organization_id
      AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF (p_client_id IS NULL AND p_company_id IS NULL) OR
     (p_client_id IS NOT NULL AND p_company_id IS NOT NULL) THEN
    RAISE EXCEPTION 'entity_scope_required' USING ERRCODE = '22023';
  END IF;

  -- Cumulative retained earnings = sum of (credit-debit) on INCOME minus (debit-credit) on EXPENSE,
  -- across all dates up to and including p_as_at_date.
  SELECT
    COALESCE(SUM(
      CASE
        WHEN a.account_type = 'INCOME'  THEN le.credit - le.debit
        WHEN a.account_type = 'EXPENSE' THEN le.credit - le.debit
        ELSE 0
      END
    ), 0)
  INTO v_retained_earnings
  FROM public.ledger_entries le
  JOIN public.bookkeeping_accounts a ON a.id = le.account_id
  WHERE le.organization_id = p_organization_id
    AND ((p_client_id  IS NOT NULL AND le.client_id  = p_client_id) OR
         (p_company_id IS NOT NULL AND le.company_id = p_company_id))
    AND le.entry_date <= p_as_at_date
    AND a.account_type IN ('INCOME','EXPENSE');

  RETURN QUERY
  SELECT
    a.id,
    a.code,
    a.name,
    a.account_type,
    a.account_subtype,
    CASE
      WHEN a.account_type = 'ASSET'     THEN COALESCE(SUM(le.debit - le.credit), 0)
      WHEN a.account_type = 'LIABILITY' THEN COALESCE(SUM(le.credit - le.debit), 0)
      WHEN a.account_type = 'EQUITY'    THEN COALESCE(SUM(le.credit - le.debit), 0)
      ELSE 0
    END::numeric AS balance
  FROM public.bookkeeping_accounts a
  LEFT JOIN public.ledger_entries le
    ON le.account_id = a.id
   AND le.organization_id = p_organization_id
   AND ((p_client_id  IS NOT NULL AND le.client_id  = p_client_id) OR
        (p_company_id IS NOT NULL AND le.company_id = p_company_id))
   AND le.entry_date <= p_as_at_date
  WHERE a.organization_id = p_organization_id
    AND ((p_client_id  IS NOT NULL AND a.client_id  = p_client_id) OR
         (p_company_id IS NOT NULL AND a.company_id = p_company_id))
    AND a.account_type IN ('ASSET','LIABILITY','EQUITY')
  GROUP BY a.id, a.code, a.name, a.account_type, a.account_subtype
  HAVING COALESCE(SUM(le.debit), 0) <> 0 OR COALESCE(SUM(le.credit), 0) <> 0
  ORDER BY a.account_type, a.code;

  -- Append synthetic retained-earnings row (current-period + prior cumulative).
  IF v_retained_earnings <> 0 THEN
    RETURN QUERY SELECT
      NULL::uuid,
      '__RETAINED_EARNINGS__'::text,
      'Retained Earnings (Computed)'::text,
      'EQUITY'::text,
      'RETAINED_EARNINGS'::text,
      v_retained_earnings::numeric;
  END IF;
END;
$$;


--
-- Name: get_bank_connection_health_for_entity(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_bank_connection_health_for_entity(_client_id uuid, _company_id uuid) RETURNS TABLE(connection_id uuid, bank_name text, bank_logo_url text, derived_status text, consent_expires_at timestamp with time zone, last_synced_at timestamp with time zone, client_safe_message text, account_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.portal_can_access_bookkeeping(_client_id, _company_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF NOT public.portal_has_perm(_client_id, _company_id, 'show_bank_accounts') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    c.id,
    c.bank_name,
    c.bank_logo_url,
    public.derive_bank_connection_status(c.consent_expires_at, c.status, c.last_error, c.last_synced_at),
    c.consent_expires_at,
    c.last_synced_at,
    CASE
      WHEN c.consent_expires_at IS NOT NULL AND c.consent_expires_at < now()
        THEN 'Bank connection expired. Reconnect bank.'
      WHEN c.consent_expires_at IS NOT NULL
        AND c.consent_expires_at < (now() + interval '7 days')
        THEN 'Your bank connection needs refreshing.'
      WHEN c.last_error IS NOT NULL AND c.last_error <> ''
        THEN 'Sync failed - contact your accountant.'
      ELSE NULL
    END,
    (SELECT count(*) FROM public.bank_accounts ba
       WHERE ba.organization_id = c.organization_id
         AND (
           (_client_id IS NOT NULL AND ba.client_id = _client_id)
           OR (_company_id IS NOT NULL AND ba.company_id = _company_id)
         ))
  FROM public.bank_connections c
  WHERE
    (_client_id IS NOT NULL AND c.client_id = _client_id)
    OR (_company_id IS NOT NULL AND c.company_id = _company_id);
END;
$$;


--
-- Name: get_bank_connection_health_for_org(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_bank_connection_health_for_org(_org_id uuid) RETURNS TABLE(connection_id uuid, organization_id uuid, client_id uuid, company_id uuid, provider text, bank_name text, bank_logo_url text, status text, derived_status text, consent_expires_at timestamp with time zone, last_synced_at timestamp with time zone, last_error text, account_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users ou
    WHERE ou.user_id = auth.uid() AND ou.organization_id = _org_id
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    c.id,
    c.organization_id,
    c.client_id,
    c.company_id,
    c.provider,
    c.bank_name,
    c.bank_logo_url,
    c.status,
    public.derive_bank_connection_status(c.consent_expires_at, c.status, c.last_error, c.last_synced_at),
    c.consent_expires_at,
    c.last_synced_at,
    c.last_error,
    (SELECT count(*) FROM public.bank_accounts ba
       WHERE ba.organization_id = c.organization_id
         AND (
           (c.client_id IS NOT NULL AND ba.client_id = c.client_id)
           OR (c.company_id IS NOT NULL AND ba.company_id = c.company_id)
         ))
  FROM public.bank_connections c
  WHERE c.organization_id = _org_id;
END;
$$;


--
-- Name: get_check_constraint_values(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_check_constraint_values(constraint_name text) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_def text;
  v_inner text;
  v_values text[];
BEGIN
  SELECT pg_get_constraintdef(c.oid)
    INTO v_def
  FROM pg_constraint c
  JOIN pg_namespace n ON n.oid = c.connamespace
  WHERE c.conname = constraint_name
    AND n.nspname = 'public'
    AND c.contype = 'c'
  LIMIT 1;

  IF v_def IS NULL THEN
    RETURN NULL;
  END IF;

  -- Extract text inside ARRAY[ ... ] (covers the common `= ANY (ARRAY[...])` pattern)
  v_inner := substring(v_def from 'ARRAY\[(.*)\]');
  IF v_inner IS NULL THEN
    RETURN ARRAY[]::text[];
  END IF;

  -- Pull each single-quoted literal out of the array body, ignoring ::text casts.
  SELECT array_agg(m[1] ORDER BY ord)
    INTO v_values
  FROM regexp_matches(v_inner, $re$'([^']*)'$re$, 'g') WITH ORDINALITY AS t(m, ord);

  RETURN COALESCE(v_values, ARRAY[]::text[]);
END;
$_$;


--
-- Name: FUNCTION get_check_constraint_values(constraint_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_check_constraint_values(constraint_name text) IS 'Read-only introspection helper. Returns the allowed string literals of a public-schema CHECK constraint defined with `= ANY (ARRAY[...])`. Used by scripts/smoke-test.ts to detect DB/UI vocabulary drift.';


--
-- Name: get_cron_job_status(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cron_job_status(p_jobname text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE r record;
BEGIN
  SELECT j.jobname, j.schedule, j.active INTO r FROM cron.job j WHERE j.jobname = p_jobname LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('exists', false); END IF;
  RETURN jsonb_build_object('exists', true, 'active', r.active, 'schedule', r.schedule);
EXCEPTION WHEN undefined_table OR invalid_schema_name THEN
  RETURN jsonb_build_object('exists', false, 'error', 'cron schema unavailable');
END;
$$;


--
-- Name: get_general_ledger_from_ledger(uuid, uuid, uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_general_ledger_from_ledger(p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_account_id uuid, p_period_start date, p_period_end date) RETURNS TABLE(ledger_entry_id uuid, transaction_date date, reference text, description text, source_type text, source_id uuid, journal_id uuid, debit numeric, credit numeric, running_balance numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT le.id,
         le.transaction_date,
         le.reference,
         le.description,
         le.source_type,
         le.source_id,
         le.journal_id,
         le.debit,
         le.credit,
         SUM(COALESCE(le.debit,0) - COALESCE(le.credit,0))
           OVER (ORDER BY le.transaction_date, le.created_at, le.id) AS running_balance
    FROM ledger_entries le
   WHERE le.organization_id = p_organization_id
     AND (p_account_id IS NULL OR le.account_id = p_account_id)
     AND (
          (p_client_id  IS NOT NULL AND le.client_id  = p_client_id) OR
          (p_company_id IS NOT NULL AND le.company_id = p_company_id)
     )
     AND le.transaction_date BETWEEN p_period_start AND p_period_end
   ORDER BY le.transaction_date, le.created_at, le.id;
$$;


--
-- Name: get_invoice_with_lines_safe(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_invoice_with_lines_safe(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_invoice jsonb;
  v_lines jsonb;
  v_org_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  -- Get org_id first for membership check
  SELECT organization_id INTO v_org_id FROM invoices WHERE id = p_invoice_id;
  IF v_org_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
  END IF;

  IF NOT public.user_in_organization(v_user_id, v_org_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  -- Whitelisted invoice fields only
  SELECT jsonb_build_object(
    'id', i.id,
    'organization_id', i.organization_id,
    'client_id', i.client_id,
    'company_id', i.company_id,
    'customer_id', i.customer_id,
    'invoice_type', i.invoice_type,
    'status', i.status,
    'invoice_number', i.invoice_number,
    'contact_name', i.contact_name,
    'contact_email', i.contact_email,
    'reference', i.reference,
    'issue_date', i.issue_date,
    'due_date', i.due_date,
    'notes', i.notes,
    'currency', i.currency,
    'total_net', i.total_net,
    'total_vat', i.total_vat,
    'total_gross', i.total_gross,
    'amount_paid', i.amount_paid,
    'remaining_balance', i.remaining_balance,
    'created_at', i.created_at,
    'updated_at', i.updated_at
  ) INTO v_invoice
  FROM invoices i
  WHERE i.id = p_invoice_id;

  -- Whitelisted line fields only
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', il.id,
    'line_number', il.line_number,
    'description', il.description,
    'quantity', il.quantity,
    'unit_price', il.unit_price,
    'vat_rate', il.vat_rate,
    'vat_code_id', il.vat_code_id,
    'account_id', il.account_id,
    'net_amount', il.net_amount,
    'vat_amount', il.vat_amount,
    'gross_amount', il.gross_amount
  ) ORDER BY il.line_number), '[]'::jsonb) INTO v_lines
  FROM invoice_lines il
  WHERE il.invoice_id = p_invoice_id;

  RETURN jsonb_build_object(
    'success', true,
    'invoice', v_invoice,
    'lines', v_lines
  );
END;
$$;


--
-- Name: get_org_settings_safe(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_org_settings_safe(p_organization_id uuid) RETURNS public.org_settings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_settings org_settings%ROWTYPE;
BEGIN
  SELECT * INTO v_settings FROM org_settings WHERE organization_id = p_organization_id;

  IF v_settings.id IS NULL THEN
    -- Insert defaults and return
    INSERT INTO org_settings (
      organization_id,
      automation_email_mode,
      automation_rate_limit_per_rule_hour,
      automation_rate_limit_per_rule_day,
      automation_rate_limit_org_hour,
      automation_rate_limit_org_day,
      invoice_number_prefix,
      invoice_number_next,
      bill_number_prefix,
      bill_number_next
    ) VALUES (
      p_organization_id,
      'queue',
      25,
      150,
      250,
      1500,
      'INV-',
      1,
      'BILL-',
      1
    )
    RETURNING * INTO v_settings;
  END IF;

  RETURN v_settings;
END;
$$;


--
-- Name: get_portal_bank_accounts_for_entity(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_portal_bank_accounts_for_entity(_user_id uuid, _client_id uuid DEFAULT NULL::uuid, _company_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, name text, account_number text, sort_code text, currency text, provider text, last_synced_at timestamp with time zone, connection_status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _org_id uuid;
BEGIN
  -- Verify user has access to this entity
  IF NOT client_has_portal_access(_user_id, _client_id, _company_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- Get organization_id
  IF _client_id IS NOT NULL THEN
    SELECT organization_id INTO _org_id FROM clients WHERE id = _client_id;
  ELSIF _company_id IS NOT NULL THEN
    SELECT organization_id INTO _org_id FROM companies WHERE id = _company_id;
  END IF;

  -- Return bank accounts with connection status
  RETURN QUERY
  SELECT 
    ba.id,
    ba.name,
    ba.account_number,
    ba.sort_code,
    ba.currency,
    ba.provider,
    COALESCE(bc.last_synced_at, ba.last_synced_at) as last_synced_at,
    COALESCE(bc.status, 'active') as connection_status
  FROM bank_accounts ba
  LEFT JOIN bank_connections bc ON (
    bc.organization_id = ba.organization_id
    AND bc.provider = ba.provider
    AND (
      (bc.client_id IS NOT NULL AND bc.client_id = ba.client_id) OR
      (bc.company_id IS NOT NULL AND bc.company_id = ba.company_id)
    )
  )
  WHERE ba.organization_id = _org_id
    AND (
      (_client_id IS NOT NULL AND ba.client_id = _client_id) OR
      (_company_id IS NOT NULL AND ba.company_id = _company_id)
    )
    AND ba.is_active = true
  ORDER BY ba.name;
END;
$$;


--
-- Name: get_portal_entities_for_current_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_portal_entities_for_current_user() RETURNS TABLE(organization_id uuid, entity_id uuid, entity_type text, display_name text, registration_number text, tax_reference text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT * FROM get_portal_entities_for_user(auth.uid());
$$;


--
-- Name: get_portal_entities_for_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_portal_entities_for_user(_user_id uuid) RETURNS TABLE(organization_id uuid, entity_id uuid, entity_type text, display_name text, registration_number text, tax_reference text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- Get companies
  SELECT 
    pa.organization_id,
    c.id as entity_id,
    'company'::text as entity_type,
    c.company_name as display_name,
    c.company_number as registration_number,
    c.vat_number as tax_reference
  FROM portal_access pa
  JOIN companies c ON c.id = pa.company_id
  WHERE pa.user_id = _user_id
    AND pa.is_active = true
    AND pa.company_id IS NOT NULL

  UNION ALL

  -- Get clients
  SELECT 
    pa.organization_id,
    cl.id as entity_id,
    'client'::text as entity_type,
    (cl.first_name || ' ' || cl.last_name) as display_name,
    NULL as registration_number,
    cl.utr as tax_reference
  FROM portal_access pa
  JOIN clients cl ON cl.id = pa.client_id
  WHERE pa.user_id = _user_id
    AND pa.is_active = true
    AND pa.client_id IS NOT NULL
$$;


--
-- Name: get_portal_invite_details(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_portal_invite_details(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_portal_access record;
  v_org_name text;
  v_entity_name text;
  v_entity_type text;
  v_email text;
  v_user_exists boolean := false;
BEGIN
  -- Look up portal_access by token
  SELECT * INTO v_portal_access
  FROM portal_access
  WHERE invite_token = p_token
    AND status = 'invited'
    AND (invite_expires_at IS NULL OR invite_expires_at > now());

  -- If not found or expired
  IF v_portal_access.id IS NULL THEN
    -- Check if token exists but expired
    IF EXISTS (
      SELECT 1 FROM portal_access
      WHERE invite_token = p_token
        AND status = 'invited'
        AND invite_expires_at IS NOT NULL
        AND invite_expires_at <= now()
    ) THEN
      RETURN jsonb_build_object('valid', false, 'reason', 'expired');
    ELSE
      RETURN jsonb_build_object('valid', false, 'reason', 'not_found');
    END IF;
  END IF;

  -- Get organization name
  SELECT name INTO v_org_name
  FROM organizations
  WHERE id = v_portal_access.organization_id;

  -- Get entity details
  IF v_portal_access.client_id IS NOT NULL THEN
    v_entity_type := 'client';
    SELECT (first_name || ' ' || last_name) INTO v_entity_name
    FROM clients
    WHERE id = v_portal_access.client_id;
  ELSIF v_portal_access.company_id IS NOT NULL THEN
    v_entity_type := 'company';
    SELECT company_name INTO v_entity_name
    FROM companies
    WHERE id = v_portal_access.company_id;
  END IF;

  -- Get email
  IF v_portal_access.user_id IS NOT NULL THEN
    -- Get from auth.users
    SELECT email INTO v_email
    FROM auth.users
    WHERE id = v_portal_access.user_id;
  ELSE
    -- Get from email_queue (most recent invite email)
    SELECT to_email INTO v_email
    FROM email_queue
    WHERE entity_type = 'portal_access'
      AND entity_id = v_portal_access.id
    ORDER BY created_at DESC
    LIMIT 1;
  END IF;

  -- Check if user already exists with this email
  IF v_email IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM auth.users WHERE email = v_email
    ) INTO v_user_exists;
  END IF;

  -- Return valid response
  RETURN jsonb_build_object(
    'valid', true,
    'organization_name', v_org_name,
    'entity_type', v_entity_type,
    'entity_name', v_entity_name,
    'email', v_email,
    'requires_user_creation', NOT v_user_exists,
    'portal_access_id', v_portal_access.id
  );
END;
$$;


--
-- Name: get_portal_kpis_for_entity(uuid, uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_portal_kpis_for_entity(_user_id uuid, _client_id uuid DEFAULT NULL::uuid, _company_id uuid DEFAULT NULL::uuid, _period_start date DEFAULT NULL::date, _period_end date DEFAULT NULL::date) RETURNS TABLE(revenue numeric, expenses numeric, net_profit numeric, cash_balance numeric, vat_position numeric, corporation_tax_estimate numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _org_id uuid;
BEGIN
  -- Verify user has access to this entity
  IF NOT client_has_portal_access(_user_id, _client_id, _company_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- Get organization_id
  SELECT organization_id INTO _org_id
  FROM portal_access
  WHERE user_id = _user_id
    AND is_active = true
    AND (
      (_client_id IS NOT NULL AND client_id = _client_id) OR
      (_company_id IS NOT NULL AND company_id = _company_id)
    )
  LIMIT 1;

  -- Set default period to current year if not provided
  IF _period_start IS NULL THEN
    _period_start := date_trunc('year', CURRENT_DATE)::date;
  END IF;

  IF _period_end IS NULL THEN
    _period_end := CURRENT_DATE;
  END IF;

  -- Calculate KPIs from ledger_entries
  RETURN QUERY
  SELECT 
    -- Revenue: sum of INCOME accounts (credit - debit)
    COALESCE((
      SELECT SUM(le.credit - le.debit)
      FROM ledger_entries le
      JOIN bookkeeping_accounts ba ON ba.id = le.account_id
      WHERE ba.organization_id = _org_id
        AND ba.account_type = 'INCOME'
        AND (
          (_client_id IS NOT NULL AND le.client_id = _client_id) OR
          (_company_id IS NOT NULL AND le.company_id = _company_id)
        )
        AND le.transaction_date BETWEEN _period_start AND _period_end
    ), 0) as revenue,

    -- Expenses: sum of EXPENSE accounts (debit - credit)
    COALESCE((
      SELECT SUM(le.debit - le.credit)
      FROM ledger_entries le
      JOIN bookkeeping_accounts ba ON ba.id = le.account_id
      WHERE ba.organization_id = _org_id
        AND ba.account_type = 'EXPENSE'
        AND (
          (_client_id IS NOT NULL AND le.client_id = _client_id) OR
          (_company_id IS NOT NULL AND le.company_id = _company_id)
        )
        AND le.transaction_date BETWEEN _period_start AND _period_end
    ), 0) as expenses,

    -- Net Profit: revenue - expenses (calculated in select)
    COALESCE((
      SELECT SUM(le.credit - le.debit)
      FROM ledger_entries le
      JOIN bookkeeping_accounts ba ON ba.id = le.account_id
      WHERE ba.organization_id = _org_id
        AND ba.account_type = 'INCOME'
        AND (
          (_client_id IS NOT NULL AND le.client_id = _client_id) OR
          (_company_id IS NOT NULL AND le.company_id = _company_id)
        )
        AND le.transaction_date BETWEEN _period_start AND _period_end
    ), 0) - COALESCE((
      SELECT SUM(le.debit - le.credit)
      FROM ledger_entries le
      JOIN bookkeeping_accounts ba ON ba.id = le.account_id
      WHERE ba.organization_id = _org_id
        AND ba.account_type = 'EXPENSE'
        AND (
          (_client_id IS NOT NULL AND le.client_id = _client_id) OR
          (_company_id IS NOT NULL AND le.company_id = _company_id)
        )
        AND le.transaction_date BETWEEN _period_start AND _period_end
    ), 0) as net_profit,

    -- Cash Balance: sum of bank accounts (debit - credit)
    COALESCE((
      SELECT SUM(le.debit - le.credit)
      FROM ledger_entries le
      JOIN bookkeeping_accounts ba ON ba.id = le.account_id
      WHERE ba.organization_id = _org_id
        AND ba.is_bank_account = true
        AND (
          (_client_id IS NOT NULL AND le.client_id = _client_id) OR
          (_company_id IS NOT NULL AND le.company_id = _company_id)
        )
    ), 0) as cash_balance,

    -- VAT Position: from latest vat_return or NULL
    (
      SELECT vat_due
      FROM vat_returns
      WHERE organization_id = _org_id
        AND (
          (_client_id IS NOT NULL AND client_id = _client_id) OR
          (_company_id IS NOT NULL AND company_id = _company_id)
        )
      ORDER BY period_end DESC
      LIMIT 1
    ) as vat_position,

    -- Corporation Tax Estimate: from finalised workpaper or NULL
    (
      SELECT (computed_data->>'tax_liability')::numeric
      FROM workpaper_instances wi
      WHERE wi.organization_id = _org_id
        AND wi.workpaper_type = 'CT600'
        AND wi.status = 'finalised'
        AND (
          (_client_id IS NOT NULL AND wi.client_id = _client_id) OR
          (_company_id IS NOT NULL AND wi.company_id = _company_id)
        )
      ORDER BY wi.finalised_at DESC
      LIMIT 1
    ) as corporation_tax_estimate;
END;
$$;


--
-- Name: get_portal_visibility_for_entity(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_portal_visibility_for_entity(_user_id uuid, _client_id uuid DEFAULT NULL::uuid, _company_id uuid DEFAULT NULL::uuid) RETURNS TABLE(show_revenue boolean, show_profit boolean, show_cash boolean, show_vat_position boolean, show_ct_estimate boolean, show_receivables_payables boolean, show_transactions boolean, show_bank_accounts boolean, show_invoices boolean, show_trial_balance boolean, show_detailed_ledger boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _org_id uuid;
BEGIN
  -- Verify user has access to this entity
  IF NOT client_has_portal_access(_user_id, _client_id, _company_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- Get organization_id from portal_access
  SELECT organization_id INTO _org_id
  FROM portal_access
  WHERE user_id = _user_id
    AND is_active = true
    AND (
      (_client_id IS NOT NULL AND client_id = _client_id) OR
      (_company_id IS NOT NULL AND company_id = _company_id)
    )
  LIMIT 1;

  -- Return entity-specific settings if they exist, otherwise return defaults
  RETURN QUERY
  SELECT 
    COALESCE(pvs.show_revenue, true) as show_revenue,
    COALESCE(pvs.show_profit, true) as show_profit,
    COALESCE(pvs.show_cash, true) as show_cash,
    COALESCE(pvs.show_vat_position, true) as show_vat_position,
    COALESCE(pvs.show_ct_estimate, true) as show_ct_estimate,
    COALESCE(pvs.show_receivables_payables, true) as show_receivables_payables,
    COALESCE(pvs.show_transactions, true) as show_transactions,
    COALESCE(pvs.show_bank_accounts, true) as show_bank_accounts,
    COALESCE(pvs.show_invoices, true) as show_invoices,
    COALESCE(pvs.show_trial_balance, false) as show_trial_balance,
    COALESCE(pvs.show_detailed_ledger, false) as show_detailed_ledger
  FROM (
    SELECT 
      NULL::boolean as show_revenue,
      NULL::boolean as show_profit,
      NULL::boolean as show_cash,
      NULL::boolean as show_vat_position,
      NULL::boolean as show_ct_estimate,
      NULL::boolean as show_receivables_payables,
      NULL::boolean as show_transactions,
      NULL::boolean as show_bank_accounts,
      NULL::boolean as show_invoices,
      NULL::boolean as show_trial_balance,
      NULL::boolean as show_detailed_ledger
  ) defaults
  LEFT JOIN portal_visibility_settings pvs ON (
    pvs.organization_id = _org_id
    AND (
      (_client_id IS NOT NULL AND pvs.client_id = _client_id) OR
      (_company_id IS NOT NULL AND pvs.company_id = _company_id)
    )
  )
  LIMIT 1;
END;
$$;


--
-- Name: get_profit_and_loss(uuid, uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_profit_and_loss(p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_from_date date, p_to_date date) RETURNS TABLE(account_id uuid, account_code text, account_name text, account_type text, account_subtype text, debit_total numeric, credit_total numeric, net_amount numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Authorisation: caller must belong to organisation
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = p_organization_id
      AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF (p_client_id IS NULL AND p_company_id IS NULL) OR
     (p_client_id IS NOT NULL AND p_company_id IS NOT NULL) THEN
    RAISE EXCEPTION 'entity_scope_required' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    a.id,
    a.code,
    a.name,
    a.account_type,
    a.account_subtype,
    COALESCE(SUM(le.debit), 0)::numeric  AS debit_total,
    COALESCE(SUM(le.credit), 0)::numeric AS credit_total,
    CASE
      WHEN a.account_type = 'INCOME'  THEN COALESCE(SUM(le.credit - le.debit), 0)
      WHEN a.account_type = 'EXPENSE' THEN COALESCE(SUM(le.debit - le.credit), 0) * -1
      ELSE 0
    END::numeric AS net_amount
  FROM public.bookkeeping_accounts a
  LEFT JOIN public.ledger_entries le
    ON le.account_id = a.id
   AND le.organization_id = p_organization_id
   AND ((p_client_id  IS NOT NULL AND le.client_id  = p_client_id) OR
        (p_company_id IS NOT NULL AND le.company_id = p_company_id))
   AND le.entry_date BETWEEN p_from_date AND p_to_date
  WHERE a.organization_id = p_organization_id
    AND ((p_client_id  IS NOT NULL AND a.client_id  = p_client_id) OR
         (p_company_id IS NOT NULL AND a.company_id = p_company_id))
    AND a.account_type IN ('INCOME','EXPENSE')
  GROUP BY a.id, a.code, a.name, a.account_type, a.account_subtype
  HAVING COALESCE(SUM(le.debit), 0) <> 0 OR COALESCE(SUM(le.credit), 0) <> 0
  ORDER BY a.account_type DESC, a.code;
END;
$$;


--
-- Name: get_questionnaire_by_token(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_questionnaire_by_token(p_instance_id uuid, p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_link public.questionnaire_public_links;
  v_instance RECORD;
  v_hash TEXT;
BEGIN
  v_link := public._require_valid_questionnaire_link(p_instance_id, p_token);
  v_hash := public._hash_token(p_token);

  SELECT
    id, name, questions, status, period_label, submitted_at
  INTO v_instance
  FROM public.questionnaire_instances
  WHERE id = p_instance_id
  LIMIT 1;

  INSERT INTO public.questionnaire_access_log(questionnaire_instance_id, token_hash, action)
  VALUES (p_instance_id, v_hash, 'view');

  RETURN jsonb_build_object(
    'id', v_instance.id,
    'name', v_instance.name,
    'questions', v_instance.questions,
    'status', v_instance.status,
    'period_label', v_instance.period_label,
    'submitted_at', v_instance.submitted_at
  );
END;
$$;


--
-- Name: get_questionnaire_responses_by_token(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_questionnaire_responses_by_token(p_instance_id uuid, p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_link public.questionnaire_public_links;
  v_responses JSONB;
BEGIN
  v_link := public._require_valid_questionnaire_link(p_instance_id, p_token);

  SELECT jsonb_agg(jsonb_build_object(
    'id', id,
    'question_id', question_id,
    'answer_text', answer_text,
    'answer_number', answer_number,
    'answer_boolean', answer_boolean,
    'answer_date', answer_date,
    'answer_array', answer_array
  ))
  INTO v_responses
  FROM public.questionnaire_responses
  WHERE questionnaire_instance_id = p_instance_id;

  RETURN COALESCE(v_responses, '[]'::jsonb);
END;
$$;


--
-- Name: get_trial_balance_from_ledger(uuid, uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_trial_balance_from_ledger(p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_period_start date, p_period_end date) RETURNS TABLE(account_id uuid, account_code text, account_name text, account_type text, opening_balance numeric, period_debit numeric, period_credit numeric, closing_balance numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH base AS (
    SELECT a.id   AS account_id,
           a.code AS account_code,
           a.name AS account_name,
           a.account_type,
           le.transaction_date,
           COALESCE(le.debit,  0) AS d,
           COALESCE(le.credit, 0) AS c
      FROM ledger_entries le
      JOIN bookkeeping_accounts a ON a.id = le.account_id
     WHERE le.organization_id = p_organization_id
       AND (
            (p_client_id  IS NOT NULL AND le.client_id  = p_client_id) OR
            (p_company_id IS NOT NULL AND le.company_id = p_company_id)
       )
       AND le.transaction_date <= p_period_end
  )
  SELECT account_id,
         account_code,
         account_name,
         account_type,
         SUM(CASE WHEN transaction_date < p_period_start THEN d - c ELSE 0 END)::numeric AS opening_balance,
         SUM(CASE WHEN transaction_date BETWEEN p_period_start AND p_period_end THEN d ELSE 0 END)::numeric AS period_debit,
         SUM(CASE WHEN transaction_date BETWEEN p_period_start AND p_period_end THEN c ELSE 0 END)::numeric AS period_credit,
         SUM(d - c)::numeric AS closing_balance
    FROM base
   GROUP BY account_id, account_code, account_name, account_type
   ORDER BY account_code;
$$;


