--
-- Name: render_engagement_letter_body(text, text, text, text, text, numeric, numeric, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.render_engagement_letter_body(p_template text, p_firm_name text, p_client_name text, p_services_list_html text, p_currency text, p_total_one_off numeric, p_total_monthly numeric, p_accepted_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v text;
BEGIN
  IF p_template IS NULL OR length(btrim(p_template)) = 0 THEN
    RETURN NULL;
  END IF;
  v := p_template;
  v := replace(v, '{{firm_name}}',     COALESCE(p_firm_name, ''));
  v := replace(v, '{{firm.name}}',     COALESCE(p_firm_name, ''));
  v := replace(v, '{{client_name}}',   COALESCE(p_client_name, ''));
  v := replace(v, '{{client.name}}',   COALESCE(p_client_name, ''));
  v := replace(v, '{{recipient_name}}',COALESCE(p_client_name, ''));
  v := replace(v, '{{services_list}}', COALESCE(p_services_list_html, ''));
  v := replace(v, '{{currency}}',      COALESCE(p_currency, ''));
  v := replace(v, '{{total_one_off}}', COALESCE(p_total_one_off::text, '0'));
  v := replace(v, '{{total_monthly}}', COALESCE(p_total_monthly::text, '0'));
  v := replace(v, '{{accepted_date}}', to_char(COALESCE(p_accepted_at, now()), 'DD Mon YYYY'));
  v := replace(v, '{{today}}',         to_char(now(), 'DD Mon YYYY'));
  RETURN v;
END;
$$;


--
-- Name: reopen_bank_reconciliation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_bank_reconciliation(p_reconciliation_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rec public.reconciliations%ROWTYPE;
BEGIN
  IF p_reason IS NULL OR length(btrim(p_reason)) < 5 THEN
    RAISE EXCEPTION 'A reason (>= 5 chars) is required to reopen a reconciliation';
  END IF;

  SELECT * INTO v_rec FROM public.reconciliations WHERE id = p_reconciliation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reconciliation not found'; END IF;
  IF v_rec.status <> 'completed' THEN
    RAISE EXCEPTION 'Only completed reconciliations can be reopened';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = v_rec.organization_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not authorized for this organization';
  END IF;

  PERFORM public.assert_no_locked_period_write(
    v_rec.organization_id, v_rec.client_id, v_rec.company_id, v_rec.statement_end_date
  );

  UPDATE public.reconciliations
     SET status = 'in_progress',
         reopened_by = auth.uid(),
         reopened_at = now(),
         reopen_reason = p_reason,
         completed_by = NULL,
         completed_at = NULL,
         updated_at = now()
   WHERE id = p_reconciliation_id;

  -- Revert RECONCILED txns back to MATCHED so they can be re-included
  UPDATE public.bank_transactions bt
     SET status = 'MATCHED', updated_at = now()
   FROM public.reconciliation_lines rl
   WHERE rl.reconciliation_id = p_reconciliation_id
     AND bt.id = rl.bank_transaction_id
     AND bt.status = 'RECONCILED';

  INSERT INTO public.bookkeeping_audit_log (
    organization_id, client_id, company_id, entity_type, entity_id, action, performed_by, metadata
  ) VALUES (
    v_rec.organization_id, v_rec.client_id, v_rec.company_id,
    'reconciliation', p_reconciliation_id, 'reopen_bank_reconciliation', auth.uid(),
    jsonb_build_object('reason', p_reason)
  );

  RETURN p_reconciliation_id;
END;
$$;


--
-- Name: resolve_company_director(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_company_director(p_company_id uuid, p_lead_id uuid, p_org_id uuid) RETURNS TABLE(first_name text, last_name text, email text, phone text, source text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_company_name text;
  v_contact record;
  v_person record;
  v_officer jsonb;
  v_full_name text;
  v_comma_pos int;
  v_lead record;
BEGIN
  IF p_company_id IS NOT NULL THEN
    SELECT company_name INTO v_company_name FROM public.companies WHERE id = p_company_id;
  END IF;

  IF p_company_id IS NOT NULL THEN
    SELECT * INTO v_contact
    FROM public.contacts
    WHERE company_id = p_company_id
      AND role ILIKE 'director%'
    ORDER BY is_primary DESC NULLS LAST, created_at ASC
    LIMIT 1;

    IF v_contact.id IS NOT NULL AND COALESCE(trim(v_contact.name), '') <> '' THEN
      first_name := split_part(trim(v_contact.name), ' ', 1);
      last_name  := NULLIF(trim(substring(trim(v_contact.name) FROM position(' ' IN trim(v_contact.name) || ' ') + 1)), '');
      email := v_contact.email;
      phone := v_contact.phone;
      source := 'contacts';
      RETURN NEXT;
      RETURN;
    END IF;
  END IF;

  IF p_company_id IS NOT NULL THEN
    SELECT cp.first_name, cp.last_name, cp.email, cp.phone
      INTO v_person
    FROM public.company_officers co
    JOIN public.company_persons cp ON cp.id = co.person_id
    WHERE co.company_id = p_company_id
      AND co.role ILIKE 'director%'
      AND co.resigned_at IS NULL
    ORDER BY co.appointed_at ASC NULLS LAST
    LIMIT 1;

    IF v_person.first_name IS NOT NULL OR v_person.last_name IS NOT NULL THEN
      first_name := v_person.first_name;
      last_name := v_person.last_name;
      email := v_person.email;
      phone := v_person.phone;
      source := 'company_officers';
      RETURN NEXT;
      RETURN;
    END IF;
  END IF;

  IF p_company_id IS NOT NULL THEN
    SELECT officer INTO v_officer
    FROM public.companies c,
         LATERAL jsonb_array_elements(COALESCE(c.ch_company_profile->'officers','[]'::jsonb)) AS officer
    WHERE c.id = p_company_id
      AND lower(COALESCE(officer->>'officer_role','')) LIKE 'director%'
      AND (officer->>'resigned_on') IS NULL
    LIMIT 1;

    IF v_officer IS NOT NULL THEN
      v_full_name := COALESCE(v_officer->>'name', '');
      v_comma_pos := position(',' IN v_full_name);
      IF v_comma_pos > 0 THEN
        last_name := NULLIF(trim(substring(v_full_name FROM 1 FOR v_comma_pos - 1)), '');
        first_name := NULLIF(trim(substring(v_full_name FROM v_comma_pos + 1)), '');
      ELSE
        first_name := split_part(trim(v_full_name), ' ', 1);
        last_name  := NULLIF(trim(substring(trim(v_full_name) FROM position(' ' IN trim(v_full_name) || ' ') + 1)), '');
      END IF;
      IF first_name IS NOT NULL OR last_name IS NOT NULL THEN
        email := NULL;
        phone := NULL;
        source := 'ch_profile';
        RETURN NEXT;
        RETURN;
      END IF;
    END IF;
  END IF;

  IF p_lead_id IS NOT NULL THEN
    SELECT * INTO v_lead FROM public.leads WHERE id = p_lead_id;
    IF v_lead.id IS NOT NULL THEN
      v_full_name := trim(COALESCE(v_lead.first_name,'') || ' ' || COALESCE(v_lead.last_name,''));
      IF v_full_name <> ''
         AND lower(v_full_name) <> lower(COALESCE(v_company_name,''))
         AND lower(COALESCE(v_lead.first_name,'')) <> lower(COALESCE(v_company_name,'')) THEN
        first_name := v_lead.first_name;
        last_name := v_lead.last_name;
        email := v_lead.email;
        phone := v_lead.phone;
        source := 'lead';
        RETURN NEXT;
        RETURN;
      END IF;
    END IF;
  END IF;

  RETURN;
END;
$$;


--
-- Name: resolve_engagement_letter_variant(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_engagement_letter_variant(p_organization_id uuid, p_client_type text, p_service_code text, p_legal_entity text, p_engagement_kind text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT id FROM public.engagement_letter_template_variants
  WHERE organization_id = p_organization_id
    AND is_active
    AND engagement_kind = coalesce(p_engagement_kind,'recurring')
    AND (client_type = p_client_type OR client_type IS NULL)
    AND (service_code = p_service_code OR service_code IS NULL)
    AND (legal_entity = p_legal_entity OR legal_entity IS NULL)
  ORDER BY
    (client_type = p_client_type)::int DESC,
    (service_code = p_service_code)::int DESC,
    (legal_entity = p_legal_entity)::int DESC,
    is_default DESC
  LIMIT 1;
$$;


--
-- Name: resume_automation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resume_automation(p_pause_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM automation_pauses WHERE id = p_pause_id;
  IF v_org IS NULL THEN RETURN false; END IF;
  IF NOT user_in_organization(auth.uid(), v_org) THEN RAISE EXCEPTION 'not a member'; END IF;
  DELETE FROM automation_pauses WHERE id = p_pause_id;
  INSERT INTO automation_audit_logs(organization_id, actor_id, entity_type, entity_id, action)
  VALUES (v_org, auth.uid(), 'automation_pause', p_pause_id, 'resume');
  RETURN true;
END;$$;


