-- Name: resume_workflow_instance(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resume_workflow_instance(p_instance_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.automation_workflow_instances
     SET status = 'QUEUED', paused_at = NULL, next_run_at = COALESCE(next_run_at, now()), updated_at = now()
   WHERE id = p_instance_id
     AND status = 'PAUSED'
     AND org_id IN (SELECT organization_id FROM organization_users WHERE user_id = auth.uid());
END;
$$;


--
-- Name: retry_failed_email_safe(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retry_failed_email_safe(p_email_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_email RECORD;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_email FROM email_queue WHERE id = p_email_id;
  IF v_email.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Email not found');
  END IF;

  IF NOT user_in_organization(v_user_id, v_email.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  IF v_email.status != 'failed' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Can only retry failed emails');
  END IF;

  UPDATE email_queue SET
    status = 'pending',
    retry_count = COALESCE(retry_count, 0) + 1,
    last_error_message = NULL,
    updated_at = now()
  WHERE id = p_email_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id)
  VALUES (v_email.organization_id, 'email', p_email_id, 'retry_requested', v_user_id);

  RETURN jsonb_build_object('success', true, 'email_id', p_email_id);
END;
$$;


--
-- Name: revalue_bank_account_fx(uuid, date, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revalue_bank_account_fx(p_bank_account_id uuid, p_revaluation_date date, p_fx_rate_to_base numeric, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bank record;
  v_org_settings record;
  v_base_currency text;
  v_gl_account_id uuid;
  v_txn_balance numeric := 0;     -- balance in transaction currency
  v_base_balance numeric := 0;    -- current GL balance in base currency
  v_revalued_base numeric;        -- revalued amount in base currency
  v_diff numeric;                 -- gain (>0) or loss (<0)
  v_journal_id uuid;
  v_fx_account uuid;
  v_user_id uuid := auth.uid();
  v_org_id uuid;
BEGIN
  IF p_fx_rate_to_base IS NULL OR p_fx_rate_to_base <= 0 THEN
    RAISE EXCEPTION 'Invalid FX rate' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_bank FROM public.bank_accounts WHERE id = p_bank_account_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bank account not found';
  END IF;
  v_org_id := v_bank.organization_id;

  -- Org membership
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = v_org_id AND user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'Not a member of this organization';
  END IF;

  -- Period lock guard
  PERFORM public.assert_no_locked_period_write(
    v_org_id, v_bank.client_id, v_bank.company_id, p_revaluation_date
  );

  v_gl_account_id := v_bank.account_id;
  IF v_gl_account_id IS NULL THEN
    RAISE EXCEPTION 'Bank account has no mapped GL account';
  END IF;

  SELECT * INTO v_org_settings FROM public.org_settings WHERE organization_id = v_org_id;
  v_base_currency := COALESCE(v_org_settings.base_currency, 'GBP');

  IF v_bank.currency = v_base_currency THEN
    RAISE EXCEPTION 'Bank account currency matches base currency; no FX revaluation needed';
  END IF;

  -- Aggregate balances on the GL bank account, scoped to entity
  SELECT
    COALESCE(SUM(COALESCE(le.transaction_debit, le.debit) - COALESCE(le.transaction_credit, le.credit)), 0),
    COALESCE(SUM(le.debit - le.credit), 0)
  INTO v_txn_balance, v_base_balance
  FROM public.ledger_entries le
  WHERE le.account_id = v_gl_account_id
    AND le.organization_id = v_org_id
    AND le.transaction_date <= p_revaluation_date
    AND (
      (v_bank.company_id IS NOT NULL AND le.company_id = v_bank.company_id) OR
      (v_bank.client_id IS NOT NULL AND le.client_id = v_bank.client_id)
    );

  v_revalued_base := ROUND(v_txn_balance * p_fx_rate_to_base, 2);
  v_diff := ROUND(v_revalued_base - v_base_balance, 2);

  IF ABS(v_diff) < 0.005 THEN
    RETURN jsonb_build_object(
      'success', true,
      'no_adjustment', true,
      'txn_balance', v_txn_balance,
      'base_balance', v_base_balance,
      'revalued_base', v_revalued_base
    );
  END IF;

  -- Determine FX account: gain if diff > 0, loss if diff < 0
  IF v_diff > 0 THEN
    v_fx_account := v_org_settings.fx_gain_account_id;
  ELSE
    v_fx_account := v_org_settings.fx_loss_account_id;
  END IF;
  IF v_fx_account IS NULL THEN
    RAISE EXCEPTION 'FX gain/loss account not configured in org_settings';
  END IF;

  -- Build journal: adjust bank GL by v_diff (base only, txn amount = 0)
  -- Debit bank / Credit FX gain  (when diff > 0)
  -- Credit bank / Debit FX loss  (when diff < 0)
  INSERT INTO public.journals (
    organization_id, client_id, company_id, journal_date, description,
    source_type, source_id, created_by
  ) VALUES (
    v_org_id, v_bank.client_id, v_bank.company_id, p_revaluation_date,
    COALESCE(p_reason, 'FX revaluation: ' || v_bank.name),
    'FX_REVALUATION', p_bank_account_id, v_user_id
  ) RETURNING id INTO v_journal_id;

  -- Bank leg (base only)
  INSERT INTO public.journal_lines (journal_id, account_id, debit, credit, description)
  VALUES (
    v_journal_id, v_gl_account_id,
    GREATEST(v_diff, 0), GREATEST(-v_diff, 0),
    'FX revaluation adjustment'
  );

  -- FX gain/loss leg
  INSERT INTO public.journal_lines (journal_id, account_id, debit, credit, description)
  VALUES (
    v_journal_id, v_fx_account,
    GREATEST(-v_diff, 0), GREATEST(v_diff, 0),
    'FX revaluation ' || CASE WHEN v_diff > 0 THEN 'gain' ELSE 'loss' END
  );

  -- Post journal to ledger
  PERFORM public.post_to_ledger(v_journal_id);

  -- Audit log
  INSERT INTO public.bookkeeping_audit_log (
    organization_id, client_id, company_id, action, entity_type, entity_id, payload, performed_by
  ) VALUES (
    v_org_id, v_bank.client_id, v_bank.company_id,
    'fx_revaluation', 'bank_account', p_bank_account_id,
    jsonb_build_object(
      'revaluation_date', p_revaluation_date,
      'fx_rate', p_fx_rate_to_base,
      'txn_balance', v_txn_balance,
      'base_balance', v_base_balance,
      'revalued_base', v_revalued_base,
      'adjustment', v_diff,
      'journal_id', v_journal_id,
      'reason', p_reason
    ),
    v_user_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'journal_id', v_journal_id,
    'adjustment', v_diff,
    'txn_balance', v_txn_balance,
    'base_balance_before', v_base_balance,
    'base_balance_after', v_revalued_base
  );
END;
$$;


--
-- Name: reverse_bill_payment_safe(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_bill_payment_safe(p_payment_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_payment RECORD;
  v_bill RECORD;
  v_org_id UUID;
  v_reversal_id UUID;
  v_new_total_paid NUMERIC;
  v_new_status TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_payment FROM bill_payments WHERE id = p_payment_id;
  IF v_payment.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payment not found');
  END IF;

  SELECT * INTO v_bill FROM bills WHERE id = v_payment.bill_id;
  v_org_id := v_bill.organization_id;

  IF NOT can_approve_bills(v_user_id, v_org_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: manager+ required');
  END IF;

  IF v_payment.payment_type = 'reversal' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot reverse a reversal');
  END IF;

  -- Create reversal entry
  INSERT INTO bill_payments (bill_id, amount, payment_date, payment_type, reference, notes, created_by)
  VALUES (v_payment.bill_id, -v_payment.amount, CURRENT_DATE, 'reversal', 'REV-' || v_payment.id, p_reason, v_user_id)
  RETURNING id INTO v_reversal_id;

  SELECT COALESCE(SUM(amount), 0) INTO v_new_total_paid FROM bill_payments WHERE bill_id = v_payment.bill_id;

  -- FIXED: Use APPROVED when no payments remain, not AWAITING_PAYMENT
  IF v_new_total_paid <= 0 THEN
    v_new_status := 'APPROVED';
  ELSIF v_new_total_paid >= v_bill.total_gross THEN
    v_new_status := 'PAID';
  ELSE
    v_new_status := 'PART_PAID';
  END IF;

  UPDATE bills SET
    amount_paid = GREATEST(v_new_total_paid, 0),
    remaining_balance = total_gross - GREATEST(v_new_total_paid, 0),
    status = v_new_status,
    updated_at = now()
  WHERE id = v_payment.bill_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata, actor_role)
  VALUES (v_org_id, 'bill_payment', v_reversal_id, 'payment_reversed', v_user_id,
    jsonb_build_object('original_payment_id', p_payment_id, 'reason', p_reason, 'amount', v_payment.amount, 'new_status', v_new_status),
    (SELECT role FROM organization_users WHERE user_id = v_user_id AND organization_id = v_org_id LIMIT 1));

  RETURN jsonb_build_object('success', true, 'reversal_id', v_reversal_id, 'bill_status', v_new_status);
END;
$$;


--
-- Name: reverse_invoice_payment_safe(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_invoice_payment_safe(p_payment_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payment RECORD;
  v_invoice RECORD;
  v_user_id UUID;
  v_org_id UUID;
  v_new_status TEXT;
  v_new_paid NUMERIC;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF p_reason IS NULL OR p_reason = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reason is required for payment reversal');
  END IF;

  SELECT * INTO v_payment FROM invoice_payments WHERE id = p_payment_id FOR UPDATE;

  IF v_payment.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payment not found');
  END IF;

  SELECT * INTO v_invoice FROM invoices WHERE id = v_payment.invoice_id FOR UPDATE;
  v_org_id := v_invoice.organization_id;

  -- Check permission - manager+ for reversals
  IF NOT user_has_role_at_least(v_user_id, v_org_id, 'manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: payment reversal requires manager role');
  END IF;

  -- Calculate new balances
  v_new_paid := GREATEST(COALESCE(v_invoice.amount_paid, 0) - v_payment.amount, 0);

  IF v_new_paid <= 0 THEN
    v_new_status := 'ISSUED';
  ELSIF v_new_paid < v_invoice.total_gross THEN
    v_new_status := 'PART_PAID';
  ELSE
    v_new_status := 'PAID';
  END IF;

  -- Instead of deleting, mark as reversed (soft delete pattern)
  UPDATE invoice_payments SET
    payment_type = 'reversed',
    notes = COALESCE(notes, '') || E'\n[REVERSED] ' || p_reason
  WHERE id = p_payment_id;

  -- Update invoice
  UPDATE invoices SET
    amount_paid = v_new_paid,
    remaining_balance = v_invoice.total_gross - v_new_paid,
    status = v_new_status,
    updated_at = now()
  WHERE id = v_invoice.id;

  -- Write audit log
  PERFORM write_audit_log(
    v_org_id,
    'invoice_payment',
    p_payment_id,
    'reverse',
    'payment_type',
    v_payment.payment_type,
    'reversed',
    to_jsonb(v_payment),
    NULL,
    jsonb_build_object('reason', p_reason, 'invoice_id', v_invoice.id, 'new_status', v_new_status)
  );

  RETURN jsonb_build_object('success', true, 'new_invoice_status', v_new_status);
END;
$$;


--
-- Name: reverse_journal(uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_journal(p_journal_id uuid, p_reversal_date date, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_original_journal RECORD;
  v_new_journal_id UUID;
  v_is_locked BOOLEAN;
  v_line RECORD;
BEGIN
  SELECT * INTO v_original_journal
  FROM public.journals
  WHERE id = p_journal_id;

  IF v_original_journal IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Journal not found');
  END IF;

  IF v_original_journal.is_reversed THEN
    RETURN jsonb_build_object('success', false, 'error', 'Journal has already been reversed');
  END IF;

  IF NOT (auth.role() = 'service_role'
          OR public.user_in_organization(auth.uid(), v_original_journal.organization_id)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized for this organization');
  END IF;

  v_is_locked := public.is_period_locked(
    v_original_journal.organization_id,
    v_original_journal.client_id,
    v_original_journal.company_id,
    p_reversal_date
  );

  IF v_is_locked THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reversal date is in a locked period');
  END IF;

  v_new_journal_id := gen_random_uuid();

  INSERT INTO public.journals (
    id, organization_id, client_id, company_id, journal_date, reference,
    description, journal_type, status, total_debit, total_credit,
    transaction_currency, fx_rate_to_base, reverses_journal_id, created_by
  ) VALUES (
    v_new_journal_id,
    v_original_journal.organization_id,
    v_original_journal.client_id,
    v_original_journal.company_id,
    p_reversal_date,
    'REV-' || v_original_journal.reference,
    COALESCE(p_reason, 'Reversal of ' || v_original_journal.reference),
    'REVERSING',
    'POSTED',
    v_original_journal.total_credit,
    v_original_journal.total_debit,
    v_original_journal.transaction_currency,
    v_original_journal.fx_rate_to_base,
    p_journal_id,
    auth.uid()
  );

  FOR v_line IN
    SELECT * FROM public.journal_lines WHERE journal_id = p_journal_id
  LOOP
    INSERT INTO public.journal_lines (
      journal_id, account_id, debit, credit, description
    ) VALUES (
      v_new_journal_id,
      v_line.account_id,
      v_line.credit,
      v_line.debit,
      'Reversal: ' || COALESCE(v_line.description, '')
    );
  END LOOP;

  INSERT INTO public.ledger_entries (
    organization_id, client_id, company_id, account_id, entry_date, transaction_date,
    debit, credit, description, reference, journal_id, source_type, source_id,
    transaction_currency, transaction_debit, transaction_credit, fx_rate_to_base, base_currency
  )
  SELECT
    organization_id, client_id, company_id, account_id,
    p_reversal_date, p_reversal_date,
    credit, debit,
    'Reversal: ' || COALESCE(description, ''),
    'REV-' || reference,
    v_new_journal_id,
    source_type, source_id,
    transaction_currency, transaction_credit, transaction_debit,
    fx_rate_to_base, base_currency
  FROM public.ledger_entries
  WHERE journal_id = p_journal_id;

  UPDATE public.journals
  SET is_reversed = TRUE, reversal_date = p_reversal_date
  WHERE id = p_journal_id;

  INSERT INTO public.audit_log (
    organization_id, entity_type, entity_id, action, user_id, old_value, new_value, metadata
  ) VALUES (
    v_original_journal.organization_id,
    'journal',
    p_journal_id,
    'reversed',
    auth.uid(),
    p_journal_id::TEXT,
    v_new_journal_id::TEXT,
    jsonb_build_object(
      'reversal_journal_id', v_new_journal_id,
      'reversal_date', p_reversal_date,
      'reason', p_reason
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'reversal_journal_id', v_new_journal_id,
    'message', 'Journal reversed successfully'
  );
END;
$$;


--
-- Name: revert_bank_rule_application(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revert_bank_rule_application(p_bank_transaction_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_txn record;
  v_is_member boolean;
  v_journal_id uuid;
  v_before jsonb;
BEGIN
  IF p_reason IS NULL OR length(trim(p_reason)) < 5 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'reason_required',
                              'error_message', 'A reason of at least 5 characters is required');
  END IF;

  SELECT * INTO v_txn FROM bank_transactions WHERE id = p_bank_transaction_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'transaction_not_found',
                              'error_message', 'Bank transaction not found');
  END IF;

  SELECT user_in_organization(v_actor, v_txn.organization_id) INTO v_is_member;
  IF NOT COALESCE(v_is_member, false) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'forbidden',
                              'error_message', 'Not a member of this organisation');
  END IF;

  IF v_txn.rule_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'no_rule_applied',
                              'error_message', 'Transaction has no rule application to revert');
  END IF;

  IF upper(COALESCE(v_txn.status,'')) = 'RECONCILED' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'reconciled',
                              'error_message', 'Cannot revert a reconciled transaction; reopen the reconciliation first');
  END IF;

  BEGIN
    PERFORM assert_no_locked_period_write(
      v_txn.organization_id, v_txn.client_id, v_txn.company_id, v_txn.transaction_date
    );
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'period_locked',
                              'error_message', SQLERRM);
  END;

  v_before := to_jsonb(v_txn);

  -- If a journal was posted, reverse it via existing helper if available
  SELECT id INTO v_journal_id FROM journals
   WHERE source_type = 'bank_transaction'
     AND source_id = p_bank_transaction_id
     AND COALESCE(is_reversed, false) = false
   ORDER BY created_at DESC
   LIMIT 1;

  IF v_journal_id IS NOT NULL THEN
    BEGIN
      PERFORM reverse_journal(v_journal_id, p_reason);
    EXCEPTION WHEN undefined_function THEN
      UPDATE journals SET is_reversed = true, reversed_at = now(), reversed_by = v_actor,
                          reversal_reason = p_reason
       WHERE id = v_journal_id;
    END;
  END IF;

  UPDATE bank_transactions
     SET status = 'UNREVIEWED',
         rule_id = NULL,
         category = NULL,
         client_suggested_account_id = NULL,
         review_status = NULL
   WHERE id = p_bank_transaction_id;

  INSERT INTO bookkeeping_audit_log(
    organization_id, entity_type, entity_id, action, actor_id,
    before_state, after_state, metadata
  ) VALUES (
    v_txn.organization_id, 'bank_transaction', p_bank_transaction_id,
    'revert_bank_rule_application', v_actor,
    v_before,
    jsonb_build_object('status','UNREVIEWED'),
    jsonb_build_object('reason', p_reason, 'reversed_journal_id', v_journal_id)
  );

  RETURN jsonb_build_object('success', true, 'reversed_journal_id', v_journal_id);
END;
$$;


--
-- Name: revoke_approval_with_audit(uuid, uuid, text, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_approval_with_audit(p_approval_id uuid, p_old_snapshot_id uuid, p_old_snapshot_hash text, p_new_snapshot_id uuid, p_new_snapshot_hash text, p_revocation_reason text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_approval RECORD;
BEGIN
  -- Get approval details
  SELECT * INTO v_approval 
  FROM public.filing_approvals 
  WHERE id = p_approval_id AND revoked_at IS NULL;

  IF v_approval.id IS NULL THEN
    RETURN; -- Already revoked or doesn't exist
  END IF;

  -- Revoke the approval
  UPDATE public.filing_approvals
  SET 
    revoked_at = now(),
    revocation_reason = p_revocation_reason
  WHERE id = p_approval_id AND revoked_at IS NULL;

  -- Log revocation with full audit trail
  INSERT INTO public.approval_revocation_log (
    organization_id,
    approval_id,
    filing_id,
    approval_scope,
    old_snapshot_id,
    old_snapshot_hash,
    new_snapshot_id,
    new_snapshot_hash,
    revocation_reason,
    system_actor,
    metadata
  ) VALUES (
    v_approval.organization_id,
    p_approval_id,
    v_approval.filing_id,
    v_approval.approval_scope,
    p_old_snapshot_id,
    p_old_snapshot_hash,
    p_new_snapshot_id,
    p_new_snapshot_hash,
    p_revocation_reason,
    'SYSTEM',
    p_metadata
  );
END;
$$;


--
-- Name: revoke_approvals_on_snapshot_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_approvals_on_snapshot_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- If accounts snapshot changed, revoke both approvals
  IF OLD.accounts_snapshot_id IS DISTINCT FROM NEW.accounts_snapshot_id THEN
    UPDATE public.filing_approvals
    SET revoked_at = now(), revocation_reason = 'accounts_snapshot_changed'
    WHERE filing_id = NEW.id AND revoked_at IS NULL;
  -- If only CT snapshot changed, revoke CT approval only
  ELSIF OLD.ct_snapshot_id IS DISTINCT FROM NEW.ct_snapshot_id THEN
    UPDATE public.filing_approvals
    SET revoked_at = now(), revocation_reason = 'ct_snapshot_changed'
    WHERE filing_id = NEW.id AND approval_scope = 'CT600' AND revoked_at IS NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: revoke_vat_filing_approval(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_vat_filing_approval(_vat_return_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_ret record;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Not authenticated'); END IF;
  SELECT * INTO v_ret FROM public.vat_returns WHERE id = _vat_return_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'VAT return not found'); END IF;
  IF NOT public.user_in_organization(auth.uid(), v_ret.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;
  IF v_ret.submitted_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'This VAT return has already been submitted');
  END IF;
  UPDATE public.vat_returns
     SET model_snapshot_id = NULL, snapshot_hash = NULL,
         filing_approved_by = NULL, filing_approved_at = NULL, updated_at = now()
   WHERE id = _vat_return_id;
  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: revoke_vat_return_filing_approval(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_vat_return_filing_approval(_vat_return_id uuid, _reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.vat_returns%ROWTYPE;
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Access denied: not authenticated';
  END IF;

  SELECT * INTO v_row FROM public.vat_returns WHERE id = _vat_return_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'VAT return not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = v_row.organization_id AND user_id = v_uid
  ) THEN
    RAISE EXCEPTION 'Access denied: not a member of this organization';
  END IF;

  IF v_row.submitted_at IS NOT NULL THEN
    RAISE EXCEPTION 'VAT return already submitted; cannot revoke approval';
  END IF;

  UPDATE public.vat_returns
     SET filing_approved_at = NULL,
         filing_approved_by = NULL,
         model_snapshot_id = NULL,
         model_snapshot_hash = NULL,
         client_approved_at = NULL,
         client_approved_by = NULL,
         updated_at = now()
   WHERE id = _vat_return_id;

  RETURN jsonb_build_object('ok', true, 'reason', _reason);
END;
$$;


--
-- Name: role_level(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.role_level(r text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE r
    WHEN 'owner' THEN 3
    WHEN 'admin' THEN 2
    WHEN 'staff' THEN 1
    ELSE 0
  END;
$$;


--
-- Name: run_monthly_depreciation(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_monthly_depreciation(p_organization_id uuid, p_company_id uuid, p_period_end date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_asset record;
  v_results jsonb := '[]'::jsonb;
  v_r jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.organization_users WHERE user_id = auth.uid() AND organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'Cross-tenant access denied';
  END IF;

  FOR v_asset IN
    SELECT id FROM public.fixed_assets
     WHERE organization_id = p_organization_id
       AND company_id = p_company_id
       AND status = 'active'
       AND depreciation_method <> 'NONE'
  LOOP
    v_r := public.post_monthly_depreciation(v_asset.id, p_period_end);
    v_results := v_results || jsonb_build_array(jsonb_build_object('asset_id', v_asset.id, 'result', v_r));
  END LOOP;

  RETURN jsonb_build_object('success', true, 'period_end', p_period_end, 'results', v_results);
END; $$;


--
-- Name: save_questionnaire_answer_by_token(uuid, text, text, text, numeric, boolean, date, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_questionnaire_answer_by_token(p_instance_id uuid, p_token text, p_question_id text, p_answer_text text DEFAULT NULL::text, p_answer_number numeric DEFAULT NULL::numeric, p_answer_boolean boolean DEFAULT NULL::boolean, p_answer_date date DEFAULT NULL::date, p_answer_array text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_link public.questionnaire_public_links;
  v_hash TEXT;
BEGIN
  v_link := public._require_valid_questionnaire_link(p_instance_id, p_token);
  v_hash := public._hash_token(p_token);

  -- Check instance is not already submitted
  IF EXISTS (
    SELECT 1 FROM public.questionnaire_instances 
    WHERE id = p_instance_id AND status = 'submitted'
  ) THEN
    RAISE EXCEPTION 'Questionnaire already submitted';
  END IF;

  INSERT INTO public.questionnaire_responses(
    questionnaire_instance_id, 
    question_id, 
    answer_text, 
    answer_number, 
    answer_boolean, 
    answer_date, 
    answer_array
  )
  VALUES (
    p_instance_id, 
    p_question_id, 
    p_answer_text, 
    p_answer_number, 
    p_answer_boolean, 
    p_answer_date, 
    p_answer_array
  )
  ON CONFLICT (questionnaire_instance_id, question_id)
  DO UPDATE SET 
    answer_text = EXCLUDED.answer_text,
    answer_number = EXCLUDED.answer_number,
    answer_boolean = EXCLUDED.answer_boolean,
    answer_date = EXCLUDED.answer_date,
    answer_array = EXCLUDED.answer_array;

  -- Update instance status to in_progress if it was sent
  UPDATE public.questionnaire_instances
  SET status = 'in_progress'
  WHERE id = p_instance_id AND status = 'sent';

  INSERT INTO public.questionnaire_access_log(questionnaire_instance_id, token_hash, action)
  VALUES (p_instance_id, v_hash, 'save');

  RETURN jsonb_build_object('ok', true);
END;
$$;


