--
-- Name: override_bill_lock_safe(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.override_bill_lock_safe(p_bill_id uuid, p_changes jsonb, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_bill RECORD;
  v_org_id UUID;
  v_override_entry JSONB;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_bill FROM bills WHERE id = p_bill_id;
  IF v_bill.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bill not found');
  END IF;

  v_org_id := v_bill.organization_id;
  IF NOT can_override_locked_records(v_user_id, v_org_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: admin+ required');
  END IF;

  IF p_reason IS NULL OR length(trim(p_reason)) < 10 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Override reason must be at least 10 characters');
  END IF;

  v_override_entry := jsonb_build_object(
    'at', now(),
    'by', v_user_id,
    'reason', p_reason,
    'changes', p_changes,
    'before', to_jsonb(v_bill)
  );

  UPDATE bills SET
    supplier_id = COALESCE((p_changes->>'supplier_id')::UUID, supplier_id),
    issue_date = COALESCE((p_changes->>'issue_date')::DATE, issue_date),
    due_date = COALESCE((p_changes->>'due_date')::DATE, due_date),
    total_net = COALESCE((p_changes->>'total_net')::NUMERIC, total_net),
    total_vat = COALESCE((p_changes->>'total_vat')::NUMERIC, total_vat),
    total_gross = COALESCE((p_changes->>'total_gross')::NUMERIC, total_gross),
    notes = COALESCE(p_changes->>'notes', notes),
    override_history = COALESCE(override_history, '[]'::jsonb) || v_override_entry,
    updated_at = now()
  WHERE id = p_bill_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata, actor_role)
  VALUES (v_org_id, 'bill', p_bill_id, 'lock_overridden', v_user_id,
    jsonb_build_object('reason', p_reason, 'changes', p_changes),
    (SELECT role FROM organization_users WHERE user_id = v_user_id AND organization_id = v_org_id LIMIT 1));

  RETURN jsonb_build_object('success', true, 'bill_id', p_bill_id);
END;
$$;


--
-- Name: override_invoice_lock_safe(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.override_invoice_lock_safe(p_invoice_id uuid, p_changes jsonb, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice RECORD;
  v_user_id UUID;
  v_org_id UUID;
  v_before_state JSONB;
  v_override_entry JSONB;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF p_reason IS NULL OR p_reason = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reason is required for lock override');
  END IF;

  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
  END IF;

  v_org_id := v_invoice.organization_id;

  -- Check permission - admin/owner only
  IF NOT can_override_invoice_lock(v_user_id, v_org_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: only admin/owner can override locks');
  END IF;

  v_before_state := to_jsonb(v_invoice);

  -- Build override history entry
  v_override_entry := jsonb_build_object(
    'timestamp', now(),
    'user_id', v_user_id,
    'reason', p_reason,
    'changes', p_changes,
    'before_values', jsonb_build_object()
  );

  -- Apply changes (this is intentionally permissive for admin override)
  UPDATE invoices SET
    customer_id = COALESCE((p_changes->>'customer_id')::UUID, customer_id),
    contact_name = COALESCE(p_changes->>'contact_name', contact_name),
    contact_email = COALESCE(p_changes->>'contact_email', contact_email),
    issue_date = COALESCE((p_changes->>'issue_date')::DATE, issue_date),
    due_date = COALESCE((p_changes->>'due_date')::DATE, due_date),
    notes = COALESCE(p_changes->>'notes', notes),
    override_history = COALESCE(override_history, '[]'::JSONB) || v_override_entry,
    updated_at = now()
  WHERE id = p_invoice_id;

  -- Write detailed audit log
  PERFORM write_audit_log(
    v_org_id,
    'invoice',
    p_invoice_id,
    'override_lock',
    NULL,
    NULL,
    NULL,
    v_before_state,
    (SELECT to_jsonb(i) FROM invoices i WHERE i.id = p_invoice_id),
    jsonb_build_object('changes', p_changes, 'reason', p_reason, 'override_type', 'admin_override')
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


