--
-- Name: port_quote_to_client(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.port_quote_to_client(p_quote_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_quote record;
  v_lead record;
  v_client_id uuid;
  v_org_id uuid;
BEGIN
  SELECT * INTO v_quote FROM public.quotes WHERE id = p_quote_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Quote not found'; END IF;
  IF v_quote.ported_to_client_id IS NOT NULL THEN RETURN v_quote.ported_to_client_id; END IF;
  v_org_id := v_quote.organization_id;
  IF NOT user_has_organization_access(v_org_id) THEN RAISE EXCEPTION 'Not authorised'; END IF;

  v_client_id := v_quote.client_id;
  IF v_client_id IS NULL THEN
    IF v_quote.lead_id IS NULL THEN RAISE EXCEPTION 'Quote has no client or lead to port from'; END IF;
    SELECT * INTO v_lead FROM public.leads WHERE id = v_quote.lead_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Lead not found'; END IF;

    SELECT id INTO v_client_id FROM public.clients
      WHERE organization_id = v_org_id AND lower(email) = lower(v_lead.email)
      LIMIT 1;

    IF v_client_id IS NULL THEN
      INSERT INTO public.clients (organization_id, first_name, last_name, email, phone, client_type, status)
      VALUES (v_org_id, v_lead.first_name, v_lead.last_name, v_lead.email, v_lead.phone,
              coalesce(v_lead.lead_type,'other'), 'pending')
      RETURNING id INTO v_client_id;
    END IF;
  END IF;

  UPDATE public.quotes SET ported_to_client_id = v_client_id, ported_at = now(), client_id = v_client_id WHERE id = p_quote_id;

  INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, new_value, metadata)
  VALUES (v_org_id, 'CLIENT_ONBOARDING_STARTED', 'client', v_client_id,
          jsonb_build_object('quote_id', p_quote_id),
          jsonb_build_object('source','port_quote_to_client'));

  RETURN v_client_id;
END;
$$;


--
-- Name: portal_approve_vat_return(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_approve_vat_return(_vat_return_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ret public.vat_returns%ROWTYPE;
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT * INTO v_ret FROM public.vat_returns WHERE id = _vat_return_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'vat_return_not_found'; END IF;

  IF NOT public.portal_has_perm(v_ret.client_id, v_ret.company_id, 'allow_vat_approval') THEN
    RAISE EXCEPTION 'permission_denied';
  END IF;

  IF NOT COALESCE(v_ret.client_approval_required, false) THEN
    RAISE EXCEPTION 'approval_not_requested';
  END IF;

  IF v_ret.client_approved_at IS NOT NULL THEN
    RAISE EXCEPTION 'already_approved';
  END IF;

  UPDATE public.vat_returns
     SET client_approved_at = now(),
         client_approved_by = v_uid,
         updated_at         = now()
   WHERE id = _vat_return_id;

  INSERT INTO public.bookkeeping_audit_log
    (organization_id, entity_type, entity_id, action, actor_id, actor_role, after_state, metadata)
  VALUES (
    v_ret.organization_id,
    CASE WHEN v_ret.client_id IS NOT NULL THEN 'client' ELSE 'company' END,
    COALESCE(v_ret.client_id, v_ret.company_id),
    'portal.vat_return.approved',
    v_uid,
    'portal_client',
    jsonb_build_object('vat_return_id', _vat_return_id),
    jsonb_build_object('source','portal')
  );

  RETURN _vat_return_id;
END
$$;


