--
-- Name: portal_categorise_transaction(uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_categorise_transaction(p_bank_transaction_id uuid, p_contra_account_id uuid, p_vat_code_id uuid DEFAULT NULL::uuid, p_vat_amount numeric DEFAULT 0, p_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client  uuid;
  v_company uuid;
  v_result  jsonb;
BEGIN
  SELECT client_id, company_id INTO v_client, v_company
  FROM public.bank_transactions WHERE id = p_bank_transaction_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transaction not found';
  END IF;

  IF NOT public.portal_has_perm(v_client, v_company, 'allow_client_post_to_ledger') THEN
    RAISE EXCEPTION 'Not permitted to categorise transactions' USING ERRCODE = '42501';
  END IF;

  v_result := public.post_bank_transaction(
    p_bank_transaction_id, p_contra_account_id, p_vat_code_id, p_vat_amount, p_description);

  IF COALESCE((v_result->>'success')::boolean, false) THEN
    UPDATE public.bank_transactions
       SET client_explained_by     = auth.uid(),
           client_explained_status = 'client_posted'
     WHERE id = p_bank_transaction_id;
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: portal_explain_transaction(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_explain_transaction(_transaction_id uuid, _explanation text, _suggested_account_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_txn public.bank_transactions%ROWTYPE;
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT * INTO v_txn FROM public.bank_transactions WHERE id = _transaction_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'transaction_not_found'; END IF;

  IF NOT public.portal_has_perm(v_txn.client_id, v_txn.company_id, 'allow_transaction_explain') THEN
    RAISE EXCEPTION 'permission_denied';
  END IF;

  UPDATE public.bank_transactions
     SET client_explanation          = _explanation,
         client_suggested_account_id = _suggested_account_id,
         client_explained_status     = 'client_explained',
         client_explained_at         = now(),
         client_explained_by         = v_uid,
         updated_at                  = now()
   WHERE id = _transaction_id;

  INSERT INTO public.bookkeeping_audit_log
    (organization_id, entity_type, entity_id, action, actor_id, actor_role, after_state, metadata)
  VALUES (
    v_txn.organization_id,
    CASE WHEN v_txn.client_id IS NOT NULL THEN 'client' ELSE 'company' END,
    COALESCE(v_txn.client_id, v_txn.company_id),
    'portal.transaction.explained',
    v_uid,
    'portal_client',
    jsonb_build_object(
      'transaction_id', _transaction_id,
      'explanation', _explanation,
      'suggested_account_id', _suggested_account_id
    ),
    jsonb_build_object('source','portal')
  );

  RETURN _transaction_id;
END
$$;


