--
-- Name: portal_has_perm(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_has_perm(_client_id uuid, _company_id uuid, _permission text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v boolean; v_master boolean; v_settings_col text;
BEGIN
  -- Hard accountant-only — never granted to portal regardless of settings
  IF _permission IN (
    'vat.submit','filings.submit','periods.close','lock_dates.manage',
    'journals.create','workpapers.finalise','org.settings'
  ) THEN
    RETURN false;
  END IF;

  -- Known permissions (legacy + new)
  IF _permission NOT IN (
    'allow_bank_connect','allow_transaction_explain','allow_receipt_upload',
    'allow_invoice_create','allow_invoice_send','show_bills','allow_bill_create',
    'show_vat_returns','allow_vat_approval',
    'show_reports_summary','show_reports_detail','allow_reports_download',
    'show_bank_accounts','show_transactions','show_invoices','show_trial_balance',
    'show_detailed_ledger','full_bookkeeping',
    'allow_customer_create','allow_supplier_create','allow_receipt_match','allow_query_respond',
    'allow_client_reconcile','allow_client_post_to_ledger'
  ) THEN RETURN false; END IF;

  IF NOT public.portal_can_access_bookkeeping(_client_id, _company_id) THEN RETURN false; END IF;

  IF _client_id IS NOT NULL THEN
    SELECT COALESCE(full_bookkeeping_access, false) INTO v_master
      FROM public.portal_visibility_settings WHERE client_id = _client_id LIMIT 1;
  ELSIF _company_id IS NOT NULL THEN
    SELECT COALESCE(full_bookkeeping_access, false) INTO v_master
      FROM public.portal_visibility_settings WHERE company_id = _company_id LIMIT 1;
  END IF;

  IF COALESCE(v_master, false) THEN RETURN true; END IF;
  IF _permission = 'full_bookkeeping' THEN RETURN false; END IF;

  IF _client_id IS NOT NULL THEN
    EXECUTE format('SELECT COALESCE(%I, false) FROM public.portal_visibility_settings WHERE client_id = $1 LIMIT 1', _permission)
      INTO v USING _client_id;
  ELSIF _company_id IS NOT NULL THEN
    EXECUTE format('SELECT COALESCE(%I, false) FROM public.portal_visibility_settings WHERE company_id = $1 LIMIT 1', _permission)
      INTO v USING _company_id;
  ELSE RETURN false; END IF;

  RETURN COALESCE(v, false);
END $_$;


--
-- Name: portal_list_ledger_accounts(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_list_ledger_accounts(p_client_id uuid, p_company_id uuid) RETURNS TABLE(id uuid, code text, name text, account_type text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  IF NOT public.portal_can_access_bookkeeping(p_client_id, p_company_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_client_id IS NOT NULL THEN
    SELECT organization_id INTO v_org FROM public.clients WHERE id = p_client_id;
  ELSE
    SELECT organization_id INTO v_org FROM public.companies WHERE id = p_company_id;
  END IF;

  RETURN QUERY
    SELECT a.id, a.code, a.name, a.account_type
    FROM public.bookkeeping_accounts a
    WHERE a.organization_id = v_org
      AND COALESCE(a.is_active, true) = true
      AND COALESCE(a.is_bank_account, false) = false
    ORDER BY a.account_type, a.code;
END;
$$;


--
-- Name: portal_send_message(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_send_message(p_client_id uuid, p_company_id uuid, p_body text, p_subject text DEFAULT NULL::text, p_parent_message_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_id  uuid;
BEGIN
  IF p_body IS NULL OR length(btrim(p_body)) = 0 THEN
    RAISE EXCEPTION 'Message body is required';
  END IF;

  IF (p_client_id IS NULL) = (p_company_id IS NULL) THEN
    RAISE EXCEPTION 'Provide exactly one of client or company';
  END IF;

  IF NOT public.client_has_portal_access(auth.uid(), p_client_id, p_company_id) THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;

  IF p_client_id IS NOT NULL THEN
    SELECT organization_id INTO v_org FROM public.clients WHERE id = p_client_id;
  ELSE
    SELECT organization_id INTO v_org FROM public.companies WHERE id = p_company_id;
  END IF;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Entity not found';
  END IF;

  INSERT INTO public.client_messages (
    organization_id, client_id, company_id, sender_id, sender_type,
    message_type, visibility, content, subject, parent_message_id
  ) VALUES (
    v_org, p_client_id, p_company_id, auth.uid(), 'client',
    'message', 'client_visible', btrim(p_body), p_subject, p_parent_message_id
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: portal_user_has_entity_access(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_user_has_entity_access(_user_id uuid, _client_id uuid, _company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.portal_access pa
    WHERE pa.user_id = _user_id AND pa.is_active = true
      AND ((_client_id IS NOT NULL AND pa.client_id = _client_id)
        OR (_company_id IS NOT NULL AND pa.company_id = _company_id))
  );
$$;


--
-- Name: post_bank_transaction(uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_bank_transaction(p_bank_transaction_id uuid, p_contra_account_id uuid, p_vat_code_id uuid DEFAULT NULL::uuid, p_vat_amount numeric DEFAULT 0, p_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_txn record;
  v_bank record;
  v_bank_account_ledger_id uuid;
  v_vat_account_id uuid;
  v_org_settings record;
  v_amount numeric;
  v_gross numeric;
  v_net numeric;
  v_vat numeric;
  v_entries jsonb;
  v_result jsonb;
  v_journal_id uuid;
  v_actor uuid := auth.uid();
  v_is_receive boolean;
BEGIN
  -- Load transaction
  SELECT * INTO v_txn FROM bank_transactions WHERE id = p_bank_transaction_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'transaction_not_found',
                              'error_message', 'Bank transaction not found');
  END IF;

  IF upper(COALESCE(v_txn.status,'')) IN ('MATCHED','RECONCILED') THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'already_matched',
                              'error_message', 'Transaction is already matched');
  END IF;

  -- Load bank account and its ledger account
  SELECT * INTO v_bank FROM bank_accounts WHERE id = v_txn.bank_account_id;
  IF NOT FOUND OR v_bank.account_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'bank_account_unmapped',
                              'error_message', 'Bank account is not mapped to a ledger account');
  END IF;
  v_bank_account_ledger_id := v_bank.account_id;

  -- VAT split
  v_gross := abs(v_txn.amount);
  v_vat   := COALESCE(p_vat_amount, 0);
  IF v_vat < 0 OR v_vat > v_gross THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'invalid_vat_amount',
                              'error_message', 'VAT amount must be between zero and the gross amount');
  END IF;
  v_net := v_gross - v_vat;
  v_is_receive := v_txn.amount > 0;

  -- VAT control account (from org_settings)
  IF v_vat > 0 THEN
    SELECT * INTO v_org_settings FROM org_settings
      WHERE organization_id = v_txn.organization_id LIMIT 1;
    v_vat_account_id := v_org_settings.vat_control_account_id;
    IF v_vat_account_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'vat_control_not_set',
                                'error_message', 'VAT control account is not configured for this organisation');
    END IF;
  END IF;

  -- Build entries:
  --   RECEIVE: Dr Bank (gross), Cr Contra (net) [, Cr VAT (vat)]
  --   SPEND:   Dr Contra (net) [, Dr VAT (vat)], Cr Bank (gross)
  IF v_is_receive THEN
    v_entries := jsonb_build_array(
      jsonb_build_object('account_id', v_bank_account_ledger_id, 'debit', v_gross,
                         'description', COALESCE(p_description, v_txn.description)),
      jsonb_build_object('account_id', p_contra_account_id, 'credit', v_net,
                         'vat_code_id', p_vat_code_id,
                         'description', COALESCE(p_description, v_txn.description))
    );
    IF v_vat > 0 THEN
      v_entries := v_entries || jsonb_build_array(
        jsonb_build_object('account_id', v_vat_account_id, 'credit', v_vat,
                           'vat_code_id', p_vat_code_id,
                           'description', 'VAT on ' || COALESCE(p_description, v_txn.description))
      );
    END IF;
  ELSE
    v_entries := jsonb_build_array(
      jsonb_build_object('account_id', p_contra_account_id, 'debit', v_net,
                         'vat_code_id', p_vat_code_id,
                         'description', COALESCE(p_description, v_txn.description))
    );
    IF v_vat > 0 THEN
      v_entries := v_entries || jsonb_build_array(
        jsonb_build_object('account_id', v_vat_account_id, 'debit', v_vat,
                           'vat_code_id', p_vat_code_id,
                           'description', 'VAT on ' || COALESCE(p_description, v_txn.description))
      );
    END IF;
    v_entries := v_entries || jsonb_build_array(
      jsonb_build_object('account_id', v_bank_account_ledger_id, 'credit', v_gross,
                         'description', COALESCE(p_description, v_txn.description))
    );
  END IF;

  v_result := post_to_ledger(
    v_txn.organization_id, v_txn.client_id, v_txn.company_id,
    v_txn.transaction_date,
    COALESCE(NULLIF(v_txn.description, ''), 'Bank transaction'),
    COALESCE(p_description, v_txn.description, 'Bank transaction'),
    CASE WHEN v_is_receive THEN 'BANK_RECEIVE' ELSE 'BANK_SPEND' END,
    'BANK_TRANSACTION', p_bank_transaction_id,
    COALESCE(v_txn.currency, 'GBP'), 1.0, v_actor, v_entries
  );

  IF NOT COALESCE((v_result->>'success')::boolean, false) THEN
    RETURN v_result;
  END IF;

  v_journal_id := (v_result->>'journal_id')::uuid;

  UPDATE bank_transactions
     SET status = 'MATCHED',
         matched_ledger_entry_id = (
           SELECT id FROM ledger_entries
            WHERE journal_id = v_journal_id AND account_id = v_bank_account_ledger_id
            LIMIT 1
         ),
         updated_at = now()
   WHERE id = p_bank_transaction_id;

  RETURN jsonb_build_object('success', true, 'journal_id', v_journal_id);
END;
$$;


--
-- Name: post_bank_transfer(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_bank_transfer(p_source_transaction_id uuid, p_destination_bank_account_id uuid, p_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_txn record;
  v_src record;
  v_dst record;
  v_entries jsonb;
  v_result jsonb;
  v_actor uuid := auth.uid();
  v_amount numeric;
BEGIN
  SELECT * INTO v_txn FROM bank_transactions WHERE id = p_source_transaction_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'transaction_not_found',
                              'error_message', 'Bank transaction not found');
  END IF;
  IF upper(COALESCE(v_txn.status,'')) IN ('MATCHED','RECONCILED') THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'already_matched',
                              'error_message', 'Transaction is already matched');
  END IF;

  SELECT * INTO v_src FROM bank_accounts WHERE id = v_txn.bank_account_id;
  SELECT * INTO v_dst FROM bank_accounts WHERE id = p_destination_bank_account_id;
  IF v_src IS NULL OR v_dst IS NULL OR v_src.account_id IS NULL OR v_dst.account_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'bank_account_unmapped',
                              'error_message', 'Source or destination bank account is unmapped');
  END IF;
  IF v_src.organization_id <> v_dst.organization_id THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'cross_org_transfer',
                              'error_message', 'Transfers across organisations are not permitted');
  END IF;

  v_amount := abs(v_txn.amount);

  -- If source amount is negative (money out), src is source; otherwise reverse.
  IF v_txn.amount < 0 THEN
    v_entries := jsonb_build_array(
      jsonb_build_object('account_id', v_dst.account_id, 'debit',  v_amount,
                         'description', COALESCE(p_description, 'Transfer to ' || v_dst.name)),
      jsonb_build_object('account_id', v_src.account_id, 'credit', v_amount,
                         'description', COALESCE(p_description, 'Transfer from ' || v_src.name))
    );
  ELSE
    v_entries := jsonb_build_array(
      jsonb_build_object('account_id', v_src.account_id, 'debit',  v_amount,
                         'description', COALESCE(p_description, 'Transfer into ' || v_src.name)),
      jsonb_build_object('account_id', v_dst.account_id, 'credit', v_amount,
                         'description', COALESCE(p_description, 'Transfer out of ' || v_dst.name))
    );
  END IF;

  v_result := post_to_ledger(
    v_txn.organization_id, v_txn.client_id, v_txn.company_id,
    v_txn.transaction_date,
    'Bank transfer',
    COALESCE(p_description, 'Bank transfer'),
    'BANK_TRANSFER',
    'BANK_TRANSACTION', p_source_transaction_id,
    COALESCE(v_txn.currency, 'GBP'), 1.0, v_actor, v_entries
  );

  IF NOT COALESCE((v_result->>'success')::boolean, false) THEN
    RETURN v_result;
  END IF;

  UPDATE bank_transactions
     SET status = 'MATCHED', updated_at = now()
   WHERE id = p_source_transaction_id;

  RETURN v_result;
END;
$$;


--
-- Name: post_monthly_depreciation(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_monthly_depreciation(p_asset_id uuid, p_period_end date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_asset public.fixed_assets%ROWTYPE;
  v_user uuid := auth.uid();
  v_period_start date := date_trunc('month', p_period_end)::date;
  v_period_end date := (date_trunc('month', p_period_end) + interval '1 month - 1 day')::date;
  v_reference text;
  v_existing uuid;
  v_dep_acct uuid;
  v_accum_acct uuid;
  v_asset_acct uuid;
  v_depreciable numeric;
  v_charge numeric := 0;
  v_remaining numeric;
  v_entries jsonb;
  v_result jsonb;
BEGIN
  SELECT * INTO v_asset FROM public.fixed_assets WHERE id = p_asset_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Asset not found'; END IF;

  IF NOT public.has_role(v_user, 'owner') AND NOT public.has_role(v_user, 'admin') AND NOT public.has_role(v_user, 'staff') THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.organization_users WHERE user_id = v_user AND organization_id = v_asset.organization_id) THEN
    RAISE EXCEPTION 'Cross-tenant access denied';
  END IF;

  IF v_asset.status <> 'active' THEN
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'asset_not_active');
  END IF;

  IF v_asset.depreciation_method = 'NONE' THEN
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'no_depreciation');
  END IF;

  IF v_asset.depreciation_start_date IS NULL OR v_period_end < v_asset.depreciation_start_date THEN
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'before_start_date');
  END IF;

  v_reference := 'DEPN-' || p_asset_id::text || '-' || to_char(v_period_end, 'YYYYMM');
  SELECT id INTO v_existing FROM public.journals
    WHERE organization_id = v_asset.organization_id AND source_type = 'DEPRECIATION' AND reference = v_reference;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'already_posted', 'journal_id', v_existing);
  END IF;

  v_dep_acct := COALESCE(v_asset.depreciation_expense_account_id,
    (SELECT depreciation_expense_account_id FROM public.org_settings WHERE organization_id = v_asset.organization_id LIMIT 1));
  v_accum_acct := COALESCE(v_asset.accumulated_depreciation_account_id,
    (SELECT accumulated_depreciation_account_id FROM public.org_settings WHERE organization_id = v_asset.organization_id LIMIT 1));
  v_asset_acct := v_asset.fixed_asset_account_id;

  IF v_dep_acct IS NULL OR v_accum_acct IS NULL THEN
    RAISE EXCEPTION 'Depreciation expense or accumulated depreciation account not configured';
  END IF;

  v_depreciable := GREATEST(v_asset.cost - COALESCE(v_asset.residual_value,0), 0);
  v_remaining := GREATEST(v_depreciable - COALESCE(v_asset.accumulated_depreciation,0), 0);

  IF v_asset.depreciation_method = 'SL' THEN
    IF v_asset.useful_life_months IS NULL OR v_asset.useful_life_months <= 0 THEN
      RAISE EXCEPTION 'Useful life (months) required for straight-line';
    END IF;
    v_charge := round(v_depreciable / v_asset.useful_life_months, 2);
  ELSIF v_asset.depreciation_method = 'RB' THEN
    IF v_asset.depreciation_rate_pct IS NULL OR v_asset.depreciation_rate_pct <= 0 THEN
      RAISE EXCEPTION 'Depreciation rate required for reducing balance';
    END IF;
    v_charge := round((v_asset.cost - COALESCE(v_asset.accumulated_depreciation,0)) * (v_asset.depreciation_rate_pct/100.0) / 12.0, 2);
  END IF;

  v_charge := LEAST(v_charge, v_remaining);

  IF v_charge <= 0 THEN
    UPDATE public.fixed_assets SET status='fully_depreciated', updated_at=now() WHERE id=p_asset_id;
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'fully_depreciated');
  END IF;

  v_entries := jsonb_build_array(
    jsonb_build_object('account_id', v_dep_acct, 'debit', v_charge, 'credit', 0,
                       'description', 'Depreciation: ' || v_asset.asset_name),
    jsonb_build_object('account_id', v_accum_acct, 'debit', 0, 'credit', v_charge,
                       'description', 'Accumulated depreciation: ' || v_asset.asset_name)
  );

  v_result := public.post_to_ledger(
    p_organization_id := v_asset.organization_id,
    p_client_id       := NULL,
    p_company_id      := v_asset.company_id,
    p_journal_date    := v_period_end,
    p_reference       := v_reference,
    p_description     := 'Monthly depreciation - ' || v_asset.asset_name,
    p_journal_type    := 'DEPRECIATION',
    p_source_type     := 'DEPRECIATION',
    p_source_id       := p_asset_id,
    p_currency        := 'GBP',
    p_fx_rate         := 1.0,
    p_created_by      := v_user,
    p_entries         := v_entries,
    p_lock_override_reason := NULL,
    p_idempotency_key := v_reference
  );

  IF (v_result->>'success')::boolean IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'post_to_ledger failed: %', v_result->>'error';
  END IF;

  UPDATE public.fixed_assets
     SET accumulated_depreciation = COALESCE(accumulated_depreciation,0) + v_charge,
         last_depreciation_date = v_period_end,
         status = CASE WHEN COALESCE(accumulated_depreciation,0) + v_charge >= v_depreciable
                       THEN 'fully_depreciated' ELSE status END,
         updated_at = now()
   WHERE id = p_asset_id;

  INSERT INTO public.bookkeeping_audit_log(organization_id, entity_type, entity_id, action, actor_id, after_state)
  VALUES (v_asset.organization_id, 'fixed_asset', p_asset_id, 'post_depreciation', v_user,
          jsonb_build_object('period_end', v_period_end, 'charge', v_charge, 'journal_id', v_result->>'journal_id'));

  RETURN jsonb_build_object('success', true, 'charge', v_charge, 'journal_id', v_result->>'journal_id', 'period_end', v_period_end);
END; $$;


--
-- Name: post_to_ledger(uuid, uuid, uuid, date, text, text, text, text, uuid, text, numeric, uuid, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_to_ledger(p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_journal_date date, p_reference text, p_description text, p_journal_type text, p_source_type text, p_source_id uuid, p_currency text DEFAULT 'GBP'::text, p_fx_rate numeric DEFAULT 1.0, p_created_by uuid DEFAULT NULL::uuid, p_entries jsonb DEFAULT '[]'::jsonb, p_lock_override_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_journal_id uuid;
  v_total_debit numeric := 0;
  v_total_credit numeric := 0;
  v_entry jsonb;
  v_line_number int := 0;
  v_ledger_ids uuid[] := '{}';
  v_ledger_id uuid;
  v_lock_date date;
  v_actor uuid := COALESCE(p_created_by, auth.uid());
  v_is_admin boolean;
  v_account_record record;
  v_dup_count int;
  v_err_code text;
  v_err_msg text;
  v_entity_type text;
  v_entity_id uuid;
  v_debit numeric;
  v_credit numeric;
  v_account_id uuid;
  v_allow_duplicate_sources text[] :=
    ARRAY['JOURNAL','REVERSAL','PAYMENT','CREDIT_NOTE','VAT_ADJUSTMENT','OPENING_BALANCE_REVERSAL'];
BEGIN
  -- ---- Header validations ---------------------------------------------------
  IF p_organization_id IS NULL THEN
    v_err_code := 'missing_organization'; v_err_msg := 'organization_id is required';
    PERFORM 1; RAISE EXCEPTION '%', v_err_msg;
  END IF;

  IF (p_client_id IS NULL AND p_company_id IS NULL)
     OR (p_client_id IS NOT NULL AND p_company_id IS NOT NULL) THEN
    v_err_code := 'invalid_entity_scope';
    v_err_msg  := 'Exactly one of client_id or company_id must be provided';
    RAISE EXCEPTION '%', v_err_msg;
  END IF;

  v_entity_type := CASE WHEN p_client_id IS NOT NULL THEN 'client' ELSE 'company' END;
  v_entity_id   := COALESCE(p_client_id, p_company_id);

  -- caller must belong to organization (defense in depth; RPC is SECURITY DEFINER)
  IF v_actor IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM organization_users
       WHERE organization_id = p_organization_id AND user_id = v_actor
     ) THEN
    v_err_code := 'cross_tenant';
    v_err_msg  := 'Caller is not a member of the target organization';
    RAISE EXCEPTION '%', v_err_msg;
  END IF;

  IF jsonb_array_length(COALESCE(p_entries, '[]'::jsonb)) < 2 THEN
    v_err_code := 'insufficient_lines';
    v_err_msg  := 'At least two ledger lines are required';
    RAISE EXCEPTION '%', v_err_msg;
  END IF;

  -- ---- Line validations + totals -------------------------------------------
  FOR v_entry IN SELECT * FROM jsonb_array_elements(p_entries) LOOP
    v_account_id := (v_entry->>'account_id')::uuid;
    v_debit  := COALESCE((v_entry->>'debit')::numeric,  0);
    v_credit := COALESCE((v_entry->>'credit')::numeric, 0);

    IF v_account_id IS NULL THEN
      v_err_code := 'missing_account';
      v_err_msg  := 'Every line requires account_id';
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    IF v_debit < 0 OR v_credit < 0 THEN
      v_err_code := 'negative_amount';
      v_err_msg  := 'Negative debit or credit values are not permitted';
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    IF (v_debit > 0 AND v_credit > 0) OR (v_debit = 0 AND v_credit = 0) THEN
      v_err_code := 'invalid_line';
      v_err_msg  := 'Each line must have exactly one of debit or credit set';
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    SELECT id, organization_id, client_id, company_id, is_active, is_system_account
      INTO v_account_record
      FROM bookkeeping_accounts
     WHERE id = v_account_id;

    IF NOT FOUND THEN
      v_err_code := 'account_not_found';
      v_err_msg  := format('Account %s does not exist', v_account_id);
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    IF v_account_record.organization_id <> p_organization_id THEN
      v_err_code := 'account_scope_mismatch';
      v_err_msg  := 'Account belongs to a different organization';
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    -- system accounts (org-scoped templates) may have null entity; entity-specific must match
    IF v_account_record.client_id IS NOT NULL
       AND v_account_record.client_id IS DISTINCT FROM p_client_id THEN
      v_err_code := 'account_scope_mismatch';
      v_err_msg  := 'Account is scoped to a different client';
      RAISE EXCEPTION '%', v_err_msg;
    END IF;
    IF v_account_record.company_id IS NOT NULL
       AND v_account_record.company_id IS DISTINCT FROM p_company_id THEN
      v_err_code := 'account_scope_mismatch';
      v_err_msg  := 'Account is scoped to a different company';
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    IF COALESCE(v_account_record.is_active, true) = false THEN
      v_err_code := 'account_inactive';
      v_err_msg  := 'Posting to an inactive account is not permitted';
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    v_total_debit  := v_total_debit  + v_debit;
    v_total_credit := v_total_credit + v_credit;
  END LOOP;

  IF round(v_total_debit, 2) <> round(v_total_credit, 2) THEN
    v_err_code := 'unbalanced';
    v_err_msg  := format('Journal is unbalanced: debits %s != credits %s',
                         v_total_debit, v_total_credit);
    RAISE EXCEPTION '%', v_err_msg;
  END IF;

  -- ---- Period lock enforcement ---------------------------------------------
  SELECT MAX(lock_date) INTO v_lock_date
    FROM period_locks
   WHERE organization_id = p_organization_id
     AND ((p_client_id  IS NOT NULL AND client_id  = p_client_id)
       OR (p_company_id IS NOT NULL AND company_id = p_company_id));

  IF v_lock_date IS NOT NULL AND p_journal_date <= v_lock_date THEN
    IF p_lock_override_reason IS NULL
       OR length(btrim(p_lock_override_reason)) = 0 THEN
      v_err_code := 'period_locked';
      v_err_msg  := format('Period is locked through %s; override reason required', v_lock_date);
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    SELECT (has_organization_role(p_organization_id, 'owner')
         OR has_organization_role(p_organization_id, 'admin'))
      INTO v_is_admin;

    IF NOT COALESCE(v_is_admin, false) THEN
      v_err_code := 'period_locked_no_role';
      v_err_msg  := 'Only owners/admins may override a locked period';
      RAISE EXCEPTION '%', v_err_msg;
    END IF;

    INSERT INTO bookkeeping_audit_log
      (organization_id, entity_type, entity_id, action, actor_id, reason, metadata)
    VALUES (p_organization_id, v_entity_type, v_entity_id, 'period_lock_override',
            v_actor, p_lock_override_reason,
            jsonb_build_object('journal_date', p_journal_date, 'lock_date', v_lock_date,
                               'source_type', p_source_type, 'source_id', p_source_id));
  END IF;

  -- ---- Duplicate-source guard ----------------------------------------------
  IF p_source_id IS NOT NULL
     AND NOT (upper(COALESCE(p_source_type,'')) = ANY (v_allow_duplicate_sources)) THEN
    SELECT count(*) INTO v_dup_count
      FROM journals
     WHERE organization_id = p_organization_id
       AND ((p_client_id IS NOT NULL AND client_id = p_client_id)
         OR (p_company_id IS NOT NULL AND company_id = p_company_id))
       AND id IN (
         SELECT journal_id FROM ledger_entries
          WHERE source_type = p_source_type AND source_id = p_source_id
       );

    IF v_dup_count > 0 THEN
      v_err_code := 'duplicate_source';
      v_err_msg  := format('Source %s/%s already posted', p_source_type, p_source_id);
      RAISE EXCEPTION '%', v_err_msg;
    END IF;
  END IF;

  -- ---- Persist journal + lines + ledger entries ----------------------------
  INSERT INTO journals
    (organization_id, client_id, company_id, journal_date, reference, description,
     journal_type, total_debit, total_credit, transaction_currency, fx_rate_to_base,
     is_posted, posted_at, created_by)
  VALUES
    (p_organization_id, p_client_id, p_company_id, p_journal_date, p_reference, p_description,
     p_journal_type, v_total_debit, v_total_credit, p_currency, p_fx_rate,
     true, now(), v_actor)
  RETURNING id INTO v_journal_id;

  FOR v_entry IN SELECT * FROM jsonb_array_elements(p_entries) LOOP
    v_line_number := v_line_number + 1;
    v_debit  := NULLIF(COALESCE((v_entry->>'debit')::numeric,  0), 0);
    v_credit := NULLIF(COALESCE((v_entry->>'credit')::numeric, 0), 0);

    INSERT INTO journal_lines
      (journal_id, line_number, account_id, debit, credit, vat_code_id, description)
    VALUES
      (v_journal_id, v_line_number, (v_entry->>'account_id')::uuid,
       v_debit, v_credit, (v_entry->>'vat_code_id')::uuid, v_entry->>'description');

    INSERT INTO ledger_entries
      (organization_id, client_id, company_id, transaction_date, entry_date,
       account_id, debit, credit, description, reference, journal_id,
       source_type, source_id, vat_code_id, transaction_currency,
       transaction_debit, transaction_credit, fx_rate_to_base, base_currency, created_by)
    VALUES
      (p_organization_id, p_client_id, p_company_id, p_journal_date, p_journal_date,
       (v_entry->>'account_id')::uuid,
       CASE WHEN v_debit  IS NULL THEN NULL ELSE v_debit  * p_fx_rate END,
       CASE WHEN v_credit IS NULL THEN NULL ELSE v_credit * p_fx_rate END,
       v_entry->>'description', p_reference, v_journal_id,
       p_source_type, p_source_id, (v_entry->>'vat_code_id')::uuid, p_currency,
       v_debit, v_credit, p_fx_rate, 'GBP', v_actor)
    RETURNING id INTO v_ledger_id;
    v_ledger_ids := v_ledger_ids || v_ledger_id;
  END LOOP;

  INSERT INTO bookkeeping_audit_log
    (organization_id, entity_type, entity_id, action, actor_id, after_state, metadata)
  VALUES
    (p_organization_id, v_entity_type, v_entity_id, 'ledger_post', v_actor,
     jsonb_build_object('journal_id', v_journal_id, 'total_debit', v_total_debit,
                        'total_credit', v_total_credit, 'line_count', v_line_number),
     jsonb_build_object('source_type', p_source_type, 'source_id', p_source_id,
                        'journal_type', p_journal_type, 'idempotency_key', p_idempotency_key));

  RETURN jsonb_build_object('success', true,
                            'journal_id', v_journal_id,
                            'ledger_entry_ids', to_jsonb(v_ledger_ids));

EXCEPTION WHEN OTHERS THEN
  BEGIN
    INSERT INTO bookkeeping_audit_log
      (organization_id, entity_type, entity_id, action, actor_id, reason, metadata)
    VALUES
      (COALESCE(p_organization_id, '00000000-0000-0000-0000-000000000000'::uuid),
       COALESCE(v_entity_type, 'unknown'),
       COALESCE(v_entity_id, '00000000-0000-0000-0000-000000000000'::uuid),
       'ledger_post_blocked', v_actor,
       COALESCE(v_err_msg, SQLERRM),
       jsonb_build_object('error_code', COALESCE(v_err_code, 'unknown'),
                          'source_type', p_source_type,
                          'source_id',   p_source_id,
                          'journal_date', p_journal_date));
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  RETURN jsonb_build_object('success', false,
                            'error_code',    COALESCE(v_err_code, 'unknown'),
                            'error_message', COALESCE(v_err_msg, SQLERRM));
END;
$$;


--
-- Name: prevent_accepted_quote_line_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_accepted_quote_line_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
  v_quote_id uuid;
BEGIN
  v_quote_id := COALESCE(NEW.quote_id, OLD.quote_id);
  SELECT status INTO v_status FROM public.quotes WHERE id = v_quote_id;
  IF v_status = 'accepted' THEN
    RAISE EXCEPTION 'Cannot modify line items on an accepted quote (quote_id: %). Issue a new quote instead.', v_quote_id;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


