--
-- Name: lifecycle_approve_onboarding(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_approve_onboarding(p_onboarding_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_onboarding record;
  v_questionnaire_instance record;
  v_questionnaire_responses jsonb;
  v_client_id uuid;
  v_company_id uuid;
  v_engagement_ids uuid[] := ARRAY[]::uuid[];
  v_job_ids uuid[] := ARRAY[]::uuid[];
  v_engagement_id uuid;
  v_job_id uuid;
  v_portal_access_result jsonb;
  v_entity_type text;
  v_entity_id uuid;
  v_primary_email text;
  v_quote_line record;
  v_trigger_date date;
  v_aml_expiry_date date;
  v_period_label text;
BEGIN
  SELECT * INTO v_onboarding FROM onboarding_applications WHERE id = p_onboarding_id;

  IF v_onboarding.id IS NULL THEN
    RAISE EXCEPTION 'Onboarding application not found: %', p_onboarding_id;
  END IF;

  IF NOT user_has_organization_access(v_onboarding.organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization';
  END IF;

  IF v_onboarding.status = 'approved' THEN
    RAISE EXCEPTION 'Onboarding application already approved';
  END IF;

  IF v_onboarding.status = 'rejected' THEN
    RAISE EXCEPTION 'Cannot approve rejected application';
  END IF;

  IF public.is_canonical_lifecycle_enabled(v_onboarding.organization_id) THEN
    DECLARE
      v_gates jsonb := public.lifecycle_onboarding_gates(p_onboarding_id);
    BEGIN
      -- T2b: gate on activation_ready (signatures/AML/submission) — billing no longer blocks.
      IF NOT COALESCE((v_gates->>'activation_ready')::boolean, false) THEN
        RAISE EXCEPTION 'Cannot approve onboarding %: outstanding activation gates %',
          p_onboarding_id, (v_gates->>'outstanding');
      END IF;
    END;
  END IF;

  v_aml_expiry_date := CURRENT_DATE + INTERVAL '5 years';

  IF v_onboarding.onboarding_questionnaire_instance_id IS NOT NULL THEN
    SELECT * INTO v_questionnaire_instance
    FROM questionnaire_instances
    WHERE id = v_onboarding.onboarding_questionnaire_instance_id;

    SELECT jsonb_object_agg(qr.question_id, qr.response_value)
    INTO v_questionnaire_responses
    FROM questionnaire_responses qr
    WHERE qr.questionnaire_instance_id = v_onboarding.onboarding_questionnaire_instance_id;
  END IF;

  IF v_onboarding.application_type = 'individual' THEN
    IF v_onboarding.client_id IS NOT NULL THEN
      v_client_id := v_onboarding.client_id;
      UPDATE clients
      SET
        status = 'active',
        activated_at = now(),
        aml_verified_at = CASE WHEN v_onboarding.aml_status = 'verified' THEN v_onboarding.aml_verified_at ELSE NULL END,
        aml_expiry_date = CASE WHEN v_onboarding.aml_status = 'verified' THEN v_aml_expiry_date ELSE NULL END,
        aml_verified_by = CASE WHEN v_onboarding.aml_status = 'verified' THEN auth.uid() ELSE NULL END,
        first_name = COALESCE(v_questionnaire_responses->>'first_name', first_name),
        last_name = COALESCE(v_questionnaire_responses->>'last_name', last_name),
        date_of_birth = COALESCE((v_questionnaire_responses->>'date_of_birth')::date, date_of_birth),
        address_line_1 = COALESCE(v_questionnaire_responses->>'address_line_1', address_line_1),
        address_line_2 = COALESCE(v_questionnaire_responses->>'address_line_2', address_line_2),
        city = COALESCE(v_questionnaire_responses->>'city', city),
        postcode = COALESCE(v_questionnaire_responses->>'postcode', postcode),
        country = COALESCE(v_questionnaire_responses->>'country', country),
        phone = COALESCE(v_questionnaire_responses->>'phone', phone),
        national_insurance_number = COALESCE(v_questionnaire_responses->>'national_insurance_number', national_insurance_number),
        utr = COALESCE(v_questionnaire_responses->>'utr', utr)
      WHERE id = v_client_id;
    ELSE
      INSERT INTO clients (
        organization_id, first_name, last_name, email, phone, date_of_birth,
        address_line_1, address_line_2, city, postcode, country,
        national_insurance_number, utr, status, activated_at,
        aml_verified_at, aml_expiry_date, aml_verified_by
      )
      VALUES (
        v_onboarding.organization_id,
        COALESCE(v_questionnaire_responses->>'first_name', v_onboarding.first_name),
        COALESCE(v_questionnaire_responses->>'last_name', v_onboarding.last_name),
        v_onboarding.email,
        COALESCE(v_questionnaire_responses->>'phone', v_onboarding.phone),
        COALESCE((v_questionnaire_responses->>'date_of_birth')::date, v_onboarding.date_of_birth),
        COALESCE(v_questionnaire_responses->>'address_line_1', v_onboarding.address_line_1),
        COALESCE(v_questionnaire_responses->>'address_line_2', v_onboarding.address_line_2),
        COALESCE(v_questionnaire_responses->>'city', v_onboarding.city),
        COALESCE(v_questionnaire_responses->>'postcode', v_onboarding.postcode),
        COALESCE(v_questionnaire_responses->>'country', v_onboarding.country),
        COALESCE(v_questionnaire_responses->>'national_insurance_number', v_onboarding.national_insurance_number),
        COALESCE(v_questionnaire_responses->>'utr', v_onboarding.utr),
        'active', now(),
        CASE WHEN v_onboarding.aml_status = 'verified' THEN v_onboarding.aml_verified_at ELSE NULL END,
        CASE WHEN v_onboarding.aml_status = 'verified' THEN v_aml_expiry_date ELSE NULL END,
        CASE WHEN v_onboarding.aml_status = 'verified' THEN auth.uid() ELSE NULL END
      )
      RETURNING id INTO v_client_id;

      UPDATE onboarding_applications SET client_id = v_client_id WHERE id = p_onboarding_id;

      INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
      VALUES (v_onboarding.organization_id, 'client', v_client_id, 'created', auth.uid(),
        jsonb_build_object('onboarding_id', p_onboarding_id, 'status', 'active', 'source', 'onboarding_approval'));
    END IF;

    v_entity_type := 'client';
    v_entity_id := v_client_id;

  ELSIF v_onboarding.application_type = 'company' THEN
    IF v_onboarding.company_id IS NOT NULL THEN
      v_company_id := v_onboarding.company_id;
      UPDATE companies
      SET
        status = 'active',
        activated_at = now(),
        aml_verified_at = CASE WHEN v_onboarding.aml_status = 'verified' THEN v_onboarding.aml_verified_at ELSE NULL END,
        aml_expiry_date = CASE WHEN v_onboarding.aml_status = 'verified' THEN v_aml_expiry_date ELSE NULL END,
        aml_verified_by = CASE WHEN v_onboarding.aml_status = 'verified' THEN auth.uid() ELSE NULL END,
        company_name = COALESCE(v_questionnaire_responses->>'company_name', company_name),
        company_number = COALESCE(v_questionnaire_responses->>'company_number', company_number),
        address_line_1 = COALESCE(v_questionnaire_responses->>'address_line_1', address_line_1),
        address_line_2 = COALESCE(v_questionnaire_responses->>'address_line_2', address_line_2),
        city = COALESCE(v_questionnaire_responses->>'city', city),
        postcode = COALESCE(v_questionnaire_responses->>'postcode', postcode),
        country = COALESCE(v_questionnaire_responses->>'country', country),
        phone = COALESCE(v_questionnaire_responses->>'phone', phone),
        vat_number = COALESCE(v_questionnaire_responses->>'vat_number', vat_number),
        incorporation_date = COALESCE((v_questionnaire_responses->>'incorporation_date')::date, incorporation_date),
        year_end_month = COALESCE((v_questionnaire_responses->>'year_end_month')::integer, year_end_month),
        year_end_day = COALESCE((v_questionnaire_responses->>'year_end_day')::integer, year_end_day)
      WHERE id = v_company_id;
    ELSE
      INSERT INTO companies (
        organization_id, company_name, company_number, email, phone,
        address_line_1, address_line_2, city, postcode, country,
        vat_number, incorporation_date, year_end_month, year_end_day,
        status, activated_at, aml_verified_at, aml_expiry_date, aml_verified_by
      )
      VALUES (
        v_onboarding.organization_id,
        COALESCE(v_questionnaire_responses->>'company_name', v_onboarding.company_name),
        COALESCE(v_questionnaire_responses->>'company_number', v_onboarding.company_number),
        v_onboarding.email,
        COALESCE(v_questionnaire_responses->>'phone', v_onboarding.phone),
        COALESCE(v_questionnaire_responses->>'address_line_1', v_onboarding.address_line_1),
        COALESCE(v_questionnaire_responses->>'address_line_2', v_onboarding.address_line_2),
        COALESCE(v_questionnaire_responses->>'city', v_onboarding.city),
        COALESCE(v_questionnaire_responses->>'postcode', v_onboarding.postcode),
        COALESCE(v_questionnaire_responses->>'country', v_onboarding.country),
        COALESCE(v_questionnaire_responses->>'vat_number', v_onboarding.vat_number),
        COALESCE((v_questionnaire_responses->>'incorporation_date')::date, v_onboarding.incorporation_date),
        COALESCE((v_questionnaire_responses->>'year_end_month')::integer, v_onboarding.year_end_month),
        COALESCE((v_questionnaire_responses->>'year_end_day')::integer, v_onboarding.year_end_day),
        'active', now(),
        CASE WHEN v_onboarding.aml_status = 'verified' THEN v_onboarding.aml_verified_at ELSE NULL END,
        CASE WHEN v_onboarding.aml_status = 'verified' THEN v_aml_expiry_date ELSE NULL END,
        CASE WHEN v_onboarding.aml_status = 'verified' THEN auth.uid() ELSE NULL END
      )
      RETURNING id INTO v_company_id;

      UPDATE onboarding_applications SET company_id = v_company_id WHERE id = p_onboarding_id;

      INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
      VALUES (v_onboarding.organization_id, 'company', v_company_id, 'created', auth.uid(),
        jsonb_build_object('onboarding_id', p_onboarding_id, 'status', 'active', 'source', 'onboarding_approval'));
    END IF;

    v_entity_type := 'company';
    v_entity_id := v_company_id;
  END IF;

  IF v_onboarding.quote_id IS NOT NULL THEN
    -- Canonical engine: the SINGLE idempotent source for engagements + jobs + deadlines.
    PERFORM public.lifecycle_materialize_jobs(
      v_onboarding.organization_id, v_client_id, v_company_id, NULL,
      v_onboarding.quote_id, 'onboarding_approval:' || p_onboarding_id::text);

    FOR v_quote_line IN
      SELECT ql.*, sc.code AS service_code, sc.name AS service_name,
             sc.trigger_date_type, sc.trigger_date_offset_days, sc.information_request_template_id
      FROM quote_lines ql
      LEFT JOIN services_catalog sc ON sc.id = ql.service_id
      WHERE ql.quote_id = v_onboarding.quote_id
    LOOP
      SELECT id INTO v_engagement_id
      FROM engagements
      WHERE quote_id = v_onboarding.quote_id AND service_id = v_quote_line.service_id
      LIMIT 1;
      IF v_engagement_id IS NOT NULL THEN
        v_engagement_ids := array_append(v_engagement_ids, v_engagement_id);
      END IF;

      SELECT id INTO v_job_id
      FROM jobs
      WHERE organization_id = v_onboarding.organization_id
        AND service_type = COALESCE(v_quote_line.service_code, v_quote_line.service_id::text)
        AND COALESCE(client_id::text, '') = COALESCE(v_client_id::text, '')
        AND COALESCE(company_id::text, '') = COALESCE(v_company_id::text, '')
      ORDER BY created_at DESC
      LIMIT 1;
      IF v_job_id IS NOT NULL THEN
        v_job_ids := array_append(v_job_ids, v_job_id);
      END IF;

      IF v_quote_line.trigger_date_type IS NOT NULL AND v_quote_line.information_request_template_id IS NOT NULL THEN
        v_trigger_date := CASE v_quote_line.trigger_date_type
          WHEN 'tax_year_end' THEN
            CASE WHEN CURRENT_DATE > make_date(EXTRACT(YEAR FROM CURRENT_DATE)::int, 4, 5)
              THEN make_date(EXTRACT(YEAR FROM CURRENT_DATE)::int, 4, 5)
              ELSE make_date(EXTRACT(YEAR FROM CURRENT_DATE)::int - 1, 4, 5)
            END
          WHEN 'financial_year_end' THEN
            CASE WHEN v_company_id IS NOT NULL THEN
              (SELECT make_date(
                CASE WHEN CURRENT_DATE > make_date(EXTRACT(YEAR FROM CURRENT_DATE)::int, COALESCE(c.year_end_month, 3), COALESCE(c.year_end_day, 31))
                  THEN EXTRACT(YEAR FROM CURRENT_DATE)::int
                  ELSE EXTRACT(YEAR FROM CURRENT_DATE)::int - 1
                END,
                COALESCE(c.year_end_month, 3),
                COALESCE(c.year_end_day, 31)
              ) FROM companies c WHERE c.id = v_company_id)
            ELSE CURRENT_DATE - INTERVAL '1 day'
            END
          ELSE CURRENT_DATE - INTERVAL '1 day'
        END;

        IF CURRENT_DATE > v_trigger_date + (COALESCE(v_quote_line.trigger_date_offset_days,0) || ' days')::interval THEN
          INSERT INTO email_queue (
            organization_id, to_email, to_name, subject, body_html,
            template_id, client_id, company_id, job_id, entity_type, entity_id,
            merge_data, status
          )
          SELECT
            v_onboarding.organization_id,
            v_onboarding.email,
            COALESCE(v_onboarding.first_name || ' ' || v_onboarding.last_name, v_onboarding.company_name),
            COALESCE(t.name, 'Information Request') || ' - ' || COALESCE(v_quote_line.service_name,'Service'),
            COALESCE(t.content->>'body_html', '<p>We need some information to complete your ' || COALESCE(v_quote_line.service_name,'service') || '.</p>'),
            v_quote_line.information_request_template_id,
            v_client_id,
            v_company_id,
            v_job_id,
            'job',
            v_job_id,
            jsonb_build_object(
              'client_name', COALESCE(v_onboarding.first_name || ' ' || v_onboarding.last_name, v_onboarding.company_name),
              'service_name', v_quote_line.service_name,
              'trigger_date', v_trigger_date::text
            ),
            'pending'
          FROM templates t WHERE t.id = v_quote_line.information_request_template_id;

          INSERT INTO client_tasks (
            organization_id, client_id, company_id, title, description,
            status, visibility, due_date
          )
          VALUES (
            v_onboarding.organization_id, v_client_id, v_company_id,
            'Provide information for ' || COALESCE(v_quote_line.service_name,'service'),
            'Please provide the required information to complete your ' || COALESCE(v_quote_line.service_name,'service'),
            'not_started', 'client_visible',
            CURRENT_DATE + INTERVAL '14 days'
          );
        END IF;
      END IF;

      IF v_engagement_id IS NOT NULL THEN
        INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
        VALUES (v_onboarding.organization_id, 'engagement', v_engagement_id, 'created', auth.uid(),
          jsonb_build_object('onboarding_id', p_onboarding_id, 'service_id', v_quote_line.service_id));
      END IF;
    END LOOP;
  END IF;

  IF public.is_canonical_lifecycle_enabled(v_onboarding.organization_id) THEN
    IF v_company_id IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM public.accountant_client_links
                     WHERE practice_id = v_onboarding.organization_id
                       AND company_id = v_company_id AND status = 'active') THEN
        INSERT INTO public.accountant_client_links (practice_id, company_id, status, initiated_by, activated_at)
        VALUES (v_onboarding.organization_id, v_company_id, 'active', 'practice', now());
      END IF;
    ELSIF v_client_id IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM public.accountant_client_links
                     WHERE practice_id = v_onboarding.organization_id
                       AND client_id = v_client_id AND status = 'active') THEN
        INSERT INTO public.accountant_client_links (practice_id, client_id, status, initiated_by, activated_at)
        VALUES (v_onboarding.organization_id, v_client_id, 'active', 'practice', now());
      END IF;
    END IF;
  END IF;

  UPDATE onboarding_applications
  SET
    status = 'approved',
    approved_at = now(),
    approved_by = auth.uid(),
    aml_expiry_date = v_aml_expiry_date,
    aml_documents_migrated = true
  WHERE id = p_onboarding_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, old_value, new_value, user_id)
  VALUES (v_onboarding.organization_id, 'onboarding', p_onboarding_id, 'approved', v_onboarding.status, 'approved', auth.uid());

  v_primary_email := v_onboarding.email;
  IF v_primary_email IS NOT NULL AND v_primary_email != '' AND v_entity_type IS NOT NULL AND v_entity_id IS NOT NULL THEN
    BEGIN
      v_portal_access_result := lifecycle_grant_portal_access(v_entity_type, v_entity_id, v_primary_email, 'primary_contact');
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
      VALUES (v_onboarding.organization_id, 'onboarding', p_onboarding_id, 'portal_access_failed', auth.uid(),
        jsonb_build_object('error', SQLERRM, 'sqlstate', SQLSTATE, 'email', v_primary_email));
      v_portal_access_result := jsonb_build_object('ok', false, 'error', SQLERRM, 'sqlstate', SQLSTATE);
    END;
  ELSE
    v_portal_access_result := jsonb_build_object('ok', false, 'skipped', true, 'reason',
      CASE WHEN v_primary_email IS NULL OR v_primary_email = '' THEN 'no_email' ELSE 'no_entity' END);
  END IF;

  RETURN jsonb_build_object(
    'onboarding_id', p_onboarding_id,
    'status', 'approved',
    'client_id', v_client_id,
    'company_id', v_company_id,
    'engagement_ids', v_engagement_ids,
    'job_ids', v_job_ids,
    'portal_access', v_portal_access_result,
    'aml_expiry_date', v_aml_expiry_date,
    'questionnaire_data_populated', v_questionnaire_responses IS NOT NULL
  );
END;
$$;


--
-- Name: lifecycle_create_manual_job(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_create_manual_job(p_client_id uuid, p_company_id uuid, p_service_code text, p_tax_year_start integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_svc record;
  v_today date := CURRENT_DATE;
  v_company record;
  v_period_start date; v_period_end date; v_period_label text;
  v_job_id uuid;
BEGIN
  IF p_client_id IS NULL AND p_company_id IS NULL THEN
    RAISE EXCEPTION 'A client or company is required';
  END IF;

  IF p_client_id IS NOT NULL THEN
    SELECT organization_id INTO v_org FROM public.clients WHERE id = p_client_id;
  ELSE
    SELECT organization_id INTO v_org FROM public.companies WHERE id = p_company_id;
  END IF;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Entity not found'; END IF;
  IF NOT public.user_has_organization_access(v_org) THEN
    RAISE EXCEPTION 'Access denied to organization' USING ERRCODE='42501';
  END IF;

  SELECT code, name INTO v_svc FROM public.services_catalog WHERE code = p_service_code AND organization_id = v_org LIMIT 1;
  IF v_svc.code IS NULL THEN
    SELECT code, name INTO v_svc FROM public.services_catalog WHERE code = p_service_code LIMIT 1;
  END IF;
  IF v_svc.code IS NULL THEN RAISE EXCEPTION 'Unknown service %', p_service_code; END IF;

  IF p_service_code IN ('sa_mtd','sa_non_mtd') THEN
    IF p_tax_year_start IS NULL THEN
      IF EXTRACT(MONTH FROM v_today) > 4 OR (EXTRACT(MONTH FROM v_today) = 4 AND EXTRACT(DAY FROM v_today) >= 6) THEN
        p_tax_year_start := EXTRACT(YEAR FROM v_today)::int;
      ELSE
        p_tax_year_start := EXTRACT(YEAR FROM v_today)::int - 1;
      END IF;
    END IF;
    v_period_start := make_date(p_tax_year_start, 4, 6);
    v_period_end := make_date(p_tax_year_start + 1, 4, 5);
    v_period_label := p_tax_year_start::text || '/' || substr((p_tax_year_start + 1)::text, 3, 2);
  ELSIF p_company_id IS NOT NULL THEN
    SELECT * INTO v_company FROM public.companies WHERE id = p_company_id;
    IF v_company.year_end_month IS NOT NULL AND v_company.year_end_day IS NOT NULL THEN
      v_period_end := make_date(EXTRACT(YEAR FROM v_today)::int, v_company.year_end_month, v_company.year_end_day);
      IF v_period_end > v_today THEN v_period_end := v_period_end - INTERVAL '1 year'; END IF;
      v_period_start := v_period_end - INTERVAL '1 year' + INTERVAL '1 day';
      v_period_label := to_char(v_period_end, 'YYYY') || ' Year-End';
    ELSE
      v_period_start := v_today; v_period_end := v_today + INTERVAL '30 days'; v_period_label := 'Setup Pending';
    END IF;
  ELSE
    v_period_start := v_today; v_period_end := v_today + INTERVAL '30 days'; v_period_label := 'Setup Pending';
  END IF;

  v_job_id := public.lifecycle_upsert_job_with_deadlines(
    v_org, p_client_id, p_company_id, NULL, v_svc.code, v_svc.name,
    v_period_start, v_period_end, v_period_label, 'manual');

  RETURN jsonb_build_object('job_id', v_job_id, 'period_label', v_period_label);
END;
$$;


--
-- Name: lifecycle_evaluate_onboarding_activation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_evaluate_onboarding_activation(p_application_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  a          public.onboarding_applications%ROWTYPE;
  v_flag     boolean;
  v_gates    jsonb;
  v_all_pass boolean;
  v_approve  jsonb;
BEGIN
  SELECT * INTO a FROM public.onboarding_applications WHERE id = p_application_id;
  IF a.id IS NULL THEN
    RAISE EXCEPTION 'Onboarding application not found: %', p_application_id;
  END IF;

  IF NOT public.user_has_organization_access(a.organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization' USING ERRCODE='42501';
  END IF;

  v_flag     := public.is_canonical_lifecycle_enabled(a.organization_id);
  v_gates    := public.lifecycle_onboarding_gates(p_application_id);
  -- T2b: activation is driven by signatures/AML/submission (activation_ready), NOT billing.
  v_all_pass := COALESCE((v_gates->>'activation_ready')::boolean, false);

  IF NOT v_flag THEN
    RETURN jsonb_build_object('mode', 'dry_run', 'flag', false,
                              'would_activate', v_all_pass, 'gates', v_gates);
  END IF;

  IF a.status IN ('approved','rejected','cancelled') THEN
    RETURN jsonb_build_object('mode', 'noop_closed', 'status', a.status, 'gates', v_gates);
  END IF;

  IF NOT v_all_pass THEN
    UPDATE public.onboarding_applications
       SET status = 'for_review',
           review_feedback = COALESCE(review_feedback, '') ||
             CASE WHEN COALESCE(review_feedback,'') = '' THEN '' ELSE E'\n' END ||
             'Auto-evaluation outstanding gates: ' || (v_gates->>'outstanding'),
           updated_at = now()
     WHERE id = p_application_id;
    RETURN jsonb_build_object('mode', 'routed_to_review', 'gates', v_gates);
  END IF;

  IF a.application_type = 'company' AND a.company_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.accountant_client_links
      WHERE practice_id = a.organization_id AND company_id = a.company_id AND status = 'active'
    ) THEN
      INSERT INTO public.accountant_client_links (practice_id, company_id, status, initiated_by, activated_at)
      VALUES (a.organization_id, a.company_id, 'active', 'practice', now());
    END IF;
  ELSIF a.client_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.accountant_client_links
      WHERE practice_id = a.organization_id AND client_id = a.client_id AND status = 'active'
    ) THEN
      INSERT INTO public.accountant_client_links (practice_id, client_id, status, initiated_by, activated_at)
      VALUES (a.organization_id, a.client_id, 'active', 'practice', now());
    END IF;
  END IF;

  v_approve := public.lifecycle_approve_onboarding(p_application_id);

  RETURN jsonb_build_object('mode', 'activated', 'gates', v_gates, 'approve', v_approve);
END;
$$;


--
-- Name: FUNCTION lifecycle_evaluate_onboarding_activation(p_application_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lifecycle_evaluate_onboarding_activation(p_application_id uuid) IS 'Sprint 1: flag-aware onboarding activation evaluator. Org-access gated (members only). Flag OFF => dry-run, no writes. Flag ON => activate (link + delegate to approve) when gates pass, else route to for_review. Dormant.';


--
-- Name: lifecycle_generate_deadlines_for_job(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_generate_deadlines_for_job(p_job_id uuid, p_facts jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job       RECORD;
  v_rule      RECORD;
  v_calc      jsonb;
  v_due       date;
  v_missing   text[];
  v_fact      text;
  v_created   int := 0;
  v_skipped   int := 0;
  v_missing_facts_logged int := 0;
  v_existing  uuid;
  v_results   jsonb := '[]'::jsonb;
  v_tax_year_end date;
  v_after_tax  boolean;
  v_fixed_txt  text;
  v_existing_dl record;
BEGIN
  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id;
  IF v_job IS NULL THEN
    RAISE EXCEPTION 'Job % not found', p_job_id;
  END IF;

  IF NOT public._canonical_caller_in_org(v_job.organization_id) THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;

  IF NOT public._canonical_spine_enabled(v_job.organization_id) THEN
    RETURN jsonb_build_object('status','skipped','reason','canonical_spine_v1 flag disabled');
  END IF;

  IF v_job.job_template_code IS NULL OR v_job.canonical_service_code IS NULL THEN
    RAISE EXCEPTION 'Job % is not mapped to a canonical job template', p_job_id;
  END IF;

  FOR v_rule IN
    SELECT * FROM public.canonical_deadline_rules
     WHERE active = true
       AND (job_template_code = v_job.job_template_code
            OR (job_template_code IS NULL AND canonical_service_code = v_job.canonical_service_code))
  LOOP
    v_calc := v_rule.calculation_method;
    v_due := NULL;
    v_missing := ARRAY[]::text[];

    -- Check required_facts presence in p_facts JSON
    IF v_rule.required_facts IS NOT NULL THEN
      FOREACH v_fact IN ARRAY v_rule.required_facts
      LOOP
        -- skip "fact" entries that actually reference another deadline_code we may have just made
        IF p_facts ? v_fact THEN
          CONTINUE;
        END IF;
        -- internal cross-deadline references are resolved later; not blocking
        IF v_fact IN ('companies_house_accounts_filing','ct600_filing','partnership_tax_return_filing') THEN
          CONTINUE;
        END IF;
        v_missing := v_missing || v_fact;
      END LOOP;
    END IF;

    IF array_length(v_missing, 1) > 0 THEN
      -- create a client_task as a missing-fact placeholder (idempotent on title+job)
      IF NOT EXISTS (
        SELECT 1 FROM public.client_tasks
         WHERE job_id = p_job_id
           AND title = 'Missing data: ' || v_rule.deadline_name
      ) THEN
        INSERT INTO public.client_tasks (
          organization_id, client_id, company_id, job_id,
          title, description, status, visibility
        ) VALUES (
          v_job.organization_id, v_job.client_id, v_job.company_id, p_job_id,
          'Missing data: ' || v_rule.deadline_name,
          'Cannot compute "' || v_rule.deadline_name || '" — missing fact(s): '
            || array_to_string(v_missing, ', '),
          'pending', 'internal'
        );
        v_missing_facts_logged := v_missing_facts_logged + 1;
      END IF;
      v_results := v_results || jsonb_build_object(
        'deadline_code', v_rule.deadline_code,
        'action', 'missing_facts',
        'missing', v_missing
      );
      CONTINUE;
    END IF;

    -- Compute due_date from calculation_method (covers the common shapes)
    IF v_calc ? 'add_months_to' THEN
      v_due := ((p_facts->>(v_calc->>'add_months_to'))::date
                + ((v_calc->>'months')::int || ' months')::interval)::date;
    ELSIF v_calc ? 'add_to' THEN
      v_due := ((p_facts->>(v_calc->>'add_to'))::date
                + ((COALESCE(v_calc->>'months','0'))::int || ' months')::interval
                + ((COALESCE(v_calc->>'days','0'))::int || ' days')::interval)::date;
    ELSIF v_calc ? 'fixed_date' AND COALESCE((v_calc->>'after_tax_year')::boolean, false) THEN
      -- tax year of form '2024/25' → year-end 5 April 2025 → due = fixed_date in calendar year after tax_year_end
      v_tax_year_end := (
        SELECT (split_part(p_facts->>'tax_year','/',1)::int + 1)::text || '-04-05'
      )::date;
      v_fixed_txt := v_calc->>'fixed_date';
      v_due := to_date(v_fixed_txt || ' ' || (extract(year FROM v_tax_year_end)::int + 1)::text, 'DD Month YYYY');
    ELSIF v_calc ? 'offset_days_before' THEN
      -- Resolve against a previously created deadline by deadline_code on this job
      SELECT due_date INTO v_due FROM public.deadlines
       WHERE job_id = p_job_id AND deadline_code = (v_calc->>'offset_days_before')
       ORDER BY created_at DESC LIMIT 1;
      IF v_due IS NOT NULL THEN
        v_due := v_due - ((v_calc->>'default_days')::int);
      END IF;
    END IF;

    IF v_due IS NULL THEN
      v_results := v_results || jsonb_build_object(
        'deadline_code', v_rule.deadline_code,
        'action', 'unsupported_calculation'
      );
      CONTINUE;
    END IF;

    -- Idempotent upsert keyed on (job_id, deadline_code)
    SELECT id INTO v_existing FROM public.deadlines
     WHERE job_id = p_job_id AND deadline_code = v_rule.deadline_code
     LIMIT 1;

    IF v_existing IS NULL THEN
      INSERT INTO public.deadlines (
        organization_id, client_id, company_id, engagement_id, job_id,
        name, deadline_type, service_code, canonical_service_code, deadline_code,
        due_date, status
      ) VALUES (
        v_job.organization_id, v_job.client_id, v_job.company_id, NULL, p_job_id,
        v_rule.deadline_name, v_rule.deadline_type, v_job.canonical_service_code,
        v_job.canonical_service_code, v_rule.deadline_code,
        v_due, 'open'
      );
      v_created := v_created + 1;
      v_results := v_results || jsonb_build_object(
        'deadline_code', v_rule.deadline_code, 'due_date', v_due, 'action', 'created'
      );
    ELSE
      UPDATE public.deadlines
         SET due_date = v_due, updated_at = now()
       WHERE id = v_existing AND status NOT IN ('completed','filed');
      v_skipped := v_skipped + 1;
      v_results := v_results || jsonb_build_object(
        'deadline_code', v_rule.deadline_code, 'due_date', v_due, 'action', 'updated'
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'status','ok',
    'job_id', p_job_id,
    'deadlines_created', v_created,
    'deadlines_updated', v_skipped,
    'missing_fact_tasks', v_missing_facts_logged,
    'results', v_results
  );
END;
$$;


--
-- Name: lifecycle_generate_jobs_for_service(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_generate_jobs_for_service(p_engagement_id uuid, p_period_start date DEFAULT NULL::date, p_period_end date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_eng       RECORD;
  v_svc       RECORD;
  v_tpl       RECORD;
  v_job_id    uuid;
  v_existing  uuid;
  v_created   int := 0;
  v_skipped   int := 0;
  v_results   jsonb := '[]'::jsonb;
  v_period_label text;
BEGIN
  SELECT * INTO v_eng FROM public.engagements WHERE id = p_engagement_id;
  IF v_eng IS NULL THEN
    RAISE EXCEPTION 'Engagement % not found', p_engagement_id;
  END IF;

  IF NOT public._canonical_caller_in_org(v_eng.organization_id) THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;

  IF NOT public._canonical_spine_enabled(v_eng.organization_id) THEN
    RETURN jsonb_build_object('status','skipped','reason','canonical_spine_v1 flag disabled');
  END IF;

  IF v_eng.canonical_service_code IS NULL THEN
    RAISE EXCEPTION 'Engagement % is not mapped to a canonical service', p_engagement_id;
  END IF;

  IF v_eng.status <> 'active' THEN
    RETURN jsonb_build_object('status','skipped','reason','engagement not active');
  END IF;

  SELECT * INTO v_svc FROM public.canonical_services WHERE code = v_eng.canonical_service_code;
  IF v_svc IS NULL OR NOT v_svc.creates_jobs THEN
    RETURN jsonb_build_object('status','skipped','reason','canonical service does not create jobs');
  END IF;

  v_period_label := CASE
    WHEN p_period_start IS NOT NULL AND p_period_end IS NOT NULL
      THEN to_char(p_period_start,'YYYY-MM-DD') || ' to ' || to_char(p_period_end,'YYYY-MM-DD')
    ELSE NULL
  END;

  FOR v_tpl IN
    SELECT * FROM public.canonical_job_templates
     WHERE canonical_service_code = v_eng.canonical_service_code AND active = true
  LOOP
    -- Idempotency key: org + entity + job_template_code + period
    SELECT id INTO v_existing
      FROM public.jobs
     WHERE organization_id = v_eng.organization_id
       AND job_template_code = v_tpl.job_template_code
       AND COALESCE(client_id::text,'') = COALESCE(v_eng.client_id::text,'')
       AND COALESCE(company_id::text,'') = COALESCE(v_eng.company_id::text,'')
       AND COALESCE(period_start::text,'') = COALESCE(p_period_start::text,'')
       AND COALESCE(period_end::text,'')   = COALESCE(p_period_end::text,'')
     LIMIT 1;

    IF v_existing IS NULL THEN
      INSERT INTO public.jobs (
        organization_id, client_id, company_id, job_name, service_type,
        canonical_service_code, job_template_code,
        period_start, period_end, period_label,
        status, priority, is_auto_generated, auto_generated_at, generation_reason,
        automation_source
      ) VALUES (
        v_eng.organization_id, v_eng.client_id, v_eng.company_id,
        v_tpl.display_name || COALESCE(' — ' || v_period_label, ''),
        v_eng.canonical_service_code, -- service_type kept human readable; canonical codes carry truth
        v_eng.canonical_service_code, v_tpl.job_template_code,
        p_period_start, p_period_end, v_period_label,
        COALESCE(v_tpl.default_status, 'blank'), 'normal', true, now(),
        'canonical_lifecycle',
        'canonical_spine_v1'
      )
      RETURNING id INTO v_job_id;
      v_created := v_created + 1;
      v_results := v_results || jsonb_build_object(
        'job_template_code', v_tpl.job_template_code,
        'job_id', v_job_id,
        'action', 'created'
      );
    ELSE
      v_skipped := v_skipped + 1;
      v_results := v_results || jsonb_build_object(
        'job_template_code', v_tpl.job_template_code,
        'job_id', v_existing,
        'action', 'reused'
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'status','ok',
    'engagement_id', p_engagement_id,
    'jobs_created', v_created,
    'jobs_reused', v_skipped,
    'results', v_results
  );
END;
$$;


--
-- Name: lifecycle_grant_portal_access(text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_grant_portal_access(p_entity_type text, p_entity_id uuid, p_email text, p_role text DEFAULT 'primary_contact'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_organization_id uuid;
  v_user_id uuid;
  v_portal_access_id uuid;
  v_invite_token text;
  v_invite_expires_at timestamptz;
  v_entity_name text;
  v_firm_name text;
  v_portal_url text;
BEGIN
  IF p_entity_type = 'client' THEN
    SELECT organization_id, (first_name || ' ' || last_name)
    INTO v_organization_id, v_entity_name
    FROM clients WHERE id = p_entity_id;
    IF v_organization_id IS NULL THEN
      RAISE EXCEPTION 'Client not found: %', p_entity_id;
    END IF;
  ELSIF p_entity_type = 'company' THEN
    SELECT organization_id, company_name
    INTO v_organization_id, v_entity_name
    FROM companies WHERE id = p_entity_id;
    IF v_organization_id IS NULL THEN
      RAISE EXCEPTION 'Company not found: %', p_entity_id;
    END IF;
  ELSE
    RAISE EXCEPTION 'Invalid entity_type: %. Must be "client" or "company"', p_entity_type;
  END IF;

  IF NOT user_has_organization_access(v_organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization';
  END IF;

  SELECT name INTO v_firm_name FROM organizations WHERE id = v_organization_id;
  SELECT id INTO v_user_id FROM auth.users WHERE email = p_email LIMIT 1;

  v_invite_token := generate_invite_token();
  v_invite_expires_at := now() + interval '14 days';

  INSERT INTO portal_access (
    organization_id, user_id, client_id, company_id, role, status, is_active,
    invite_token, invite_expires_at, invited_at, created_by
  )
  VALUES (
    v_organization_id, v_user_id,
    CASE WHEN p_entity_type = 'client' THEN p_entity_id ELSE NULL END,
    CASE WHEN p_entity_type = 'company' THEN p_entity_id ELSE NULL END,
    p_role, 'invited', true, v_invite_token, v_invite_expires_at, now(), auth.uid()
  )
  RETURNING id INTO v_portal_access_id;

  v_portal_url := 'https://client.accountancyos.com/auth/portal-invite?token=' || v_invite_token;

  INSERT INTO email_queue (
    organization_id, to_email, subject, body_html, entity_type, entity_id, merge_data, status, context
  )
  VALUES (
    v_organization_id,
    p_email,
    'You have passed AML verification - set up your ' || v_firm_name || ' client portal',
    '<p>Hello ' || v_entity_name || ',</p>' ||
    '<p>Good news - you have successfully passed our AML (Anti-Money Laundering) verification checks with ' || v_firm_name || '.</p>' ||
    '<p>The final step is to set up your secure client portal login. From the portal you can view your jobs, share documents, approve work, and message us directly.</p>' ||
    '<p><a href="' || v_portal_url || '" style="display:inline-block;padding:10px 18px;background:#0f766e;color:#ffffff;text-decoration:none;border-radius:6px;">Set up your client portal</a></p>' ||
    '<p>This link is valid for 14 days. If it expires, just let us know and we will reissue it.</p>' ||
    '<p>Kind regards,<br/>' || v_firm_name || '</p>',
    'portal_access',
    v_portal_access_id,
    jsonb_build_object(
      'client_name', v_entity_name,
      'firm_name', v_firm_name,
      'portal_url', v_portal_url
    ),
    'pending',
    'onboarding'
  );

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
  VALUES (
    v_organization_id, 'portal_access', v_portal_access_id, 'invited', auth.uid(),
    jsonb_build_object('email', p_email, 'target_entity_type', p_entity_type, 'target_entity_id', p_entity_id, 'role', p_role)
  );

  RETURN jsonb_build_object(
    'portal_access_id', v_portal_access_id,
    'invite_token', v_invite_token,
    'invite_expires_at', v_invite_expires_at,
    'email_queued', true,
    'user_exists', v_user_id IS NOT NULL,
    'ok', true
  );
END;
$$;


--
-- Name: lifecycle_materialize_jobs(uuid, uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_materialize_jobs(p_org uuid, p_client_id uuid, p_company_id uuid, p_partnership_id uuid, p_quote_id uuid, p_source text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today date := CURRENT_DATE;
  v_company record;
  v_tax_year_start date; v_tax_year_end date;
  v_line record; v_frequency text;
  v_target_client uuid; v_target_company uuid; v_engagement_id uuid;
  v_period_start date; v_period_end date; v_period_label text;
  v_jobs int := 0;
BEGIN
  IF p_company_id IS NOT NULL THEN
    SELECT * INTO v_company FROM public.companies WHERE id = p_company_id;
  ELSE
    SELECT NULL::uuid AS id, NULL::int AS year_end_month, NULL::int AS year_end_day INTO v_company;
  END IF;

  IF EXTRACT(MONTH FROM v_today) > 4
     OR (EXTRACT(MONTH FROM v_today) = 4 AND EXTRACT(DAY FROM v_today) >= 6) THEN
    v_tax_year_start := make_date(EXTRACT(YEAR FROM v_today)::int, 4, 6);
  ELSE
    v_tax_year_start := make_date(EXTRACT(YEAR FROM v_today)::int - 1, 4, 6);
  END IF;
  v_tax_year_end := v_tax_year_start + INTERVAL '1 year' - INTERVAL '1 day';

  FOR v_line IN
    SELECT ql.*, sc.entity_scope, sc.code, sc.name AS service_name
    FROM public.quote_lines ql
    JOIN public.services_catalog sc ON sc.id = ql.service_id
    WHERE ql.quote_id = p_quote_id
  LOOP
    v_frequency := CASE WHEN v_line.billing_frequency = 'monthly' THEN 'monthly' ELSE 'one_off' END;

    IF v_line.entity_scope = 'company'
       OR (v_line.entity_scope = 'either' AND p_company_id IS NOT NULL
           AND v_line.code NOT IN ('sa_mtd','sa_non_mtd','cgt_60_day')) THEN
      v_target_company := p_company_id; v_target_client := NULL;
    ELSIF v_line.entity_scope = 'partnership' THEN
      v_target_client := COALESCE(p_partnership_id, p_client_id); v_target_company := NULL;
    ELSE
      v_target_client := p_client_id; v_target_company := NULL;
    END IF;
    IF v_target_client IS NULL AND v_target_company IS NULL THEN CONTINUE; END IF;

    SELECT id INTO v_engagement_id FROM public.engagements
      WHERE quote_id = p_quote_id AND service_id = v_line.service_id LIMIT 1;
    IF v_engagement_id IS NULL THEN
      INSERT INTO public.engagements
        (organization_id, client_id, company_id, service_id, quote_id, frequency, start_date, status, activated_at)
      VALUES
        (p_org, v_target_client, v_target_company, v_line.service_id, p_quote_id, v_frequency, v_today, 'active', now())
      RETURNING id INTO v_engagement_id;
    END IF;

    v_period_start := NULL; v_period_end := NULL; v_period_label := NULL;
    IF v_target_company IS NOT NULL AND v_company.year_end_month IS NOT NULL AND v_company.year_end_day IS NOT NULL THEN
      v_period_end := make_date(EXTRACT(YEAR FROM v_today)::int, v_company.year_end_month, v_company.year_end_day);
      IF v_period_end > v_today THEN v_period_end := v_period_end - INTERVAL '1 year'; END IF;
      v_period_start := v_period_end - INTERVAL '1 year' + INTERVAL '1 day';
      v_period_label := to_char(v_period_end, 'YYYY') || ' Year-End';
    ELSIF v_line.code IN ('sa_mtd','sa_non_mtd') THEN
      v_period_start := v_tax_year_start; v_period_end := v_tax_year_end;
      v_period_label := EXTRACT(YEAR FROM v_tax_year_start)::text || '/' || substr(EXTRACT(YEAR FROM v_tax_year_end)::text, 3, 2);
    ELSIF v_line.code = 'payroll' THEN
      v_period_start := date_trunc('month', v_today)::date;
      v_period_end := (date_trunc('month', v_today) + INTERVAL '1 month - 1 day')::date;
      v_period_label := to_char(v_today, 'Mon YYYY');
    ELSE
      v_period_start := v_today; v_period_end := v_today + INTERVAL '30 days'; v_period_label := 'Setup Pending';
    END IF;

    -- Proposal Phase 1 T1 (the ONLY behavioural change): an explicit per-line period set on
    -- the quote_line wins over the computed fallback above. Fully backward-compatible — a NULL
    -- line period (every pre-existing line) falls straight through to the computed value.
    v_period_start := COALESCE(v_line.period_start, v_period_start);
    v_period_end   := COALESCE(v_line.period_end,   v_period_end);
    v_period_label := COALESCE(NULLIF(v_line.period_label, ''), v_period_label);

    PERFORM public.lifecycle_upsert_job_with_deadlines(
      p_org, v_target_client, v_target_company, v_engagement_id,
      v_line.code, v_line.service_name, v_period_start, v_period_end, v_period_label, p_source);
    v_jobs := v_jobs + 1;
  END LOOP;

  -- Proposal Phase 1 T6b-2 (the ONLY addition in this migration): a CT600 job depends on
  -- the finalised Accounts for the SAME company + SAME accounts year-end. Idempotent —
  -- only writes when the link differs, and only when we are materializing for a company.
  -- The ct.period_end IS NOT NULL guard prevents a NULL period_end from cross-linking a
  -- CT600 to an Accounts job of a different (or unknown) accounts year.
  IF p_company_id IS NOT NULL THEN
    UPDATE public.jobs ct
       SET prerequisite_job_id = acc.id
      FROM public.jobs acc
     WHERE ct.organization_id = p_org
       AND ct.company_id      = p_company_id
       AND ct.service_type    = 'corporation_tax'
       AND ct.period_end      IS NOT NULL
       AND acc.organization_id = p_org
       AND acc.company_id      = p_company_id
       AND acc.service_type    = 'company_accounts'
       AND acc.period_end      = ct.period_end          -- same accounts year-end
       AND ct.prerequisite_job_id IS DISTINCT FROM acc.id;
  END IF;

  RETURN jsonb_build_object('status','ok','services', v_jobs);
END;
$$;


--
-- Name: lifecycle_onboarding_gates(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_onboarding_gates(p_application_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  a                  public.onboarding_applications%ROWTYPE;
  v_el_signed        boolean := false;
  v_aml              boolean := false;
  v_billing          boolean := false;
  v_submitted        boolean := false;
  v_open             boolean := false;
  v_context          boolean := false;
  v_has_lines        boolean := false;
  v_activation_ready boolean := false;
  v_letter_id        uuid;
  v_sig              jsonb;
  v_outstanding      text[] := ARRAY[]::text[];
BEGIN
  SELECT * INTO a FROM public.onboarding_applications WHERE id = p_application_id;
  IF a.id IS NULL THEN
    RETURN jsonb_build_object('error', 'application_not_found', 'all_pass', false,
                              'activation_ready', false,
                              'outstanding', to_jsonb(ARRAY['application_not_found']));
  END IF;

  -- T2b: engagement-letter signature via the signature RULE over engagement_letter_signatories,
  -- with the legacy single-signer check as fallback when no signatory rows exist.
  -- T2d-1: the rule itself now lives in public.el_signature_progress (one implementation).
  -- Equivalence with the T2b inline block: has_signatories mirrors the previous
  -- EXISTS(required rows) branch test, and `satisfied` computes the same
  -- 'any' => signed >= 1 / 'all' => total > 0 AND signed = total over the same rows.
  SELECT el.id INTO v_letter_id
    FROM public.engagement_letters el
   WHERE el.onboarding_application_id = p_application_id
   ORDER BY el.created_at DESC
   LIMIT 1;

  v_sig := public.el_signature_progress(v_letter_id);

  IF COALESCE((v_sig->>'has_signatories')::boolean, false) THEN
    v_el_signed := COALESCE((v_sig->>'satisfied')::boolean, false);
  ELSE
    -- Legacy fallback: unchanged from the live body (signed letter + contracts_signed_at).
    v_el_signed := (
      EXISTS (
        SELECT 1 FROM public.engagement_letters el
        WHERE el.onboarding_application_id = p_application_id AND el.signed_at IS NOT NULL
      )
      AND a.contracts_signed_at IS NOT NULL
    );
  END IF;

  v_aml       := (a.aml_status = 'verified');
  v_billing   := (a.billing_status IN ('completed','skipped','not_required'));
  v_submitted := (a.submitted_for_review_at IS NOT NULL OR a.status IN ('portal_pending','for_review'));
  v_open      := (a.status NOT IN ('approved','rejected','cancelled'));

  SELECT EXISTS (SELECT 1 FROM public.quote_lines ql WHERE ql.quote_id = a.quote_id) INTO v_has_lines;
  v_context := (
    a.organization_id IS NOT NULL
    AND a.quote_id IS NOT NULL
    AND v_has_lines
    AND (a.client_id IS NOT NULL OR a.company_id IS NOT NULL
         OR a.application_type IN ('individual','company'))
  );

  IF NOT v_el_signed THEN v_outstanding := v_outstanding || 'engagement_letter_signed'; END IF;
  IF NOT v_aml       THEN v_outstanding := v_outstanding || 'aml_passed'; END IF;
  IF NOT v_billing   THEN v_outstanding := v_outstanding || 'billing_settled'; END IF;
  IF NOT v_submitted THEN v_outstanding := v_outstanding || 'onboarding_submitted'; END IF;
  IF NOT v_open      THEN v_outstanding := v_outstanding || 'not_already_closed'; END IF;
  IF NOT v_context   THEN v_outstanding := v_outstanding || 'missing_activation_context'; END IF;

  -- T2b: activation gates on signatures/AML/submission/open/context — NOT billing.
  v_activation_ready := (v_el_signed AND v_aml AND v_submitted AND v_open AND v_context);

  RETURN jsonb_build_object(
    'gates', jsonb_build_object(
      'engagement_letter_signed', v_el_signed,
      'aml_passed', v_aml,
      'billing_settled', v_billing,
      'onboarding_submitted', v_submitted,
      'not_already_closed', v_open,
      'activation_context_present', v_context
    ),
    'all_pass', (array_length(v_outstanding, 1) IS NULL),
    'activation_ready', v_activation_ready,
    'billing_settled', v_billing,
    'outstanding', to_jsonb(v_outstanding)
  );
END;
$$;


--
-- Name: FUNCTION lifecycle_onboarding_gates(p_application_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lifecycle_onboarding_gates(p_application_id uuid) IS 'Sprint 1: read-only canonical activation gates for an onboarding application. Returns {gates, all_pass, outstanding}. Shared by lifecycle_evaluate_onboarding_activation and the lifecycle_approve_onboarding guard. Writes nothing.';

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

--
-- Name: protect_signatory_signature(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_signatory_signature() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.signed_at IS NOT NULL AND (
       OLD.signed_at            IS DISTINCT FROM NEW.signed_at OR
       OLD.signer_name          IS DISTINCT FROM NEW.signer_name OR
       OLD.signer_email         IS DISTINCT FROM NEW.signer_email OR
       OLD.signature_ip         IS DISTINCT FROM NEW.signature_ip OR
       OLD.signature_user_agent IS DISTINCT FROM NEW.signature_user_agent
  ) THEN
    RAISE EXCEPTION 'Cannot modify signature fields on a signed signatory';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: protect_system_vat_codes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_system_vat_codes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.is_system THEN
      RAISE EXCEPTION 'System VAT code "%" cannot be deleted', OLD.code
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.is_system AND (
       NEW.code IS DISTINCT FROM OLD.code
       OR NEW.rate IS DISTINCT FROM OLD.rate
       OR NEW.vat_type IS DISTINCT FROM OLD.vat_type
       OR NEW.is_system IS DISTINCT FROM OLD.is_system
    ) THEN
      RAISE EXCEPTION 'System VAT code "%" core fields (code/rate/type/is_system) cannot be modified', OLD.code
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: public_accept_quote_by_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_accept_quote_by_token(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tok record;
  v_quote record;
  v_lead record;
  v_org uuid;
  v_canonical boolean;
  v_client_id uuid;
  v_company_id uuid;
  v_partnership_id uuid;
  v_has_individual boolean := false;
  v_has_company boolean := false;
  v_has_partnership boolean := false;
  v_has_cgt boolean := false;
  v_is_mtd boolean := false;
  v_company_name text;
  v_company record;
  v_today date := current_date;
  v_tax_year_start date;
  v_tax_year_end date;
  v_token_uuid uuid;
  v_director record;
  v_sa_first text;
  v_sa_last text;
  v_sa_email text;
  v_sa_phone text;
  v_sa_blocked boolean := false;
BEGIN
  BEGIN
    v_token_uuid := p_token::uuid;
  EXCEPTION WHEN others THEN
    RETURN jsonb_build_object('error','invalid');
  END;

  SELECT * INTO v_tok FROM public.quote_acceptance_tokens WHERE token = v_token_uuid;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','invalid'); END IF;
  IF v_tok.used_at IS NOT NULL THEN RETURN jsonb_build_object('error','used'); END IF;
  IF v_tok.expires_at IS NOT NULL AND v_tok.expires_at < now() THEN
    RETURN jsonb_build_object('error','expired');
  END IF;

  SELECT * INTO v_quote FROM public.quotes WHERE id = v_tok.quote_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','invalid'); END IF;

  IF v_quote.status = 'accepted' THEN
    UPDATE public.quote_acceptance_tokens SET used_at = now() WHERE token = v_token_uuid AND used_at IS NULL;
    RETURN jsonb_build_object('success', true, 'client_id', v_quote.ported_to_client_id, 'company_id', v_quote.ported_to_company_id, 'replay', true);
  END IF;

  IF v_quote.status NOT IN ('draft','sent') THEN
    RETURN jsonb_build_object('error','not_open');
  END IF;

  v_org := v_quote.organization_id;
  v_canonical := public.is_canonical_lifecycle_enabled(v_org);

  SELECT
    bool_or(sc.entity_scope = 'individual') OR bool_or(sc.code IN ('sa_mtd','sa_non_mtd','cgt_60_day')),
    bool_or(sc.entity_scope = 'company'),
    bool_or(sc.entity_scope = 'partnership'),
    bool_or(sc.code = 'sa_mtd'),
    bool_or(sc.code = 'cgt_60_day')
  INTO v_has_individual, v_has_company, v_has_partnership, v_is_mtd, v_has_cgt
  FROM public.quote_lines ql
  JOIN public.services_catalog sc ON sc.id = ql.service_id
  WHERE ql.quote_id = v_quote.id;

  v_has_individual := COALESCE(v_has_individual, false);
  v_has_company := COALESCE(v_has_company, false);
  v_has_partnership := COALESCE(v_has_partnership, false);
  v_has_cgt := COALESCE(v_has_cgt, false);

  IF v_quote.lead_id IS NOT NULL THEN
    SELECT * INTO v_lead FROM public.leads WHERE id = v_quote.lead_id;
  END IF;

  v_client_id := v_quote.client_id;
  v_company_id := v_quote.company_id;

  IF v_has_company AND v_company_id IS NULL AND v_lead.id IS NOT NULL THEN
    v_company_name := COALESCE(
      NULLIF(v_lead.ch_company_profile->>'company_name',''),
      NULLIF(v_lead.ch_company_profile->>'title',''),
      trim(coalesce(v_lead.first_name,'') || ' ' || coalesce(v_lead.last_name,''))
    );

    SELECT id INTO v_company_id FROM public.companies
      WHERE organization_id = v_org AND lower(email) = lower(v_lead.email)
      LIMIT 1;
    IF v_company_id IS NULL THEN
      INSERT INTO public.companies (organization_id, company_name, email, phone, company_number,
                                    ch_company_profile, status, notes)
      VALUES (v_org, v_company_name, v_lead.email, v_lead.phone,
              v_lead.ch_company_profile->>'company_number',
              v_lead.ch_company_profile, 'pending', v_lead.notes)
      RETURNING id INTO v_company_id;

      IF NOT v_canonical THEN
      INSERT INTO public.accountant_client_links (practice_id, company_id, status, initiated_by, activated_at)
      VALUES (v_org, v_company_id, 'active', 'practice', now());
      END IF;
    END IF;
  END IF;

  IF v_has_individual AND v_client_id IS NULL AND v_lead.id IS NOT NULL THEN
    IF v_has_company THEN
      SELECT * INTO v_director FROM public.resolve_company_director(v_company_id, v_quote.lead_id, v_org);
      IF v_director.first_name IS NOT NULL OR v_director.last_name IS NOT NULL THEN
        v_sa_first := v_director.first_name;
        v_sa_last  := v_director.last_name;
        v_sa_email := COALESCE(v_director.email, v_lead.email);
        v_sa_phone := COALESCE(v_director.phone, v_lead.phone);
      ELSE
        v_sa_blocked := true;
        INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, metadata)
        VALUES (v_org, 'SA_DIRECTOR_DETAILS_REQUIRED', 'company', v_company_id,
                jsonb_build_object(
                  'quote_id', v_quote.id,
                  'lead_id', v_quote.lead_id,
                  'reason', 'no_director_on_file'
                ));
      END IF;
    ELSE
      v_sa_first := v_lead.first_name;
      v_sa_last  := v_lead.last_name;
      v_sa_email := v_lead.email;
      v_sa_phone := v_lead.phone;
    END IF;

    IF NOT v_sa_blocked THEN
      SELECT id INTO v_client_id FROM public.clients
        WHERE organization_id = v_org AND lower(email) = lower(v_sa_email)
          AND client_type IN ('sa_non_mtd','sa_mtd')
        LIMIT 1;
      IF v_client_id IS NULL THEN
        INSERT INTO public.clients (organization_id, first_name, last_name, email, phone, client_type, status, notes)
        VALUES (v_org, v_sa_first, v_sa_last, v_sa_email, v_sa_phone,
                CASE WHEN v_is_mtd THEN 'sa_mtd' ELSE 'sa_non_mtd' END,
                'pending', v_lead.notes)
        RETURNING id INTO v_client_id;

        INSERT INTO public.client_detail_sa (client_id, organization_id, is_mtd)
        VALUES (v_client_id, v_org, v_is_mtd)
        ON CONFLICT DO NOTHING;

        IF NOT v_canonical THEN
        INSERT INTO public.accountant_client_links (practice_id, client_id, status, initiated_by, activated_at)
        VALUES (v_org, v_client_id, 'active', 'practice', now());
        END IF;
      END IF;

      IF v_has_cgt THEN
        INSERT INTO public.client_detail_cgt (client_id, organization_id)
        VALUES (v_client_id, v_org)
        ON CONFLICT DO NOTHING;
      END IF;
    END IF;
  END IF;

  IF v_has_partnership AND v_lead.id IS NOT NULL THEN
    SELECT id INTO v_partnership_id FROM public.clients
      WHERE organization_id = v_org AND lower(email) = lower(v_lead.email)
        AND client_type = 'partnership'
      LIMIT 1;
    IF v_partnership_id IS NULL THEN
      INSERT INTO public.clients (organization_id, first_name, last_name, email, phone, client_type, status, notes)
      VALUES (v_org, v_lead.first_name, v_lead.last_name, v_lead.email, v_lead.phone,
              'partnership', 'pending',
              coalesce(v_lead.notes,'') || E'\n[Action required] Partnership second contact required.')
      RETURNING id INTO v_partnership_id;
      INSERT INTO public.client_detail_partnership (client_id, organization_id)
      VALUES (v_partnership_id, v_org) ON CONFLICT DO NOTHING;
      IF NOT v_canonical THEN
      INSERT INTO public.accountant_client_links (practice_id, client_id, status, initiated_by, activated_at)
      VALUES (v_org, v_partnership_id, 'active', 'practice', now());
      END IF;

      INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, metadata)
      VALUES (v_org, 'PARTNERSHIP_SECOND_CONTACT_REQUIRED', 'client', v_partnership_id,
              jsonb_build_object('quote_id', v_quote.id, 'lead_id', v_lead.id));
    END IF;
    IF v_client_id IS NULL THEN v_client_id := v_partnership_id; END IF;
  END IF;

  IF v_company_id IS NOT NULL THEN
    SELECT * INTO v_company FROM public.companies WHERE id = v_company_id;
  ELSE
    SELECT NULL::uuid AS id,
           NULL::int  AS year_end_month,
           NULL::int  AS year_end_day
    INTO v_company;
  END IF;

  IF EXTRACT(MONTH FROM v_today) > 4
     OR (EXTRACT(MONTH FROM v_today) = 4 AND EXTRACT(DAY FROM v_today) >= 6) THEN
    v_tax_year_start := make_date(EXTRACT(YEAR FROM v_today)::int, 4, 6);
  ELSE
    v_tax_year_start := make_date(EXTRACT(YEAR FROM v_today)::int - 1, 4, 6);
  END IF;
  v_tax_year_end := v_tax_year_start + INTERVAL '1 year' - INTERVAL '1 day';

  IF NOT v_canonical THEN
    PERFORM public.lifecycle_materialize_jobs(
      v_org, v_client_id, v_company_id, v_partnership_id, v_quote.id,
      'quote_acceptance:' || v_quote.id::text);
  END IF;

  UPDATE public.quotes
     SET status = 'accepted',
         accepted_at = now(),
         sent_at = COALESCE(sent_at, now()),
         client_id = COALESCE(client_id, v_client_id),
         company_id = COALESCE(company_id, v_company_id),
         ported_to_client_id = COALESCE(ported_to_client_id, v_client_id),
         ported_to_company_id = COALESCE(ported_to_company_id, v_company_id),
         ported_at = COALESCE(ported_at, now())
   WHERE id = v_quote.id;

  IF v_quote.lead_id IS NOT NULL THEN
    UPDATE public.leads SET pipeline_stage = 'won', updated_at = now() WHERE id = v_quote.lead_id;
  END IF;

  UPDATE public.quote_acceptance_tokens SET used_at = now() WHERE token = v_token_uuid;

  INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, metadata)
  VALUES (v_org, 'QUOTE_ACCEPTED', 'quote', v_quote.id,
          jsonb_build_object('client_id', v_client_id, 'company_id', v_company_id, 'partnership_id', v_partnership_id));

  RETURN jsonb_build_object('success', true, 'client_id', v_client_id, 'company_id', v_company_id, 'partnership_id', v_partnership_id);
END;
$$;


--
-- Name: public_complete_billing(uuid, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_complete_billing(p_application_id uuid, p_stripe_session_id text, p_amount numeric, p_access_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id FOR UPDATE;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);

  UPDATE public.onboarding_applications
     SET billing_status = 'completed',
         billing_amount = COALESCE(p_amount, billing_amount),
         stripe_checkout_session_id = COALESCE(p_stripe_session_id, stripe_checkout_session_id),
         billing_completed_at = now(),
         status = CASE WHEN status IN ('billing_pending','aml_pending','engagement_pending')
                       THEN 'portal_pending' ELSE status END,
         updated_at = now()
   WHERE id = p_application_id;

  RETURN jsonb_build_object('status','portal_pending');
END;
$$;


--
-- Name: public_get_engagement_letter_for_signing(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_get_engagement_letter_for_signing(p_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uuid     uuid;
  v_sig      public.engagement_letter_signatories%ROWTYPE;
  v_letter   public.engagement_letters%ROWTYPE;
  v_org_name text;
  v_progress jsonb;
  v_expired  boolean;
BEGIN
  IF p_token IS NULL OR length(trim(p_token)) = 0 THEN
    RETURN jsonb_build_object('found', false, 'error', 'Missing signing token');
  END IF;

  -- A signatory token is a uuid; a letter token is free text. A non-uuid string simply
  -- means "this can only be a letter token".
  BEGIN
    v_uuid := trim(p_token)::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    v_uuid := NULL;
  END;

  IF v_uuid IS NOT NULL THEN
    SELECT * INTO v_sig
      FROM public.engagement_letter_signatories
     WHERE signature_token = v_uuid;
  END IF;

  IF v_sig.id IS NOT NULL THEN
    SELECT * INTO v_letter FROM public.engagement_letters WHERE id = v_sig.engagement_letter_id;
  ELSE
    SELECT * INTO v_letter FROM public.engagement_letters WHERE signature_token = trim(p_token);
  END IF;

  IF v_letter.id IS NULL THEN
    RETURN jsonb_build_object('found', false,
      'error', 'This engagement letter link is invalid or has expired.');
  END IF;

  SELECT COALESCE(NULLIF(ob.trading_name, ''), NULLIF(ob.legal_name, ''), o.name)
    INTO v_org_name
    FROM public.organizations o
    LEFT JOIN public.organization_branding ob ON ob.organization_id = o.id
   WHERE o.id = v_letter.organization_id;

  v_progress := public.el_signature_progress(v_letter.id);
  v_expired  := (v_letter.token_expires_at IS NOT NULL AND v_letter.token_expires_at < now());

  RETURN jsonb_build_object(
    'found', true,
    'firm_name', COALESCE(v_org_name, 'Your Accountant'),
    'letter', jsonb_build_object(
      'id',             v_letter.id,
      'document_content', v_letter.document_content,
      'status',         v_letter.status,
      'signing_rule',   COALESCE(v_letter.signing_rule, 'all'),
      'signed_at',      v_letter.signed_at,
      'expired',        v_expired
    ),
    'signer', CASE WHEN v_sig.id IS NULL THEN NULL ELSE jsonb_build_object(
      'kind',         'signatory',
      'signatory_id', v_sig.id,
      'name',         v_sig.signer_name,
      'email',        v_sig.signer_email,
      'required',     v_sig.required,
      'signed_at',    v_sig.signed_at
    ) END,
    'progress', v_progress,
    'requires_personal_link', (
      v_sig.id IS NULL AND COALESCE((v_progress->>'has_signatories')::boolean, false)
    )
  );
END;
$$;


--
-- Name: FUNCTION public_get_engagement_letter_for_signing(p_token text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.public_get_engagement_letter_for_signing(p_token text) IS 'Public (anon) read for the engagement-letter signing page. Resolves a per-signatory token or the letter-level token. Exists because engagement_letters has RLS with no anon SELECT policy — the page must never query that table directly.';


--
-- Name: public_get_onboarding(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_get_onboarding(p_application_id uuid, p_access_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_app record;
  v_org record;
  v_brand record;
  v_quote record;
  v_docs jsonb;
  v_engagement record;
  v_has_connect boolean;
  v_display_name text;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Onboarding application not found' USING ERRCODE='P0002'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);

  SELECT id, name, logo_url, stripe_connect_account_id INTO v_org
    FROM public.organizations WHERE id = v_app.organization_id;
  v_has_connect := v_org.stripe_connect_account_id IS NOT NULL;

  SELECT trading_name, legal_name INTO v_brand
    FROM public.organization_branding WHERE organization_id = v_app.organization_id;

  v_display_name := COALESCE(NULLIF(v_brand.trading_name, ''), NULLIF(v_brand.legal_name, ''), v_org.name);

  SELECT id, quote_number, accepted_snapshot, currency
    INTO v_quote FROM public.quotes WHERE id = v_app.quote_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', id, 'document_type', document_type, 'file_name', file_name,
    'file_path', file_path, 'created_at', created_at
  ) ORDER BY created_at), '[]'::jsonb) INTO v_docs
    FROM public.onboarding_documents WHERE application_id = p_application_id;

  SELECT id, signed_at, sent_at, document_content INTO v_engagement
    FROM public.engagement_letters
   WHERE onboarding_application_id = p_application_id
   ORDER BY created_at DESC LIMIT 1;

  RETURN jsonb_build_object(
    'application', to_jsonb(v_app) - 'access_token' - 'access_token_expires_at',
    'organization', jsonb_build_object(
      'id', v_org.id,
      'name', v_display_name,
      'logo_url', v_org.logo_url,
      'has_stripe_connect', v_has_connect
    ),
    'quote', to_jsonb(v_quote),
    'documents', v_docs,
    'engagement_letter', to_jsonb(v_engagement)
  );
END;
$$;


--
-- Name: public_get_quote_by_token(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_get_quote_by_token(p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tok record; v_quote record; v_practice_name text; v_recipient_name text; v_lines jsonb;
  v_onboarding_id uuid;
  v_access_token text;
  v_lead record;
  v_app_type text;
  v_first_name text;
  v_last_name text;
  v_preferred text;
  v_email text;
  v_phone text;
  v_company_name text;
  v_company_number text;
  v_has_company boolean;
  v_snapshot jsonb;
  v_total_now numeric;
  v_total_monthly numeric;
  v_total_annual numeric;
BEGIN
  SELECT * INTO v_tok FROM quote_acceptance_tokens WHERE token = p_token;
  IF v_tok.token IS NULL THEN RETURN jsonb_build_object('error', 'invalid'); END IF;
  IF v_tok.expires_at <= now() THEN RETURN jsonb_build_object('error', 'expired'); END IF;

  SELECT * INTO v_quote FROM quotes WHERE id = v_tok.quote_id;

  SELECT COALESCE(NULLIF(ob.trading_name, ''), NULLIF(ob.legal_name, ''), o.name)
    INTO v_practice_name
  FROM organizations o LEFT JOIN organization_branding ob ON ob.organization_id = o.id
  WHERE o.id = v_quote.organization_id;

  IF v_quote.lead_id IS NOT NULL THEN
    SELECT NULLIF(trim(coalesce(first_name,'') || ' ' || coalesce(last_name,'')), '')
      INTO v_recipient_name FROM leads WHERE id = v_quote.lead_id;
  ELSIF v_quote.client_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(trim(preferred_name), ''),
                    NULLIF(trim(coalesce(first_name,'') || ' ' || coalesce(last_name,'')), ''))
      INTO v_recipient_name FROM clients WHERE id = v_quote.client_id;
  END IF;

  IF v_recipient_name IS NULL AND v_quote.company_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(trim(c.preferred_name), ''),
                    NULLIF(trim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''))
      INTO v_recipient_name
    FROM clients c
    WHERE c.company_id = v_quote.company_id
    ORDER BY c.created_at ASC LIMIT 1;

    IF v_recipient_name IS NULL THEN
      SELECT company_name INTO v_recipient_name FROM companies WHERE id = v_quote.company_id;
    END IF;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'service_id', ql.service_id,
    'service_code', sc.code,
    'service_name', COALESCE(NULLIF(ql.description_override, ''), sc.name),
    'quantity', ql.quantity, 'unit_price', ql.unit_price,
    'subtotal', ql.subtotal, 'billing_frequency', ql.billing_frequency
  ) ORDER BY ql.line_order, ql.created_at), '[]'::jsonb)
    INTO v_lines
  FROM quote_lines ql JOIN services_catalog sc ON sc.id = ql.service_id
  WHERE ql.quote_id = v_quote.id;

  SELECT id, access_token INTO v_onboarding_id, v_access_token
  FROM onboarding_applications
  WHERE quote_id = v_quote.id
    AND status <> 'cancelled'
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_onboarding_id IS NULL AND v_quote.status = 'accepted' THEN
    IF v_quote.lead_id IS NOT NULL THEN
      SELECT * INTO v_lead FROM leads WHERE id = v_quote.lead_id;
      v_first_name := v_lead.first_name;
      v_last_name := v_lead.last_name;
      v_email := v_lead.email;
      v_phone := v_lead.phone;
    ELSIF v_quote.client_id IS NOT NULL THEN
      SELECT first_name, last_name, email, phone
        INTO v_first_name, v_last_name, v_email, v_phone
        FROM clients WHERE id = v_quote.client_id;
    END IF;

    v_has_company := v_quote.company_id IS NOT NULL;
    IF v_has_company THEN
      SELECT company_name, company_number INTO v_company_name, v_company_number
        FROM companies WHERE id = v_quote.company_id;
    END IF;

    v_app_type := CASE WHEN v_has_company THEN 'company' ELSE 'individual' END;

    INSERT INTO onboarding_applications (
      organization_id, lead_id, quote_id, application_type, status,
      first_name, last_name, email, phone,
      company_name, company_number, client_id, company_id
    ) VALUES (
      v_quote.organization_id, v_quote.lead_id, v_quote.id, v_app_type, 'in_progress',
      v_first_name, v_last_name, v_email, v_phone,
      v_company_name, v_company_number, v_quote.client_id, v_quote.company_id
    )
    RETURNING id, access_token INTO v_onboarding_id, v_access_token;
  END IF;

  IF v_quote.status <> 'accepted' THEN
    v_access_token := NULL;

  ELSIF v_onboarding_id IS NOT NULL AND (v_access_token IS NULL OR v_access_token = '') THEN
    UPDATE onboarding_applications
       SET access_token = public.gen_onboarding_access_token(),
           access_token_expires_at = COALESCE(access_token_expires_at, now() + interval '90 days')
     WHERE id = v_onboarding_id
    RETURNING access_token INTO v_access_token;
  END IF;

  IF v_quote.status = 'accepted' AND (v_quote.accepted_snapshot IS NULL OR v_quote.accepted_snapshot = 'null'::jsonb) THEN
    SELECT
      COALESCE(SUM(CASE WHEN COALESCE(billing_frequency,'one_off') NOT IN ('monthly','annual') THEN COALESCE(subtotal,0) ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN COALESCE(billing_frequency,'one_off') = 'monthly' THEN COALESCE(subtotal,0) ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN COALESCE(billing_frequency,'one_off') = 'annual'  THEN COALESCE(subtotal,0) ELSE 0 END), 0)
      INTO v_total_now, v_total_monthly, v_total_annual
    FROM jsonb_to_recordset(v_lines)
      AS x(subtotal numeric, billing_frequency text);

    v_snapshot := jsonb_build_object(
      'lines', v_lines,
      'currency', COALESCE(v_quote.currency, 'GBP'),
      'quote_number', v_quote.quote_number,
      'accepted_at', COALESCE(v_quote.accepted_at, now()),
      'valid_until', v_quote.valid_until,
      'total_now', v_total_now,
      'total_monthly', v_total_monthly,
      'total_annual', v_total_annual,
      'total_amount', COALESCE(v_quote.total_amount, v_total_now + v_total_monthly + v_total_annual)
    );

    UPDATE quotes SET accepted_snapshot = v_snapshot WHERE id = v_quote.id;
    v_quote.accepted_snapshot := v_snapshot;
  END IF;

  RETURN jsonb_build_object(
    'quote_id', v_quote.id, 'quote_number', v_quote.quote_number, 'status', v_quote.status,
    'currency', v_quote.currency, 'total_amount', v_quote.total_amount,
    'valid_until', v_quote.valid_until, 'sent_at', v_quote.sent_at,
    'accepted_at', v_quote.accepted_at, 'rejected_at', v_quote.rejected_at,
    'notes', v_quote.notes, 'practice_name', v_practice_name,
    'recipient_name', v_recipient_name, 'lines', v_lines,
    'used', v_tok.used_at IS NOT NULL,
    'onboarding_application_id', v_onboarding_id,
    'onboarding_access_token', v_access_token
  );
END;
$$;


--
-- Name: public_preview_engagement_letter(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_preview_engagement_letter(p_application_id uuid, p_access_token text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
  v_quote record;
  v_org_name text;
  v_lines text := '';
  v_line jsonb;
  v_client_name text;
  v_preferred text;
  v_currency text;
  v_accepted_at timestamptz;
  v_total_now numeric;
  v_total_monthly numeric;
  v_client_type text;
  v_variant_id uuid;
  v_letter_body text;
  v_rendered text;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id;
  IF v_app IS NULL THEN RETURN NULL; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);

  SELECT COALESCE(NULLIF(ob.trading_name, ''), NULLIF(ob.legal_name, ''), o.name)
    INTO v_org_name
  FROM public.organizations o
  LEFT JOIN public.organization_branding ob ON ob.organization_id = o.id
  WHERE o.id = v_app.organization_id;

  SELECT accepted_snapshot, currency, accepted_at
    INTO v_quote FROM public.quotes WHERE id = v_app.quote_id;

  IF v_app.client_id IS NOT NULL THEN
    SELECT preferred_name INTO v_preferred FROM public.clients WHERE id = v_app.client_id;
  END IF;

  v_client_name := COALESCE(
    NULLIF(trim(v_preferred), ''),
    NULLIF(trim(coalesce(v_app.first_name,'') || ' ' || coalesce(v_app.last_name,'')), ''),
    v_app.company_name
  );
  v_currency := COALESCE(v_quote.currency, 'GBP');
  v_accepted_at := COALESCE((v_quote.accepted_snapshot->>'accepted_at')::timestamptz, v_quote.accepted_at, now());
  v_total_now := COALESCE((v_quote.accepted_snapshot->>'total_now')::numeric, 0);
  v_total_monthly := COALESCE((v_quote.accepted_snapshot->>'total_monthly')::numeric, 0);

  IF v_quote.accepted_snapshot IS NOT NULL THEN
    FOR v_line IN SELECT * FROM jsonb_array_elements(v_quote.accepted_snapshot->'lines') LOOP
      v_lines := v_lines || '<li>' || (v_line->>'service_name') ||
        ' — ' || v_currency || ' ' || (v_line->>'subtotal') ||
        ' (' || COALESCE(v_line->>'billing_frequency','annual') || ')</li>';
    END LOOP;
  END IF;

  v_client_type := CASE WHEN v_app.application_type = 'individual' THEN 'individual' ELSE 'limited_company' END;
  v_variant_id := public.resolve_engagement_letter_variant(
    v_app.organization_id, v_client_type, NULL, NULL, 'recurring'
  );
  IF v_variant_id IS NOT NULL THEN
    SELECT letter_body INTO v_letter_body
      FROM public.engagement_letter_template_variants WHERE id = v_variant_id;
    v_rendered := public.render_engagement_letter_body(
      v_letter_body, v_org_name, v_client_name,
      '<ul>' || v_lines || '</ul>',
      v_currency, v_total_now, v_total_monthly, v_accepted_at
    );
    IF v_rendered IS NOT NULL THEN RETURN v_rendered; END IF;
  END IF;

  RETURN '<h1>Engagement Letter</h1>' ||
    '<p>Between <strong>' || v_org_name || '</strong> ("the Firm") and <strong>' ||
    v_client_name || '</strong> ("the Client").</p>' ||
    '<h2>Scope of Services</h2><ul>' || v_lines || '</ul>' ||
    '<h2>Fees</h2>' ||
    '<p>One-off fees due now total ' || v_currency || ' ' || v_total_now::text || '. ' ||
    'Ongoing monthly fees total ' || v_currency || ' ' || v_total_monthly::text || ' per month.</p>' ||
    '<h2>Confidentiality</h2>' ||
    '<p>The Firm will treat all information received in the course of this engagement as confidential, except where disclosure is required by law or regulatory authority.</p>' ||
    '<h2>Acceptance</h2>' ||
    '<p>By signing below the Client confirms acceptance of the terms above, in respect of the proposal accepted on ' ||
    to_char(v_accepted_at, 'DD Mon YYYY') || '.</p>';
END;
$$;


--
-- Name: public_record_aml_upload(uuid, text, text, text, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_record_aml_upload(p_application_id uuid, p_document_type text, p_file_name text, p_file_path text, p_file_size integer, p_mime_type text, p_access_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
  v_has_id boolean;
  v_has_poa boolean;
  v_next_status text;
BEGIN
  IF p_document_type NOT IN ('id','proof_of_address','incorporation_cert','other') THEN
    RAISE EXCEPTION 'Invalid document type';
  END IF;

  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id FOR UPDATE;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);
  IF v_app.status IN ('approved','rejected','cancelled') THEN
    RAISE EXCEPTION 'Onboarding is closed';
  END IF;

  INSERT INTO public.onboarding_documents (
    organization_id, application_id, document_type, file_name, file_path, file_size, mime_type
  ) VALUES (
    v_app.organization_id, p_application_id, p_document_type, p_file_name, p_file_path, p_file_size, p_mime_type
  );

  v_has_id := v_app.id_document_uploaded OR p_document_type = 'id';
  v_has_poa := v_app.proof_of_address_uploaded OR p_document_type = 'proof_of_address';

  v_next_status := v_app.status;
  IF v_has_id AND v_has_poa AND v_app.status IN ('engagement_pending','aml_pending') THEN
    v_next_status := 'billing_pending';
  END IF;

  UPDATE public.onboarding_applications
     SET id_document_uploaded = v_has_id,
         proof_of_address_uploaded = v_has_poa,
         additional_documents_uploaded = CASE WHEN p_document_type IN ('incorporation_cert','other')
                                              THEN true ELSE additional_documents_uploaded END,
         aml_submitted_at = COALESCE(aml_submitted_at,
                                     CASE WHEN v_has_id AND v_has_poa THEN now() ELSE NULL END),
         status = v_next_status,
         updated_at = now()
   WHERE id = p_application_id;

  RETURN jsonb_build_object('status', v_next_status);
END;
$$;


--
-- Name: public_reject_quote_by_token(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_reject_quote_by_token(p_token text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tok record;
  v_quote record;
  v_org uuid;
BEGIN
  SELECT * INTO v_tok FROM public.quote_acceptance_tokens WHERE token = p_token;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','invalid'); END IF;
  IF v_tok.used_at IS NOT NULL THEN RETURN jsonb_build_object('error','used'); END IF;
  IF v_tok.expires_at IS NOT NULL AND v_tok.expires_at < now() THEN
    RETURN jsonb_build_object('error','expired');
  END IF;

  SELECT * INTO v_quote FROM public.quotes WHERE id = v_tok.quote_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','invalid'); END IF;
  IF v_quote.status NOT IN ('draft','sent') THEN RETURN jsonb_build_object('error','not_open'); END IF;

  v_org := v_quote.organization_id;

  UPDATE public.quotes
     SET status = 'rejected',
         rejected_at = now(),
         rejection_reason = COALESCE(NULLIF(p_reason,''), 'Declined by client')
   WHERE id = v_quote.id;

  UPDATE public.quote_acceptance_tokens SET used_at = now() WHERE id = v_tok.id;

  IF v_quote.lead_id IS NOT NULL THEN
    UPDATE public.leads
       SET pipeline_stage = 'lost',
           lost_at = now(),
           lost_reason = COALESCE(NULLIF(p_reason,''), 'Quote declined')
     WHERE id = v_quote.lead_id
       AND pipeline_stage <> 'won';
  END IF;

  INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, metadata)
  VALUES (v_org, 'QUOTE_REJECTED', 'quote', v_quote.id,
          jsonb_build_object('reason', p_reason, 'source','public_token'));

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: public_reject_quote_by_token(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_reject_quote_by_token(p_token uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_tok record; v_quote record; v_old_status text;
BEGIN
  SELECT * INTO v_tok FROM quote_acceptance_tokens WHERE token = p_token;
  IF v_tok.token IS NULL THEN RETURN jsonb_build_object('error', 'invalid'); END IF;
  IF v_tok.used_at IS NOT NULL THEN RETURN jsonb_build_object('error', 'already_used'); END IF;
  IF v_tok.expires_at <= now() THEN RETURN jsonb_build_object('error', 'expired'); END IF;

  SELECT * INTO v_quote FROM quotes WHERE id = v_tok.quote_id FOR UPDATE;
  IF v_quote.status NOT IN ('draft','sent') THEN
    RETURN jsonb_build_object('error','invalid_status','status', v_quote.status);
  END IF;
  v_old_status := v_quote.status;

  UPDATE quotes SET status='rejected', rejected_at=now(),
                   rejection_reason=COALESCE(p_reason,'Declined by client')
  WHERE id = v_quote.id;
  UPDATE quote_acceptance_tokens SET used_at=now() WHERE token = p_token;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, old_value, new_value, user_id, metadata)
  VALUES (v_quote.organization_id, 'quote', v_quote.id, 'status_change', v_old_status, 'rejected', NULL,
          jsonb_build_object('source','public_token','reason', p_reason));

  RETURN jsonb_build_object('success', true, 'quote_id', v_quote.id, 'status','rejected');
END;
$$;


--
-- Name: public_save_onboarding_details(uuid, text, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_save_onboarding_details(p_application_id uuid, p_access_token text, p_utr text DEFAULT NULL::text, p_vat_number text DEFAULT NULL::text, p_paye_reference text DEFAULT NULL::text, p_personal_details jsonb DEFAULT NULL::jsonb, p_ch_correction_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id FOR UPDATE;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);
  IF v_app.status IN ('approved','rejected','cancelled') THEN
    RAISE EXCEPTION 'Onboarding is closed';
  END IF;

  UPDATE public.onboarding_applications
     SET utr = COALESCE(p_utr, utr),
         vat_number = COALESCE(p_vat_number, vat_number),
         paye_reference = COALESCE(p_paye_reference, paye_reference),
         personal_details = COALESCE(p_personal_details, personal_details),
         ch_correction_note = COALESCE(p_ch_correction_note, ch_correction_note),
         updated_at = now()
   WHERE id = p_application_id;

  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: public_sign_engagement_letter(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_sign_engagement_letter(p_application_id uuid, p_signature_data jsonb, p_access_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
  v_quote record;
  v_org_name text;
  v_content text;
  v_letter_id uuid;
  v_lines text := '';
  v_line jsonb;
  v_client_name text;
  v_preferred text;
  v_currency text;
  v_accepted_at timestamptz;
  v_total_now numeric;
  v_total_monthly numeric;
  v_client_type text;
  v_variant_id uuid;
  v_letter_body text;
  v_rendered text;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id FOR UPDATE;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);
  IF v_app.status IN ('approved','rejected','cancelled') THEN
    RAISE EXCEPTION 'Onboarding is closed';
  END IF;

  SELECT COALESCE(NULLIF(ob.trading_name, ''), NULLIF(ob.legal_name, ''), o.name)
    INTO v_org_name
  FROM public.organizations o
  LEFT JOIN public.organization_branding ob ON ob.organization_id = o.id
  WHERE o.id = v_app.organization_id;

  SELECT accepted_snapshot, currency, accepted_at
    INTO v_quote FROM public.quotes WHERE id = v_app.quote_id;

  IF v_app.client_id IS NOT NULL THEN
    SELECT preferred_name INTO v_preferred FROM public.clients WHERE id = v_app.client_id;
  END IF;

  v_client_name := COALESCE(
    NULLIF(trim(v_preferred), ''),
    NULLIF(trim(coalesce(v_app.first_name,'') || ' ' || coalesce(v_app.last_name,'')), ''),
    v_app.company_name
  );
  v_currency := COALESCE(v_quote.currency, 'GBP');
  v_accepted_at := COALESCE((v_quote.accepted_snapshot->>'accepted_at')::timestamptz, v_quote.accepted_at, now());
  v_total_now := COALESCE((v_quote.accepted_snapshot->>'total_now')::numeric, 0);
  v_total_monthly := COALESCE((v_quote.accepted_snapshot->>'total_monthly')::numeric, 0);

  IF v_quote.accepted_snapshot IS NOT NULL THEN
    FOR v_line IN SELECT * FROM jsonb_array_elements(v_quote.accepted_snapshot->'lines') LOOP
      v_lines := v_lines || '<li>' || (v_line->>'service_name') ||
        ' — ' || v_currency || ' ' || (v_line->>'subtotal') ||
        ' (' || COALESCE(v_line->>'billing_frequency','annual') || ')</li>';
    END LOOP;
  END IF;

  v_client_type := CASE WHEN v_app.application_type = 'individual' THEN 'individual' ELSE 'limited_company' END;
  v_variant_id := public.resolve_engagement_letter_variant(
    v_app.organization_id, v_client_type, NULL, NULL, 'recurring'
  );
  IF v_variant_id IS NOT NULL THEN
    SELECT letter_body INTO v_letter_body
      FROM public.engagement_letter_template_variants WHERE id = v_variant_id;
    v_rendered := public.render_engagement_letter_body(
      v_letter_body, v_org_name, v_client_name,
      '<ul>' || v_lines || '</ul>',
      v_currency, v_total_now, v_total_monthly, v_accepted_at
    );
  END IF;

  v_content := COALESCE(
    v_rendered,
    '<h1>Engagement Letter</h1>' ||
    '<p>Between <strong>' || v_org_name || '</strong> ("the Firm") and <strong>' ||
    v_client_name || '</strong> ("the Client").</p>' ||
    '<h2>Scope of Services</h2><ul>' || v_lines || '</ul>' ||
    '<h2>Fees</h2><p>Total commercial terms as per accepted proposal dated ' ||
    to_char(v_accepted_at, 'DD Mon YYYY') || '.</p>' ||
    '<h2>Acceptance</h2><p>By signing below the Client confirms acceptance of the terms above.</p>'
  );

  SELECT id INTO v_letter_id FROM public.engagement_letters
   WHERE onboarding_application_id = p_application_id ORDER BY created_at DESC LIMIT 1;

  IF v_letter_id IS NULL THEN
    INSERT INTO public.engagement_letters (
      organization_id, onboarding_application_id, document_content,
      sent_at, signed_at, signature_ip, signature_user_agent
    ) VALUES (
      v_app.organization_id, p_application_id, v_content,
      now(), now(),
      p_signature_data->>'ip', p_signature_data->>'user_agent'
    ) RETURNING id INTO v_letter_id;
  ELSE
    UPDATE public.engagement_letters
       SET document_content = v_content,
           signed_at = now(),
           sent_at = COALESCE(sent_at, now()),
           signature_ip = COALESCE(signature_ip, p_signature_data->>'ip'),
           signature_user_agent = COALESCE(signature_user_agent, p_signature_data->>'user_agent'),
           updated_at = now()
     WHERE id = v_letter_id;
  END IF;

  UPDATE public.onboarding_applications
     SET status = 'aml_pending',
         contracts_signed_at = now(),
         contracts_sent_at = COALESCE(contracts_sent_at, now()),
         signature_data = p_signature_data,
         updated_at = now()
   WHERE id = p_application_id;

  RETURN jsonb_build_object('engagement_letter_id', v_letter_id, 'status','aml_pending');
END;
$$;


--
-- Name: public_sign_engagement_letter_as_signatory(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_sign_engagement_letter_as_signatory(p_token text, p_signature_data jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uuid       uuid;
  v_sig        public.engagement_letter_signatories%ROWTYPE;
  v_letter     public.engagement_letters%ROWTYPE;
  v_app        public.onboarding_applications%ROWTYPE;
  v_name       text;
  v_progress   jsonb;
  v_satisfied  boolean;
  v_status     text;
BEGIN
  IF p_token IS NULL OR length(trim(p_token)) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Missing signing token');
  END IF;

  BEGIN
    v_uuid := trim(p_token)::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN jsonb_build_object('success', false, 'error', 'This signing link is not valid.');
  END;

  -- Lock signatory then letter then application — always in that order, so two
  -- signatories of the same letter signing at the same moment serialise instead of
  -- deadlocking.
  SELECT * INTO v_sig
    FROM public.engagement_letter_signatories
   WHERE signature_token = v_uuid
   FOR UPDATE;

  IF v_sig.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'This signing link is not valid.');
  END IF;

  SELECT * INTO v_letter
    FROM public.engagement_letters
   WHERE id = v_sig.engagement_letter_id
   FOR UPDATE;

  IF v_letter.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'This signing link is not valid.');
  END IF;

  -- Idempotent: re-opening the emailed link and signing again is a no-op success, never
  -- a second signature.
  IF v_sig.signed_at IS NOT NULL THEN
    v_progress := public.el_signature_progress(v_letter.id);
    RETURN jsonb_build_object(
      'success', true, 'already_signed', true, 'signed_at', v_sig.signed_at,
      'all_signed', COALESCE((v_progress->>'satisfied')::boolean, false),
      'progress', v_progress, 'letter_status', v_letter.status
    );
  END IF;

  IF v_letter.token_expires_at IS NOT NULL AND v_letter.token_expires_at < now() THEN
    RETURN jsonb_build_object('success', false,
      'error', 'This signing link has expired. Please ask your accountant to resend it.');
  END IF;

  SELECT * INTO v_app
    FROM public.onboarding_applications
   WHERE id = COALESCE(v_sig.onboarding_application_id, v_letter.onboarding_application_id)
   FOR UPDATE;

  IF v_app.id IS NOT NULL AND v_app.status IN ('approved','rejected','cancelled') THEN
    RETURN jsonb_build_object('success', false,
      'error', 'This engagement is no longer open for signature. Please contact your accountant.');
  END IF;

  v_name := COALESCE(NULLIF(trim(p_signature_data->>'full_name'), ''), v_sig.signer_name);

  UPDATE public.engagement_letter_signatories
     SET signed_at            = now(),
         signer_name          = v_name,
         signature_ip         = p_signature_data->>'ip',
         signature_user_agent = p_signature_data->>'user_agent'
   WHERE id = v_sig.id;

  -- The rule lives in ONE place (T2d-1) — the same function the activation gate calls.
  v_progress  := public.el_signature_progress(v_letter.id);
  v_satisfied := COALESCE((v_progress->>'satisfied')::boolean, false);

  IF v_satisfied THEN
    UPDATE public.engagement_letters
       SET signed_at            = COALESCE(signed_at, now()),
           status               = 'signed',
           signature_name       = COALESCE(signature_name, v_name),
           signature_ip         = COALESCE(signature_ip, p_signature_data->>'ip'),
           signature_user_agent = COALESCE(signature_user_agent, p_signature_data->>'user_agent'),
           viewed_at            = COALESCE(viewed_at, now()),
           updated_at           = now()
     WHERE id = v_letter.id;

    -- The application-side write the emailed-link path has always been missing.
    IF v_app.id IS NOT NULL THEN
      UPDATE public.onboarding_applications
         SET contracts_signed_at = COALESCE(contracts_signed_at, now()),
             contracts_sent_at   = COALESCE(contracts_sent_at, now()),
             signature_data      = COALESCE(signature_data, p_signature_data),
             status = CASE
               WHEN status IN ('draft','in_progress','engagement_pending') THEN 'aml_pending'
               ELSE status
             END,
             updated_at = now()
       WHERE id = v_app.id;
    END IF;
  ELSE
    UPDATE public.engagement_letters
       SET status     = CASE WHEN status = 'signed' THEN 'signed' ELSE 'partially_signed' END,
           viewed_at  = COALESCE(viewed_at, now()),
           updated_at = now()
     WHERE id = v_letter.id;
  END IF;

  SELECT status INTO v_status FROM public.engagement_letters WHERE id = v_letter.id;

  RETURN jsonb_build_object(
    'success', true, 'signed_at', now(), 'all_signed', v_satisfied,
    'progress', v_progress, 'letter_status', v_status
  );
END;
$$;


--
-- Name: FUNCTION public_sign_engagement_letter_as_signatory(p_token text, p_signature_data jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.public_sign_engagement_letter_as_signatory(p_token text, p_signature_data jsonb) IS 'Records ONE signatory''s signature from their own emailed link, then evaluates the signing rule via el_signature_progress: letter status becomes partially_signed until the rule is satisfied, then signed + onboarding contracts_signed_at. Idempotent.';


--
-- Name: public_sign_engagement_letter_by_token(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_sign_engagement_letter_by_token(p_signature_token text, p_signature_data jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_letter   record;
  v_progress jsonb;
BEGIN
  IF p_signature_token IS NULL OR length(trim(p_signature_token)) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Missing signing token');
  END IF;

  SELECT * INTO v_letter
    FROM public.engagement_letters
   WHERE signature_token = p_signature_token
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'This signing link is not valid.');
  END IF;

  IF v_letter.token_expires_at IS NOT NULL AND v_letter.token_expires_at < now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'This signing link has expired. Please ask your accountant to resend it.');
  END IF;

  IF v_letter.signed_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'already_signed', true, 'signed_at', v_letter.signed_at);
  END IF;

  -- T2d-2 (1): per-signatory letters must be signed through each signatory's own link.
  v_progress := public.el_signature_progress(v_letter.id);
  IF COALESCE((v_progress->>'has_signatories')::boolean, false) THEN
    RETURN jsonb_build_object('success', false, 'requires_personal_link', true,
      'error', 'This engagement letter is signed by each signatory using the personal link emailed to them. Please use your own link, or ask your accountant to resend it.');
  END IF;

  UPDATE public.engagement_letters
     SET signed_at = now(),
         signature_name = COALESCE(signature_name, NULLIF(trim(p_signature_data->>'full_name'), '')),
         signature_user_agent = COALESCE(signature_user_agent, p_signature_data->>'user_agent'),
         viewed_at = COALESCE(viewed_at, now())
   WHERE id = v_letter.id;

  -- T2d-2 (2): the application-side write this path always omitted.
  UPDATE public.engagement_letters
     SET status = 'signed', updated_at = now()
   WHERE id = v_letter.id;

  UPDATE public.onboarding_applications
     SET contracts_signed_at = COALESCE(contracts_signed_at, now()),
         contracts_sent_at   = COALESCE(contracts_sent_at, now()),
         signature_data      = COALESCE(signature_data, p_signature_data),
         status = CASE
           WHEN status IN ('draft','in_progress','engagement_pending') THEN 'aml_pending'
           ELSE status
         END,
         updated_at = now()
   WHERE id = v_letter.onboarding_application_id
     AND status NOT IN ('approved','rejected','cancelled');

  RETURN jsonb_build_object('success', true, 'signed_at', now());
END;
$$;


--
-- Name: public_skip_billing(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_skip_billing(p_application_id uuid, p_access_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);
  UPDATE public.onboarding_applications
     SET billing_status = 'skipped',
         status = CASE WHEN status IN ('billing_pending','aml_pending','engagement_pending')
                       THEN 'portal_pending' ELSE status END,
         updated_at = now()
   WHERE id = p_application_id
     AND status NOT IN ('approved','rejected','cancelled');
  RETURN jsonb_build_object('status','portal_pending');
END;
$$;

