--
-- Name: seed_standard_chart_of_accounts(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_standard_chart_of_accounts(p_organization_id uuid, p_client_id uuid, p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inserted int := 0;
  v_actor uuid := auth.uid();
  v_ar uuid; v_ap uuid; v_vat uuid; v_bc uuid; v_obe uuid; v_re uuid;
  v_susp uuid; v_dl uuid; v_fa uuid; v_ad uuid;
  v_entity_type text;
  v_entity_id uuid;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;
  IF (p_client_id IS NULL AND p_company_id IS NULL)
     OR (p_client_id IS NOT NULL AND p_company_id IS NOT NULL) THEN
    RAISE EXCEPTION 'Exactly one of client_id or company_id must be provided';
  END IF;

  IF v_actor IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM organization_users
                      WHERE organization_id = p_organization_id AND user_id = v_actor) THEN
    RAISE EXCEPTION 'Caller is not a member of the target organization';
  END IF;

  v_entity_type := CASE WHEN p_client_id IS NOT NULL THEN 'client' ELSE 'company' END;
  v_entity_id   := COALESCE(p_client_id, p_company_id);

  -- Seed accounts idempotently
  WITH seed(code, name, account_type, account_subtype, is_control, is_bank) AS (
    VALUES
      ('1000','Bank Current Account','ASSET','BANK', false, true),
      ('1100','Accounts Receivable','ASSET','TRADE_DEBTORS', true, false),
      ('1200','Fixed Assets','ASSET','FIXED_ASSETS', false, false),
      ('1210','Accumulated Depreciation','ASSET','ACCUMULATED_DEPRECIATION', false, false),
      ('1500','Stock / Inventory','ASSET','INVENTORY', false, false),
      ('2000','Accounts Payable','LIABILITY','TRADE_CREDITORS', true, false),
      ('2100','VAT Control','LIABILITY','VAT_CONTROL', true, false),
      ('2200','PAYE / NIC Control','LIABILITY','PAYE_NIC', true, false),
      ('2210','Pension Control','LIABILITY','PENSION_CONTROL', true, false),
      ('2300','Corporation Tax Control','LIABILITY','CT_CONTROL', true, false),
      ('2400','Director Loan','LIABILITY','DIRECTOR_LOAN', false, false),
      ('3000','Share Capital','EQUITY','SHARE_CAPITAL', false, false),
      ('3100','Retained Earnings','EQUITY','RETAINED_EARNINGS', false, false),
      ('3200','Opening Balance Equity','EQUITY','OPENING_BALANCE_EQUITY', false, false),
      ('3900','Suspense Account','EQUITY','SUSPENSE', false, false),
      ('4000','Sales','INCOME','SALES', false, false),
      ('4900','Sales Discounts','INCOME','SALES_DISCOUNTS', false, false),
      ('5000','Cost of Sales','EXPENSE','COST_OF_SALES', false, false),
      ('5100','Purchases','EXPENSE','PURCHASES', false, false),
      ('6000','Wages and Salaries','EXPENSE','WAGES', false, false),
      ('7000','Bank Charges','EXPENSE','BANK_CHARGES', false, false),
      ('7900','Bad Debts','EXPENSE','BAD_DEBTS', false, false)
  )
  INSERT INTO bookkeeping_accounts
    (organization_id, client_id, company_id, code, name,
     account_type, account_subtype, is_control_account, is_bank_account,
     is_system_account, is_active)
  SELECT p_organization_id, p_client_id, p_company_id, s.code, s.name,
         s.account_type, s.account_subtype, s.is_control, s.is_bank,
         true, true
    FROM seed s
   WHERE NOT EXISTS (
     SELECT 1 FROM bookkeeping_accounts a
      WHERE a.organization_id = p_organization_id
        AND a.code = s.code
        AND ((p_client_id IS NOT NULL AND a.client_id  = p_client_id)
          OR (p_company_id IS NOT NULL AND a.company_id = p_company_id))
   );
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  -- Look up the seeded ids (whether just inserted or pre-existing)
  SELECT id INTO v_ar  FROM bookkeeping_accounts WHERE organization_id = p_organization_id AND code = '1100'
    AND ((p_client_id IS NOT NULL AND client_id  = p_client_id) OR (p_company_id IS NOT NULL AND company_id = p_company_id));
  SELECT id INTO v_ap  FROM bookkeeping_accounts WHERE organization_id = p_organization_id AND code = '2000'
    AND ((p_client_id IS NOT NULL AND client_id  = p_client_id) OR (p_company_id IS NOT NULL AND company_id = p_company_id));
  SELECT id INTO v_vat FROM bookkeeping_accounts WHERE organization_id = p_organization_id AND code = '2100'
    AND ((p_client_id IS NOT NULL AND client_id  = p_client_id) OR (p_company_id IS NOT NULL AND company_id = p_company_id));
  SELECT id INTO v_bc  FROM bookkeeping_accounts WHERE organization_id = p_organization_id AND code = '7000'
    AND ((p_client_id IS NOT NULL AND client_id  = p_client_id) OR (p_company_id IS NOT NULL AND company_id = p_company_id));
  SELECT id INTO v_obe FROM bookkeeping_accounts WHERE organization_id = p_organization_id AND code = '3200'
    AND ((p_client_id IS NOT NULL AND client_id  = p_client_id) OR (p_company_id IS NOT NULL AND company_id = p_company_id));
  SELECT id INTO v_re  FROM bookkeeping_accounts WHERE organization_id = p_organization_id AND code = '3100'
    AND ((p_client_id IS NOT NULL AND client_id  = p_client_id) OR (p_company_id IS NOT NULL AND company_id = p_company_id));
  SELECT id INTO v_susp FROM bookkeeping_accounts WHERE organization_id = p_organization_id AND code = '3900'
    AND ((p_client_id IS NOT NULL AND client_id  = p_client_id) OR (p_company_id IS NOT NULL AND company_id = p_company_id));
  SELECT id INTO v_dl  FROM bookkeeping_accounts WHERE organization_id = p_organization_id AND code = '2400'
    AND ((p_client_id IS NOT NULL AND client_id  = p_client_id) OR (p_company_id IS NOT NULL AND company_id = p_company_id));
  SELECT id INTO v_fa  FROM bookkeeping_accounts WHERE organization_id = p_organization_id AND code = '1200'
    AND ((p_client_id IS NOT NULL AND client_id  = p_client_id) OR (p_company_id IS NOT NULL AND company_id = p_company_id));
  SELECT id INTO v_ad  FROM bookkeeping_accounts WHERE organization_id = p_organization_id AND code = '1210'
    AND ((p_client_id IS NOT NULL AND client_id  = p_client_id) OR (p_company_id IS NOT NULL AND company_id = p_company_id));

  -- Populate org_settings control-account pointers if not already set.
  -- org_settings is org-scoped (one row per org), so we use the first matching row.
  UPDATE org_settings
     SET accounts_receivable_account_id   = COALESCE(accounts_receivable_account_id,   v_ar),
         accounts_payable_account_id      = COALESCE(accounts_payable_account_id,      v_ap),
         vat_control_account_id           = COALESCE(vat_control_account_id,           v_vat),
         bank_charges_account_id          = COALESCE(bank_charges_account_id,          v_bc),
         opening_balance_equity_account_id= COALESCE(opening_balance_equity_account_id,v_obe),
         retained_earnings_account_id     = COALESCE(retained_earnings_account_id,     v_re),
         suspense_account_id              = COALESCE(suspense_account_id,              v_susp),
         director_loan_account_id         = COALESCE(director_loan_account_id,         v_dl),
         fixed_assets_account_id          = COALESCE(fixed_assets_account_id,          v_fa),
         accumulated_depreciation_account_id = COALESCE(accumulated_depreciation_account_id, v_ad)
   WHERE organization_id = p_organization_id;

  INSERT INTO bookkeeping_audit_log
    (organization_id, entity_type, entity_id, action, actor_id, after_state)
  VALUES (p_organization_id, v_entity_type, v_entity_id, 'seed_standard_chart', v_actor,
          jsonb_build_object('inserted', v_inserted));

  RETURN jsonb_build_object('success', true, 'inserted', v_inserted);
END;
$$;


--
-- Name: seed_system_vat_codes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_system_vat_codes(p_organization_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer := 0;
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = p_organization_id AND user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'Not a member of organization %', p_organization_id;
  END IF;

  WITH seed(code, description, rate, vat_type, supply_category, is_reclaimable, reverse_charge, is_common) AS (
    VALUES
      ('S20', 'Standard rated sales 20%',           20.0, 'OUTPUT', 'STANDARD',     false, false, true),
      ('S5',  'Reduced rated sales 5%',              5.0, 'OUTPUT', 'REDUCED',      false, false, true),
      ('Z',   'Zero rated sales',                    0.0, 'ZERO',   'ZERO_RATED',   false, false, true),
      ('E',   'Exempt sales',                        0.0, 'EXEMPT', 'EXEMPT',       false, false, true),
      ('OS',  'Outside the scope of UK VAT',         0.0, 'EXEMPT', 'OUT_OF_SCOPE', false, false, false),
      ('P20', 'Standard rated purchases 20%',       20.0, 'INPUT',  'STANDARD',     true,  false, true),
      ('P5',  'Reduced rated purchases 5%',          5.0, 'INPUT',  'REDUCED',      true,  false, true),
      ('PZ',  'Zero rated purchases',                0.0, 'ZERO',   'ZERO_RATED',   true,  false, false),
      ('PE',  'Exempt purchases',                    0.0, 'EXEMPT', 'EXEMPT',       false, false, false),
      ('NV',  'No VAT / outside scope purchases',    0.0, 'EXEMPT', 'OUT_OF_SCOPE', false, false, true),
      ('RC',  'Reverse charge (domestic services)', 20.0, 'INPUT',  'REVERSE_CHG',  true,  true,  false),
      ('IMP', 'Import VAT (PVA)',                   20.0, 'INPUT',  'IMPORT',       true,  false, false),
      ('EXP', 'Export of goods outside UK',          0.0, 'ZERO',   'EXPORT',       false, false, false),
      ('EU_GOODS', 'EU acquisitions of goods',      20.0, 'INPUT',  'EU_GOODS',     true,  true,  false)
  )
  INSERT INTO public.vat_codes (
    organization_id, code, description, rate, vat_type,
    supply_category, is_reclaimable, reverse_charge, is_common,
    is_active, is_system, jurisdiction
  )
  SELECT
    p_organization_id, s.code, s.description, s.rate, s.vat_type,
    s.supply_category, s.is_reclaimable, s.reverse_charge, s.is_common,
    true, true, 'UK'
  FROM seed s
  ON CONFLICT (organization_id, code) DO UPDATE
    SET is_system   = true,
        description = EXCLUDED.description,
        is_active   = true,
        updated_at  = now()
  ;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: send_onboarding_questionnaire(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_onboarding_questionnaire(p_onboarding_id uuid, p_template_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_onboarding record;
  v_template record;
  v_instance_id uuid;
  v_access_token text;
BEGIN
  SELECT * INTO v_onboarding FROM onboarding_applications WHERE id = p_onboarding_id;

  IF v_onboarding.id IS NULL THEN
    RAISE EXCEPTION 'Onboarding application not found';
  END IF;

  IF NOT user_has_organization_access(v_onboarding.organization_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT * INTO v_template FROM templates WHERE id = p_template_id AND template_type = 'questionnaire';

  IF v_template.id IS NULL THEN
    RAISE EXCEPTION 'Questionnaire template not found';
  END IF;

  -- Generate access token
  v_access_token := encode(gen_random_bytes(32), 'base64');

  -- Create questionnaire instance
  INSERT INTO questionnaire_instances (
    organization_id, template_id, client_id, company_id,
    access_token, token_expires_at, status
  )
  VALUES (
    v_onboarding.organization_id, p_template_id, v_onboarding.client_id, v_onboarding.company_id,
    v_access_token, now() + interval '30 days', 'sent'
  )
  RETURNING id INTO v_instance_id;

  -- Link to onboarding
  UPDATE onboarding_applications 
  SET onboarding_questionnaire_instance_id = v_instance_id
  WHERE id = p_onboarding_id;

  -- Queue email
  INSERT INTO email_queue (
    organization_id, to_email, to_name, subject, body_html,
    entity_type, entity_id, merge_data, status
  )
  VALUES (
    v_onboarding.organization_id,
    v_onboarding.email,
    COALESCE(v_onboarding.first_name || ' ' || v_onboarding.last_name, v_onboarding.company_name),
    'Please complete your onboarding questionnaire',
    '<p>Please complete the onboarding questionnaire to proceed with your application.</p>',
    'questionnaire_instance',
    v_instance_id,
    jsonb_build_object(
      'questionnaire_url', '/questionnaire/' || v_instance_id || '?token=' || v_access_token,
      'client_name', COALESCE(v_onboarding.first_name || ' ' || v_onboarding.last_name, v_onboarding.company_name)
    ),
    'pending'
  );

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
  VALUES (v_onboarding.organization_id, 'onboarding', p_onboarding_id, 'questionnaire_sent', auth.uid(),
    jsonb_build_object('template_id', p_template_id, 'instance_id', v_instance_id));

  RETURN jsonb_build_object(
    'success', true,
    'instance_id', v_instance_id,
    'access_token', v_access_token
  );
END;
$$;


--
-- Name: send_queued_email_now(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_queued_email_now(p_email_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_org uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  SELECT organization_id INTO v_org FROM public.email_queue WHERE id = p_email_id;
  IF v_org IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Email not found');
  END IF;
  IF NOT public.user_in_organization(v_user_id, v_org) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;
  UPDATE public.email_queue
     SET scheduled_at = now(),
         status = CASE WHEN status IN ('pending','queued','failed','draft') THEN 'pending' ELSE status END,
         error_message = NULL,
         updated_at = now()
   WHERE id = p_email_id;
  RETURN jsonb_build_object('success', true, 'email_id', p_email_id);
END;
$$;


--
-- Name: set_primary_contact(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_primary_contact(p_company_id uuid, p_person_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_organization_id uuid;
  v_associated boolean;
BEGIN
  SELECT organization_id INTO v_organization_id
  FROM public.companies WHERE id = p_company_id;

  IF v_organization_id IS NULL THEN
    RAISE EXCEPTION 'Company not found: %', p_company_id;
  END IF;

  IF NOT public.user_has_organization_access(v_organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.company_officers
    WHERE company_id = p_company_id AND person_id = p_person_id
  ) OR EXISTS (
    SELECT 1 FROM public.contacts
    WHERE company_id = p_company_id AND person_id = p_person_id
  ) INTO v_associated;

  IF NOT v_associated THEN
    RAISE EXCEPTION 'Person % is not associated with company % (no officer or contacts row)', p_person_id, p_company_id;
  END IF;

  UPDATE public.companies
  SET primary_contact_person_id = p_person_id
  WHERE id = p_company_id;

  RETURN jsonb_build_object(
    'ok', true,
    'company_id', p_company_id,
    'primary_contact_person_id', p_person_id
  );
END;
$$;


--
-- Name: set_signatory(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_signatory(p_officer_id uuid, p_on boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_organization_id uuid;
  v_is_signatory boolean;
BEGIN
  SELECT co.organization_id INTO v_organization_id
  FROM public.company_officers o
  JOIN public.companies co ON co.id = o.company_id
  WHERE o.id = p_officer_id;

  IF v_organization_id IS NULL THEN
    RAISE EXCEPTION 'Officer not found: %', p_officer_id;
  END IF;

  IF NOT public.user_has_organization_access(v_organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization';
  END IF;

  UPDATE public.company_officers
  SET is_signatory = p_on
  WHERE id = p_officer_id
  RETURNING is_signatory INTO v_is_signatory;

  RETURN jsonb_build_object(
    'ok', true,
    'officer_id', p_officer_id,
    'is_signatory', v_is_signatory
  );
END;
$$;


--
-- Name: split_bank_transaction(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.split_bank_transaction(p_bank_transaction_id uuid, p_splits jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_txn RECORD;
  v_bank RECORD;
  v_settings RECORD;
  v_split JSONB;
  v_total NUMERIC := 0;
  v_amount NUMERIC;
  v_vat_amount NUMERIC;
  v_contra UUID;
  v_vat_code UUID;
  v_desc TEXT;
  v_entries JSONB := '[]'::jsonb;
  v_money_in BOOLEAN;
  v_user_id UUID := auth.uid();
  v_post_result JSONB;
  v_before JSONB;
BEGIN
  SELECT * INTO v_txn FROM public.bank_transactions WHERE id = p_bank_transaction_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bank transaction not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE user_id = v_user_id AND organization_id = v_txn.organization_id
  ) THEN
    RAISE EXCEPTION 'Not authorised for organization';
  END IF;

  IF upper(COALESCE(v_txn.status,'')) IN ('MATCHED','RECONCILED') THEN
    RAISE EXCEPTION 'Transaction is already %', v_txn.status;
  END IF;

  PERFORM assert_no_locked_period_write(
    v_txn.organization_id, v_txn.client_id, v_txn.company_id, v_txn.transaction_date
  );

  IF jsonb_typeof(p_splits) <> 'array' OR jsonb_array_length(p_splits) < 2 THEN
    RAISE EXCEPTION 'Splits must be an array with at least two entries';
  END IF;

  SELECT * INTO v_bank FROM public.bank_accounts WHERE id = v_txn.bank_account_id;
  IF NOT FOUND OR v_bank.account_id IS NULL THEN
    RAISE EXCEPTION 'Bank account not mapped to a ledger account';
  END IF;

  SELECT * INTO v_settings FROM public.org_settings
   WHERE organization_id = v_txn.organization_id LIMIT 1;

  v_money_in := v_txn.amount > 0;

  -- Validate splits + sum
  FOR v_split IN SELECT * FROM jsonb_array_elements(p_splits) LOOP
    v_amount := COALESCE((v_split->>'amount')::numeric, 0);
    IF v_amount <= 0 THEN
      RAISE EXCEPTION 'Split amounts must be positive';
    END IF;
    IF NULLIF(v_split->>'contra_account_id','') IS NULL THEN
      RAISE EXCEPTION 'Each split must include a contra_account_id';
    END IF;
    v_total := v_total + v_amount;
  END LOOP;

  IF ROUND(v_total::numeric, 2) <> ROUND(ABS(v_txn.amount)::numeric, 2) THEN
    RAISE EXCEPTION 'Splits total (%) must equal transaction amount (%)',
      v_total, ABS(v_txn.amount);
  END IF;

  v_before := to_jsonb(v_txn);

  -- Bank leg (full amount, one line)
  IF v_money_in THEN
    v_entries := v_entries || jsonb_build_array(
      jsonb_build_object('account_id', v_txn.bank_account_id,
                         'debit', ABS(v_txn.amount), 'credit', 0,
                         'description', COALESCE(v_txn.description, 'Split receipt'))
    );
  ELSE
    v_entries := v_entries || jsonb_build_array(
      jsonb_build_object('account_id', v_txn.bank_account_id,
                         'debit', 0, 'credit', ABS(v_txn.amount),
                         'description', COALESCE(v_txn.description, 'Split payment'))
    );
  END IF;

  -- Contra legs (one per split) + optional VAT legs
  FOR v_split IN SELECT * FROM jsonb_array_elements(p_splits) LOOP
    v_amount := (v_split->>'amount')::numeric;
    v_vat_amount := COALESCE(NULLIF(v_split->>'vat_amount','')::numeric, 0);
    v_contra := (v_split->>'contra_account_id')::uuid;
    v_vat_code := NULLIF(v_split->>'vat_code_id','')::uuid;
    v_desc := COALESCE(v_split->>'description', v_txn.description, 'Split');

    -- Net amount goes to the contra account; VAT (if any) routes to the VAT control account
    DECLARE
      v_net NUMERIC := v_amount - v_vat_amount;
    BEGIN
      IF v_money_in THEN
        v_entries := v_entries || jsonb_build_array(
          jsonb_build_object('account_id', v_contra, 'debit', 0, 'credit', v_net, 'description', v_desc)
        );
        IF v_vat_amount > 0 THEN
          IF v_settings.vat_control_account_id IS NULL THEN
            RAISE EXCEPTION 'VAT control account not configured in org_settings';
          END IF;
          v_entries := v_entries || jsonb_build_array(
            jsonb_build_object('account_id', v_settings.vat_control_account_id,
                               'debit', 0, 'credit', v_vat_amount,
                               'description', 'VAT: ' || v_desc,
                               'vat_code_id', v_vat_code)
          );
        END IF;
      ELSE
        v_entries := v_entries || jsonb_build_array(
          jsonb_build_object('account_id', v_contra, 'debit', v_net, 'credit', 0, 'description', v_desc)
        );
        IF v_vat_amount > 0 THEN
          IF v_settings.vat_control_account_id IS NULL THEN
            RAISE EXCEPTION 'VAT control account not configured in org_settings';
          END IF;
          v_entries := v_entries || jsonb_build_array(
            jsonb_build_object('account_id', v_settings.vat_control_account_id,
                               'debit', v_vat_amount, 'credit', 0,
                               'description', 'VAT: ' || v_desc,
                               'vat_code_id', v_vat_code)
          );
        END IF;
      END IF;
    END;
  END LOOP;

  v_post_result := public.post_to_ledger(
    p_organization_id := v_txn.organization_id,
    p_client_id       := v_txn.client_id,
    p_company_id      := v_txn.company_id,
    p_transaction_date:= v_txn.transaction_date,
    p_description     := 'Split: ' || LEFT(COALESCE(v_txn.description,''), 80),
    p_source_type     := 'BANK_TRANSACTION',
    p_source_id       := p_bank_transaction_id,
    p_entries         := v_entries
  );

  UPDATE public.bank_transactions
     SET status = 'MATCHED',
         matched_ledger_entry_id = (v_post_result->>'journal_id')::uuid
   WHERE id = p_bank_transaction_id;

  INSERT INTO public.bookkeeping_audit_log(
    organization_id, entity_type, entity_id, action, actor_id,
    before_state, after_state, metadata
  ) VALUES (
    v_txn.organization_id, 'bank_transaction', p_bank_transaction_id, 'split_bank_transaction', v_user_id,
    v_before,
    jsonb_build_object('status','MATCHED','journal_id', v_post_result->>'journal_id'),
    jsonb_build_object('splits', p_splits)
  );

  RETURN v_post_result;
END;
$$;


