    NEW.created_by_portal := true;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: stamp_portal_provenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_portal_provenance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_portal boolean := public.is_portal_user();
  v_contact uuid;
  v_require boolean := false;
  v_mode public.bk_mode;
BEGIN
  IF NOT v_is_portal THEN
    -- Accountant write: keep defaults
    RETURN NEW;
  END IF;

  -- Contact attribution is UNRESOLVABLE in the current schema, and that is the
  -- defect (DEF-028). This is where the function used to read a contact id off
  -- public.portal_access keyed by auth.uid(). That table has no such column and
  -- never has, so the statement raised 42703 on every portal write from the day
  -- the function was created in 20260608112113.
  --
  -- There is no correct column to substitute. No table links an authenticated
  -- user to a contacts row: portal_access carries user_id, client_id, company_id
  -- and role; contacts carries no user_id.
  --
  -- v_contact is therefore left NULL. That is not a silent downgrade: because
  -- the lookup always raised, created_by_contact_id has never been populated on
  -- any row, so nothing that works today is lost. Actor attribution is
  -- unaffected and still durable — bookkeeping_audit_log.actor_id records
  -- auth.uid(), and created_by_portal / source = 'portal' still mark provenance.
  --
  -- Deliberately NOT done: matching a portal user to a contact by email or name.
  -- Identity by name-match is forbidden by the governance design
  -- (docs/superpowers/specs/2026-07-22-data-governance-architecture-design.md).
  -- It would attribute writes to the wrong person, which is worse than NULL.
  --
  -- Whether portal_access should carry a real contact FK is an open product
  -- decision for the owner, tracked on the DEF-028 receipt. The COALESCE below
  -- is kept so an explicitly supplied value still wins, and so that populating
  -- v_contact later needs no other change here.
  v_contact := NULL;

  IF TG_TABLE_NAME = 'bank_transactions' THEN
    NEW.updated_by_portal := true;
    NEW.source := 'portal';
    NEW.created_by_contact_id := COALESCE(NEW.created_by_contact_id, v_contact);
  ELSE
    IF TG_OP = 'INSERT' THEN
      NEW.created_by_portal := true;
      NEW.source := 'portal';
      NEW.created_by_contact_id := COALESCE(NEW.created_by_contact_id, v_contact);
    END IF;
  END IF;

  -- Resolve review mode from portal_visibility_settings
  SELECT client_bookkeeping_mode,
         CASE TG_TABLE_NAME
           WHEN 'invoices' THEN require_review_for_invoice_sending
           WHEN 'bills' THEN require_review_for_bill_approval
           WHEN 'bank_transactions' THEN require_review_for_transaction_explanations
           WHEN 'receipts' THEN require_review_for_receipt_matching
           ELSE false
         END
  INTO v_mode, v_require
  FROM public.portal_visibility_settings
  WHERE (NEW.client_id IS NOT NULL AND client_id = NEW.client_id)
     OR (NEW.company_id IS NOT NULL AND company_id = NEW.company_id)
  LIMIT 1;

  IF v_mode = 'review_required' OR v_require THEN
    IF TG_OP = 'INSERT' THEN
      NEW.review_status := 'pending_review';
    END IF;
  END IF;

  -- Audit log
  INSERT INTO public.bookkeeping_audit_log(
    organization_id, entity_type, entity_id, action, actor_id, actor_role,
    before_state, after_state, metadata
  ) VALUES (
    NEW.organization_id,
    TG_TABLE_NAME,
    NEW.id,
    TG_OP,
    auth.uid(),
    'portal',
    CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) ELSE NULL END,
    to_jsonb(NEW),
    jsonb_build_object('source','portal','contact_id', v_contact,
      'contact_attribution',
      CASE WHEN v_contact IS NULL THEN 'unresolved_no_portal_contact_link' ELSE 'resolved' END)
  );

  RETURN NEW;
END $$;


--
-- Name: start_bank_reconciliation(uuid, date, date, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_bank_reconciliation(p_bank_account_id uuid, p_statement_start_date date, p_statement_end_date date, p_statement_opening_balance numeric, p_statement_closing_balance numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_client uuid;
  v_company uuid;
  v_id uuid;
  v_existing uuid;
BEGIN
  SELECT organization_id, client_id, company_id
    INTO v_org, v_client, v_company
  FROM public.bank_accounts WHERE id = p_bank_account_id;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Bank account not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = v_org AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not authorized for this organization';
  END IF;

  IF p_statement_end_date < p_statement_start_date THEN
    RAISE EXCEPTION 'Statement end date must be on or after start date';
  END IF;

  -- Locked-period guard: cannot reconcile inside a locked period
  PERFORM public.assert_no_locked_period_write(v_org, v_client, v_company, p_statement_end_date);

  -- Prevent overlapping in-progress reconciliations for same account
  SELECT id INTO v_existing
  FROM public.reconciliations
  WHERE bank_account_id = p_bank_account_id
    AND status = 'in_progress'
  LIMIT 1;

  IF v_existing IS NOT NULL THEN
    RAISE EXCEPTION 'An in-progress reconciliation already exists for this bank account: %', v_existing;
  END IF;

  -- Prevent overlapping date ranges with completed reconciliations
  IF EXISTS (
    SELECT 1 FROM public.reconciliations
    WHERE bank_account_id = p_bank_account_id
      AND status = 'completed'
      AND daterange(statement_start_date, statement_end_date, '[]') &&
          daterange(p_statement_start_date, p_statement_end_date, '[]')
  ) THEN
    RAISE EXCEPTION 'Date range overlaps an existing completed reconciliation';
  END IF;

  INSERT INTO public.reconciliations (
    organization_id, client_id, company_id, bank_account_id,
    statement_start_date, statement_end_date,
    statement_opening_balance, statement_closing_balance,
    status, created_by
  ) VALUES (
    v_org, v_client, v_company, p_bank_account_id,
    p_statement_start_date, p_statement_end_date,
    p_statement_opening_balance, p_statement_closing_balance,
    'in_progress', auth.uid()
  ) RETURNING id INTO v_id;

  INSERT INTO public.bookkeeping_audit_log (
    organization_id, client_id, company_id, entity_type, entity_id, action, performed_by, metadata
  ) VALUES (
    v_org, v_client, v_company, 'reconciliation', v_id, 'start_bank_reconciliation', auth.uid(),
    jsonb_build_object(
      'bank_account_id', p_bank_account_id,
      'period', jsonb_build_object('start', p_statement_start_date, 'end', p_statement_end_date),
      'opening', p_statement_opening_balance,
      'closing', p_statement_closing_balance
    )
  );

  RETURN v_id;
END;
$$;


--
-- Name: start_kyc_pack(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_kyc_pack(p_client_id uuid, p_subjects jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org_id uuid; v_pack_id uuid; v_subj jsonb;
BEGIN
  SELECT organization_id INTO v_org_id FROM public.clients WHERE id = p_client_id;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Client not found'; END IF;
  IF NOT user_has_organization_access(v_org_id) THEN RAISE EXCEPTION 'Not authorised'; END IF;

  INSERT INTO public.kyc_packs (organization_id, client_id, status, due_at)
  VALUES (v_org_id, p_client_id, 'in_progress', now() + interval '14 days')
  RETURNING id INTO v_pack_id;

  FOR v_subj IN SELECT * FROM jsonb_array_elements(coalesce(p_subjects, '[]'::jsonb))
  LOOP
    INSERT INTO public.kyc_pack_subjects (
      organization_id, kyc_pack_id, subject_type, subject_ref_type, subject_ref_id, subject_name, due_at
    ) VALUES (
      v_org_id, v_pack_id,
      coalesce(v_subj->>'subject_type','individual_client'),
      v_subj->>'subject_ref_type',
      nullif(v_subj->>'subject_ref_id','')::uuid,
      coalesce(v_subj->>'subject_name','Subject'),
      now() + interval '14 days'
    );
  END LOOP;

  UPDATE public.clients SET last_kyc_pack_id = v_pack_id WHERE id = p_client_id;

  INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, new_value)
  VALUES (v_org_id, 'KYC_STATUS_CHANGED', 'client', p_client_id,
          jsonb_build_object('kyc_pack_id', v_pack_id, 'status', 'in_progress'));

  RETURN v_pack_id;
END;
$$;


--
-- Name: submit_filing_safe(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_filing_safe(p_filing_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_filing record;
BEGIN
  -- Fetch filing
  SELECT * INTO v_filing FROM filings WHERE id = p_filing_id;

  IF v_filing.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Filing not found');
  END IF;

  -- Check permission
  IF NOT can_submit_filings(auth.uid(), v_filing.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: Only managers and above can submit filings');
  END IF;

  -- Update filing
  UPDATE filings SET 
    status = 'filed',
    submitted_by = auth.uid(),
    submitted_at = now()
  WHERE id = p_filing_id;

  -- Write audit log
  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, field_name, old_value, new_value, user_id)
  VALUES (v_filing.organization_id, 'filing', p_filing_id, 'submit', 'status', v_filing.status, 'filed', auth.uid());

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: submit_questionnaire_by_token(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_questionnaire_by_token(p_instance_id uuid, p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_link public.questionnaire_public_links;
  v_hash TEXT;
BEGIN
  v_link := public._require_valid_questionnaire_link(p_instance_id, p_token);
  v_hash := public._hash_token(p_token);

  -- Check not already submitted
  IF EXISTS (
    SELECT 1 FROM public.questionnaire_instances 
    WHERE id = p_instance_id AND status = 'submitted'
  ) THEN
    RAISE EXCEPTION 'Questionnaire already submitted';
  END IF;

  UPDATE public.questionnaire_instances
  SET status = 'submitted',
      submitted_at = COALESCE(submitted_at, now())
  WHERE id = p_instance_id;

  -- Revoke link after submit to prevent reuse
  UPDATE public.questionnaire_public_links
  SET revoked_at = now()
  WHERE id = v_link.id;

  INSERT INTO public.questionnaire_access_log(questionnaire_instance_id, token_hash, action)
  VALUES (p_instance_id, v_hash, 'submit');

  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: sync_aged_balance_from_cna(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_aged_balance_from_cna() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_inv uuid := COALESCE(NEW.invoice_id, OLD.invoice_id);
        v_bill uuid := COALESCE(NEW.bill_id, OLD.bill_id);
        v_total numeric; v_paid numeric; v_s text;
BEGIN
  IF v_inv IS NOT NULL THEN
    SELECT total_amount INTO v_total FROM public.invoices WHERE id = v_inv;
    IF v_total IS NOT NULL THEN
      SELECT COALESCE((SELECT SUM(amount) FROM public.invoice_payments WHERE invoice_id = v_inv),0)
           + COALESCE((SELECT SUM(amount) FROM public.credit_note_allocations WHERE invoice_id = v_inv),0)
        INTO v_paid;
      UPDATE public.invoices
      SET amount_paid = v_paid, remaining_balance = GREATEST(v_total - v_paid, 0),
          status = CASE WHEN v_paid <= 0 THEN status
            WHEN v_paid >= v_total - 0.005 THEN 'paid' ELSE 'part_paid' END,
          updated_at = now()
      WHERE id = v_inv AND lower(status) NOT IN ('voided','draft','cancelled');
    END IF;
  END IF;
  IF v_bill IS NOT NULL THEN
    SELECT total_amount, status INTO v_total, v_s FROM public.bills WHERE id = v_bill;
    IF v_total IS NOT NULL THEN
      SELECT COALESCE((SELECT SUM(amount) FROM public.bill_payments WHERE bill_id = v_bill),0)
           + COALESCE((SELECT SUM(amount) FROM public.credit_note_allocations WHERE bill_id = v_bill),0)
        INTO v_paid;
      UPDATE public.bills
      SET amount_paid = v_paid, remaining_balance = GREATEST(v_total - v_paid, 0),
          status = CASE WHEN v_paid <= 0 THEN status
            WHEN v_paid >= v_total - 0.005 THEN CASE WHEN v_s = upper(v_s) THEN 'PAID' ELSE 'paid' END
            ELSE CASE WHEN v_s = upper(v_s) THEN 'PART_PAID' ELSE 'part_paid' END END,
          updated_at = now()
      WHERE id = v_bill AND lower(status) NOT IN ('voided','void','draft','cancelled');
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END; $$;


