--
-- Name: lifecycle_reconciliation_report(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_reconciliation_report(p_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_jobs_total       int;
  v_setup_pending    int;
  v_null_label       int;
  v_both_entity      int;
  v_dup_groups       int;
  v_dup_excess       int;
  v_null_dup_groups  int;
  v_active_links     int;
  v_accepted_no_onb  int;
  v_onb_unlinked     int;
  v_dup_onb_groups   int;
  v_present          text[];
  v_expected         text[] := ARRAY['jobs_client_period_uq','jobs_company_period_uq',
                                     'engagements_quote_service_uq','acl_active_client_uq',
                                     'acl_active_company_uq'];
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
     WHERE organization_id = p_organization_id AND user_id = auth.uid()
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  SELECT count(*) INTO v_jobs_total
    FROM public.jobs WHERE organization_id = p_organization_id;

  SELECT count(*) INTO v_setup_pending
    FROM public.jobs
   WHERE organization_id = p_organization_id AND period_label ILIKE 'Setup Pending';

  SELECT count(*) INTO v_null_label
    FROM public.jobs
   WHERE organization_id = p_organization_id AND period_label IS NULL AND status <> 'cancelled';

  SELECT count(*) INTO v_both_entity
    FROM public.jobs
   WHERE organization_id = p_organization_id
     AND client_id IS NOT NULL AND company_id IS NOT NULL;

  WITH grp AS (
    SELECT count(*) AS n FROM public.jobs
     WHERE organization_id = p_organization_id AND status <> 'cancelled'
     GROUP BY service_type, client_id, company_id, period_label HAVING count(*) > 1
  )
  SELECT COALESCE(count(*),0), COALESCE(sum(n - 1),0) INTO v_dup_groups, v_dup_excess FROM grp;

  WITH ngrp AS (
    SELECT 1 FROM public.jobs
     WHERE organization_id = p_organization_id AND status <> 'cancelled' AND period_label IS NULL
     GROUP BY service_type, client_id, company_id HAVING count(*) > 1
  )
  SELECT COALESCE(count(*),0) INTO v_null_dup_groups FROM ngrp;

  SELECT count(*) INTO v_active_links
    FROM public.accountant_client_links
   WHERE practice_id = p_organization_id AND status = 'active';

  SELECT count(*) INTO v_accepted_no_onb
    FROM public.quotes q
   WHERE q.organization_id = p_organization_id
     AND q.status = 'accepted'
     AND NOT EXISTS (
       SELECT 1 FROM public.onboarding_applications o
        WHERE o.quote_id = q.id AND o.status <> 'rejected');

  SELECT count(*) INTO v_onb_unlinked
    FROM public.onboarding_applications o
   WHERE o.organization_id = p_organization_id
     AND o.status NOT IN ('approved','rejected')
     AND o.client_id IS NULL AND o.company_id IS NULL;

  WITH og AS (
    SELECT quote_id FROM public.onboarding_applications
     WHERE organization_id = p_organization_id AND quote_id IS NOT NULL AND status <> 'rejected'
     GROUP BY quote_id HAVING count(*) > 1
  )
  SELECT COALESCE(count(*),0) INTO v_dup_onb_groups FROM og;

  SELECT COALESCE(array_agg(indexname), ARRAY[]::text[]) INTO v_present
    FROM pg_indexes
   WHERE schemaname = 'public' AND indexname = ANY(v_expected);

  RETURN jsonb_build_object(
    'success', true,
    'organization_id', p_organization_id,
    'jobs_total', v_jobs_total,
    'setup_pending_jobs', v_setup_pending,
    'null_period_label_jobs', v_null_label,
    'both_entity_jobs', v_both_entity,
    'duplicate_job_groups', v_dup_groups,
    'duplicate_job_excess_rows', v_dup_excess,
    'null_label_duplicate_groups', v_null_dup_groups,
    'active_client_links', v_active_links,
    'accepted_quotes_without_onboarding', v_accepted_no_onb,
    'onboarding_apps_unlinked', v_onb_unlinked,
    'duplicate_onboarding_app_groups', v_dup_onb_groups,
    'backstop_indexes_present', to_jsonb(v_present),
    'backstop_indexes_missing', to_jsonb(ARRAY(SELECT unnest(v_expected) EXCEPT SELECT unnest(v_present)))
  );
END;
$$;


--
-- Name: lifecycle_require_onboarding_token(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_require_onboarding_token(p_application_id uuid, p_access_token text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_access_token IS NULL
     OR NOT public.validate_onboarding_access_token(p_application_id, p_access_token) THEN
    RAISE EXCEPTION 'Invalid or missing onboarding access token' USING ERRCODE='42501';
  END IF;
END;
$$;


--
-- Name: lifecycle_send_back_onboarding(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_send_back_onboarding(p_application_id uuid, p_step text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_app RECORD;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Onboarding application % not found', p_application_id;
  END IF;

  UPDATE public.onboarding_applications
     SET status = 'needs_client_action',
         updated_at = now()
   WHERE id = p_application_id;

  IF v_app.email IS NOT NULL AND v_app.email <> '' THEN
    INSERT INTO public.email_queue (
      organization_id, to_email, to_name, subject, body_html,
      entity_type, entity_id, context, status
    ) VALUES (
      v_app.organization_id,
      v_app.email,
      COALESCE(v_app.company_name, TRIM(COALESCE(v_app.first_name,'') || ' ' || COALESCE(v_app.last_name,''))),
      'Action required to complete your onboarding',
      '<p>Hello,</p><p>Your accountant has reviewed your onboarding and needs you to revisit the <strong>' || p_step || '</strong> step.</p>' ||
      CASE WHEN p_reason IS NOT NULL AND p_reason <> '' THEN '<p><em>' || p_reason || '</em></p>' ELSE '' END ||
      '<p>Please continue here: <a href="' || COALESCE(current_setting('app.public_url', true), '') || '/onboard/' || p_application_id || '">Resume onboarding</a></p>',
      'onboarding_application',
      p_application_id,
      'onboarding',
      'pending'
    );
  END IF;

  RETURN jsonb_build_object('status', 'needs_client_action');
END;
$$;


--
-- Name: lifecycle_send_quote(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_send_quote(p_quote_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_quote               record;
  v_line_count          integer;
  v_recipient_email     text;
  v_recipient_name      text;
  v_recipient_first     text;
  v_preferred           text;
  v_first               text;
  v_last                text;
  v_email_queued        boolean := false;
  v_practice_name       text;
  v_template_id         uuid;
  v_template_content    jsonb;
  v_token               uuid;
  v_valid_until         date;
  v_lines_html          text := '';
  v_line                record;
  v_freq_label          text;
  v_unit_display        numeric;
  v_subtotal_display    numeric;
  v_unit_suffix         text;
  v_subtotal_suffix     text;
  v_total_now           numeric := 0;
  v_total_monthly       numeric := 0;
  v_base_url            text := 'https://app.accountancyos.com';
  v_subject             text;
  v_body_html           text;
  v_merge               jsonb;
  v_key                 text;
  v_val                 text;
  v_currency            text;
  v_accept_url          text;
  v_mailbox_id          uuid;
  v_mailbox_provider    text;
  v_mailbox_from        text;
  v_creator             uuid;
BEGIN
  SELECT * INTO v_quote FROM quotes WHERE id = p_quote_id;
  IF v_quote.id IS NULL THEN RAISE EXCEPTION 'Quote not found: %', p_quote_id; END IF;
  IF NOT user_has_organization_access(v_quote.organization_id) THEN RAISE EXCEPTION 'Access denied to organization'; END IF;
  IF v_quote.status != 'draft' THEN RAISE EXCEPTION 'Quote cannot be sent. Current status: %. Only draft quotes can be sent.', v_quote.status; END IF;

  SELECT COUNT(*) INTO v_line_count FROM quote_lines WHERE quote_id = p_quote_id;
  IF v_line_count = 0 THEN RAISE EXCEPTION 'Quote has no line items. Add services before sending.'; END IF;

  v_valid_until := COALESCE(v_quote.valid_until, (now() + interval '30 days')::date);
  v_currency := COALESCE(v_quote.currency, 'GBP');
  v_creator := COALESCE(v_quote.created_by, auth.uid());

  IF v_quote.lead_id IS NOT NULL THEN
    SELECT email, first_name, last_name
      INTO v_recipient_email, v_first, v_last
    FROM leads WHERE id = v_quote.lead_id;
  ELSIF v_quote.client_id IS NOT NULL THEN
    SELECT email, preferred_name, first_name, last_name
      INTO v_recipient_email, v_preferred, v_first, v_last
    FROM clients WHERE id = v_quote.client_id;
  END IF;

  IF v_recipient_email IS NULL AND v_quote.company_id IS NOT NULL THEN
    SELECT c.email, c.preferred_name, c.first_name, c.last_name
      INTO v_recipient_email, v_preferred, v_first, v_last
    FROM clients c
    WHERE c.company_id = v_quote.company_id
      AND c.email IS NOT NULL
    ORDER BY c.created_at ASC
    LIMIT 1;

    IF v_recipient_email IS NULL THEN
      SELECT email INTO v_recipient_email FROM companies WHERE id = v_quote.company_id;
    END IF;
  END IF;

  v_recipient_first := COALESCE(NULLIF(trim(v_preferred), ''), NULLIF(trim(v_first), ''));
  v_recipient_name  := COALESCE(
    NULLIF(trim(v_preferred), ''),
    NULLIF(trim(coalesce(v_first,'') || ' ' || coalesce(v_last,'')), '')
  );

  IF v_recipient_name IS NULL AND v_quote.company_id IS NOT NULL THEN
    SELECT company_name INTO v_recipient_name FROM companies WHERE id = v_quote.company_id;
    v_recipient_first := COALESCE(v_recipient_first, v_recipient_name);
  END IF;

  SELECT COALESCE(NULLIF(ob.trading_name, ''), NULLIF(ob.legal_name, ''), o.name)
    INTO v_practice_name
  FROM organizations o
  LEFT JOIN organization_branding ob ON ob.organization_id = o.id
  WHERE o.id = v_quote.organization_id;

  IF v_creator IS NOT NULL THEN
    SELECT id, provider, email_address
      INTO v_mailbox_id, v_mailbox_provider, v_mailbox_from
    FROM connected_mailboxes
    WHERE organization_id = v_quote.organization_id
      AND user_id = v_creator
      AND status = 'active'
      AND COALESCE(sync_enabled, true) = true
    ORDER BY updated_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  IF v_mailbox_id IS NULL THEN
    SELECT id, provider, email_address
      INTO v_mailbox_id, v_mailbox_provider, v_mailbox_from
    FROM connected_mailboxes
    WHERE organization_id = v_quote.organization_id
      AND status = 'active'
      AND COALESCE(sync_enabled, true) = true
    ORDER BY updated_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  SELECT id, content INTO v_template_id, v_template_content
  FROM templates
  WHERE organization_id = v_quote.organization_id
    AND type = 'email'
    AND (
          COALESCE(tags, '[]'::jsonb) ? 'quote'
       OR name ILIKE '%quote%'
       OR name ILIKE '%proposal%'
        )
    AND COALESCE(status, 'active') = 'active'
  ORDER BY updated_at DESC NULLS LAST
  LIMIT 1;

  FOR v_line IN
    SELECT ql.*, sc.name AS service_name
    FROM quote_lines ql
    LEFT JOIN services_catalog sc ON sc.id = ql.service_id
    WHERE ql.quote_id = p_quote_id
    ORDER BY ql.line_order
  LOOP
    IF v_line.billing_frequency = 'monthly' THEN
      v_freq_label := 'Monthly';
      v_unit_display := ROUND(COALESCE(v_line.unit_price,0) / 12.0, 2);
      v_subtotal_display := ROUND(v_unit_display * COALESCE(v_line.quantity,1), 2);
      v_unit_suffix := '/mo';
      v_subtotal_suffix := '/mo';
      v_total_monthly := v_total_monthly + v_subtotal_display;
    ELSE
      v_freq_label := 'Bill Now';
      v_unit_display := COALESCE(v_line.unit_price, 0);
      v_subtotal_display := COALESCE(v_line.subtotal, v_unit_display * COALESCE(v_line.quantity,1));
      v_unit_suffix := '';
      v_subtotal_suffix := '';
      v_total_now := v_total_now + v_subtotal_display;
    END IF;

    v_lines_html := v_lines_html ||
      '<tr><td style="padding:6px 8px;border-bottom:1px solid #eee">' || COALESCE(v_line.service_name, 'Service') ||
      '</td><td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:right">' || COALESCE(v_line.quantity,1) ||
      '</td><td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:right">' || v_currency || ' ' || to_char(v_unit_display, 'FM999,999,990.00') || v_unit_suffix ||
      '</td><td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:right">' || v_currency || ' ' || to_char(v_subtotal_display, 'FM999,999,990.00') || v_subtotal_suffix ||
      '</td></tr>';
  END LOOP;

  v_lines_html :=
    '<table style="border-collapse:collapse;width:100%;margin:12px 0">' ||
    '<thead><tr>' ||
    '<th style="text-align:left;padding:6px 8px;border-bottom:2px solid #ccc">Service</th>' ||
    '<th style="text-align:right;padding:6px 8px;border-bottom:2px solid #ccc">Qty</th>' ||
    '<th style="text-align:right;padding:6px 8px;border-bottom:2px solid #ccc">Unit</th>' ||
    '<th style="text-align:right;padding:6px 8px;border-bottom:2px solid #ccc">Subtotal</th>' ||
    '</tr></thead><tbody>' || v_lines_html || '</tbody></table>';

  v_token := gen_random_uuid();
  INSERT INTO quote_acceptance_tokens(token, quote_id, organization_id, expires_at)
  VALUES (v_token, p_quote_id, v_quote.organization_id, now() + interval '30 days');

  v_accept_url := v_base_url || '/q/' || v_token::text;

  v_merge := jsonb_build_object(
    'recipient_name', v_recipient_name,
    'recipient_first_name', v_recipient_first,
    'practice_name', v_practice_name,
    'quote_number', v_quote.quote_number,
    'currency', v_currency,
    'total_now', to_char(v_total_now, 'FM999,999,990.00'),
    'total_monthly', to_char(v_total_monthly, 'FM999,999,990.00'),
    'total_amount', to_char(COALESCE(v_quote.total_amount, 0), 'FM999,999,990.00'),
    'valid_until', to_char(v_valid_until, 'DD Mon YYYY'),
    'accept_url', v_accept_url,
    'lines_html', v_lines_html,
    'quote_total_now', to_char(v_total_now, 'FM999,999,990.00'),
    'quote_total_monthly', to_char(v_total_monthly, 'FM999,999,990.00'),
    'quote_total', to_char(COALESCE(v_quote.total_amount, 0), 'FM999,999,990.00'),
    'accept_link', v_accept_url,
    'quote_lines_table', v_lines_html
  );

  IF v_template_content IS NOT NULL THEN
    v_subject   := COALESCE(v_template_content->>'subject', 'Proposal from ' || v_practice_name);
    v_body_html := COALESCE(
      NULLIF(v_template_content->>'htmlBody', ''),
      NULLIF(v_template_content->>'body_html', ''),
      NULLIF(v_template_content->>'body', ''),
      ''
    );
    FOR v_key, v_val IN SELECT * FROM jsonb_each_text(v_merge) LOOP
      v_subject   := replace(v_subject, '{{' || v_key || '}}', COALESCE(v_val,''));
      v_body_html := replace(v_body_html, '{{' || v_key || '}}', COALESCE(v_val,''));
    END LOOP;
  ELSE
    v_subject := 'Proposal ' || v_quote.quote_number || ' from ' || v_practice_name;
    v_body_html :=
      '<p>Dear ' || COALESCE(v_recipient_first, v_recipient_name, 'Client') || ',</p>' ||
      '<p>Please find your proposal below.</p>' ||
      v_lines_html ||
      '<p><strong>Payable Now:</strong> ' || v_currency || ' ' || to_char(v_total_now, 'FM999,999,990.00') || '<br/>' ||
      '<strong>Payable Monthly:</strong> ' || v_currency || ' ' || to_char(v_total_monthly, 'FM999,999,990.00') || '</p>' ||
      '<p><a href="' || v_accept_url || '">Review and accept your proposal</a></p>' ||
      '<p>Kind regards,<br/>' || v_practice_name || '</p>';
  END IF;

  IF v_body_html !~ '<[a-zA-Z]' THEN
    v_body_html := replace(v_body_html, E'\n', '<br/>');
  END IF;

  IF v_recipient_email IS NOT NULL THEN
    INSERT INTO email_queue (
      organization_id, client_id, company_id,
      entity_type, entity_id, context,
      to_email, to_name, subject, body_html,
      mailbox_id, provider, created_by, queued_by,
      status, scheduled_at, created_at
    ) VALUES (
      v_quote.organization_id, v_quote.client_id, v_quote.company_id,
      'quote', v_quote.id, 'quote',
      v_recipient_email, v_recipient_name, v_subject, v_body_html,
      v_mailbox_id, v_mailbox_provider, v_creator, auth.uid(),
      'pending', now() + interval '15 minutes', now()
    );
    v_email_queued := true;
  END IF;

  UPDATE quotes
     SET status = 'sent',
         sent_at = COALESCE(sent_at, now()),
         valid_until = v_valid_until,
         updated_at = now()
   WHERE id = p_quote_id;

  RETURN jsonb_build_object(
    'quote_id', p_quote_id,
    'status', 'sent',
    'email_queued', v_email_queued,
    'recipient_email', v_recipient_email,
    'recipient_name', v_recipient_name,
    'sender_mailbox', v_mailbox_from,
    'sender_provider', v_mailbox_provider
  );
END;
$$;


--
-- Name: lifecycle_upsert_job_with_deadlines(uuid, uuid, uuid, uuid, text, text, date, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_upsert_job_with_deadlines(p_org uuid, p_client_id uuid, p_company_id uuid, p_engagement_id uuid, p_service_code text, p_service_name text, p_period_start date, p_period_end date, p_period_label text, p_source text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_filing_deadline date;
  v_job_id uuid;
BEGIN
  v_filing_deadline := CASE p_service_code
    WHEN 'company_accounts' THEN public.calculate_deadline('companies_house_accounts', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'confirmation_statement' THEN public.calculate_deadline('companies_house_confirmation', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'corporation_tax' THEN public.calculate_deadline('corporation_tax_filing', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'sa_mtd' THEN public.calculate_deadline('self_assessment', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'sa_non_mtd' THEN public.calculate_deadline('self_assessment', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'vat_return' THEN public.calculate_deadline('vat_return', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'payroll' THEN public.calculate_deadline('payroll_fps', p_period_start, p_period_end, '{}'::jsonb)
    ELSE NULL
  END;

  SELECT id INTO v_job_id FROM public.jobs
    WHERE organization_id = p_org
      AND service_type = p_service_code
      AND COALESCE(client_id::text,'') = COALESCE(p_client_id::text,'')
      AND COALESCE(company_id::text,'') = COALESCE(p_company_id::text,'')
      AND COALESCE(period_label,'') = COALESCE(p_period_label,'')
    LIMIT 1;

  IF v_job_id IS NULL THEN
    INSERT INTO public.jobs (organization_id, client_id, company_id, job_name, service_type,
                             period_start, period_end, period_label, status, priority,
                             filing_deadline, automation_source, is_auto_generated, auto_generated_at,
                             generation_reason)
    VALUES (p_org, p_client_id, p_company_id,
            p_service_name || ' - ' || COALESCE(p_period_label,'Setup Pending'),
            p_service_code, p_period_start, p_period_end, p_period_label,
            'blank', 'normal', v_filing_deadline, 'template', true, now(),
            p_source)
    RETURNING id INTO v_job_id;
  END IF;

  IF v_filing_deadline IS NOT NULL AND p_service_code IN ('company_accounts','confirmation_statement','corporation_tax','sa_mtd','sa_non_mtd','vat_return','payroll') THEN
    INSERT INTO public.deadlines (organization_id, client_id, company_id, engagement_id, job_id,
                                  name, deadline_type, filing_body, service_code,
                                  period_start, period_end, due_date, warning_date, status)
    SELECT p_org, p_client_id, p_company_id, p_engagement_id, v_job_id,
           p_service_name || ' - ' || COALESCE(p_period_label,''),
           'statutory',
           CASE p_service_code
             WHEN 'company_accounts' THEN 'COMPANIES_HOUSE'
             WHEN 'confirmation_statement' THEN 'COMPANIES_HOUSE'
             ELSE 'HMRC'
           END,
           p_service_code, p_period_start, p_period_end, v_filing_deadline,
           v_filing_deadline - INTERVAL '30 days', 'pending'
    WHERE NOT EXISTS (
      SELECT 1 FROM public.deadlines
      WHERE job_id = v_job_id AND service_code = p_service_code AND due_date = v_filing_deadline
    );

    IF p_service_code = 'corporation_tax' THEN
      INSERT INTO public.deadlines (organization_id, client_id, company_id, engagement_id, job_id,
                                    name, deadline_type, filing_body, service_code,
                                    period_start, period_end, due_date, warning_date, status)
      SELECT p_org, p_client_id, p_company_id, p_engagement_id, v_job_id,
             'Corporation Tax Payment - ' || COALESCE(p_period_label,''),
             'statutory', 'HMRC', 'corporation_tax_payment',
             p_period_start, p_period_end,
             public.calculate_deadline('corporation_tax_payment', p_period_start, p_period_end, '{}'::jsonb),
             public.calculate_deadline('corporation_tax_payment', p_period_start, p_period_end, '{}'::jsonb) - INTERVAL '30 days',
             'pending'
      WHERE NOT EXISTS (
        SELECT 1 FROM public.deadlines
        WHERE job_id = v_job_id AND service_code = 'corporation_tax_payment'
      );
    END IF;
  END IF;

  RETURN v_job_id;
END;
$$;


--
-- Name: link_onboarding_documents_on_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_onboarding_documents_on_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'approved'
     AND (TG_OP = 'INSERT'
          OR OLD.status IS DISTINCT FROM NEW.status
          OR OLD.client_id  IS DISTINCT FROM NEW.client_id
          OR OLD.company_id IS DISTINCT FROM NEW.company_id) THEN
    UPDATE public.onboarding_documents
       SET client_id  = NEW.client_id,
           company_id = NEW.company_id
     WHERE application_id = NEW.id
       AND (client_id  IS DISTINCT FROM NEW.client_id
         OR company_id IS DISTINCT FROM NEW.company_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: link_person_to_sa_client(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_person_to_sa_client(p_person_id uuid, p_client_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_organization_id uuid;
  v_client_org_id uuid;
BEGIN
  SELECT organization_id INTO v_organization_id
  FROM public.company_persons WHERE id = p_person_id;

  IF v_organization_id IS NULL THEN
    RAISE EXCEPTION 'Person not found: %', p_person_id;
  END IF;

  IF NOT public.user_has_organization_access(v_organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization';
  END IF;

  SELECT organization_id INTO v_client_org_id
  FROM public.clients WHERE id = p_client_id;

  IF v_client_org_id IS NULL THEN
    RAISE EXCEPTION 'Client not found: %', p_client_id;
  END IF;

  IF v_client_org_id <> v_organization_id THEN
    RAISE EXCEPTION 'Client % belongs to a different organization than person %', p_client_id, p_person_id;
  END IF;

  UPDATE public.company_persons
  SET linked_client_id = p_client_id
  WHERE id = p_person_id;

  RETURN jsonb_build_object(
    'ok', true,
    'person_id', p_person_id,
    'linked_client_id', p_client_id
  );
END;
$$;


--
-- Name: lock_period(uuid, text, uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_period(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_lock_date date, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_existing_lock date;
  v_unposted_count int;
  v_lock_id uuid;
BEGIN
  IF v_user IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Not authenticated'); END IF;
  IF NOT (public.has_organization_role(p_organization_id, 'owner')
       OR public.has_organization_role(p_organization_id, 'admin')) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only owners or admins may lock periods');
  END IF;
  IF p_entity_type NOT IN ('client','company') THEN
    RETURN jsonb_build_object('success', false, 'error', 'entity_type must be client or company');
  END IF;

  SELECT count(*) INTO v_unposted_count
  FROM public.journals j
  WHERE j.organization_id = p_organization_id
    AND ((p_entity_type = 'client'  AND j.client_id  = p_entity_id)
      OR (p_entity_type = 'company' AND j.company_id = p_entity_id))
    AND j.journal_date <= p_lock_date
    AND j.status = 'DRAFT';

  IF v_unposted_count > 0 THEN
    RETURN jsonb_build_object('success', false,
      'error', format('%s draft journal(s) on or before %s must be posted or voided first', v_unposted_count, p_lock_date));
  END IF;

  SELECT lock_date INTO v_existing_lock FROM public.period_locks
  WHERE organization_id = p_organization_id
    AND ((p_entity_type = 'client'  AND client_id  = p_entity_id)
      OR (p_entity_type = 'company' AND company_id = p_entity_id));

  IF v_existing_lock IS NOT NULL AND p_lock_date < v_existing_lock THEN
    RETURN jsonb_build_object('success', false,
      'error', format('Lock date cannot move backwards. Current lock: %s. Use unlock_period first.', v_existing_lock));
  END IF;

  INSERT INTO public.period_locks(organization_id, client_id, company_id, lock_date, locked_by, reason)
  VALUES (p_organization_id,
    CASE WHEN p_entity_type='client'  THEN p_entity_id END,
    CASE WHEN p_entity_type='company' THEN p_entity_id END,
    p_lock_date, v_user, p_reason)
  ON CONFLICT (organization_id, client_id, company_id)
  DO UPDATE SET lock_date = EXCLUDED.lock_date, locked_by = EXCLUDED.locked_by,
                locked_at = now(), reason = EXCLUDED.reason
  RETURNING id INTO v_lock_id;

  RETURN jsonb_build_object('success', true, 'lock_id', v_lock_id, 'lock_date', p_lock_date);
END; $$;


