--
-- Name: mcp_cron_job_health(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_cron_job_health(p_window_minutes integer DEFAULT 20) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t.jobname), '[]'::jsonb)
  FROM (
    SELECT
      j.jobname,
      j.schedule,
      j.active,
      count(d.runid)                                                    AS runs,
      count(*) FILTER (WHERE d.status = 'succeeded')                    AS succeeded,
      count(*) FILTER (WHERE d.status IS NOT NULL
                         AND d.status <> 'succeeded')                   AS failed,
      max(d.start_time)                                                 AS last_run_at,
      (ARRAY_AGG(d.status ORDER BY d.start_time DESC)
         FILTER (WHERE d.status IS NOT NULL))[1]                        AS last_status,
      public.redact_secrets(
        (ARRAY_AGG(d.return_message ORDER BY d.start_time DESC)
           FILTER (WHERE d.return_message IS NOT NULL))[1]
      )                                                                 AS last_message,
      -- The DEF-018 signature. Surfaced explicitly so a regression is unmistakable
      -- rather than something to be inferred from an error string.
      count(*) FILTER (
        WHERE d.return_message ILIKE '%unrecognized configuration parameter%'
      )                                                                 AS unrecognized_parameter_failures
    FROM cron.job j
    LEFT JOIN cron.job_run_details d
      ON d.jobid = j.jobid
     AND d.start_time > now() - make_interval(mins => greatest(p_window_minutes, 1))
    GROUP BY j.jobname, j.schedule, j.active
  ) t;
$$;


--
-- Name: FUNCTION mcp_cron_job_health(p_window_minutes integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mcp_cron_job_health(p_window_minutes integer) IS 'Read-only cron health projection. cron.job_run_details is unreadable by the executor role and by the database connector, which is why DEF-018 (26,208 silent failures) was undetectable. DEF-019.';


--
-- Name: mcp_http_delivery_health(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_http_delivery_health(p_window_minutes integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_result jsonb;
BEGIN
  -- pg_net's response relation is internal and has been renamed across versions. Report the
  -- fact rather than raising, so a verifier check fails with a legible reason.
  IF to_regclass('net._http_response') IS NULL THEN
    RETURN jsonb_build_object(
      'available', false,
      'reason', 'net._http_response is not present in this pg_net version; delivery cannot be verified from SQL.'
    );
  END IF;

  EXECUTE format($q$
    SELECT jsonb_build_object(
      'available', true,
      'window_minutes', %1$s,
      'total',        count(*),
      'succeeded_2xx',count(*) FILTER (WHERE status_code BETWEEN 200 AND 299),
      'unauthorized', count(*) FILTER (WHERE status_code IN (401, 403)),
      'client_error', count(*) FILTER (WHERE status_code BETWEEN 400 AND 499),
      'server_error', count(*) FILTER (WHERE status_code BETWEEN 500 AND 599),
      'timed_out',    count(*) FILTER (WHERE timed_out),
      'no_response',  count(*) FILTER (WHERE status_code IS NULL),
      'sample_errors', coalesce((
        SELECT jsonb_agg(jsonb_build_object(
                 'status_code', s.status_code,
                 'created', s.created,
                 'error', public.redact_secrets(s.error_msg)))
        FROM (
          SELECT status_code, created, error_msg
          FROM net._http_response
          WHERE created > now() - make_interval(mins => greatest(%1$s, 1))
            AND (status_code IS NULL OR status_code >= 400)
          ORDER BY created DESC
          LIMIT 5
        ) s), '[]'::jsonb)
    )
    FROM net._http_response
    WHERE created > now() - make_interval(mins => greatest(%1$s, 1))
  $q$, p_window_minutes)
  INTO v_result;

  RETURN v_result;
END;
$_$;


--
-- Name: FUNCTION mcp_http_delivery_health(p_window_minutes integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mcp_http_delivery_health(p_window_minutes integer) IS 'Read-only HTTP delivery projection over net._http_response. pg_cron reports SQL success while net.http_post is asynchronous, so cron status alone cannot distinguish a delivered call from a 401. Never returns response content or headers. DEF-019.';


--
-- Name: mcp_list_cron_jobs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_list_cron_jobs() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  result jsonb;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron')
     AND EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'cron') THEN
    EXECUTE $q$
      SELECT coalesce(jsonb_agg(row_to_json(j) ORDER BY j.jobname), '[]'::jsonb)
      FROM (
        SELECT jobid, schedule, jobname, command, active, database, username
        FROM cron.job
      ) j
    $q$ INTO result;
    RETURN coalesce(result, '[]'::jsonb);
  END IF;
  RETURN '[]'::jsonb;
END;
$_$;


--
-- Name: mcp_list_functions(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_list_functions(name_like text DEFAULT NULL::text, include_source boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t.name), '[]'::jsonb)
  FROM (
    SELECT
      n.nspname                                     AS schema,
      p.proname                                     AS name,
      pg_get_function_identity_arguments(p.oid)     AS arguments,
      pg_get_function_result(p.oid)                 AS return_type,
      l.lanname                                     AS language,
      p.prosecdef                                   AS security_definer,
      CASE p.provolatile WHEN 'i' THEN 'immutable' WHEN 's' THEN 'stable' WHEN 'v' THEN 'volatile' END AS volatility,
      (
        SELECT string_agg(cfg, ', ')
        FROM unnest(coalesce(p.proconfig, ARRAY[]::text[])) AS cfg
        WHERE cfg LIKE 'search_path=%'
      )                                             AS search_path,
      md5(pg_get_functiondef(p.oid))                AS definition_hash,
      CASE WHEN mcp_list_functions.include_source
           THEN pg_get_functiondef(p.oid)
           ELSE NULL END                            AS definition
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    JOIN pg_language  l ON l.oid = p.prolang
    WHERE n.nspname = 'public'
      AND p.prokind = 'f'
      AND (mcp_list_functions.name_like IS NULL
           OR p.proname ILIKE '%' || mcp_list_functions.name_like || '%')
  ) t;
$$;


--
-- Name: mcp_list_grants(text); Type: FUNCTION; Schema: public; Owner: -
