--
-- Name: mcp_list_schema(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_list_schema() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(jsonb_object_agg(table_name, cols), '{}'::jsonb)
  FROM (
    SELECT c.table_name,
           jsonb_agg(jsonb_build_object(
             'column', c.column_name,
             'type', c.data_type,
             'nullable', c.is_nullable = 'YES',
             'default', c.column_default
           ) ORDER BY c.ordinal_position) AS cols
    FROM information_schema.columns c
    JOIN information_schema.tables t
      ON t.table_schema = c.table_schema AND t.table_name = c.table_name
    WHERE c.table_schema = 'public'
      AND t.table_type = 'BASE TABLE'
    GROUP BY c.table_name
  ) s;
$$;


--
-- Name: mcp_list_triggers(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_list_triggers(table_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t."table", t.name), '[]'::jsonb)
  FROM (
    SELECT
      n.nspname                              AS schema,
      c.relname                              AS "table",
      tg.tgname                              AS name,
      CASE WHEN (tg.tgtype & 2) = 2 THEN 'BEFORE'
           WHEN (tg.tgtype & 64) = 64 THEN 'INSTEAD OF'
           ELSE 'AFTER' END                  AS timing,
      array_remove(ARRAY[
        CASE WHEN (tg.tgtype & 4)  = 4  THEN 'INSERT' END,
        CASE WHEN (tg.tgtype & 8)  = 8  THEN 'DELETE' END,
        CASE WHEN (tg.tgtype & 16) = 16 THEN 'UPDATE' END,
        CASE WHEN (tg.tgtype & 32) = 32 THEN 'TRUNCATE' END
      ], NULL)                               AS events,
      pn.nspname                             AS function_schema,
      p.proname                              AS function_name,
      tg.tgenabled <> 'D'                    AS enabled,
      pg_get_triggerdef(tg.oid)              AS definition
    FROM pg_trigger tg
    JOIN pg_class     c  ON c.oid  = tg.tgrelid
    JOIN pg_namespace n  ON n.oid  = c.relnamespace
    JOIN pg_proc      p  ON p.oid  = tg.tgfoid
    JOIN pg_namespace pn ON pn.oid = p.pronamespace
    WHERE NOT tg.tgisinternal
      AND n.nspname = 'public'
      AND (mcp_list_triggers.table_name IS NULL OR c.relname = mcp_list_triggers.table_name)
  ) t;
$$;


--
-- Name: mcp_vault_secret_present(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_vault_secret_present(p_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_secret text;
BEGIN
  BEGIN
    SELECT decrypted_secret INTO v_secret
    FROM vault.decrypted_secrets
    WHERE name = p_name
    LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    -- Owner of this function cannot read the vault either. Say so rather than
    -- returning false, which would read as "the secret is missing".
    RAISE EXCEPTION 'vault.decrypted_secrets is not readable even as the function owner (%)', SQLERRM;
  END;

  RETURN v_secret IS NOT NULL AND length(btrim(v_secret)) > 0;
END;
$$;


--
-- Name: FUNCTION mcp_vault_secret_present(p_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mcp_vault_secret_present(p_name text) IS 'TRUE when a vault secret exists and is non-empty. Never returns the value. Cannot prove the value is current or valid — a rotated key is present, non-empty, and 401s on every call; only mcp_http_delivery_health can show that. DEF-019.';


--
-- Name: move_to_dlq(text, text, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.move_to_dlq(source_queue text, dlq_name text, message_id bigint, payload jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE new_id BIGINT;
BEGIN
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  PERFORM pgmq.delete(source_queue, message_id);
  RETURN new_id;
EXCEPTION WHEN undefined_table THEN
  BEGIN
    PERFORM pgmq.create(dlq_name);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  BEGIN
    PERFORM pgmq.delete(source_queue, message_id);
  EXCEPTION WHEN undefined_table THEN
    NULL;
  END;
  RETURN new_id;
END;
$$;


