-- Name: notify_onboarding_approved(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_onboarding_approved() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_recipient_name text;
BEGIN
  IF NEW.status = 'approved' AND COALESCE(OLD.status,'') <> 'approved' THEN
    v_recipient_name := COALESCE(
      NULLIF(TRIM(CONCAT_WS(' ', NEW.first_name, NEW.last_name)), ''),
      NEW.company_name,
      'there'
    );

    INSERT INTO notifications (organization_id, user_id, type, title, message, entity_type, entity_id)
    SELECT
      NEW.organization_id, om.user_id,
      'onboarding_approved',
      'Client activated',
      v_recipient_name || ' has been approved and activated.',
      'onboarding', NEW.id
    FROM public.organization_users om
    WHERE om.organization_id = NEW.organization_id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: notify_onboarding_for_review(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_onboarding_for_review() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_member RECORD;
  v_label TEXT;
BEGIN
  IF NEW.status = 'for_review' AND (OLD.status IS DISTINCT FROM 'for_review') THEN
    v_label := COALESCE(
      NEW.company_name,
      NULLIF(TRIM(COALESCE(NEW.first_name,'') || ' ' || COALESCE(NEW.last_name,'')), ''),
      NEW.email,
      'New onboarding'
    );

    FOR v_member IN
      SELECT user_id FROM public.organization_users
      WHERE organization_id = NEW.organization_id
    LOOP
      INSERT INTO public.notifications (
        organization_id, user_id, type, title, message, entity_type, entity_id, payload
      ) VALUES (
        NEW.organization_id,
        v_member.user_id,
        'onboarding_for_review',
        'Onboarding ready for review',
        v_label || ' has completed onboarding and is ready for your review.',
        'onboarding_application',
        NEW.id,
        jsonb_build_object('application_id', NEW.id, 'recipient', v_label)
      );
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: on_cgt_disposal_date_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.on_cgt_disposal_date_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_client_id uuid;
  v_deadline_date date;
BEGIN
  IF NEW.disposal_date IS NOT NULL AND (OLD.disposal_date IS NULL OR OLD.disposal_date != NEW.disposal_date) THEN
    v_deadline_date := NEW.disposal_date::date + INTERVAL '60 days';

    SELECT c.organization_id, c.id INTO v_org_id, v_client_id
    FROM public.clients c
    WHERE c.id = NEW.client_id;

    IF v_org_id IS NOT NULL THEN
      INSERT INTO public.deadlines (
        organization_id, client_id, service_code, deadline_type,
        due_date, title, status, created_at
      ) VALUES (
        v_org_id, v_client_id, 'CGT', 'filing',
        v_deadline_date, 'CGT Return - 60 Day Deadline',
        CASE WHEN v_deadline_date < CURRENT_DATE THEN 'overdue' ELSE 'upcoming' END,
        now()
      )
      ON CONFLICT (organization_id, client_id, service_code, deadline_type)
      DO UPDATE SET
        due_date = EXCLUDED.due_date,
        title = EXCLUDED.title,
        status = CASE WHEN EXCLUDED.due_date < CURRENT_DATE THEN 'overdue' ELSE 'upcoming' END,
        updated_at = now();
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

