--
-- Name: public_submit_onboarding_for_review(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_submit_onboarding_for_review(p_application_id uuid, p_portal_email text, p_access_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
  v_org_name text;
  v_member record;
  v_client_name text;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id FOR UPDATE;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);
  IF v_app.status = 'for_review' THEN
    RETURN jsonb_build_object('status','for_review','already', true);
  END IF;

  UPDATE public.onboarding_applications
     SET status = 'for_review',
         portal_email = COALESCE(p_portal_email, portal_email),
         submitted_for_review_at = now(),
         updated_at = now()
   WHERE id = p_application_id;

  SELECT name INTO v_org_name FROM public.organizations WHERE id = v_app.organization_id;
  v_client_name := COALESCE(v_app.company_name,
    NULLIF(trim(coalesce(v_app.first_name,'') || ' ' || coalesce(v_app.last_name,'')), ''),
    v_app.email, 'New onboarding');

  FOR v_member IN
    SELECT user_id FROM public.organization_users WHERE organization_id = v_app.organization_id
  LOOP
    INSERT INTO public.notifications (
      organization_id, user_id, type, title, message, entity_type, entity_id
    ) VALUES (
      v_app.organization_id, v_member.user_id, 'onboarding_for_review',
      'New onboarding ready for review',
      v_client_name || ' has completed onboarding and is ready for review.',
      'onboarding_application', p_application_id
    );
  END LOOP;

  INSERT INTO public.email_queue (
    organization_id, to_email, to_name, subject, body_html, status, context, entity_type, entity_id
  )
  SELECT v_app.organization_id,
         u.email,
         COALESCE(u.raw_user_meta_data->>'full_name', u.email),
         'Onboarding ready for review: ' || v_client_name,
         '<p>' || v_client_name || ' has completed the onboarding wizard.</p>' ||
         '<p>Please review in AccountancyOS.</p>',
         'pending', 'onboarding', 'onboarding_application', p_application_id
    FROM public.organization_users om
    JOIN auth.users u ON u.id = om.user_id
   WHERE om.organization_id = v_app.organization_id
     AND om.role = 'owner'
     AND u.email IS NOT NULL;

  RETURN jsonb_build_object('status','for_review','already', false);
END;
$$;


--
-- Name: queue_email_safe(uuid, text, text, text, text, uuid, jsonb, timestamp with time zone, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_email_safe(p_organization_id uuid, p_to_email text, p_to_name text DEFAULT NULL::text, p_subject text DEFAULT NULL::text, p_body_html text DEFAULT NULL::text, p_template_id uuid DEFAULT NULL::uuid, p_merge_data jsonb DEFAULT '{}'::jsonb, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_email_id uuid;
  v_status text;
BEGIN
  PERFORM set_config('app.rpc', '1', true);

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF NOT public.user_in_organization(v_user_id, p_organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  -- Draft if no scheduled_at, queued otherwise
  v_status := CASE WHEN p_scheduled_at IS NULL THEN 'draft' ELSE 'queued' END;

  INSERT INTO email_queue (
    organization_id, to_email, to_name, subject, body_html, template_id,
    merge_data, scheduled_at, status, entity_type, entity_id, created_by
  ) VALUES (
    p_organization_id, p_to_email, p_to_name, p_subject, p_body_html, p_template_id,
    p_merge_data, p_scheduled_at, v_status, p_entity_type, p_entity_id, v_user_id
  ) RETURNING id INTO v_email_id;

  INSERT INTO audit_log (organization_id, user_id, entity_type, entity_id, action, after_state)
  VALUES (p_organization_id, v_user_id, 'email', v_email_id, 'queued',
    jsonb_build_object('status', v_status, 'to_email', p_to_email));

  RETURN jsonb_build_object('success', true, 'email_id', v_email_id, 'status', v_status);
END;
$$;


--
-- Name: queue_filing_for_submission(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_filing_for_submission(p_filing_id uuid, p_filing_type text, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_validation JSONB;
  v_filing RECORD;
  v_snapshot_hash TEXT;
  v_idempotency_key TEXT;
  v_queue_id UUID;
  v_existing_queue RECORD;
BEGIN
  -- Validate first
  v_validation := public.validate_filing_submission(p_filing_id, p_filing_type, p_user_id);

  IF NOT (v_validation->>'valid')::boolean THEN
    RETURN v_validation;
  END IF;

  -- Get filing and snapshot hash
  SELECT * INTO v_filing FROM public.filings WHERE id = p_filing_id;

  IF p_filing_type = 'ACCOUNTS_CH' THEN
    SELECT snapshot_hash INTO v_snapshot_hash 
    FROM public.accounts_model_snapshots WHERE id = v_filing.accounts_snapshot_id;
  ELSE
    SELECT snapshot_hash INTO v_snapshot_hash 
    FROM public.ct_computation_snapshots WHERE id = v_filing.ct_snapshot_id;
  END IF;

  -- Generate idempotency key
  v_idempotency_key := v_filing.organization_id || ':' || p_filing_type || ':' || 
    COALESCE(v_filing.company_id::text, v_filing.client_id::text) || ':' ||
    v_filing.period_start || ':' || v_filing.period_end || ':' || v_snapshot_hash;

  -- Check for existing queue entry
  SELECT * INTO v_existing_queue 
  FROM public.filing_queue 
  WHERE idempotency_key = v_idempotency_key AND status NOT IN ('failed', 'cancelled');

  IF v_existing_queue.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'valid', false,
      'errors', ARRAY['Filing already queued or submitted with this snapshot'],
      'existing_queue_id', v_existing_queue.id
    );
  END IF;

  -- Insert queue entry
  INSERT INTO public.filing_queue (
    organization_id, filing_id, filing_type, idempotency_key, snapshot_hash, 
    approval_id, status
  )
  VALUES (
    v_filing.organization_id, p_filing_id, p_filing_type, v_idempotency_key, 
    v_snapshot_hash, (v_validation->>'approval_id')::uuid, 'queued'
  )
  RETURNING id INTO v_queue_id;

  -- Update filing status
  UPDATE public.filings SET status = 'queued' WHERE id = p_filing_id;

  RETURN jsonb_build_object(
    'valid', true,
    'queue_id', v_queue_id,
    'idempotency_key', v_idempotency_key
  );
END;
$$;


