CREATE FUNCTION public.record_automation_execution(p_organization_id uuid, p_rule_id uuid, p_triggered_by_entity text, p_triggered_by_id uuid, p_execution_hash text, p_status text, p_error_message text DEFAULT NULL::text, p_action_result jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_execution_id UUID;
BEGIN
  INSERT INTO public.automation_executions (
    organization_id,
    automation_rule_id,
    triggered_by_entity,
    triggered_by_id,
    execution_hash,
    status,
    error_message,
    action_result,
    executed_at
  ) VALUES (
    p_organization_id,
    p_rule_id,
    p_triggered_by_entity,
    p_triggered_by_id,
    p_execution_hash,
    p_status,
    p_error_message,
    p_action_result,
    CASE WHEN p_status IN ('success', 'failed') THEN now() ELSE NULL END
  )
  ON CONFLICT (automation_rule_id, execution_hash) 
  WHERE execution_hash IS NOT NULL
