      p_source_id       := v_payment_id,
      p_currency        := COALESCE(v_invoice.currency,'GBP'),
      p_fx_rate         := 1.0,
      p_created_by      := v_uid,
      p_entries         := v_entries
    );

    IF NOT (v_post_result->>'success')::boolean THEN
      RAISE EXCEPTION 'Payment posting failed: %', v_post_result->>'error_message'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  v_new_paid := COALESCE(v_invoice.amount_paid,0) + v_alloc;
  v_new_remaining := COALESCE(v_invoice.total_gross,0) - v_new_paid;
  v_new_status := CASE WHEN v_new_remaining <= 0 THEN 'PAID' ELSE 'PART_PAID' END;

  UPDATE invoices
     SET amount_paid = v_new_paid,
         remaining_balance = v_new_remaining,
         status = v_new_status,
         updated_at = now()
   WHERE id = p_invoice_id;

  RETURN jsonb_build_object('success', true, 'payment_id', v_payment_id,
    'fx_diff_base', COALESCE(v_fx_diff,0));
END;
$$;


--
-- Name: record_invoice_payment_safe(uuid, numeric, date, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_invoice_payment_safe(p_invoice_id uuid, p_amount numeric, p_payment_date date, p_bank_account_id uuid DEFAULT NULL::uuid, p_payment_method text DEFAULT NULL::text, p_reference text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_invoice record;
  v_res jsonb;
BEGIN
  PERFORM set_config('app.rpc', '1', true);
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
  END IF;
  IF NOT public.user_in_organization(v_user_id, v_invoice.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;
  IF v_invoice.status NOT IN ('AWAITING_PAYMENT', 'PART_PAID') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot record payment for this invoice status');
  END IF;
  v_res := public.record_invoice_payment(
    p_invoice_id, p_amount, p_payment_date, p_bank_account_id, NULL,
    p_reference, p_payment_method, v_user_id);
  IF NOT COALESCE((v_res->>'success')::boolean, false) THEN
    RAISE EXCEPTION 'Could not post payment: %',
      COALESCE(v_res->>'error_message', v_res->>'error', 'posting error')
      USING ERRCODE = 'P0001';
  END IF;
  RETURN jsonb_build_object('success', true, 'payment_id', v_res->>'payment_id');
END;
$$;


--
-- Name: record_kyc_subject_progress(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_kyc_subject_progress(p_subject_id uuid, p_new_status text, p_notes text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_pack_id uuid; v_org_id uuid; v_client_id uuid; v_all_done boolean;
BEGIN
  UPDATE public.kyc_pack_subjects
    SET subject_status = p_new_status,
        waiver_reason = CASE WHEN p_new_status = 'waived' THEN p_notes ELSE waiver_reason END
  WHERE id = p_subject_id
  RETURNING kyc_pack_id, organization_id INTO v_pack_id, v_org_id;
  IF v_pack_id IS NULL THEN RAISE EXCEPTION 'Subject not found'; END IF;
  IF NOT user_has_organization_access(v_org_id) THEN RAISE EXCEPTION 'Not authorised'; END IF;

  SELECT bool_and(subject_status IN ('complete','waived')) INTO v_all_done
  FROM public.kyc_pack_subjects WHERE kyc_pack_id = v_pack_id;

  IF v_all_done THEN
    UPDATE public.kyc_packs SET status = 'submitted', submitted_at = now()
    WHERE id = v_pack_id RETURNING client_id INTO v_client_id;
    INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, new_value)
    VALUES (v_org_id, 'KYC_STATUS_CHANGED', 'client', v_client_id,
            jsonb_build_object('kyc_pack_id', v_pack_id, 'status', 'submitted'));
  END IF;
END;
$$;


--
-- Name: record_vat_filing_approval(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_vat_filing_approval(_vat_return_id uuid, _snapshot_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_ret record; v_snap record;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Not authenticated'); END IF;
  SELECT * INTO v_ret FROM public.vat_returns WHERE id = _vat_return_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'VAT return not found'); END IF;
  IF NOT public.user_in_organization(auth.uid(), v_ret.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;
  IF v_ret.submitted_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'This VAT return has already been submitted');
  END IF;
  SELECT * INTO v_snap FROM public.filing_model_snapshots WHERE id = _snapshot_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Snapshot not found'); END IF;
  IF v_snap.organization_id <> v_ret.organization_id
     OR v_snap.snapshot_type <> 'vat_return'
     OR v_snap.company_id IS DISTINCT FROM v_ret.company_id
     OR v_snap.client_id  IS DISTINCT FROM v_ret.client_id
     OR v_snap.period_start <> v_ret.period_start
     OR v_snap.period_end   <> v_ret.period_end THEN
    RETURN jsonb_build_object('success', false, 'error', 'Snapshot does not match this VAT return');
  END IF;
  IF v_ret.model_snapshot_id = _snapshot_id AND v_ret.filing_approved_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'already_approved', true,
                              'snapshot_id', _snapshot_id, 'snapshot_hash', v_ret.snapshot_hash);
  END IF;
  UPDATE public.vat_returns
     SET model_snapshot_id  = _snapshot_id, snapshot_hash = v_snap.snapshot_hash,
         filing_approved_by = auth.uid(), filing_approved_at = now(), updated_at = now()
   WHERE id = _vat_return_id;
  RETURN jsonb_build_object('success', true, 'snapshot_id', _snapshot_id, 'snapshot_hash', v_snap.snapshot_hash);
END;
$$;


--
-- Name: redact_secrets(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redact_secrets(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT CASE
    WHEN p_text IS NULL THEN NULL
    ELSE regexp_replace(
           regexp_replace(p_text, 'eyJ[A-Za-z0-9_-]{6,}\.[A-Za-z0-9_-]{6,}\.[A-Za-z0-9_-]*', '[REDACTED-JWT]', 'g'),
           '(?i)(bearer|apikey|api[-_]?key|password|secret)[=: ]+\S+', '\1 [REDACTED]', 'g')
  END
$$;


--
-- Name: regenerate_ct_snapshot_on_accounts_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.regenerate_ct_snapshot_on_accounts_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_filing RECORD;
BEGIN
  -- Find filings using this accounts snapshot
  FOR v_filing IN 
    SELECT f.* FROM public.filings f
    WHERE f.accounts_snapshot_id = NEW.id
    AND f.filing_type IN ('corporation_tax', 'CT600')
  LOOP
    -- Mark that CT snapshot needs regeneration
    -- The actual regeneration should be triggered by application code
    -- Here we just log the event
    INSERT INTO public.audit_log (
      organization_id,
      entity_type,
      entity_id,
      action,
      metadata
    ) VALUES (
      v_filing.organization_id,
      'filing',
      v_filing.id,
      'ct_snapshot_regeneration_required',
      jsonb_build_object(
        'accounts_snapshot_id', NEW.id,
        'old_hash', OLD.snapshot_hash,
        'new_hash', NEW.snapshot_hash
      )
    );
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: regress_filing_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.regress_filing_status(p_filing_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_filing RECORD;
BEGIN
  SELECT * INTO v_filing FROM public.filings WHERE id = p_filing_id;

  IF v_filing.id IS NULL THEN
    RETURN;
  END IF;

  -- Only regress if in a state that can be regressed
  -- Never regress 'filed' or 'accepted' filings (they need amendments)
  IF v_filing.status IN ('approved', 'queued', 'ready_for_approval', 'draft') THEN
    UPDATE public.filings
    SET 
      status = 'ready_for_approval',
      updated_at = now()
    WHERE id = p_filing_id
    AND status NOT IN ('filed', 'accepted', 'submitted');

    -- Log audit event
    INSERT INTO public.audit_log (
      organization_id,
      entity_type,
      entity_id,
      action,
      old_value,
      new_value,
      metadata
    ) VALUES (
      v_filing.organization_id,
      'filing',
      p_filing_id,
      'status_regressed',
      v_filing.status,
      'ready_for_approval',
      jsonb_build_object('reason', p_reason, 'system_actor', 'SYSTEM')
    );
  END IF;
END;
$$;


--
-- Name: reissue_quote(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reissue_quote(p_quote_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_src record;
  v_new_id uuid;
  v_new_number text;
BEGIN
  SELECT * INTO v_src FROM public.quotes WHERE id = p_quote_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Quote not found'; END IF;
  IF NOT user_has_organization_access(v_src.organization_id) THEN RAISE EXCEPTION 'Not authorised'; END IF;
  IF v_src.status = 'accepted' THEN RAISE EXCEPTION 'Accepted quotes cannot be re-issued'; END IF;

  v_new_number := public.generate_quote_number(v_src.organization_id);

  INSERT INTO public.quotes
    (organization_id, quote_number, lead_id, client_id, company_id, status,
     total_amount, currency, valid_until, notes, supersedes_quote_id)
  VALUES
    (v_src.organization_id, v_new_number, v_src.lead_id, v_src.client_id, v_src.company_id, 'draft',
     v_src.total_amount, v_src.currency, v_src.valid_until, v_src.notes, v_src.id)
  RETURNING id INTO v_new_id;

  INSERT INTO public.quote_lines
    (organization_id, quote_id, service_id, description_override, quantity, unit_price, subtotal, line_order, billing_frequency)
  SELECT organization_id, v_new_id, service_id, description_override, quantity, unit_price, subtotal, line_order, billing_frequency
    FROM public.quote_lines WHERE quote_id = v_src.id;

  -- Supersede original if still open
  IF v_src.status IN ('draft','sent') THEN
    UPDATE public.quotes SET status = 'superseded' WHERE id = v_src.id;
  END IF;

  -- Invalidate any open acceptance tokens for the original
  UPDATE public.quote_acceptance_tokens
     SET used_at = now()
   WHERE quote_id = v_src.id AND used_at IS NULL;

  RETURN v_new_id;
END;
$$;


--
-- Name: remove_reconciliation_line(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_reconciliation_line(p_line_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rec public.reconciliations%ROWTYPE;
  v_txn_id uuid;
BEGIN
  SELECT r.* INTO v_rec
  FROM public.reconciliation_lines rl
  JOIN public.reconciliations r ON r.id = rl.reconciliation_id
  WHERE rl.id = p_line_id FOR UPDATE OF r;

  IF NOT FOUND THEN RAISE EXCEPTION 'Reconciliation line not found'; END IF;
  IF v_rec.status <> 'in_progress' THEN
    RAISE EXCEPTION 'Reconciliation is not in progress (status=%)', v_rec.status;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = v_rec.organization_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not authorized for this organization';
  END IF;

  SELECT bank_transaction_id INTO v_txn_id FROM public.reconciliation_lines WHERE id = p_line_id;
  DELETE FROM public.reconciliation_lines WHERE id = p_line_id;

  -- Restore prior status (matched/posted)
  UPDATE public.bank_transactions
     SET status = CASE
       WHEN matched_ledger_entry_id IS NOT NULL THEN 'MATCHED'
       ELSE 'UNREVIEWED'
     END,
     updated_at = now()
   WHERE id = v_txn_id;
END;
$$;

