--
-- Name: update_issued_invoice_safe(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_issued_invoice_safe(p_invoice_id uuid, p_updates jsonb, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice RECORD;
  v_user_id UUID;
  v_org_id UUID;
  v_user_role TEXT;
  v_before_state JSONB;
  v_allowed_fields TEXT[] := ARRAY['notes', 'internal_notes', 'tags', 'attachments', 'message_to_customer'];
  v_manager_fields TEXT[] := ARRAY['due_date'];
  v_key TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
  END IF;

  v_org_id := v_invoice.organization_id;

  -- Check basic permission
  IF NOT user_in_organization(v_user_id, v_org_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied');
  END IF;

  -- Get user role
  SELECT role INTO v_user_role FROM organization_users 
  WHERE user_id = v_user_id AND organization_id = v_org_id;

  -- Validate status - only issued, part_paid, or paid invoices
  IF v_invoice.status NOT IN ('ISSUED', 'PART_PAID', 'PAID', 'AWAITING_PAYMENT') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot update invoice in ' || v_invoice.status || ' status');
  END IF;

  v_before_state := to_jsonb(v_invoice);

  -- Validate each field in updates
  FOR v_key IN SELECT jsonb_object_keys(p_updates)
  LOOP
    -- Check if field is allowed for all users
    IF v_key = ANY(v_allowed_fields) THEN
      CONTINUE;
    -- Check if field is allowed for manager+
    ELSIF v_key = ANY(v_manager_fields) THEN
      IF NOT user_has_role_at_least(v_user_id, v_org_id, 'manager') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Permission denied: ' || v_key || ' requires manager role');
      END IF;
    ELSE
      RETURN jsonb_build_object('success', false, 'error', 'Field ' || v_key || ' is locked on issued invoices');
    END IF;
  END LOOP;

  -- Apply updates
  UPDATE invoices SET
    notes = COALESCE(p_updates->>'notes', notes),
    due_date = COALESCE((p_updates->>'due_date')::DATE, due_date),
    updated_at = now()
  WHERE id = p_invoice_id;

  -- Write audit log
  PERFORM write_audit_log(
    v_org_id,
    'invoice',
    p_invoice_id,
    'update_issued',
    NULL,
    NULL,
    NULL,
    v_before_state,
    (SELECT to_jsonb(i) FROM invoices i WHERE i.id = p_invoice_id),
    jsonb_build_object('updates', p_updates, 'reason', p_reason)
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: update_job_status_safe(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_job_status_safe(p_job_id uuid, p_new_status text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_job record;
  v_old_status text;
BEGIN
  -- Fetch job
  SELECT * INTO v_job FROM jobs WHERE id = p_job_id;

  IF v_job.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Job not found');
  END IF;

  -- Check permission
  IF NOT can_modify_jobs(auth.uid(), v_job.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied');
  END IF;

  v_old_status := v_job.status;

  -- Update job
  UPDATE jobs SET status = p_new_status, updated_at = now() WHERE id = p_job_id;

  -- Write audit log
  INSERT INTO audit_log (
    organization_id, entity_type, entity_id, action,
    field_name, old_value, new_value, user_id, metadata
  ) VALUES (
    v_job.organization_id, 'job', p_job_id, 'status_change',
    'status', v_old_status, p_new_status, auth.uid(),
    jsonb_build_object('reason', p_reason)
  );

  RETURN jsonb_build_object('success', true, 'old_status', v_old_status, 'new_status', p_new_status);
END;
$$;


--
-- Name: update_queued_email_safe(uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_queued_email_safe(p_email_id uuid, p_subject text DEFAULT NULL::text, p_body_html text DEFAULT NULL::text, p_to_email text DEFAULT NULL::text, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_email RECORD;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_email FROM email_queue WHERE id = p_email_id;
  IF v_email.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Email not found');
  END IF;

  IF NOT user_in_organization(v_user_id, v_email.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  -- FIXED: Block edits to failed emails and sending/sent
  IF v_email.status NOT IN ('draft', 'pending', 'queued') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Can only edit draft, pending, or queued emails');
  END IF;

  UPDATE email_queue SET
    subject = COALESCE(p_subject, subject),
    body_html = COALESCE(p_body_html, body_html),
    to_email = COALESCE(p_to_email, to_email),
    scheduled_at = COALESCE(p_scheduled_at, scheduled_at),
    updated_at = now()
  WHERE id = p_email_id;

  RETURN jsonb_build_object('success', true, 'email_id', p_email_id);
END;
$$;


--
-- Name: update_shareholder_on_allotment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_shareholder_on_allotment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Update shareholder shares_held
  UPDATE company_shareholders
  SET 
    shares_held = shares_held + NEW.shares_allotted,
    as_at_date = NEW.allotment_date,
    updated_at = now()
  WHERE id = NEW.shareholder_id;

  -- Update share class total
  UPDATE company_share_classes
  SET 
    total_shares_issued = total_shares_issued + NEW.shares_allotted,
    updated_at = now()
  WHERE id = NEW.share_class_id;

  -- Create register event
  INSERT INTO company_register_events (
    company_id, event_type, event_date, source, details,
    shareholder_id, allotment_id, created_by
  )
  VALUES (
    NEW.company_id, 'allotment', NEW.allotment_date, 'workpaper',
    jsonb_build_object(
      'shares_allotted', NEW.shares_allotted,
      'price_per_share', NEW.price_per_share,
      'total_consideration', NEW.total_consideration
    ),
    NEW.shareholder_id, NEW.id, auth.uid()
  );

  RETURN NEW;
END;
$$;


--
-- Name: update_shareholders_on_transfer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_shareholders_on_transfer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Decrease from_shareholder
  UPDATE company_shareholders
  SET 
    shares_held = shares_held - NEW.shares_transferred,
    as_at_date = NEW.transfer_date,
    updated_at = now()
  WHERE id = NEW.from_shareholder_id;

  -- Increase to_shareholder
  UPDATE company_shareholders
  SET 
    shares_held = shares_held + NEW.shares_transferred,
    as_at_date = NEW.transfer_date,
    updated_at = now()
  WHERE id = NEW.to_shareholder_id;

  -- Create register event
  INSERT INTO company_register_events (
    company_id, event_type, event_date, source, details,
    transfer_id, created_by
  )
  VALUES (
    NEW.company_id, 'transfer', NEW.transfer_date, 'workpaper',
    jsonb_build_object(
      'shares_transferred', NEW.shares_transferred,
      'from_shareholder_id', NEW.from_shareholder_id,
      'to_shareholder_id', NEW.to_shareholder_id,
      'consideration', NEW.consideration
    ),
    NEW.id, auth.uid()
  );

  RETURN NEW;
END;
$$;


