--
-- Name: validate_filing_approval_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_filing_approval_token(p_token text) RETURNS TABLE(filing_id uuid, is_valid boolean, error_message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_filing RECORD;
BEGIN
  -- Find filing by token
  SELECT f.id, f.status, f.approval_token_expires_at
  INTO v_filing
  FROM public.filings f
  WHERE f.approval_token = p_token;

  IF NOT FOUND THEN
    RETURN QUERY SELECT NULL::UUID, FALSE, 'Invalid approval token'::TEXT;
    RETURN;
  END IF;

  IF v_filing.approval_token_expires_at < NOW() THEN
    RETURN QUERY SELECT v_filing.id, FALSE, 'Approval token has expired'::TEXT;
    RETURN;
  END IF;

  IF v_filing.status != 'awaiting_approval' THEN
    RETURN QUERY SELECT v_filing.id, FALSE, 'Filing is not awaiting approval'::TEXT;
    RETURN;
  END IF;

  RETURN QUERY SELECT v_filing.id, TRUE, NULL::TEXT;
END;
$$;


--
-- Name: validate_filing_status_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_filing_status_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  valid_transitions jsonb := '{
    "draft": ["in_progress", "ready_for_review"],
    "in_progress": ["ready_for_review", "draft"],
    "ready_for_review": ["approved", "draft", "in_progress"],
    "approved": ["ready_to_file", "draft"],
    "ready_to_file": ["submitted", "approved"],
    "submitted": ["accepted", "rejected", "error"],
    "accepted": [],
    "rejected": ["ready_to_file", "draft"],
    "error": ["ready_to_file", "submitted"],
    "sent_to_client": ["client_approved", "client_rejected", "draft"],
    "client_approved": ["ready_to_file", "submitted"],
    "client_rejected": ["draft", "in_progress"]
  }'::jsonb;
  allowed_next jsonb;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;
  allowed_next := valid_transitions -> COALESCE(OLD.status, 'draft');
  IF allowed_next IS NOT NULL AND jsonb_typeof(allowed_next) = 'array' THEN
    IF NOT (allowed_next ? NEW.status) THEN
      RAISE EXCEPTION 'Invalid filing status transition: % -> % is not allowed', COALESCE(OLD.status, 'draft'), NEW.status;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_filing_submission(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_filing_submission(p_filing_id uuid, p_filing_type text, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_filing RECORD;
  v_approval RECORD;
  v_errors TEXT[] := ARRAY[]::TEXT[];
  v_user_role TEXT;
BEGIN
  -- Get filing
  SELECT * INTO v_filing FROM public.filings WHERE id = p_filing_id;

  IF v_filing.id IS NULL THEN
    RETURN jsonb_build_object('valid', false, 'errors', ARRAY['Filing not found']);
  END IF;

  -- Check user role (must be accountant)
  SELECT role INTO v_user_role 
  FROM public.organization_users 
  WHERE user_id = p_user_id AND organization_id = v_filing.organization_id;

  IF v_user_role NOT IN ('owner', 'admin', 'staff') THEN
    v_errors := array_append(v_errors, 'Only accountants can submit filings');
  END IF;

  -- Check approval exists and is valid
  SELECT * INTO v_approval 
  FROM public.filing_approvals 
  WHERE filing_id = p_filing_id 
    AND approval_scope = CASE WHEN p_filing_type = 'ACCOUNTS_CH' THEN 'ACCOUNTS' ELSE 'CT600' END
    AND revoked_at IS NULL
  ORDER BY approved_at DESC
  LIMIT 1;

  IF v_approval.id IS NULL THEN
    v_errors := array_append(v_errors, 'Approval required before submission');
  ELSE
    -- Verify snapshot hash matches
    IF p_filing_type = 'ACCOUNTS_CH' THEN
      IF v_approval.snapshot_hash != (
        SELECT snapshot_hash FROM public.accounts_model_snapshots WHERE id = v_filing.accounts_snapshot_id
      ) THEN
        v_errors := array_append(v_errors, 'Snapshot hash mismatch - approval invalid');
      END IF;
    ELSE
      IF v_approval.snapshot_hash != (
        SELECT snapshot_hash FROM public.ct_computation_snapshots WHERE id = v_filing.ct_snapshot_id
      ) THEN
        v_errors := array_append(v_errors, 'Snapshot hash mismatch - approval invalid');
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'valid', array_length(v_errors, 1) IS NULL,
    'errors', COALESCE(v_errors, ARRAY[]::TEXT[]),
    'approval_id', v_approval.id
  );
END;
$$;


