--
-- Name: verify_aml(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_aml(p_onboarding_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_onboarding record;
BEGIN
  SELECT * INTO v_onboarding FROM onboarding_applications WHERE id = p_onboarding_id;

  IF v_onboarding.id IS NULL THEN
    RAISE EXCEPTION 'Onboarding application not found';
  END IF;

  IF NOT user_has_organization_access(v_onboarding.organization_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  UPDATE onboarding_applications
  SET 
    aml_status = 'verified',
    aml_verified_at = now(),
    aml_expiry_date = CURRENT_DATE + INTERVAL '5 years'
  WHERE id = p_onboarding_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, old_value, new_value, user_id)
  VALUES (v_onboarding.organization_id, 'onboarding', p_onboarding_id, 'aml_verified', 
    v_onboarding.aml_status, 'verified', auth.uid());

  RETURN jsonb_build_object(
    'success', true,
    'aml_status', 'verified',
    'aml_verified_at', now(),
    'aml_expiry_date', CURRENT_DATE + INTERVAL '5 years'
  );
END;
$$;


--
-- Name: verify_aml_and_approve(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_aml_and_approve(p_onboarding_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_onboarding record;
  v_approval jsonb;
  v_approval_error text;
BEGIN
  SELECT * INTO v_onboarding FROM onboarding_applications WHERE id = p_onboarding_id;
  IF v_onboarding.id IS NULL THEN
    RAISE EXCEPTION 'Onboarding application not found';
  END IF;

  IF NOT user_has_organization_access(v_onboarding.organization_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF v_onboarding.aml_status IS DISTINCT FROM 'verified' THEN
    UPDATE onboarding_applications
    SET aml_status = 'verified',
        aml_verified_at = now(),
        aml_expiry_date = CURRENT_DATE + INTERVAL '5 years'
    WHERE id = p_onboarding_id;

    INSERT INTO audit_log (organization_id, entity_type, entity_id, action, old_value, new_value, user_id)
    VALUES (v_onboarding.organization_id, 'onboarding', p_onboarding_id, 'aml_verified',
      v_onboarding.aml_status, 'verified', auth.uid());
  END IF;

  IF v_onboarding.status IN ('approved', 'rejected') THEN
    RETURN jsonb_build_object(
      'aml_status', 'verified',
      'aml_verified_at', now(),
      'aml_expiry_date', CURRENT_DATE + INTERVAL '5 years',
      'already_finalized', true,
      'status', v_onboarding.status
    );
  END IF;

  BEGIN
    v_approval := public.approve_onboarding_transactional(p_onboarding_id, auth.uid());
  EXCEPTION WHEN OTHERS THEN
    v_approval_error := SQLERRM;
    RETURN jsonb_build_object(
      'aml_status', 'verified',
      'aml_verified_at', now(),
      'aml_expiry_date', CURRENT_DATE + INTERVAL '5 years',
      'approval_error', v_approval_error
    );
  END;

  IF (v_approval->>'blocked')::boolean IS TRUE THEN
    RETURN jsonb_build_object(
      'aml_status', 'verified',
      'aml_verified_at', now(),
      'aml_expiry_date', CURRENT_DATE + INTERVAL '5 years',
      'approval_error', v_approval->>'reason'
    );
  END IF;

  RETURN v_approval
    || jsonb_build_object(
      'aml_status', 'verified',
      'aml_verified_at', now(),
      'aml_expiry_date', CURRENT_DATE + INTERVAL '5 years'
    );
END;
$$;


--
-- Name: void_bill(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_bill(p_bill_id uuid, p_reason text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_bill RECORD;
  v_journal_id uuid;
  v_entries jsonb := '[]'::jsonb;
  v_line RECORD;
  v_post_result jsonb;
  v_entity_type text;
  v_entity_id uuid;
  v_uid uuid := COALESCE(p_user_id, auth.uid());
BEGIN
  SELECT * INTO v_bill FROM bills WHERE id = p_bill_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_found', 'error_message', 'Bill not found');
  END IF;
  IF v_bill.status = 'VOIDED' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'already_voided', 'error_message', 'Bill already voided');
  END IF;
  IF COALESCE(v_bill.amount_paid,0) > 0 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'has_payments', 'error_message', 'Cannot void bill with payments. Refund first.');
  END IF;
  IF NOT (auth.role() = 'service_role'
          OR public.user_in_organization(auth.uid(), v_bill.organization_id)) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_authorized', 'error_message', 'Not authorized for this organization');
  END IF;
  v_uid := CASE WHEN auth.role() = 'service_role' THEN COALESCE(p_user_id, auth.uid()) ELSE auth.uid() END;

  v_entity_type := CASE WHEN v_bill.client_id IS NOT NULL THEN 'client' ELSE 'company' END;
  v_entity_id   := COALESCE(v_bill.client_id, v_bill.company_id);

  IF v_bill.is_posted THEN
    SELECT journal_id INTO v_journal_id FROM ledger_entries
      WHERE source_type = 'BILL' AND source_id = p_bill_id LIMIT 1;

    IF v_journal_id IS NOT NULL THEN
      FOR v_line IN
        SELECT account_id, debit, credit, description, vat_code_id
          FROM ledger_entries WHERE journal_id = v_journal_id
      LOOP
        v_entries := v_entries || jsonb_build_array(jsonb_build_object(
          'account_id', v_line.account_id,
          'debit',  v_line.credit,
          'credit', v_line.debit,
          'description', 'REVERSAL: ' || COALESCE(v_line.description,'') ||
                         CASE WHEN p_reason IS NOT NULL THEN ' - ' || p_reason ELSE '' END,
          'vat_code_id', v_line.vat_code_id
        ));
      END LOOP;

      v_post_result := post_to_ledger(
        p_organization_id := v_bill.organization_id,
        p_client_id       := CASE WHEN v_entity_type='client'  THEN v_entity_id ELSE NULL END,
        p_company_id      := CASE WHEN v_entity_type='company' THEN v_entity_id ELSE NULL END,
        p_journal_date    := CURRENT_DATE,
        p_reference       := 'VOID-' || COALESCE(v_bill.bill_number, substr(p_bill_id::text,1,8)),
        p_description     := 'BILL void',
        p_journal_type    := 'SYSTEM',
        p_source_type     := 'JOURNAL',
        p_source_id       := v_journal_id,
        p_currency        := COALESCE(v_bill.currency,'GBP'),
        p_fx_rate         := 1.0,
        p_created_by      := v_uid,
        p_entries         := v_entries
      );

      IF NOT (v_post_result->>'success')::boolean THEN
        RAISE EXCEPTION 'Reversal failed: %', v_post_result->>'error_message'
          USING ERRCODE = 'P0001';
      END IF;
    END IF;
  END IF;

  UPDATE bills SET status='VOIDED', is_posted=false, updated_at=now() WHERE id = p_bill_id;
  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: void_bill_safe(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_bill_safe(p_bill_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_bill record;
BEGIN
  PERFORM set_config('app.rpc', '1', true);

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_bill FROM bills WHERE id = p_bill_id;
  IF v_bill.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bill not found');
  END IF;

  IF NOT public.user_in_organization(v_user_id, v_bill.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  IF NOT public.user_has_role_at_least(v_user_id, v_bill.organization_id, 'admin') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin role required');
  END IF;

  UPDATE bills SET status = 'VOIDED', void_reason = p_reason, voided_at = now(), voided_by = v_user_id
  WHERE id = p_bill_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, after_state)
  VALUES (v_bill.organization_id, 'bill', p_bill_id, 'voided', v_user_id,
    jsonb_build_object('reason', p_reason));

  RETURN jsonb_build_object('success', true, 'bill_id', p_bill_id);
END;
$$;


