--
-- Name: void_invoice_safe(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_invoice_safe(p_invoice_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_invoice record;
  v_res jsonb;
BEGIN
  PERFORM set_config('app.rpc', '1', true);
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
  END IF;
  IF NOT public.user_in_organization(v_user_id, v_invoice.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;
  IF NOT public.can_void_invoices(v_user_id, v_invoice.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: cannot void invoices');
  END IF;
  v_res := public.void_invoice(p_invoice_id, p_reason, v_user_id);
  IF NOT COALESCE((v_res->>'success')::boolean, false) THEN
    RETURN jsonb_build_object('success', false,
      'error', COALESCE(v_res->>'error_message', v_res->>'error', 'Could not void invoice'));
  END IF;
  RETURN jsonb_build_object('success', true, 'invoice_id', p_invoice_id);
END;
$$;


--
-- Name: write_audit_log(uuid, text, uuid, text, text, text, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.write_audit_log(p_org_id uuid, p_entity_type text, p_entity_id uuid, p_action text, p_field_name text DEFAULT NULL::text, p_old_value text DEFAULT NULL::text, p_new_value text DEFAULT NULL::text, p_before_state jsonb DEFAULT NULL::jsonb, p_after_state jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_audit_id UUID;
  v_user_id UUID;
  v_user_role TEXT;
BEGIN
  v_user_id := auth.uid();

  -- Get user's role in org
  SELECT role INTO v_user_role
  FROM organization_users
  WHERE user_id = v_user_id AND organization_id = p_org_id;

  INSERT INTO audit_log (
    organization_id,
    entity_type,
    entity_id,
    action,
    field_name,
    old_value,
    new_value,
    user_id,
    actor_role,
    before_state,
    after_state,
    metadata
  ) VALUES (
    p_org_id,
    p_entity_type,
    p_entity_id,
    p_action,
    p_field_name,
    p_old_value,
    p_new_value,
    v_user_id,
    v_user_role,
    p_before_state,
    p_after_state,
    p_metadata
  )
  RETURNING id INTO v_audit_id;

  RETURN v_audit_id;
END;
$$;

