-- ---------------------------------------------------------------------------------------
-- VERIFICATION AFTER APPLY — a green pg_cron run is NOT evidence.
-- pg_cron marks a run succeeded when the SQL completes, even if net.http_post returns 401.
-- That is how four legacy jobs failed unnoticed for weeks. Prove delivery instead:
--   SELECT status_code, count(*) FROM net._http_response
--    WHERE created > now() - interval '20 minutes' GROUP BY 1;
-- Expect 2xx only. Any 401 means a credential mismatch — check the Vault secret against the
-- Edge Function environment variable of the same purpose.
-- ---------------------------------------------------------------------------------------

-- 001 — email_queue vocabulary reconciliation and sender classification
-- LONDON ONLY. Source of truth: docs/migration/london-increments/001_email_vocabulary_and_sender_classification.sql
--
-- STATUS: email_queue_status_check permits only pending|sent|failed|cancelled, but
-- queue_email_safe, trigger_records_request(uuid) and acknowledge_failed_email_safe each wrote a
-- value outside it. Every one raised 23514 and rolled back its whole transaction, so Compose
-- Email, records-requests and failure-dismissal were all non-functional. The synonyms are
-- collapsed rather than the constraint widened: widening would convert three loud 23514 errors
-- into three silent never-drains, because the drainer selects on status='pending'. The scheduled
-- synonym duplicates scheduled_at; the dismissal synonym duplicates acknowledged_at/by. A draft is
-- the one genuinely distinct state and is expressed as status='pending' AND scheduled_at IS NULL —
-- the drainer's .lte('scheduled_at', now) never matches NULL, so such a row cannot be sent.
--
-- CONTEXT: process-email-queue routes on it — 'system' goes out through Postmark as AccountancyOS,
-- everything else INCLUDING NULL goes through the practice's mailbox and is HELD if none exists.
-- So an unclassified sender does not fail, it queues mail that never sends. Several senders set no
-- context; one set a value that is not in the constraint at all.

BEGIN;

DO $pre$
DECLARE
  v_status_def text;
  v_context_def text;
BEGIN
  SELECT pg_get_constraintdef(oid) INTO v_status_def
    FROM pg_constraint WHERE conname = 'email_queue_status_check'
     AND conrelid = 'public.email_queue'::regclass;
  IF v_status_def IS NULL THEN
    RAISE EXCEPTION '001: email_queue_status_check is missing';
  END IF;
  IF v_status_def NOT LIKE '%''pending''%' OR v_status_def NOT LIKE '%''sent''%'
     OR v_status_def NOT LIKE '%''failed''%' OR v_status_def NOT LIKE '%''cancelled''%' THEN
    RAISE EXCEPTION '001: email_queue_status_check is not the expected four-value set: %', v_status_def;
  END IF;
  IF v_status_def LIKE '%''draft''%' OR v_status_def LIKE '%''queued''%'
     OR v_status_def LIKE '%''ignored''%' OR v_status_def LIKE '%''held''%' THEN
    RAISE EXCEPTION '001: email_queue_status_check widened out of band (%); reconcile intent first', v_status_def;
  END IF;

  SELECT pg_get_constraintdef(oid) INTO v_context_def
    FROM pg_constraint WHERE conname = 'email_queue_context_check'
     AND conrelid = 'public.email_queue'::regclass;
  IF v_context_def IS NULL THEN
    RAISE EXCEPTION '001: email_queue_context_check is missing; routing depends on it';
  END IF;
  IF v_context_def NOT LIKE '%''system''%' OR v_context_def NOT LIKE '%''general''%'
     OR v_context_def NOT LIKE '%''job''%' OR v_context_def NOT LIKE '%''onboarding''%' THEN
    RAISE EXCEPTION '001: email_queue_context_check is not the expected set: %', v_context_def;
  END IF;
END $pre$;

-- 1. queue_email_safe. DROP + CREATE in one transaction: appending a parameter via CREATE OR
-- REPLACE is rejected by Postgres, and creating the new form alongside the old would leave two
-- overloads resolvable by the same named-argument call (the DEF-002 ambiguity class). All callers
-- pass named arguments via supabase.rpc, so appending is safe.

DROP FUNCTION IF EXISTS public.queue_email_safe(uuid, text, text, text, text, uuid, jsonb, timestamptz, text, uuid);

CREATE FUNCTION public.queue_email_safe(
  p_organization_id uuid,
  p_to_email text,
  p_to_name text DEFAULT NULL::text,
  p_subject text DEFAULT NULL::text,
  p_body_html text DEFAULT NULL::text,
  p_template_id uuid DEFAULT NULL::uuid,
  p_merge_data jsonb DEFAULT '{}'::jsonb,
  p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone,
  p_entity_type text DEFAULT NULL::text,
  p_entity_id uuid DEFAULT NULL::uuid,
  p_context text DEFAULT 'general'::text
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_email_id uuid;
  v_status text;
  v_is_draft boolean;
BEGIN
  PERFORM set_config('app.rpc', '1', true);

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF NOT public.user_in_organization(v_user_id, p_organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  -- Sender identity is a security boundary. This RPC is callable by any authenticated user, and
  -- context='system' is what makes process-email-queue send as AccountancyOS rather than through
  -- the practice's mailbox. Nothing a user composes is AccountancyOS's own mail.
  IF p_context = 'system' THEN
    RETURN jsonb_build_object('success', false, 'error',
      'Invalid context: user-composed email cannot be sent as AccountancyOS system mail');
  END IF;

  IF p_context IS NULL OR p_context NOT IN ('quote','onboarding','engagement','job','invoice','general') THEN
    RETURN jsonb_build_object('success', false, 'error',
      'Invalid context: expected one of quote, onboarding, engagement, job, invoice, general');
  END IF;

  -- A draft is an unscheduled row, not a distinct status. The drainer selects on status='pending'
  -- AND scheduled_at <= now(), and that comparison never matches NULL, so leaving scheduled_at
  -- NULL is what makes a draft unsendable. This previously derived status from a two-value CASE,
  -- neither arm of which email_queue_status_check permits, so every call raised 23514.
  v_status := 'pending';
  v_is_draft := (p_scheduled_at IS NULL);

  INSERT INTO email_queue (
    organization_id, to_email, to_name, subject, body_html, template_id,
    merge_data, scheduled_at, status, entity_type, entity_id, created_by, context
  ) VALUES (
    p_organization_id, p_to_email, p_to_name, p_subject, p_body_html, p_template_id,
    p_merge_data, p_scheduled_at, v_status, p_entity_type, p_entity_id, v_user_id, p_context
  ) RETURNING id INTO v_email_id;

  -- NOTE: the action below is an audit_log.action value, NOT an email_queue.status value. Same
  -- word, different vocabulary, different column. Do not "fix" it to match the status set.
  INSERT INTO audit_log (organization_id, user_id, entity_type, entity_id, action, after_state)
  VALUES (p_organization_id, v_user_id, 'email', v_email_id, 'queued',
    jsonb_build_object('status', v_status, 'to_email', p_to_email, 'context', p_context,
                       'is_draft', v_is_draft));

  RETURN jsonb_build_object('success', true, 'email_id', v_email_id, 'status', v_status,
                            'is_draft', v_is_draft, 'context', p_context);
END;
$function$;

ALTER FUNCTION public.queue_email_safe(uuid, text, text, text, text, uuid, jsonb, timestamptz, text, uuid, text)
  OWNER TO postgres;

-- DROP takes the ACL with it. DELIBERATE NARROWING: the previous ACL also granted EXECUTE to
-- PUBLIC and anon. Those are not re-granted; the function's first act is to reject a NULL
-- auth.uid(), so no anonymous caller could ever succeed. Restore with GRANT ... TO PUBLIC if this
-- turns out to be load-bearing.
GRANT EXECUTE ON FUNCTION public.queue_email_safe(uuid, text, text, text, text, uuid, jsonb, timestamptz, text, uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.queue_email_safe(uuid, text, text, text, text, uuid, jsonb, timestamptz, text, uuid, text) TO service_role;

-- 2. Small functions, replaced in full.

-- The retired dismissal value is not permitted. 'cancelled' carries the same meaning; that it was
-- a dismissal of a failure is already recorded by acknowledged_at/acknowledged_by.
CREATE OR REPLACE FUNCTION public.acknowledge_failed_email_safe(p_email_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_email RECORD;
  v_org_id UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_email FROM email_queue WHERE id = p_email_id;
  IF v_email.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Email not found');
  END IF;

  v_org_id := v_email.organization_id;
  IF NOT user_has_role_at_least(v_user_id, v_org_id, 'manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: manager+ required');
  END IF;

  IF v_email.status != 'failed' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Can only acknowledge failed emails');
  END IF;

  UPDATE email_queue SET
    status = 'cancelled',
    acknowledged_at = now(),
    acknowledged_by = v_user_id,
    updated_at = now()
  WHERE id = p_email_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
  VALUES (v_org_id, 'email', p_email_id, 'acknowledged_failure', v_user_id,
    jsonb_build_object('last_error', v_email.last_error_message));

  RETURN jsonb_build_object('success', true, 'email_id', p_email_id);
END;
$function$;

-- The retired scheduled synonym can no longer exist. The scheduled_at > now() predicate is left as
-- is, deliberately: it excludes NULL, which is what stops a flush sweeping drafts into the outbox.
CREATE OR REPLACE FUNCTION public.flush_email_queue_now(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_count integer;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  IF NOT public.user_in_organization(v_user_id, p_organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;
  UPDATE public.email_queue
     SET scheduled_at = now(),
         updated_at = now()
   WHERE organization_id = p_organization_id
     AND status = 'pending'
     AND scheduled_at > now();
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('success', true, 'flushed', v_count);
END;
$function$;

-- Same dead-value cleanup. This one DOES legitimately promote a draft: setting scheduled_at = now()
-- on a row whose scheduled_at was NULL is exactly the send-this-now action.
CREATE OR REPLACE FUNCTION public.send_queued_email_now(p_email_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_org uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  SELECT organization_id INTO v_org FROM public.email_queue WHERE id = p_email_id;
  IF v_org IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Email not found');
  END IF;
  IF NOT public.user_in_organization(v_user_id, v_org) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;
  UPDATE public.email_queue
     SET scheduled_at = now(),
         status = CASE WHEN status IN ('pending','failed') THEN 'pending' ELSE status END,
         error_message = NULL,
         updated_at = now()
   WHERE id = p_email_id;
  RETURN jsonb_build_object('success', true, 'email_id', p_email_id);
END;
$function$;

-- A draft is a pending row with a NULL scheduled_at, so gating on status='pending' keeps drafts
-- editable, which is what the original three-value list was reaching for.
CREATE OR REPLACE FUNCTION public.update_queued_email_safe(p_email_id uuid, p_subject text DEFAULT NULL::text, p_body_html text DEFAULT NULL::text, p_to_email text DEFAULT NULL::text, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_email RECORD;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_email FROM email_queue WHERE id = p_email_id;
  IF v_email.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Email not found');
  END IF;

  IF NOT user_in_organization(v_user_id, v_email.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  IF v_email.status <> 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Can only edit unsent emails');
  END IF;

  UPDATE email_queue SET
    subject = COALESCE(p_subject, subject),
    body_html = COALESCE(p_body_html, body_html),
    to_email = COALESCE(p_to_email, to_email),
    scheduled_at = COALESCE(p_scheduled_at, scheduled_at),
    updated_at = now()
  WHERE id = p_email_id;

  RETURN jsonb_build_object('success', true, 'email_id', p_email_id);
END;
$function$;

-- Recipients here are the practice's own staff (organization_users joined to auth.users, at their
-- AccountancyOS login address, body says 'Please review in AccountancyOS'). That is the platform
-- notifying its users, which is what 'system' is reserved for. Left as 'onboarding' it would route
-- through the practice's mailbox and be HELD whenever none is connected — which is exactly the
-- state a practice is most likely to be in during onboarding.
CREATE OR REPLACE FUNCTION public.public_submit_onboarding_for_review(p_application_id uuid, p_portal_email text, p_access_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
  v_org_name text;
  v_member record;
  v_client_name text;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id FOR UPDATE;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);
  IF v_app.status = 'for_review' THEN
    RETURN jsonb_build_object('status','for_review','already', true);
  END IF;

  UPDATE public.onboarding_applications
     SET status = 'for_review',
         portal_email = COALESCE(p_portal_email, portal_email),
         submitted_for_review_at = now(),
         updated_at = now()
   WHERE id = p_application_id;

  SELECT name INTO v_org_name FROM public.organizations WHERE id = v_app.organization_id;
  v_client_name := COALESCE(v_app.company_name,
    NULLIF(trim(coalesce(v_app.first_name,'') || ' ' || coalesce(v_app.last_name,'')), ''),
    v_app.email, 'New onboarding');

  FOR v_member IN
    SELECT user_id FROM public.organization_users WHERE organization_id = v_app.organization_id
  LOOP
    INSERT INTO public.notifications (
      organization_id, user_id, type, title, message, entity_type, entity_id
    ) VALUES (
      v_app.organization_id, v_member.user_id, 'onboarding_for_review',
      'New onboarding ready for review',
      v_client_name || ' has completed onboarding and is ready for review.',
      'onboarding_application', p_application_id
    );
  END LOOP;

  INSERT INTO public.email_queue (
    organization_id, to_email, to_name, subject, body_html, status, context, entity_type, entity_id
  )
  SELECT v_app.organization_id,
         u.email,
         COALESCE(u.raw_user_meta_data->>'full_name', u.email),
         'Onboarding ready for review: ' || v_client_name,
         '<p>' || v_client_name || ' has completed the onboarding wizard.</p>' ||
         '<p>Please review in AccountancyOS.</p>',
         'pending', 'system', 'onboarding_application', p_application_id
    FROM public.organization_users om
    JOIN auth.users u ON u.id = om.user_id
   WHERE om.organization_id = v_app.organization_id
     AND om.role = 'owner'
     AND u.email IS NOT NULL;

  RETURN jsonb_build_object('status','for_review','already', false);
END;
$function$;

-- 3. Large bodies (2.6 KB, 3.9 KB, 17.9 KB) — surgical text edits. Each reads the live definition,
-- asserts its anchor appears exactly once, rewrites that span only, and re-executes. A body that
-- has drifted fails loudly rather than being half-edited.

-- 3a. send_onboarding_questionnaire -> 'onboarding' (recipient is the onboarding applicant).
DO $mig$
DECLARE
  v_def text;
  v_new text;
  v_cols_from text := $a$    entity_type, entity_id, merge_data, status
  )$a$;
  v_cols_to text := $a$    entity_type, entity_id, merge_data, status, context
  )$a$;
  v_vals_from text := $a$    'pending'
  );$a$;
  v_vals_to text := $a$    'pending',
    'onboarding'
  );$a$;
  v_hits int;
BEGIN
  v_def := pg_get_functiondef('public.send_onboarding_questionnaire(uuid,uuid)'::regprocedure);

  IF position(v_cols_to in v_def) > 0 THEN
    RAISE NOTICE '001/3a: already classified; skipping';
    RETURN;
  END IF;

  v_hits := (length(v_def) - length(replace(v_def, v_cols_from, ''))) / length(v_cols_from);
  IF v_hits <> 1 THEN
    RAISE EXCEPTION '001/3a: expected 1 match for the column list, found %', v_hits;
  END IF;
  v_hits := (length(v_def) - length(replace(v_def, v_vals_from, ''))) / length(v_vals_from);
  IF v_hits <> 1 THEN
    RAISE EXCEPTION '001/3a: expected 1 match for the VALUES tail, found %', v_hits;
  END IF;

  v_new := replace(v_def, v_cols_from, v_cols_to);
  v_new := replace(v_new, v_vals_from, v_vals_to);
  EXECUTE v_new;
END $mig$;

-- 3b. lifecycle_approve_onboarding -> 'job'. The queued email is an information request tied to a
-- job (it already writes entity_type='job', entity_id=v_job_id), addressed to the applicant.
DO $mig$
DECLARE
  v_def text;
  v_new text;
  v_cols_from text := $a$            merge_data, status
          )
          SELECT$a$;
  v_cols_to text := $a$            merge_data, status, context
          )
          SELECT$a$;
  v_vals_from text := $a$            'pending'
          FROM templates t$a$;
  v_vals_to text := $a$            'pending',
            'job'
          FROM templates t$a$;
  v_hits int;
BEGIN
  v_def := pg_get_functiondef('public.lifecycle_approve_onboarding(uuid)'::regprocedure);

  IF position(v_cols_to in v_def) > 0 THEN
    RAISE NOTICE '001/3b: already classified; skipping';
    RETURN;
  END IF;

  v_hits := (length(v_def) - length(replace(v_def, v_cols_from, ''))) / length(v_cols_from);
  IF v_hits <> 1 THEN
    RAISE EXCEPTION '001/3b: expected 1 match for the column list, found %', v_hits;
  END IF;
  v_hits := (length(v_def) - length(replace(v_def, v_vals_from, ''))) / length(v_vals_from);
  IF v_hits <> 1 THEN
    RAISE EXCEPTION '001/3b: expected 1 match for the SELECT tail, found %', v_hits;
  END IF;

  v_new := replace(v_def, v_cols_from, v_cols_to);
  v_new := replace(v_new, v_vals_from, v_vals_to);
  EXECUTE v_new;
END $mig$;

-- 3c. trigger_records_request(uuid): two violations in one INSERT — a retired status value, and a
-- context value that is not in email_queue_context_check at all. That context literal appears
-- TWICE in the body; the first is job_questionnaire_instances.questionnaire_type, a different
-- column on a different table with its own vocabulary, which MUST NOT change. Only the email_queue
-- context is rewritten, which is why the anchor carries its neighbouring lines rather than matching
-- the bare literal. The 2-arg overload is already correct and is left alone.
DO $mig$
DECLARE
  v_def text;
  v_new text;
  v_ctx_from text := $a$    v_job.company_id,
    'records_request',$a$;
  v_ctx_to text := $a$    v_job.company_id,
    'job',$a$;
  v_status_from text := $a$    'queued',
    'questionnaire',$a$;
  v_status_to text := $a$    'pending',
    'questionnaire',$a$;
  v_keep text := $a$    'records_request',
    'awaiting_info',$a$;
  v_hits int;
BEGIN
  v_def := pg_get_functiondef('public.trigger_records_request(uuid)'::regprocedure);

  IF position(v_ctx_to in v_def) > 0 AND position(v_status_to in v_def) > 0 THEN
    RAISE NOTICE '001/3c: already corrected; skipping';
    RETURN;
  END IF;

  v_hits := (length(v_def) - length(replace(v_def, v_ctx_from, ''))) / length(v_ctx_from);
  IF v_hits <> 1 THEN
    RAISE EXCEPTION '001/3c: expected 1 match for the context anchor, found % — refusing to touch the questionnaire_type literal', v_hits;
  END IF;
  v_hits := (length(v_def) - length(replace(v_def, v_status_from, ''))) / length(v_status_from);
  IF v_hits <> 1 THEN
    RAISE EXCEPTION '001/3c: expected 1 match for the status anchor, found %', v_hits;
  END IF;

  v_new := replace(v_def, v_ctx_from, v_ctx_to);
  v_new := replace(v_new, v_status_from, v_status_to);

  v_hits := (length(v_new) - length(replace(v_new, v_keep, ''))) / length(v_keep);
  IF v_hits <> 1 THEN
    RAISE EXCEPTION '001/3c: the questionnaire_type literal was damaged (found %, expected 1)', v_hits;
  END IF;
  v_hits := (length(v_new) - length(replace(v_new, $a$'records_request'$a$, ''))) / length($a$'records_request'$a$);
  IF v_hits <> 1 THEN
    RAISE EXCEPTION '001/3c: expected exactly 1 remaining records_request literal, found %', v_hits;
  END IF;

  EXECUTE v_new;
END $mig$;

-- POST-ASSERTIONS

DO $post$
DECLARE
  v_bad text;
  v_nargs int;
  v_qes text;
BEGIN
  -- Targeted rather than a blanket scan: a blanket search across everything touching email_queue
  -- would false-positive on lifecycle_send_quote, which legitimately uses the same word for the
  -- QUOTES table's own status vocabulary.
  --
  -- queue_email_safe is deliberately NOT in this list either. It legitimately writes the word as
  -- an audit_log.action value — a different column with a different vocabulary — so a body-wide
  -- grep would false-positive on it too. It gets a precise assertion below instead.
  FOR v_bad IN
    SELECT sig FROM (VALUES
      ('public.flush_email_queue_now(uuid)'),
      ('public.send_queued_email_now(uuid)'),
      ('public.update_queued_email_safe(uuid,text,text,text,timestamptz)')
    ) AS t(sig)
  LOOP
    IF pg_get_functiondef(v_bad::regprocedure) LIKE '%''queued''%'
       OR pg_get_functiondef(v_bad::regprocedure) LIKE '%''draft''%' THEN
      RAISE EXCEPTION '001: % still carries a retired status literal', v_bad;
    END IF;
  END LOOP;

  SELECT pg_get_functiondef(p.oid) INTO v_qes
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public' AND p.proname = 'queue_email_safe';

  IF v_qes NOT LIKE '%v_status := ''pending'';%' THEN
    RAISE EXCEPTION '001: queue_email_safe does not assign the canonical pending status';
  END IF;
  IF v_qes LIKE '%v_status := CASE%' THEN
    RAISE EXCEPTION '001: queue_email_safe still derives its status from the retired two-value CASE';
  END IF;

  IF pg_get_functiondef('public.acknowledge_failed_email_safe(uuid)'::regprocedure) LIKE '%''ignored''%' THEN
    RAISE EXCEPTION '001: acknowledge_failed_email_safe still writes the retired dismissal value';
  END IF;

  IF pg_get_functiondef('public.trigger_records_request(uuid)'::regprocedure) LIKE '%company_id,
    ''records_request'',%' THEN
    RAISE EXCEPTION '001: trigger_records_request(uuid) still sets an invalid email_queue.context';
  END IF;
  IF (length(pg_get_functiondef('public.trigger_records_request(uuid)'::regprocedure))
      - length(replace(pg_get_functiondef('public.trigger_records_request(uuid)'::regprocedure), '''records_request''', '')))
     / length('''records_request''') <> 1 THEN
    RAISE EXCEPTION '001: trigger_records_request(uuid) should retain exactly one questionnaire_type literal';
  END IF;

  IF pg_get_functiondef('public.send_onboarding_questionnaire(uuid,uuid)'::regprocedure) NOT LIKE '%merge_data, status, context%' THEN
    RAISE EXCEPTION '001: send_onboarding_questionnaire still sets no context';
  END IF;
  IF pg_get_functiondef('public.lifecycle_approve_onboarding(uuid)'::regprocedure) NOT LIKE '%merge_data, status, context%' THEN
    RAISE EXCEPTION '001: lifecycle_approve_onboarding still sets no context';
  END IF;

  -- The anchor guards prove the right SPAN was rewritten, not that it was rewritten with the right
  -- TEXT. A mistyped literal would satisfy every check so far and fail at 23514 months later.
  IF pg_get_functiondef('public.lifecycle_approve_onboarding(uuid)'::regprocedure) NOT LIKE '%''pending'',
            ''job''
          FROM templates t%' THEN
    RAISE EXCEPTION '001: lifecycle_approve_onboarding context value is not the expected job';
  END IF;
  IF pg_get_functiondef('public.send_onboarding_questionnaire(uuid,uuid)'::regprocedure) NOT LIKE '%''pending'',
    ''onboarding''
  );%' THEN
    RAISE EXCEPTION '001: send_onboarding_questionnaire context value is not the expected onboarding';
  END IF;
  IF pg_get_functiondef('public.trigger_records_request(uuid)'::regprocedure) NOT LIKE '%company_id,
    ''job'',%' THEN
    RAISE EXCEPTION '001: trigger_records_request(uuid) context value is not the expected job';
  END IF;

  IF pg_get_functiondef('public.public_submit_onboarding_for_review(uuid,text,text)'::regprocedure) NOT LIKE '%''pending'', ''system''%' THEN
    RAISE EXCEPTION '001: public_submit_onboarding_for_review was not reclassified to system';
  END IF;

  SELECT count(*) INTO v_nargs FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public' AND p.proname = 'queue_email_safe';
  IF v_nargs <> 1 THEN
    RAISE EXCEPTION '001: expected exactly 1 queue_email_safe overload, found % — ambiguity risk', v_nargs;
  END IF;
  SELECT p.pronargs INTO v_nargs FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public' AND p.proname = 'queue_email_safe';
  IF v_nargs <> 11 THEN
    RAISE EXCEPTION '001: queue_email_safe has % arguments, expected 11', v_nargs;
  END IF;
  IF v_qes NOT LIKE '%user-composed email cannot be sent as AccountancyOS system mail%' THEN
    RAISE EXCEPTION '001: queue_email_safe is missing the system-context guard';
  END IF;

  IF NOT has_function_privilege('authenticated',
       (SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
         WHERE n.nspname='public' AND p.proname='queue_email_safe'), 'EXECUTE') THEN
    RAISE EXCEPTION '001: authenticated lost EXECUTE on queue_email_safe';
  END IF;
  IF NOT has_function_privilege('service_role',
       (SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
         WHERE n.nspname='public' AND p.proname='queue_email_safe'), 'EXECUTE') THEN
    RAISE EXCEPTION '001: service_role lost EXECUTE on queue_email_safe';
  END IF;
END $post$;

COMMIT;

-- 002 — make the sender-identity boundary real at the database layer
-- LONDON ONLY. Source: docs/migration/london-increments/002_sender_identity_enforcement.sql
--
-- Hard prerequisite for deploying the rewritten drainer.
--
-- 1. RLS does not constrain `context`, so increment 001's RPC guard is bypassable: `authenticated`
--    holds a direct INSERT grant and the policy checks only organization_id. Any member can
--    PostgREST-insert context='system' and skip the RPC. UPDATE too — insert 'general', update to
--    'system' — so both policies must be fixed or the gap just moves. Inert today because the
--    deployed worker has no Postmark path; a live send-as-AccountancyOS hole the moment it ships.
--
-- 2. claim_email_queue_row does not return `context`. The rewritten drainer routes on the CLAIMED
--    row, so context would be undefined for every message, isSystemEmail() false universally, and
--    all system mail silently HELD forever with no error anywhere.
--
-- Verified live: service_role/postgres rolbypassrls=true, authenticated/anon false,
-- email_queue relrowsecurity=true. So this removes an attacker's path to 'system' without
-- removing any legitimate one (the drainer is service_role; SECURITY DEFINER senders are postgres).
-- `IS DISTINCT FROM` not `<>`: NULL context is the ordinary client-mail default and must stay
-- insertable.

BEGIN;

DO $pre$
DECLARE
  v_bypass boolean;
  v_rls boolean;
  v_system_rows bigint;
BEGIN
  SELECT rolbypassrls INTO v_bypass FROM pg_roles WHERE rolname = 'service_role';
  IF v_bypass IS DISTINCT FROM true THEN
    RAISE EXCEPTION '002: service_role does not bypass RLS; tightening these policies would break the drainer';
  END IF;

  SELECT relrowsecurity INTO v_rls FROM pg_class WHERE oid = 'public.email_queue'::regclass;
  IF v_rls IS DISTINCT FROM true THEN
    RAISE EXCEPTION '002: RLS is not enabled on email_queue; a policy change would be decorative';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_policy WHERE polrelid = 'public.email_queue'::regclass
                  AND polname = 'email_queue_insert_org') THEN
    RAISE EXCEPTION '002: email_queue_insert_org is missing; refusing to guess the intended policy set';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policy WHERE polrelid = 'public.email_queue'::regclass
                  AND polname = 'email_queue_update_org') THEN
    RAISE EXCEPTION '002: email_queue_update_org is missing; refusing to guess the intended policy set';
  END IF;

  SELECT count(*) INTO v_system_rows FROM public.email_queue WHERE context = 'system';
  IF v_system_rows > 0 THEN
    RAISE NOTICE '002: % existing row(s) carry context=system — review provenance; they predate this guard', v_system_rows;
  END IF;
END $pre$;

-- 1. Constrain `context` in the authenticated RLS policies.

DROP POLICY IF EXISTS email_queue_insert_org ON public.email_queue;
CREATE POLICY email_queue_insert_org ON public.email_queue
  FOR INSERT TO authenticated
  WITH CHECK (
    user_has_organization_access(organization_id)
    -- context='system' makes process-email-queue send through Postmark AS AccountancyOS rather
    -- than through the practice's own mailbox. That is a sender-identity decision, and it is not
    -- a user's to make. Only service_role and SECURITY DEFINER functions (both bypass RLS) may.
    AND context IS DISTINCT FROM 'system'
  );

DROP POLICY IF EXISTS email_queue_update_org ON public.email_queue;
CREATE POLICY email_queue_update_org ON public.email_queue
  FOR UPDATE TO authenticated
  USING (user_has_organization_access(organization_id))
  WITH CHECK (
    user_has_organization_access(organization_id)
    -- Without this the guard above is trivially defeated: insert 'general', then update to
    -- 'system'. WITH CHECK governs the post-update row, which is what has to be constrained.
    AND context IS DISTINCT FROM 'system'
  );

-- 2. Return `context` (and the back-off inputs) from the claim RPC.
-- CREATE OR REPLACE cannot change a return type, so DROP + CREATE inside the transaction.

DROP FUNCTION IF EXISTS public.claim_email_queue_row(uuid, timestamptz);

CREATE FUNCTION public.claim_email_queue_row(p_email_id uuid, p_stale_before timestamp with time zone)
 RETURNS TABLE(
   id uuid,
   organization_id uuid,
   to_email text,
   to_name text,
   subject text,
   body_html text,
   body_text text,
   mailbox_id uuid,
   provider text,
   created_by uuid,
   attachments jsonb,
   context text,
   retry_count integer,
   entity_type text,
   entity_id uuid
 )
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  UPDATE public.email_queue q
     SET claimed_at = now(),
         updated_at = now()
   WHERE q.id = p_email_id
     AND q.status = 'pending'
     AND (q.claimed_at IS NULL OR q.claimed_at < p_stale_before)
  RETURNING
     q.id,
     q.organization_id,
     q.to_email,
     q.to_name,
     q.subject,
     q.body_html,
     q.body_text,
     q.mailbox_id,
     q.provider,
     q.created_by,
     q.attachments,
     -- The routing decision. Absent from the previous return shape, which would have made the
     -- rewritten drainer treat every message as non-system and hold all auth mail, silently.
     q.context,
     -- COALESCEd because the column is nullable: the drainer does arithmetic on this for the hold
     -- back-off, and NULL would propagate to NaN rather than failing loudly.
     COALESCE(q.retry_count, 0),
     q.entity_type,
     q.entity_id;
END;
$function$;

ALTER FUNCTION public.claim_email_queue_row(uuid, timestamptz) OWNER TO postgres;

-- Claiming a queue row is a worker operation; an authenticated user able to claim could stall or
-- steal sends, and no user-facing path needs it. Explicit REVOKE, not narrowing by omission:
-- Supabase default privileges re-grant PUBLIC/anon/authenticated on CREATE (learned in 001).
REVOKE EXECUTE ON FUNCTION public.claim_email_queue_row(uuid, timestamptz) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.claim_email_queue_row(uuid, timestamptz) FROM anon;
REVOKE EXECUTE ON FUNCTION public.claim_email_queue_row(uuid, timestamptz) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.claim_email_queue_row(uuid, timestamptz) TO service_role;

DO $post$
DECLARE
  v_check text;
  v_cols text;
BEGIN
  SELECT pg_get_expr(polwithcheck, polrelid) INTO v_check
    FROM pg_policy WHERE polrelid = 'public.email_queue'::regclass
     AND polname = 'email_queue_insert_org';
  IF v_check IS NULL OR v_check NOT LIKE '%context%' THEN
    RAISE EXCEPTION '002: insert policy does not constrain context: %', v_check;
  END IF;

  SELECT pg_get_expr(polwithcheck, polrelid) INTO v_check
    FROM pg_policy WHERE polrelid = 'public.email_queue'::regclass
     AND polname = 'email_queue_update_org';
  IF v_check IS NULL OR v_check NOT LIKE '%context%' THEN
    RAISE EXCEPTION '002: update policy WITH CHECK does not constrain context: %', v_check;
  END IF;

  SELECT pg_get_function_result('public.claim_email_queue_row(uuid,timestamptz)'::regprocedure)
    INTO v_cols;
  IF v_cols NOT LIKE '%context text%' THEN
    RAISE EXCEPTION '002: claim_email_queue_row does not return context — the drainer would hold all system mail silently. Got: %', v_cols;
  END IF;
  IF v_cols NOT LIKE '%retry_count integer%' THEN
    RAISE EXCEPTION '002: claim_email_queue_row does not return retry_count: %', v_cols;
  END IF;

  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname = 'public' AND p.proname = 'claim_email_queue_row') <> 1 THEN
    RAISE EXCEPTION '002: expected exactly 1 claim_email_queue_row overload — ambiguity risk';
  END IF;

  IF NOT has_function_privilege('service_role',
       'public.claim_email_queue_row(uuid,timestamptz)'::regprocedure, 'EXECUTE') THEN
    RAISE EXCEPTION '002: service_role lost EXECUTE on claim_email_queue_row';
  END IF;
  IF has_function_privilege('authenticated',
       'public.claim_email_queue_row(uuid,timestamptz)'::regprocedure, 'EXECUTE') THEN
    RAISE EXCEPTION '002: authenticated still holds EXECUTE on claim_email_queue_row';
  END IF;
END $post$;

COMMIT;

-- 003 — email_send_log.status must accept 'rate_limited'
-- LONDON ONLY. Source: docs/migration/london-increments/003_email_send_log_rate_limited.sql
--
-- process-email-queue records a rate-limited send as status='rate_limited', but
-- email_send_log_status_check permitted only pending|sent|suppressed|failed|bounced|complained|dlq,
-- so the insert was rejected with 23514. The worker discards that insert's error return, so every
-- rate-limit event was recorded nowhere. The cooldown was still set, which is what made it
-- invisible: rate-limited sends simply vanished from the log rather than failing loudly.
--
-- Not reusing 'failed': the retry budget COUNTS rows with status='failed', so logging a rate limit
-- as failed would make provider back-pressure consume the budget and walk authentication email
-- into the DLQ. A rate limit is "not now", not "this failed".
--
-- This is the one place the programme deliberately WIDENS a status vocabulary, and it does not
-- contradict increment 001, which collapsed synonyms. The test is whether the value names a
-- genuinely distinct state: 'queued' duplicated 'pending' and 'ignored' duplicated 'cancelled',
-- but 'rate_limited' duplicates nothing — it is the only state that must be recorded WITHOUT
-- counting toward the retry budget.
--
-- PROVENANCE: the constraint change was applied to London on 2026-09-02 via execute_sql, which
-- leaves no row in supabase_migrations.schema_migrations, so London carried a schema change its
-- own provenance did not record. This is that change re-filed under the convention and made
-- IDEMPOTENT so it can be applied through apply_migration to record the missing ledger row. It
-- verifies the end state either way: if the value is already permitted it skips the ALTER and
-- still runs every post-assertion including the behavioural probe, so a green apply proves the
-- live state is correct regardless of which path it took.
--
-- ROLLBACK
--   BEGIN;
--   ALTER TABLE public.email_send_log DROP CONSTRAINT email_send_log_status_check;
--   ALTER TABLE public.email_send_log ADD CONSTRAINT email_send_log_status_check
--     CHECK (status = ANY (ARRAY['pending','sent','suppressed','failed','bounced','complained','dlq']));
--   COMMIT;
-- Safe only while no row holds status='rate_limited'.

BEGIN;

DO $pre$
DECLARE
  v_count int;
  v_def text;
  v_value text;
BEGIN
  IF to_regclass('public.email_send_log') IS NULL THEN
    RAISE EXCEPTION '003: public.email_send_log does not exist';
  END IF;

  SELECT count(*) INTO v_count
    FROM pg_constraint
   WHERE conrelid = 'public.email_send_log'::regclass
     AND contype = 'c'
     AND pg_get_constraintdef(oid) ILIKE '%status%';
  IF v_count <> 1 THEN
    RAISE EXCEPTION '003: expected exactly 1 check constraint governing email_send_log.status, found %', v_count;
  END IF;

  SELECT pg_get_constraintdef(oid) INTO v_def
    FROM pg_constraint
   WHERE conrelid = 'public.email_send_log'::regclass
     AND conname = 'email_send_log_status_check';
  IF v_def IS NULL THEN
    RAISE EXCEPTION '003: email_send_log_status_check not found';
  END IF;

  FOREACH v_value IN ARRAY ARRAY['pending','sent','suppressed','failed','bounced','complained','dlq'] LOOP
    IF v_def NOT ILIKE '%' || v_value || '%' THEN
      RAISE EXCEPTION '003: existing constraint does not permit baseline value %', v_value;
    END IF;
  END LOOP;
END $pre$;

DO $mig$
DECLARE
  v_def text;
BEGIN
  SELECT pg_get_constraintdef(oid) INTO v_def
    FROM pg_constraint
   WHERE conrelid = 'public.email_send_log'::regclass
     AND conname = 'email_send_log_status_check';

  IF v_def ILIKE '%rate_limited%' THEN
    RAISE NOTICE '003: rate_limited already permitted; skipping the ALTER and verifying the end state';
    RETURN;
  END IF;

  ALTER TABLE public.email_send_log DROP CONSTRAINT email_send_log_status_check;
  ALTER TABLE public.email_send_log ADD CONSTRAINT email_send_log_status_check
    CHECK (status = ANY (ARRAY[
      'pending'::text,
      'sent'::text,
      'suppressed'::text,
      'failed'::text,
      'bounced'::text,
      'complained'::text,
      'dlq'::text,
      'rate_limited'::text
    ]));
END $mig$;

DO $post$
DECLARE
  v_count int;
  v_def text;
  v_probe_id uuid;
  v_value text;
BEGIN
  SELECT count(*) INTO v_count
    FROM pg_constraint
   WHERE conrelid = 'public.email_send_log'::regclass
     AND contype = 'c'
     AND pg_get_constraintdef(oid) ILIKE '%status%';
  IF v_count <> 1 THEN
    RAISE EXCEPTION '003: expected exactly 1 status check constraint after migration, found %', v_count;
  END IF;

  SELECT pg_get_constraintdef(oid) INTO v_def
    FROM pg_constraint
   WHERE conrelid = 'public.email_send_log'::regclass
     AND conname = 'email_send_log_status_check';
  IF v_def IS NULL THEN
    RAISE EXCEPTION '003: email_send_log_status_check is absent after replacement';
  END IF;

  FOREACH v_value IN ARRAY ARRAY[
    'pending','sent','suppressed','failed','bounced','complained','dlq','rate_limited'
  ] LOOP
    IF v_def NOT ILIKE '%' || v_value || '%' THEN
      RAISE EXCEPTION '003: constraint does not permit %', v_value;
    END IF;
  END LOOP;

  -- Behavioural proof, not merely structural: insert a real row, read it back, remove it, all
  -- inside this transaction.
  INSERT INTO public.email_send_log (message_id, template_name, recipient_email, status, error_message)
  VALUES (
    gen_random_uuid()::text,
    'migration_003_probe',
    'probe@migration-003.invalid',
    'rate_limited',
    'Post-assert probe for London increment 003; deleted in the same transaction.'
  )
  RETURNING id INTO v_probe_id;

  IF v_probe_id IS NULL THEN
    RAISE EXCEPTION '003: rate_limited probe insert returned no id';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.email_send_log WHERE id = v_probe_id AND status = 'rate_limited') THEN
    RAISE EXCEPTION '003: rate_limited probe row not readable back';
  END IF;

  DELETE FROM public.email_send_log WHERE id = v_probe_id;
  IF EXISTS (SELECT 1 FROM public.email_send_log WHERE id = v_probe_id) THEN
    RAISE EXCEPTION '003: probe row could not be removed';
  END IF;

  -- ...and the constraint must still REJECT an unknown value. A CHECK accepting everything would
  -- satisfy every assertion above.
  BEGIN
    INSERT INTO public.email_send_log (message_id, template_name, recipient_email, status)
    VALUES (gen_random_uuid()::text, 'migration_003_probe', 'probe@migration-003.invalid', 'not_a_real_status');
    RAISE EXCEPTION '003: constraint accepted an invalid status value';
  EXCEPTION
    WHEN check_violation THEN
      NULL; -- expected
  END;
END $post$;

COMMIT;

-- 004 — protect system rows that already exist, and remove two standing over-grants
-- LONDON ONLY. Source: docs/migration/london-increments/004_protect_existing_system_rows.sql
--
-- Increment 002 stopped an authenticated user CREATING a context='system' row via WITH CHECK on
-- the insert and update policies. It did not close the other half: both USING clauses are still
-- organisation-only, and USING decides which EXISTING rows a statement may touch. So a member can
-- still DELETE a pending system email outright, or UPDATE one — rewriting it to 'general' passes
-- the new WITH CHECK, because the post-update row is no longer 'system'.
--
-- The attack this enables is not a forged send; it is SUPPRESSION OF THE WARNING. Held-email
-- escalation alerts are system mail. An attacker who disconnects a practice's mailbox could then
-- delete the very notification telling the practice it happened, and the queue would fill
-- silently — the exact failure mode the escalation design exists to prevent.
--
-- Also removes two over-grants: queue_email_safe's PUBLIC/anon EXECUTE (observed in 001 and
-- deliberately deferred to its own reviewed change — this is it; the grant is inert because the
-- function returns 'Not authenticated' on a null auth.uid(), so only the error shape changes), and
-- email_queue.retry_count's nullability (002 had to COALESCE it to stop NULL becoming NaN in the
-- hold back-off; forbidding the NULL beats defending against it).
--
-- Verified before authoring: service_role/postgres carry rolbypassrls, so none of this constrains
-- the drainer or the SECURITY DEFINER senders — retry_failed_email_safe and
-- acknowledge_failed_email_safe keep working. SELECT is deliberately NOT restricted: visibility of
-- a system row is not the threat, modification is, and hiding them would break the Emails list.

BEGIN;

DO $pre$
DECLARE
  v_bypass boolean;
  v_using text;
BEGIN
  SELECT rolbypassrls INTO v_bypass FROM pg_roles WHERE rolname = 'service_role';
  IF v_bypass IS DISTINCT FROM true THEN
    RAISE EXCEPTION '004: service_role does not bypass RLS; these policy changes would break the drainer';
  END IF;

  SELECT pg_get_expr(polwithcheck, polrelid) INTO v_using
    FROM pg_policy WHERE polrelid = 'public.email_queue'::regclass
     AND polname = 'email_queue_insert_org';
  IF v_using IS NULL OR v_using NOT LIKE '%context%' THEN
    RAISE EXCEPTION '004: increment 002 is not applied — the insert policy does not constrain context. Apply 002 first.';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_policy WHERE polrelid = 'public.email_queue'::regclass
                  AND polname = 'email_queue_delete_org') THEN
    RAISE EXCEPTION '004: email_queue_delete_org is missing; refusing to guess the intended policy set';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
                  WHERE n.nspname = 'public' AND p.proname = 'queue_email_safe' AND p.pronargs = 11) THEN
    RAISE EXCEPTION '004: the 11-argument queue_email_safe from increment 001 is not present';
  END IF;
END $pre$;

-- 1. An existing system row may not be modified or destroyed by a user.

DROP POLICY IF EXISTS email_queue_update_org ON public.email_queue;
CREATE POLICY email_queue_update_org ON public.email_queue
  FOR UPDATE TO authenticated
  -- USING decides which existing rows may be touched at all. Without the guard here, a user could
  -- UPDATE a system row and rewrite it to 'general', which passes WITH CHECK because the
  -- post-update row is no longer 'system'.
  USING (
    user_has_organization_access(organization_id)
    AND context IS DISTINCT FROM 'system'
  )
  WITH CHECK (
    user_has_organization_access(organization_id)
    AND context IS DISTINCT FROM 'system'
  );

DROP POLICY IF EXISTS email_queue_delete_org ON public.email_queue;
CREATE POLICY email_queue_delete_org ON public.email_queue
  FOR DELETE TO authenticated
  -- DELETE has no WITH CHECK — there is no resulting row — so USING is the only control.
  USING (
    user_has_organization_access(organization_id)
    AND context IS DISTINCT FROM 'system'
  );

-- 2. retry_count means a number, so let the column say so.

UPDATE public.email_queue SET retry_count = 0 WHERE retry_count IS NULL;
ALTER TABLE public.email_queue ALTER COLUMN retry_count SET DEFAULT 0;
ALTER TABLE public.email_queue ALTER COLUMN retry_count SET NOT NULL;

-- 3. Remove the standing PUBLIC/anon EXECUTE on queue_email_safe. Explicit REVOKE, not narrowing
-- by omission: Supabase default privileges re-grant on CREATE, so dropping a GRANT achieves
-- nothing (learned in 001).

REVOKE EXECUTE ON FUNCTION public.queue_email_safe(
  uuid, text, text, text, text, uuid, jsonb, timestamptz, text, uuid, text) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.queue_email_safe(
  uuid, text, text, text, text, uuid, jsonb, timestamptz, text, uuid, text) FROM anon;

DO $post$
DECLARE
  v_expr text;
BEGIN
  SELECT pg_get_expr(polqual, polrelid) INTO v_expr
    FROM pg_policy WHERE polrelid = 'public.email_queue'::regclass
     AND polname = 'email_queue_update_org';
  IF v_expr IS NULL OR v_expr NOT LIKE '%context%' THEN
    RAISE EXCEPTION '004: update policy USING does not constrain context: %', v_expr;
  END IF;
  SELECT pg_get_expr(polwithcheck, polrelid) INTO v_expr
    FROM pg_policy WHERE polrelid = 'public.email_queue'::regclass
     AND polname = 'email_queue_update_org';
  IF v_expr IS NULL OR v_expr NOT LIKE '%context%' THEN
    RAISE EXCEPTION '004: update policy WITH CHECK lost its context guard: %', v_expr;
  END IF;

  SELECT pg_get_expr(polqual, polrelid) INTO v_expr
    FROM pg_policy WHERE polrelid = 'public.email_queue'::regclass
     AND polname = 'email_queue_delete_org';
  IF v_expr IS NULL OR v_expr NOT LIKE '%context%' THEN
    RAISE EXCEPTION '004: delete policy USING does not constrain context: %', v_expr;
  END IF;

  SELECT pg_get_expr(polwithcheck, polrelid) INTO v_expr
    FROM pg_policy WHERE polrelid = 'public.email_queue'::regclass
     AND polname = 'email_queue_insert_org';
  IF v_expr IS NULL OR v_expr NOT LIKE '%context%' THEN
    RAISE EXCEPTION '004: insert policy from 002 lost its context guard: %', v_expr;
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.columns
              WHERE table_schema='public' AND table_name='email_queue'
                AND column_name='retry_count' AND is_nullable='YES') THEN
    RAISE EXCEPTION '004: email_queue.retry_count is still nullable';
  END IF;

  IF has_function_privilege('anon',
       (SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
         WHERE n.nspname='public' AND p.proname='queue_email_safe'), 'EXECUTE') THEN
    RAISE EXCEPTION '004: anon still holds EXECUTE on queue_email_safe';
  END IF;
  IF NOT has_function_privilege('authenticated',
       (SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
         WHERE n.nspname='public' AND p.proname='queue_email_safe'), 'EXECUTE') THEN
    RAISE EXCEPTION '004: authenticated lost EXECUTE on queue_email_safe';
  END IF;
  IF NOT has_function_privilege('service_role',
       (SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
         WHERE n.nspname='public' AND p.proname='queue_email_safe'), 'EXECUTE') THEN
    RAISE EXCEPTION '004: service_role lost EXECUTE on queue_email_safe';
  END IF;
END $post$;

COMMIT;

-- 004 — the system-email creation boundary, and persistent hold/escalation state
-- LONDON ONLY. Source: docs/migration/london-increments/004_system_email_boundary_and_hold_state.sql

DO $$
DECLARE v_expr text; v_n int;
BEGIN
  IF to_regclass('public.email_queue') IS NULL THEN
