CREATE OR REPLACE FUNCTION public.queue_system_email_safe(
  p_organization_id uuid, p_to_email text, p_subject text, p_body_html text,
  p_body_text text DEFAULT NULL, p_entity_type text DEFAULT NULL, p_entity_id uuid DEFAULT NULL,
  p_idempotency_key text DEFAULT NULL, p_scheduled_at timestamptz DEFAULT now())
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE v_email_id uuid;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'queue_system_email_safe: organization_id is required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_organization_id) THEN
    RAISE EXCEPTION 'queue_system_email_safe: organization % does not exist', p_organization_id; END IF;
  IF p_to_email IS NULL OR btrim(p_to_email) = '' THEN
    RAISE EXCEPTION 'queue_system_email_safe: to_email is required'; END IF;
  IF position('@' IN p_to_email) = 0 THEN
    RAISE EXCEPTION 'queue_system_email_safe: to_email % is not a valid address', p_to_email; END IF;
  IF p_subject IS NULL OR btrim(p_subject) = '' THEN
    RAISE EXCEPTION 'queue_system_email_safe: subject is required'; END IF;
  IF p_body_html IS NULL OR btrim(p_body_html) = '' THEN
    RAISE EXCEPTION 'queue_system_email_safe: body_html is required'; END IF;

  INSERT INTO public.email_queue (
    organization_id, to_email, subject, body_html, body_text,
    context, provider, status, scheduled_at, entity_type, entity_id, idempotency_key)
  VALUES (
    p_organization_id, btrim(p_to_email), p_subject, p_body_html, p_body_text,
    'system', 'postmark', 'pending', coalesce(p_scheduled_at, now()),
    p_entity_type, p_entity_id, p_idempotency_key)
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING id INTO v_email_id;

  IF v_email_id IS NULL AND p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_email_id FROM public.email_queue WHERE idempotency_key = p_idempotency_key;
  END IF;
  RETURN v_email_id;
END;
$function$;

ALTER FUNCTION public.queue_system_email_safe(uuid,text,text,text,text,text,uuid,text,timestamptz) OWNER TO postgres;
REVOKE EXECUTE ON FUNCTION public.queue_system_email_safe(uuid,text,text,text,text,text,uuid,text,timestamptz) FROM PUBLIC;
